-- Authored source-bound arcs; runtime access remains episode and branch gated.
local _,ns=...
local additions={["alterac-crown-and-freedom"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=495,["sourceHash"]="aa0427d172b67081b5f6d905b4c80e8a511c6c9eb4847ce55e1351b317f6813d"},{["minimumStage"]=4,["questID"]=518,["sourceHash"]="1234e6ccb8217784697cd3d83d2d4197eb7a19d5ee7c3e681500e13360ca5481"},{["minimumStage"]=4,["questID"]=519,["sourceHash"]="981f7e99e5b3f91fc38040921fc7c2b7c90eccab92612c23e010121fc4443d36"},{["minimumStage"]=4,["questID"]=520,["sourceHash"]="d6fa67a4fa1b6171de17d7f2b09dff141dd97b7d37972b693f2b67e0df069dd7"},{["minimumStage"]=4,["questID"]=521,["sourceHash"]="f3ca8476ca4ef12f1ef58c7748863c93be05b040611278eefab77d3cf1d48731"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="alterac-crown-and-freedom-495",["requiresAll"]={{["minimumStage"]=2,["questID"]=495}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"495:description:1-98","495:description:100-172","495:description:174-228","495:description:233-297","495:description:299-392","495:description:397-506","495:objective:1-61"},["questID"]=495,["sourceHash"]="aa0427d172b67081b5f6d905b4c80e8a511c6c9eb4847ce55e1351b317f6813d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The crown had done more than tempt an ogre with its shine. Sent to retrieve it for Sylvanas, Mug’thol had worn it himself and escaped the possession binding him to her service. Sharlindra’s answer was an order to report to Melisara in Tarren Mill."},{["episodeID"]="alterac-crown-and-freedom-518",["requiresAll"]={{["minimumStage"]=2,["questID"]=518}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"518:description:1-68","518:description:70-168","518:description:173-211","518:description:216-226","518:description:228-232","518:description:234-240","518:objective:1-55"},["questID"]=518,["sourceHash"]="1234e6ccb8217784697cd3d83d2d4197eb7a19d5ee7c3e681500e13360ca5481",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Melisara would not begin with the chieftain. His Crushridge followers held the ruins of Alterac, and she demanded their numbers be reduced before the attack could reach him."},{["episodeID"]="alterac-crown-and-freedom-519",["requiresAll"]={{["minimumStage"]=2,["questID"]=519}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"519:description:1-55","519:description:57-129","519:description:134-233","519:objective:1-82"},["questID"]=519,["sourceHash"]="981f7e99e5b3f91fc38040921fc7c2b7c90eccab92612c23e010121fc4443d36",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The campaign narrowed to Targ, Muckrake and Glommus, the three lieutenants loyal to Mug’thol. Melisara wanted their heads as the next warning against defying the Dark Lady."},{["episodeID"]="alterac-crown-and-freedom-520",["requiresAll"]={{["minimumStage"]=4,["questID"]=520}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"520:description:1-102","520:description:104-154","520:description:156-199","520:description:201-212","520:description:214-228","520:description:233-288","520:description:290-333","520:objective:1-85","520:completion:1-33","520:completion:35-181"},["questID"]=520,["sourceHash"]="d6fa67a4fa1b6171de17d7f2b09dff141dd97b7d37972b693f2b67e0df069dd7",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Mug’thol’s head and the recovered crown satisfied Melisara. She promised to display the head above Alterac and send the Deathguard after the remnants, extending her threat beyond the victory already reported."},{["episodeID"]="alterac-crown-and-freedom-521",["requiresAll"]={{["minimumStage"]=4,["questID"]=521}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"521:description:1-80","521:description:82-132","521:description:134-250","521:objective:1-57","521:completion:1-71","521:completion:76-137","521:completion:139-180","521:completion:182-285"},["questID"]=521,["sourceHash"]="f3ca8476ca4ef12f1ef58c7748863c93be05b040611278eefab77d3cf1d48731",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Sharlindra received the crown in the Undercity and promised to carry it to Sylvanas. She marveled that so simple an object had let the ogre resist the Dark Lady’s will; the same freedom had made its bearer a target."}},["grouping"]="One campaign against Mug’thol and return of the crown; possession is explicit, and the promised extermination of the remaining ogres is not a recorded outcome.",["quests"]={495,518,519,520,521},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Crown That Broke a Bond"},["andorhal-key-alliance"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=5533,["sourceHash"]="70d4f2a8fb66f70f831ceec1e14f901a3537e00869e0effba4debcfed4282bcf"},{["minimumStage"]=4,["questID"]=5537,["sourceHash"]="5c48a4671cddaac4ac5c69b9cd52c4dbd17e1b5d96bc8f884442728caadb2847"},{["minimumStage"]=4,["questID"]=5538,["sourceHash"]="7df14e39f465188278cc1668472031455293b707b3814219ca73a102e7431adb"},{["minimumStage"]=4,["questID"]=5803,["sourceHash"]="bd46bbbf3bff0fa8447ede47ac5d551087a6c69cd13d874a7e307c5e16d037ca"},{["minimumStage"]=4,["questID"]=5801,["sourceHash"]="63bcfc427ee1593863bd93d52e6904c061a48e537f85e156e594d463acf09fa5"},{["minimumStage"]=4,["questID"]=5505,["sourceHash"]="e341464036bcef5f2cd30187cbd80c9902d2d769885589353adbab24f4fdc58f"}}},["interpretation"]="The source route includes forging5801 and ends with completed key receipt5505 after scarab5803. Preparing the solvent at5803 is not the final receipt.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="andorhal-key-alliance-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=5533},{["minimumStage"]=2,["questID"]=5537}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"5533:description:1-97","5533:description:100-188","5533:description:190-218","5533:description:221-304","5533:description:309-395","5533:description:398-466","5533:description:469-498","5533:objective:1-71"},["questID"]=5533,["sourceHash"]="70d4f2a8fb66f70f831ceec1e14f901a3537e00869e0effba4debcfed4282bcf",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"5537:description:1-48","5537:description:51-188","5537:description:191-308","5537:description:313-343","5537:description:346-397","5537:description:400-498","5537:objective:1-91"},["questID"]=5537,["sourceHash"]="5c48a4671cddaac4ac5c69b9cd52c4dbd17e1b5d96bc8f884442728caadb2847",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Valorfist's suspicions about the school exceeded what he could prove inside it. Arbington offered a way through the locked entrance, beginning with fragments gathered around the ruined city."},{["episodeID"]="andorhal-key-alliance-2",["requiresAll"]={{["minimumStage"]=4,["questID"]=5538}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"5538:description:1-60","5538:description:63-146","5538:description:149-245","5538:description:248-317","5538:description:322-352","5538:description:355-411","5538:description:416-460","5538:description:463-467","5538:description:472-492","5538:description:495-504","5538:objective:1-88","5538:completion:1-61","5538:completion:63-128","5538:completion:133-165","5538:completion:167-178","5538:completion:180-257"},["questID"]=5538,["sourceHash"]="7df14e39f465188278cc1668472031455293b707b3814219ca73a102e7431adb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The bones were tempered before their journey to Gadgetzan. Goodsteel could shape what the alchemist prepared, but the macabre key still lacked its final source of power."},{["episodeID"]="andorhal-key-alliance-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=5803}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"5803:description:1-67","5803:description:70-158","5803:description:161-254","5803:description:259-366","5803:description:369-428","5803:description:433-466","5803:objective:1-113","5803:completion:1-16","5803:completion:23-93","5803:completion:95-180","5803:completion:185-227","5803:completion:229-397","5803:completion:402-434"},["questID"]=5803,["sourceHash"]="bd46bbbf3bff0fa8447ede47ac5d551087a6c69cd13d874a7e307c5e16d037ca",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The former schoolmaster's scarab returned from Andorhal. Arbington's final work would mount the signet on the key, making a crafted object into a means of entry."}},["grouping"]="Authored connected episodes with explicit source-stage gates; branches retained",["quests"]={5533,5537,5538,5803},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The Alchemist at the Locked Door"},["andorhal-key-horde"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=838,["sourceHash"]="b55d44971e2b2527e33a315be011ab316d9861a0978433c1a4c979ce02e6436c"},{["minimumStage"]=4,["questID"]=964,["sourceHash"]="697ceeeaf09c934990978124537a152b6e158f7f2d5ae7dc346d601ffc40d427"},{["minimumStage"]=4,["questID"]=5514,["sourceHash"]="0bd9f111ce0f9398f785e1ab4316560d922f397b954a9b25d4b4f1ddc4c97312"},{["minimumStage"]=4,["questID"]=5804,["sourceHash"]="a4478aeb675bfdda5d96c0dbed3d733a181c2af8ac36855e7758563c13e60b5a"},{["minimumStage"]=4,["questID"]=5802,["sourceHash"]="373b5326a500a6bb0422ff6b95a61fd22838ed7c3d7912d0e14fbc1ad6349f11"},{["minimumStage"]=4,["questID"]=5511,["sourceHash"]="ced1569269e6a3051a2d38be35b6a7294c99ba5862927da0bb16c6ad2f87673c"}}},["interpretation"]="The source route includes forging5802 and ends with the completed key receipt5511 after scarab5804. Preparing the solvent at5804 is not the final receipt.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="andorhal-key-horde-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=838},{["minimumStage"]=2,["questID"]=964}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"838:description:1-101","838:description:104-191","838:description:194-277","838:description:282-367","838:description:370-469","838:description:472-501","838:objective:1-66"},["questID"]=838,["sourceHash"]="b55d44971e2b2527e33a315be011ab316d9861a0978433c1a4c979ce02e6436c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"964:description:1-48","964:description:51-188","964:description:191-308","964:description:313-343","964:description:346-397","964:description:400-498","964:objective:1-86"},["questID"]=964,["sourceHash"]="697ceeeaf09c934990978124537a152b6e158f7f2d5ae7dc346d601ffc40d427",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A locked school protected Scourge research. Dithers's answer required dead bone shaped into a key, but material alone would never supply permission to cross its portal."},{["episodeID"]="andorhal-key-horde-2",["requiresAll"]={{["minimumStage"]=4,["questID"]=5514}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"5514:description:1-60","5514:description:63-146","5514:description:149-245","5514:description:248-317","5514:description:322-353","5514:description:356-412","5514:description:417-461","5514:description:464-468","5514:description:473-493","5514:description:496-505","5514:objective:1-88","5514:completion:1-59","5514:completion:61-126","5514:completion:131-161","5514:completion:163-174","5514:completion:176-245"},["questID"]=5514,["sourceHash"]="0bd9f111ce0f9398f785e1ab4316560d922f397b954a9b25d4b4f1ddc4c97312",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The tempered fragments reached a paid smith's mold. The work joined apothecary preparation to ordinary craft and a fee that had to be borne by the courier."},{["episodeID"]="andorhal-key-horde-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=5804}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"5804:description:1-67","5804:description:70-158","5804:description:161-254","5804:description:259-366","5804:description:369-428","5804:description:433-466","5804:objective:1-108","5804:completion:1-16","5804:completion:23-93","5804:completion:95-180","5804:completion:185-227","5804:completion:229-397","5804:completion:402-434"},["questID"]=5804,["sourceHash"]="a4478aeb675bfdda5d96c0dbed3d733a181c2af8ac36855e7758563c13e60b5a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Araj's scarab supplied the missing signet. Dithers prepared the solvent that would bind authority to the forged key and let it breach the school's door."}},["grouping"]="Authored connected episodes with explicit source-stage gates; branches retained",["quests"]={838,964,5514,5804},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="A Key of Bone and Authority"},["arathi-myzrael-shards-and-shackles"]={["authored"]=true,["branchHandling"]={"653 and688 are alternative contacts after652; either leads to687. Only the recorded contact’s episode is eligible."},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=642,["sourceHash"]="3d21ef3f48d1bb6d96990bdedc8c1ef749ce27d149ba800f9461221e3fb7cb83"},{["minimumStage"]=4,["questID"]=651,["sourceHash"]="a34a5fe5d445a6d67d681c8b2b89445937774da9d7b2fbc53ed7a3f75f4ec639"},{["minimumStage"]=4,["questID"]=652,["sourceHash"]="bca383530c8119935ab7ad5a0c3a76fb29e748326f7060537bf67afdef124c48"},{["minimumStage"]=4,["questID"]=687,["sourceHash"]="cf62c1d5b7b992220a863525e4a70b8e4e1ae808bd54b74b074d10e8e0db9c4b"},{["minimumStage"]=4,["questID"]=692,["sourceHash"]="d3b3101d8a7a4fa2486ddf1e85a317eba9965c698990292786c532ba2f09b705"},{["minimumStage"]=4,["questID"]=656,["sourceHash"]="290547ae18787557dd755acc67de4e0d88475744256d71b2e3f3a35e7fff8fbe"},{["anyOf"]={{["minimumStage"]=4,["questID"]=653,["sourceHash"]="e40e71b98515c10f11a9328a3a199ed58ca75077cb530b38e05854db1a408e2b"},{["minimumStage"]=4,["questID"]=688,["sourceHash"]="ccacd476e23076ed5e519fe811bb10ba899b07a17081214bed89684f6ca993b1"}}}}},["interpretation"]="Recorded fulfillment of either defined contact route and the final shackling; no wider elemental peace or unrelated encounter credit.",["scope"]="OBSERVED_BRANCH_ROUTE_AND_REBINDING"},["episodes"]={{["episodeID"]="arathi-myzrael-shards-and-shackles-642",["requiresAll"]={{["minimumStage"]=2,["questID"]=642}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"642:description:1-19","642:description:22-129","642:description:132-204","642:description:209-223","642:description:226-337","642:description:340-432","642:description:437-458","642:objective:1-89"},["questID"]=642,["sourceHash"]="3d21ef3f48d1bb6d96990bdedc8c1ef749ce27d149ba800f9461221e3fb7cb83",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A voice in Arathi’s crystal shards named herself Myzrael, a princess held beneath the earth by giants. Motes taken from the Drywhisker kobolds could strengthen the only channel through which she could plead with the world above."},{["episodeID"]="arathi-myzrael-shards-and-shackles-651",["requiresAll"]={{["minimumStage"]=4,["questID"]=651}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"651:description:1-55","651:description:58-103","651:description:108-180","651:description:183-240","651:description:245-349","651:objective:1-153","651:objective:158-198","651:completion:1-35","651:completion:40-56","651:completion:58-90","651:completion:92-162","651:completion:167-189","651:completion:191-201"},["questID"]=651,["sourceHash"]="a34a5fe5d445a6d67d681c8b2b89445937774da9d7b2fbc53ed7a3f75f4ec639",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Keys from three guarded stones opened the strongest binding. The princess answered with gratitude as the confinement loosened, making each broken restraint seem another kindness to a prisoner."},{["episodeID"]="arathi-myzrael-shards-and-shackles-652",["requiresAll"]={{["minimumStage"]=4,["questID"]=652}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"652:description:1-97","652:description:100-154","652:description:157-223","652:description:228-345","652:description:350-385","652:description:388-470","652:objective:1-21","652:objective:24-86","652:completion:1-34","652:completion:36-71"},["questID"]=652,["sourceHash"]="bca383530c8119935ab7ad5a0c3a76fb29e748326f7060537bf67afdef124c48",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The Rod of Order taken from Fozruk fitted the final keystone. A shudder passed beneath the stones as the remaining lock yielded; the voice’s promised gratitude had brought the work to the edge of freedom."},{["episodeID"]="arathi-myzrael-shards-and-shackles-653",["requiresAll"]={{["minimumStage"]=2,["questID"]=653}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"653:description:1-17","653:description:22-26","653:description:29-38","653:description:41-93","653:description:96-170","653:description:175-256","653:description:261-285","653:description:288-323","653:description:326-386","653:description:391-417","653:description:420-471","653:description:474-504","653:objective:1-62"},["questID"]=653,["sourceHash"]="e40e71b98515c10f11a9328a3a199ed58ca75077cb530b38e05854db1a408e2b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Myzrael intended to gather strength beyond her captors’ reach before challenging them. For the summons that would return her to the surface, she named Gerrig Bonegrip in Ironforge’s Forlorn Cavern as an ally."},{["episodeID"]="arathi-myzrael-shards-and-shackles-688",["requiresAll"]={{["minimumStage"]=2,["questID"]=688}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"688:description:1-17","688:description:22-26","688:description:29-38","688:description:41-93","688:description:96-170","688:description:175-256","688:description:261-285","688:description:288-323","688:description:326-385","688:description:390-420","688:description:423-453","688:objective:1-31"},["questID"]=688,["sourceHash"]="ccacd476e23076ed5e519fe811bb10ba899b07a17081214bed89684f6ca993b1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Myzrael planned to hide and gather strength before confronting the giants. She directed the search for a summons toward Zaruk in Hammerfall, an ally who knew how to bring her to the surface."},{["episodeID"]="arathi-myzrael-shards-and-shackles-687",["requiresAll"]={{["minimumStage"]=2,["questID"]=687}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"687:description:1-73","687:description:76-122","687:description:125-183","687:description:186-268","687:description:273-327","687:description:330-369","687:objective:1-24"},["questID"]=687,["sourceHash"]="cf62c1d5b7b992220a863525e4a70b8e4e1ae808bd54b74b074d10e8e0db9c4b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Her allies belonged to the Twilight’s Hammer. They said Theldurin had rejected their teachings and fled with the scroll needed to summon her, leaving the next trail among the Badlands’ rumors of a wandering outcast."},{["episodeID"]="arathi-myzrael-shards-and-shackles-692",["requiresAll"]={{["minimumStage"]=4,["questID"]=692}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"692:description:1-47","692:description:50-69","692:description:72-157","692:description:162-186","692:description:189-214","692:description:217-286","692:description:289-323","692:description:328-353","692:description:356-431","692:description:436-496","692:objective:1-114","692:completion:1-19","692:completion:21-34","692:completion:36-102","692:completion:107-185"},["questID"]=692,["sourceHash"]="d3b3101d8a7a4fa2486ddf1e85a317eba9965c698990292786c532ba2f09b705",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Theldurin’s warning overturned the rescue’s promise: the scroll could draw Myzrael into the world, but that might be the very danger to prevent. Enraged elementals had torn it apart. With the fragments recovered, he sought a means to rejoin them before the princess gathered too much strength."},{["episodeID"]="arathi-myzrael-shards-and-shackles-656",["requiresAll"]={{["minimumStage"]=4,["questID"]=656}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"656:description:1-53","656:description:56-141","656:description:144-273","656:description:278-293","656:description:298-379","656:description:382-466","656:description:471-509","656:objective:1-55","656:objective:60-127","656:completion:1-95","656:completion:97-129","656:completion:134-221","656:completion:223-259","656:completion:261-323"},["questID"]=656,["sourceHash"]="290547ae18787557dd755acc67de4e0d88475744256d71b2e3f3a35e7fff8fbe",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The summons became a confrontation. Myzrael’s eldritch shackles returned to the shards, and a wail rose from far below as the prison closed again. The crystals no longer offered warmth and safety; what stirred beneath them answered with open menace."}},["grouping"]="One shared Arathi route with alternative Ironforge and Hammerfall contacts; it does not require both factions’ handovers.",["quests"]={642,651,652,653,688,687,692,656},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Voice Beneath the Stones"},["arathi-trelane"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=691,["sourceHash"]="dac7d02c82e662b285310a4d0beb15612ed6f57376a85201f48c38a2e9d533df"},{["minimumStage"]=4,["questID"]=693,["sourceHash"]="06c7cff386f5fe382153a0b2aa81c55f267ab6289a149249f542963c0db66957"},{["minimumStage"]=4,["questID"]=694,["sourceHash"]="f22f4e0464f2195f2112130b5a7369287d3bf3f9449e13544f835e2db2f4f20d"},{["minimumStage"]=4,["questID"]=695,["sourceHash"]="e36e2db72ff0fc77b9b9e6e331934a7dc516e35e104049f13bb663545c281993"},{["minimumStage"]=4,["questID"]=696,["sourceHash"]="66040283e0e8c94f9fcee98f994af9342f805897bc95a682e156febe579737c4"},{["minimumStage"]=4,["questID"]=697,["sourceHash"]="dc9f3abcf71c6ff46798555166eef90af43a4e4bb435679588acf3fed5ed4570"}}},["interpretation"]="Every listed leaf requires its own observed completion. This authored route clause is not a claim that the source previousID array encodes all-of gameplay prerequisites.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="arathi-trelane-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=691},{["minimumStage"]=2,["questID"]=693}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"691:description:1-67","691:description:69-182","691:description:187-280","691:description:285-312","691:description:314-360","691:objective:1-121"},["questID"]=691,["sourceHash"]="dac7d02c82e662b285310a4d0beb15612ed6f57376a85201f48c38a2e9d533df",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"693:description:1-8","693:description:10-48","693:description:50-74","693:description:79-166","693:description:168-312","693:description:317-379","693:description:381-417","693:description:422-493","693:objective:1-76"},["questID"]=693,["sourceHash"]="06c7cff386f5fe382153a0b2aa81c55f267ab6289a149249f542963c0db66957",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The reagent expedition uncovered another problem in the ogres' hands. A stolen wand was already being used to impose order on kin, giving recovery an urgency beyond a collector's list."},{["episodeID"]="arathi-trelane-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=694},{["minimumStage"]=2,["questID"]=695}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"694:description:1-11","694:description:16-98","694:description:100-229","694:description:231-315","694:description:317-402","694:description:407-511","694:objective:1-71"},["questID"]=694,["sourceHash"]="f22f4e0464f2195f2112130b5a7369287d3bf3f9449e13544f835e2db2f4f20d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"695:description:1-17","695:description:19-132","695:description:134-212","695:description:218-234","695:description:236-281","695:description:283-324","695:description:326-376","695:objective:1-17"},["questID"]=695,["sourceHash"]="e36e2db72ff0fc77b9b9e6e331934a7dc516e35e104049f13bb663545c281993",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The remaining objects lay behind another occupied stronghold. A stolen agate, enchanted as a key, could turn the tower's own defenses into support without making its ogres harmless."},{["episodeID"]="arathi-trelane-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=696},{["minimumStage"]=4,["questID"]=697}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"696:description:1-93","696:description:98-250","696:description:255-358","696:description:360-459","696:description:464-489","696:objective:1-113","696:completion:1-70","696:completion:72-95","696:completion:100-171"},["questID"]=696,["sourceHash"]="66040283e0e8c94f9fcee98f994af9342f805897bc95a682e156febe579737c4",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"697:description:1-88","697:description:90-158","697:description:163-176","697:objective:1-74","697:completion:1-58","697:completion:63-91","697:completion:93-106","697:completion:108-134","697:completion:136-235","697:completion:240-253","697:completion:255-301"},["questID"]=697,["sourceHash"]="dc9f3abcf71c6ff46798555166eef90af43a4e4bb435679588acf3fed5ed4570",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The three objects returned and Skuerto's letter carried the result to Stormwind. Malin welcomed both the restored property and the prospect of his researchers coming home."}},["grouping"]="Authored connected episodes with explicit source-stage gates; branches retained",["quests"]={691,693,694,695,696,697},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The Tower and the Stolen Relics"},["ashenvale-anilia-branch-and-grief"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=1021,["sourceHash"]="60d315288b851af1178c735d05cc2f75583a5e25c57c390fffe4d23d5fc872c1"},{["minimumStage"]=4,["questID"]=1031,["sourceHash"]="bd776a9bb44d01b7c7ddae4cc22ac3f741e37def10742f08e3f0b433266cce1a"},{["minimumStage"]=4,["questID"]=1032,["sourceHash"]="0ca99b510ea30eb13b8f04df33bb7987943daa330efd01086a6b3b0f5cec9f2c"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="ashenvale-anilia-branch-and-grief-1021",["requiresAll"]={{["minimumStage"]=4,["questID"]=1021}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"1021:description:1-55","1021:description:57-123","1021:description:125-184","1021:description:189-214","1021:description:216-296","1021:description:298-324","1021:description:326-377","1021:objective:1-22","1021:completion:1-73"},["questID"]=1021,["sourceHash"]="60d315288b851af1178c735d05cc2f75583a5e25c57c390fffe4d23d5fc872c1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Illiyana’s sisters had gone to recover the Branch of Cenarius from the satyrs at Xavian. Two days without their return led the search into a ruined temple, where Anilia lay dying from a deep wound."},{["episodeID"]="ashenvale-anilia-branch-and-grief-1031",["requiresAll"]={{["minimumStage"]=4,["questID"]=1031}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1031:description:1-60","1031:description:62-179","1031:description:181-199","1031:description:201-315","1031:objective:1-76","1031:completion:1-12","1031:completion:20-33","1031:completion:35-111","1031:completion:116-145"},["questID"]=1031,["sourceHash"]="bd776a9bb44d01b7c7ddae4cc22ac3f741e37def10742f08e3f0b433266cce1a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Anilia’s last breath named Geltharis and pointed toward the northern arch. The branch returned to dryad hands, but Illiyana received it with the news that her companion would never again run beside her through the woods."},{["episodeID"]="ashenvale-anilia-branch-and-grief-1032",["requiresAll"]={{["minimumStage"]=4,["questID"]=1032}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1032:description:1-38","1032:description:40-92","1032:description:94-109","1032:description:111-114","1032:description:119-166","1032:description:168-216","1032:description:218-302","1032:objective:1-48","1032:completion:1-19","1032:completion:21-68"},["questID"]=1032,["sourceHash"]="0ca99b510ea30eb13b8f04df33bb7987943daa330efd01086a6b3b0f5cec9f2c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Grief turned Illiyana’s request toward the satyrs responsible. The returned horns gave her a measure of comfort, and she believed her sister’s spirit gladdened by the effort. The sacred object was safe; the loss that gave the fighting meaning remained."}},["grouping"]="Three stages connect a missing dryad party, a recovered sacred branch and mourning. No restoration of the dead or universal defeat of the satyrs is inferred.",["quests"]={1021,1031,1032},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Branch Brought Home"},["ashenvale-relara-remedies"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=1010,["sourceHash"]="46c7f301dfa8140a2ca9bf01067888b782974fdf1cdf4f05f52ba9def8d12883"},{["minimumStage"]=4,["questID"]=1020,["sourceHash"]="37e67aabf453a5b07a97db4584a999a9c662efa74c63789b6be24dc3c7927121"},{["minimumStage"]=4,["questID"]=1033,["sourceHash"]="a8aa3e76b0a64cf96dbe02f974fc86df0abe4df87fc83ccd3d851dde361e2264"},{["minimumStage"]=4,["questID"]=1034,["sourceHash"]="c9d08473703e74c078480d5427069a1d683152dd4473e278cec11059c38d105a"},{["minimumStage"]=4,["questID"]=1035,["sourceHash"]="7eaa00de9e7c479a1d5f40838426695ea1973ce1ef2a53bc3bfc2fb241110b53"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="ashenvale-relara-remedies-1010",["requiresAll"]={{["minimumStage"]=2,["questID"]=1010}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"1010:description:1-81","1010:description:84-164","1010:description:169-260","1010:description:263-326","1010:description:329-370","1010:description:375-461","1010:objective:1-57"},["questID"]=1010,["sourceHash"]="46c7f301dfa8140a2ca9bf01067888b782974fdf1cdf4f05f52ba9def8d12883",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Orendil feared that the child’s sickness reached beyond the body. Bathran’s Hair, a plant known for treating spiritual ailments, offered a first remedy, though gathering it led toward ruins now troubled by Forsaken."},{["episodeID"]="ashenvale-relara-remedies-1020",["requiresAll"]={{["minimumStage"]=4,["questID"]=1020}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1020:description:1-71","1020:description:74-148","1020:description:153-205","1020:objective:1-56","1020:completion:1-21","1020:completion:26-67","1020:completion:70-121"},["questID"]=1020,["sourceHash"]="37e67aabf453a5b07a97db4584a999a9c662efa74c63789b6be24dc3c7927121",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The herbal cure reached Pelturas in Astranaar and gave him hope for Relara. Orendil had prepared further possibilities should it fail, leaving the father with a path forward rather than certainty."},{["episodeID"]="ashenvale-relara-remedies-1033",["requiresAll"]={{["minimumStage"]=2,["questID"]=1033}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1033:description:1-109","1033:description:112-147","1033:description:150-234","1033:description:239-341","1033:description:344-394","1033:description:396-470","1033:objective:1-44"},["questID"]=1033,["sourceHash"]="a8aa3e76b0a64cf96dbe02f974fc86df0abe4df87fc83ccd3d851dde361e2264",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The first treatment only slowed the disease. Pelturas next sought Elune’s Tear from the island in Iris Lake, trusting Orendil’s account that the stone could wash away corruption."},{["episodeID"]="ashenvale-relara-remedies-1034",["requiresAll"]={{["minimumStage"]=2,["questID"]=1034}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1034:description:1-57","1034:description:60-128","1034:description:131-137","1034:description:139-167","1034:description:172-239","1034:description:242-278","1034:description:281-330","1034:description:335-377","1034:description:380-408","1034:objective:1-54"},["questID"]=1034,["sourceHash"]="c9d08473703e74c078480d5427069a1d683152dd4473e278cec11059c38d105a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Relara’s nightmares eased, but fever remained. Frosted dust from the sacred ruins south of Astranaar offered another remedy, this time as a poultice to bring the fever down."},{["episodeID"]="ashenvale-relara-remedies-1035",["requiresAll"]={{["minimumStage"]=4,["questID"]=1035}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1035:description:1-54","1035:description:57-129","1035:description:132-179","1035:description:184-250","1035:description:252-280","1035:description:285-375","1035:description:378-428","1035:description:433-478","1035:objective:1-97","1035:completion:1-35","1035:completion:37-110","1035:completion:115-179","1035:completion:181-198","1035:completion:200-248"},["questID"]=1035,["sourceHash"]="7eaa00de9e7c479a1d5f40838426695ea1973ce1ef2a53bc3bfc2fb241110b53",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="With the fever gone, weakness still held her. The last hope lay in a fallen moonstone hoarded by the Shadethicket Oracle. Its return brought Pelturas’s grateful assurance that his daughter’s strength could be restored, and a gift he treasured almost as dearly as the child."}},["grouping"]="Five connected remedies follow Relara’s illness. The final source records her father’s belief in recovery, without adding later medical history.",["quests"]={1010,1020,1033,1034,1035},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Father’s Vigil"},["atalai-felzerul-artifacts-and-prophecy"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=1424,["sourceHash"]="2dfa03ee5d160166a2a04eb203d2c8512ec580af644d206a8ec4a6dccdc504cf"},{["minimumStage"]=4,["questID"]=1429,["sourceHash"]="a6b755e9ed3cb5ec888bfadecb94f1abd319018b29ae2e88dd5b46baad9a4a5b"},{["minimumStage"]=4,["questID"]=1444,["sourceHash"]="17638bbac2e831c04e302af61bb64ab14f6726bbf4898d9a6cffcd71266d76fd"},{["minimumStage"]=4,["questID"]=1445,["sourceHash"]="b27f5c7c3a596313d707b321de83676688fa1078d06ec82f77fc6b6fd2531939"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="atalai-felzerul-artifacts-and-prophecy-1424",["requiresAll"]={{["minimumStage"]=2,["questID"]=1424}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"1424:description:1-84","1424:description:89-173","1424:description:175-271","1424:description:276-350","1424:description:355-388","1424:description:390-451","1424:description:453-505","1424:objective:1-62"},["questID"]=1424,["sourceHash"]="2dfa03ee5d160166a2a04eb203d2c8512ec580af644d206a8ec4a6dccdc504cf",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Fel’zerul had come under the warchief’s orders to investigate the Atal’ai, only to find their temple submerged and watched by green dragons. Artifacts around the Pool of Tears offered the first means to understand what had happened."},{["episodeID"]="atalai-felzerul-artifacts-and-prophecy-1429",["requiresAll"]={{["minimumStage"]=4,["questID"]=1429}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1429:description:1-129","1429:description:131-203","1429:description:208-280","1429:description:285-363","1429:description:368-397","1429:description:399-456","1429:description:458-500","1429:objective:1-78","1429:completion:1-53","1429:completion:58-160","1429:completion:162-204","1429:completion:206-229"},["questID"]=1429,["sourceHash"]="a6b755e9ed3cb5ec888bfadecb94f1abd319018b29ae2e88dd5b46baad9a4a5b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A scout’s blood-written sentence pointed to an exiled priest living among the Witherbark far to the north. The recovered objects went to him, and he recognized the apparatus of the Atal’ai’s summoning rites."},{["episodeID"]="atalai-felzerul-artifacts-and-prophecy-1444",["requiresAll"]={{["minimumStage"]=2,["questID"]=1444}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1444:description:1-75","1444:description:77-124","1444:description:129-213","1444:description:215-235","1444:description:240-321","1444:description:326-372","1444:description:374-489","1444:objective:1-31"},["questID"]=1444,["sourceHash"]="17638bbac2e831c04e302af61bb64ab14f6726bbf4898d9a6cffcd71266d76fd",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The exile had challenged Jammal’an’s prophecy and been condemned as an infidel. He judged these particular artifacts harmless, but warned that the correct enchantment could make the summoning a danger to the world."},{["episodeID"]="atalai-felzerul-artifacts-and-prophecy-1445",["requiresAll"]={{["minimumStage"]=4,["questID"]=1445}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1445:description:1-36","1445:description:41-175","1445:description:180-246","1445:description:251-300","1445:description:302-326","1445:description:328-444","1445:description:449-496","1445:objective:1-69","1445:completion:1-71","1445:completion:76-144"},["questID"]=1445,["sourceHash"]="b27f5c7c3a596313d707b321de83676688fa1078d06ec82f77fc6b6fd2531939",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Fel’zerul understood Jammal’an’s promise of immortality as a path toward disaster. Fetishes taken from the temple returned for study and disposal, advancing the investigation without establishing that Hakkar had appeared or that the whole temple had been overcome."}},["grouping"]="Four stages connect the submerged temple, exile and dangerous prophecy; fetish recovery is not a Hakkar kill or proof of a completed summoning.",["quests"]={1424,1429,1444,1445},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Temple Beneath the Water"},["authored-dam"]={["authored"]=true,["branchHandling"]={"283 is the follow-up report after280; absence of its completion in a personal record must not manufacture a return to Hinderweir."},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=250,["sourceHash"]="a3edade2785198b5582c483e0aecc751d85a3ab3520673bd4ab49b17990b0e3e"},{["minimumStage"]=4,["questID"]=199,["sourceHash"]="3799e347e4d89d39cbfd6d5f5f88245b5fe55c4464407fb664789fc856e9847c"},{["minimumStage"]=4,["questID"]=161,["sourceHash"]="85ca4f58f8ae6a38af068123cebfcd0fe7af5f55ae0131cb2b0fda80a4ab7227"},{["minimumStage"]=4,["questID"]=274,["sourceHash"]="9bc79e1acf57e5bf668641ec3dfc963eb9ee73bd0179968e472e0bd6229b32bc"},{["minimumStage"]=4,["questID"]=278,["sourceHash"]="b46cd2afbb602d7dccc6f14276fbce5b26eebee3a297d76977b1da4327fc5201"},{["minimumStage"]=4,["questID"]=280,["sourceHash"]="481cab329964a795e77e202b6d5e22e590986e25d85a6547af634b7f427403d1"},{["minimumStage"]=4,["questID"]=283,["sourceHash"]="597c9ee0376bf595b6721f48ac0537004c06ca9ba9d411a547f55d8199c1488d"}}},["interpretation"]="Every listed leaf requires its own observed completion with a matching source hash. This editorial route clause does not infer gameplay all-of prerequisites from previousID arrays.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="authored-dam-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=250}},["role"]="opening",["sourceProofs"]={{["atomIDs"]={"250:description:1-69","250:description:72-148","250:description:151-227","250:description:230-327","250:description:332-357","250:description:360-434","250:description:438-480","250:objective:1-152"},["questID"]=250,["sourceHash"]="a3edade2785198b5582c483e0aecc751d85a3ab3520673bd4ab49b17990b0e3e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The destruction of the Thandol Span and the fall of Dun Modr made Hinderweir fear that the dam would be next. With the guards depleted, he could not dismiss sappers seen at the eastern ramp."},{["episodeID"]="authored-dam-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=161},{["minimumStage"]=2,[