e"]=2,["questID"]=280}},["role"]="progression",["sourceProofs"]={{["atomIDs"]={"250:description:1-69","250:description:72-148","250:description:151-227","250:description:230-327","250:description:332-357","250:description:360-434","250:description:438-480","250:objective:1-152"},["questID"]=250,["sourceHash"]="a3edade2785198b5582c483e0aecc751d85a3ab3520673bd4ab49b17990b0e3e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"199:description:1-49","199:objective:1-78"},["questID"]=199,["sourceHash"]="3799e347e4d89d39cbfd6d5f5f88245b5fe55c4464407fb664789fc856e9847c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"161:description:1-68","161:description:71-161","161:description:164-249","161:description:252-303","161:description:308-411","161:description:414-469","161:objective:1-128"},["questID"]=161,["sourceHash"]="85ca4f58f8ae6a38af068123cebfcd0fe7af5f55ae0131cb2b0fda80a4ab7227",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"274:description:1-36","274:description:39-71","274:description:74-96","274:description:99-155","274:description:158-186","274:description:189-250","274:description:255-403","274:description:406-446","274:objective:1-103"},["questID"]=274,["sourceHash"]="9bc79e1acf57e5bf668641ec3dfc963eb9ee73bd0179968e472e0bd6229b32bc",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"278:description:1-57","278:description:60-125","278:description:128-178","278:description:181-237","278:description:240-319","278:description:324-375","278:description:378-460","278:objective:1-101"},["questID"]=278,["sourceHash"]="b46cd2afbb602d7dccc6f14276fbce5b26eebee3a297d76977b1da4327fc5201",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"280:description:1-91","280:description:94-135","280:description:138-233","280:description:236-299","280:description:302-313","280:description:318-399","280:description:402-407","280:objective:1-153"},["questID"]=280,["sourceHash"]="481cab329964a795e77e202b6d5e22e590986e25d85a6547af634b7f427403d1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Preparation and attack converged at the waterline. The gathered venom, crystal and tear could be mixed, but insurgents had already been seen carrying a keg toward the structure's base."},{["episodeID"]="authored-dam-4",["requiresAll"]={{["minimumStage"]=2,["questID"]=161},{["minimumStage"]=2,["questID"]=199},{["minimumStage"]=2,["questID"]=250},{["minimumStage"]=2,["questID"]=274},{["minimumStage"]=2,["questID"]=278},{["minimumStage"]=4,["questID"]=280}},["role"]="ending",["sourceProofs"]={{["atomIDs"]={"250:description:1-69","250:description:72-148","250:description:151-227","250:description:230-327","250:description:332-357","250:description:360-434","250:description:438-480","250:objective:1-152"},["questID"]=250,["sourceHash"]="a3edade2785198b5582c483e0aecc751d85a3ab3520673bd4ab49b17990b0e3e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"199:description:1-49","199:objective:1-78"},["questID"]=199,["sourceHash"]="3799e347e4d89d39cbfd6d5f5f88245b5fe55c4464407fb664789fc856e9847c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"161:description:1-68","161:description:71-161","161:description:164-249","161:description:252-303","161:description:308-411","161:description:414-469","161:objective:1-128"},["questID"]=161,["sourceHash"]="85ca4f58f8ae6a38af068123cebfcd0fe7af5f55ae0131cb2b0fda80a4ab7227",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"274:description:1-36","274:description:39-71","274:description:74-96","274:description:99-155","274:description:158-186","274:description:189-250","274:description:255-403","274:description:406-446","274:objective:1-103"},["questID"]=274,["sourceHash"]="9bc79e1acf57e5bf668641ec3dfc963eb9ee73bd0179968e472e0bd6229b32bc",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"278:description:1-57","278:description:60-125","278:description:128-178","278:description:181-237","278:description:240-319","278:description:324-375","278:description:378-460","278:objective:1-101"},["questID"]=278,["sourceHash"]="b46cd2afbb602d7dccc6f14276fbce5b26eebee3a297d76977b1da4327fc5201",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"280:completion:1-61"},["questID"]=280,["sourceHash"]="481cab329964a795e77e202b6d5e22e590986e25d85a6547af634b7f427403d1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The mixture settled into the keg with a slight fizz. That response closed the immediate disarming task; the wider Dark Iron threat remained beyond the reach of a single keg."},{["episodeID"]="authored-dam-hinderweir-outcome",["requiresAll"]={{["minimumStage"]=4,["questID"]=283}},["role"]="ending",["sourceProofs"]={{["atomIDs"]={"283:description:1-25","283:objective:1-44","283:objective:47-106","283:completion:1-23","283:completion:25-60","283:completion:62-161","283:completion:163-221","283:completion:226-252","283:completion:258-285"},["questID"]=283,["sourceHash"]="597c9ee0376bf595b6721f48ac0537004c06ca9ba9d411a547f55d8199c1488d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The report reached Hinderweir after the mixture settled into the keg. He thanked the helper for saving the Stonewrought Dam and judged it safe again, for the time being."}},["grouping"]="SOURCE_CONNECTED_ARC_WITH_BRANCHES",["quests"]={250,199,161,274,278,280,283},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="Powder beneath the water"},["authored-feralas-courier"]={["authored"]=true,["branchHandling"]={{["detail"]="The parcel source explicitly leaves the courier fa