/addons/questdb/files/9014639"},{["atomIDs"]={"4127:description:1-74","4127:description:77-180","4127:description:183-267","4127:description:272-410","4127:description:413-486","4127:objective:1-96"},["questID"]=4127,["sourceHash"]="0d139b8e8ea6a2fc8af250da7f93b34207a8908943bf92b06096fb410a2e18c3",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"4129:description:1-63","4129:description:65-79","4129:description:82-165","4129:description:168-257","4129:description:260-339","4129:description:344-501","4129:objective:1-72"},["questID"]=4129,["sourceHash"]="c26695979c79c3c4a3ce838305fc7e6483c04a01bed74a459a4efbdbbdf3e5cb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"4130:description:1-33","4130:description:36-74","4130:description:79-183","4130:description:186-206","4130:description:208-264","4130:description:267-321","4130:description:324-406","4130:description:409-421","4130:description:423-433","4130:description:438-462","4130:description:465-488","4130:description:491-507","4130:objective:1-56"},["questID"]=4130,["sourceHash"]="7140c4a8c40620e508deebe4c5cd68f5187cae05fab4f4c1be453958b9e15c5b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"4131:description:1-112","4131:description:115-161","4131:description:166-399","4131:description:402-503","4131:objective:1-115"},["questID"]=4131,["sourceHash"]="2a8a91865c77ff8661154226b25e695e7635fcb6e335c5f0c8303021fd4e0b78",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"4135:description:1-158","4135:description:163-282","4135:description:285-391","4135:description:394-438","4135:description:443-508","4135:objective:1-129","4135:objective:132-208"},["questID"]=4135,["sourceHash"]="41a0eadda2a1eeb38ca4a85fa9a40df32be79c925275212926cc45e5c31c8af3",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The packs found among