addons/questdb/files/9014639"}},["text"]="The report reached Gracina, who identified the insects as silithid and called them tools of a far greater threat. A missing courier's trail had exposed a danger she believed reached beyond one rescue or one stronghold."}},["grouping"]="SOURCE_CONNECTED_ARC_WITH_BRANCHES",["quests"]={4124,4125,4127,4129,4130,4131,4135,4265,4266,4267},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The packs on the tree"},["authored-kurzen-spy"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=215,["sourceHash"]="fbe14e337078fcb1e0c4ca59494548a785d84812ba8b79f9f42a3dfad039058c"},{["minimumStage"]=4,["questID"]=200,["sourceHash"]="9d6ace0a44c51e98d5efaf6a4f130d433ee953ed8c61f08c1694d972b98f826e"},{["minimumStage"]=4,["questID"]=328,["sourceHash"]="f259674e565acee60c5e9d7f49dac04afad37742d93928efba5971981e736abf"},{["minimumStage"]=4,["questID"]=329,["sourceHash"]="16edeb03b757cad0c36dd4308dfd92f15895887b3dd6d470f804440995b28658"},{["minimumStage"]=4,["questID"]=330,["sourceHash"]="e6f4dd6b41b54d1d7edd0066dd826d1d80451ae3d458eba2b33584f54a8f64bd"},{["minimumStage"]=4,["questID"]=331,["sourceHash"]="4e69a83b2d36ac92d0f99b10c29f451cf4c1621d754d2c4f89f84cb5ded32557"}}},["interpretation"]="Every listed leaf requires its own observed completion with a matching source hash. This editorial route clause does not infer gameplay all-of prerequisites from previousID arrays.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="authored-kurzen-spy-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=215}},["role"]="opening",["sourceProofs"]={{["atomIDs"]={"215:description:1-28","215:description:31-79","215:description:84-228","215:description:231-313","215:description:316-360","215:description:365-419","215:description:422-465","215:objective:1-46"},["questID"]=215,["sourceHash"]="fbe14e337078fcb1e0c4ca59494548a785d84812ba8b79f9f42a3dfad039058c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Thorsen's explanation turned apparent service under Kurzen into a secret rebel mission. Its failure sent the account back to Doren, who could explain why the attempted infiltration had mattered."},{["episodeID"]="authored-kurzen-spy-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=200},{["minimumStage"]=2,["questID"]=215},{["minimumStage"]=2,["questID"]=328}},["role"]="progression",["sourceProofs"]={{["atomIDs"]={"215:description:1-28","215:description:31-79","215:description:84-228","215:description:231-313","215:description:316-360","215:description:365-419","215:description:422-465","215:objective:1-46"},["questID"]=215,["sourceHash"]="fbe14e337078fcb1e0c4ca59494548a785d84812ba8b79f9f42a3dfad039058c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"200:description:1-66","200:description:69-112","200:description:117-172","200:description:175-270","200:description:273-362","200:description:367-470","200:description:473-509","200:objective:1-28"},["questID"]=200,["sourceHash"]="9d6ace0a44c51e98d5efaf6a4f130d433ee953ed8c61f08c1694d972b98f826e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"328:description:1-145","328:description:150-263","328:description:266-361","328:description:366-506","328:objective:1-57"},["questID"]=328,["sourceHash"]="f259674e565acee60c5e9d7f49dac04afad37742d93928efba5971981e736abf",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Herod's records did not mention Thorsen, but a hidden key led past the public ledgers. The Stockpile's strongbox offered a place for the knowledge the books did not admit."},{["episodeID"]="authored-kurzen-spy-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=200},{["minimumStage"]=2,["questID"]=215},{["minimumStage"]=2,["questID"]=328},{["minimumStage"]=2,["questID"