42:description:1-74","1042:description:76-203","1042:description:208-278","1042:description:280-349","1042:description:351-383","1042:description:385-435","1042:description:437-488","1042:objective:1-41"},["questID"]=1042,["sourceHash"]="e7f186dcb8514eb9bf11381bdcf3d0eee31e8072432117cc7c998229d6386a29",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"1043:description:1-24","1043:description:26-202","1043:description:207-271","1043:description:273-361","1043:description:366-463","1043:description:465-511","1043:objective:1-83"},["questID"]=1043,["sourceHash"]="754cdaf2e426eadfc20ae6e47840d28ac79dbf94072b38f332d33ca1311ff769",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"1044:completion:1-38","1044:completion:40-144","1044:completion:146-297","1044:completion:302-342","1044:completion:344-413"},["questID"]=1044,["sourceHash"]="896780139289ceb128692f3dbd445a3f09add2165e7ace280d19d3d0223bc5c6",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The findings returned to Thyn'tel in Darnassus. Velinde's fate now had an account, but the commander remained disturbed that the Scythe had passed from Elune's servants. Answering the search did not settle the artifact's future."}},["grouping"]="SOURCE_CONNECTED_ARC_WITH_BRANCHES",["quests"]={1022,1037,1038,1039,1040,1041,1042,1043,1044},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The road of the missing priestess"},["authored-silithid-investigation"]={["authored"]=true,["branchHandling"]={{["branches"]={{["name"]="Alliance",["questIDs"]={162,4493,4508,4510},["sourceRaceMasks"]={"77","1101","77","77"}},{["name"]="Horde",["questIDs"]={32,4494,4509,4511},["sourceRaceMasks"]={"178","690","178","178"}}},["detail"]="One source-matching native observed faction route is sufficient. Each episode keeps its own quest gate and no report implies unseen completion.",["kind"]="FA