r account."},{["episodeID"]="authored-silithid-investigation-horde-gratitude-receipt",["requiresAll"]={{["minimumStage"]=4,["questID"]=4511}},["role"]="ending",["sourceProofs"]={{["atomIDs"]={"4511:description:1-50","4511:description:53-146","4511:description:149-281","4511:description:283-337","4511:description:342-377","4511:description:380-467","4511:description:470-510","4511:objective:1-57","4511:completion:1-115","4511:completion:118-159"},["questID"]=4511,["sourceHash"]="f42fd8cdada937f34d4afa0da1812daa5192fb3bacf7c5d74dfc384f76442226",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Zilzibin feared that Un'Goro had been a mistaken lead to the silithid's origin and that a stronger presence remained elsewhere. Karus accepted his voucher at the bank and released the promised token of thanks."}},["grouping"]="SOURCE_CONNECTED_ARC_WITH_BRANCHES",["quests"]={992,82,10,110,113,32,162,4496,4507,4508,4509,4493,4494,4510,4511},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The water that went missing"},["authored-stalvan"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=66,["sourceHash"]="ac82b5b671db17cc1441ad56a4d7d28d3ac7fa52c9eeb401abeadda76eba5d99"},{["minimumStage"]=4,["questID"]=67,["sourceHash"]="d8b7a981bbecfccc0f88ca46b4abb333b80a43f8f6d9daba3b1ac0fe2d9a1a3c"},{["minimumStage"]=4,["questID"]=68,["sourceHash"]="8ed9733508a052af6d517bc0337f45de1681742de9fca601cef888f53706210a"},{["minimumStage"]=4,["questID"]=69,["sourceHash"]="8f0bd462973f5b13d34642345aa44239d1d2a23f3f2856f4c06596e895636535"},{["minimumStage"]=4,["questID"]=70,["sourceHash"]="ef8baf1292f0f73de5eb8625ad126700b8996c6665cbe3477ce8bf474133fced"},{["minimumStage"]=4,["questID"]=72,["sourceHash"]="63fa49a013e1eaed1144c50a38ae288366990ab87d7a6e66dea098b70f0608e9"},{["minimumStage"]=4,["questID"]=74,["sourceHash"]="6aa0988490c799cb0167d204bdb5b3