]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"586:description:1-31","586:description:36-45","586:description:48-73","586:description:78-150","586:description:152-159","586:description:164-227","586:description:230-340","586:description:343-346","586:description:349-388","586:description:393-464","586:objective:1-90","586:objective:95-180"},["questID"]=586,["sourceHash"]="37e95fce3c13be9039740bf74fc1fa35bacdb33750da333f20b18d85024c7358",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"588:description:1-18","588:description:23-114","588:description:119-152","588:description:157-207","588:description:210-299","588:description:304-336","588:description:341-410","588:description:413-430","588:objective:1-22"},["questID"]=588,["sourceHash"]="6069b2a17e6038a0bb2aa00f4de0f36b712abd39bbfb2ab79cdd3866e25b3870",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"589:description:1-67","589:description:70-120","589:description:123-217","589:description:222-290","589:description:293-414","589:description:417-501","589:objective:1-68"},["questID"]=589,["sourceHash"]="f8f7e59cdf306fa4f6429072e15d0d989501a2539919e918fbfa9c39753183e7",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"591:description:1-93","591:description:96-116","591:description:119-218","591:description:223-290","591:description:295-351","591:description:354-426","591:objective:1-61"},["questID"]=591,["sourceHash"]="dbea9356b56ebe9fa2f06b3f5891c456c1af08dfdb7bff8610613199626dd308",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"592:completion:1-15","592:completion:17-116","592:completion:121-233"},["questID"]=592,["sourceHash"]="faa08c9a3deb08bc1a51f046c5d7131236a7502a4c89400a09ba7e167bd75a48",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Nimboya acknowledged Yenniku freed from Zanzil's will. The undertaking ended with release from control, answering the uncertainty that had first sent the search among enemy trophies."}},["grouping"]="SOURCE_CONNECTED_ARC_WITH_BRANCHES",["quests"]={581,582,584,585,586,588,589,591,592},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The son who was missing"},["azshara-tymors-rune-rubbings"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=3448,["sourceHash"]="eaf3acc73f7dfb764333309b3c61244ef2e7fee07d0a80e25510ce2c6c07431e"},{["minimumStage"]=4,["questID"]=3449,["sourceHash"]="10c8978c78aba4e3e86d18668ee7199f495f1ecdbc3dbf88de41fdfd1ecf9ca6"},{["minimumStage"]=4,["questID"]=3461,["sourceHash"]="d96e83ddc85000a25b77b6f226d847ecb2cfc5c1cfe2f1a8e7ca5903a53ce75f"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="azshara-tymors-rune-rubbings-3448",["requiresAll"]={{["minimumStage"]=2,["questID"]=3448}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"3448:description:1-115","3448:description:117-161","3448:description:163-295","3448:description:300-423","3448:description:428-504","3448:objective:1-28"},["questID"]=3448,["sourceHash"]="eaf3acc73f7dfb764333309b3c61244ef2e7fee07d0a80e25510ce2c6c07431e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Karnik’s investigation of Azshara turned toward Tymor, a scholar drawn to the magical knowledge of the ancient elven cities. The ruins offered evidence of a past even their long-lived people might not remember clearly."},{["episodeID"]="azshara-tymors-rune-rubbings-3449",["requiresAll"]={{["minimumStage"]=2,["questID"]=3449}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"3449:description:1-57","3449:description:59-178","3449:description:180-237","3449:description:242-315","3449:description:317-402","3449:description:404-486","3449:objective:1-261"},["questID"]=3449,["sourceHash"]="10c8978c78aba4e3e86d18668ee7199f495f1ecdbc3dbf88de41fdfd1ecf9ca6",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Tymor wanted the old mages’ words preserved as rubbings rather than carried away as broken stone. Four runes in Eldarath were to be copied, then collected by Xiggs from the island off Azshara’s southern peninsula."},{["episodeID"]="azshara-tymors-rune-rubbings-3461",["requiresAll"]={{["minimumStage"]=4,["questID"]=3461}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"3461:description:1-115","3461:description:117-172","3461:description:174-221","3461:description:223-251","3461:description:253-268","3461:description:273-327","3461:description:332-368","3461:description:370-434","3461:objective:1-47","3461:completion:1-10","3461:completion:12-34","3461:completion:39-103","3461:completion:105-128","3461:completion:130-159","3461:completion:161-216","3461:completion:221-347"},["questID"]=3461,["sourceHash"]="d96e83ddc85000a25b77b6f226d847ecb2cfc5c1cfe2f1a8e7ca5903a53ce75f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The copies were on their way to Tymor, and his drawing kit returned to Ironforge. His excitement belonged to the study still ahead; recovering the inscriptions had not yet unlocked all their meaning."}},["grouping"]="Karnik’s referral, Tymor’s four rubbings and the return of his kit; study does not imply the old runes were deciphered.",["quests"]={3448,3449,3461},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Words Left in Stone"},["barrens-mangletooth"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=878,["sourceHash"]="1f832f75205595b41422b8924547f9d4786c20ec5965f49fa9465c845bbf954f"},{["minimumStage"]=4,["questID"]=5052,["sourceHash"]="303b3e0f70bd177101c6f46c6296b8a0f7e58226365990fcd773305688668899"},{["minimumStage"]=4,["questID"]=879,["sourceHash"]="29be981d25e1810348411823f818f9d1cbd079f370c87ffd80e99988b8d77c89"},{["minimumStage"]=4,["questID"]=906,["sourceHash"]="682a691621cc5c45db58e4e5213693894e9b8cd7650aff816e92ab3aa134abe1"}}},["interpretation"]="Every listed leaf requires its own observed completion. This authored route clause is not a claim that the source previousID array encodes all-of gameplay prerequisites.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="barrens-mangletooth-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=878}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"878:description:1-27","878:description:29-110","878:description:112-175","878:description:177-221","878:description:223-237","878:description:242-347","878:description:349-482","878:objective:1-149"},["questID"]=878,["sourceHash"]="1f832f75205595b41422b8924547f9d4786c20ec5965f49fa9465c845bbf954f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Mangletooth offered the Horde a route through rivalries among quilboar. Weakening Bristleback spiritual leaders was also an act in service of his own Razormane people."},{["episodeID"]="barrens-mangletooth-2",["requiresAll"]={{["minimumStage"]=4,["questID"]=5052}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"5052:description:1-124","5052:description:126-248","5052:description:250-256","5052:description:261-293","5052:description:298-364","5052:description:366-469","5052:description:471-477","5052:objective:1-66","5052:objective:71-148","5052:completion:1-22","5052:completion:24-71","5052:completion:73-137","5052:completion:139-145","5052:completion:150-190","5052:completion:192-219","5052:completion:224-251","5052:completion:253-288","5052:completion:293-329","5052:completion:331-357","5052:completion:359-391","5052:completion:393-436","5052:completion:438-463","5052:completion:465-471"},["questID"]=5052,["sourceHash"]="303b3e0f70bd177101c6f46c6296b8a0f7e58226365990fcd773305688668899",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A blood shard returned a familiar touch of power to the prisoner. His explanation of Agamaggan's magic turned into the story of a people who had left him behind."},{["episodeID"]="barrens-mangletooth-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=879},{["minimumStage"]=4,["questID"]=906}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"879:description:1-80","879:description:82-213","879:description:215-256","879:description:258-264","879:description:269-316","879:description:318-359","879:description:361-462","879:description:464-503","879:objective:1-100","879:completion:1-16","879:completion:18-59","879:completion:61-206","879:completion:211-259"},["questID"]=879,["sourceHash"]="29be981d25e1810348411823f818f9d1cbd079f370c87ffd80e99988b8d77c89",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"906:description:1-47","906:description:49-192","906:description:194-259","906:description:261-267","906:description:272-364","906:description:366-386","906:objective:1-60","906:completion:1-59","906:completion:61-68","906:completion:73-135","906:completion:137-204","906:completion:209-299","906:completion:301-320"},["questID"]=906,["sourceHash"]="682a691621cc5c45db58e4e5213693894e9b8cd7650aff816e92ab3aa134abe1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The abandoned ally named his own tribe's raiders for destruction. Lok's skull reached Thork without the explanation Mangletooth expected the Horde to doubt; the prisoner remained in his cage."}},["grouping"]="Authored connected episodes with explicit source-stage gates; branches retained",["quests"]={878,5052,879,906},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="Help From the Cage"},["barrens-samophlange-repair"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=894,["sourceHash"]="512d640a04d23a32695c5547dd2ca7440998d9528de7bf508d038e43491351e0"},{["minimumStage"]=4,["questID"]=900,["sourceHash"]="d12aabdd3cefd128a9692748aec31dbd54456c1422180a51ae5a247aa69cd753"},{["minimumStage"]=4,["questID"]=901,["sourceHash"]="eb92b37fd87de5b6d449950dab54e0878aa92e1e90f9ae1edce65560ffe31709"},{["minimumStage"]=4,["questID"]=902,["sourceHash"]="9ed8e95795fe955aa32d8066aa57bf7c8c7142ea057eee4f6ca94d77e6b5c2df"},{["minimumStage"]=4,["questID"]=3921,["sourceHash"]="1ed38bb87f58a6881af0add9b552a82b99167ebfdf096fe1a86d239aee76d431"},{["minimumStage"]=4,["questID"]=3922,["sourceHash"]="f2b999117306d6b657165cbf5b4d31f32179ca3ade5e4f2598dc533915dc7790"},{["minimumStage"]=4,["questID"]=3923,["sourceHash"]="b15fb750102c051f0b136a583cfeb740003f5166cd97ac2a1176b5d27712bc85"},{["minimumStage"]=4,["questID"]=3924,["sourceHash"]="db209163cb3dfc29c483b9d5a83cb86a787b65bf3a9ab4a18e46e407e2cec1d2"}}},["interpretation"]="Every required route step needs its own recorded hand-in and exact source hash. Optional or alternative branches retain their separate rules.",["scope"]="DEFINED_OBSERVED_ROUTE_NOT_WORLD_VICTORY"},["episodes"]={{["episodeID"]="barrens-samophlange-repair-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=894}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"894:description:1-107","894:description:109-249","894:description:254-288","894:description:290-364","894:description:369-502","894:objective:1-64"},["questID"]=894,["sourceHash"]="512d640a04d23a32695c5547dd2ca7440998d9528de7bf508d038e43491351e0",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A Venture Company experiment drew Sputtervalve's interest north of Ratchet. He knew its name and had obtained a copied manual; the research apparatus itself still had to be reached."},{["episodeID"]="barrens-samophlange-repair-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=900}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"900:description:1-46","900:description:48-173","900:objective:1-116"},["questID"]=900,["sourceHash"]="d12aabdd3cefd128a9692748aec31dbd54456c1422180a51ae5a247aa69cd753",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="At the console, three open valves kept the apparatus running. Fuel, regulator and main controls had to be closed before the machinery could be stopped."},{["episodeID"]="barrens-samophlange-repair-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=901}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"901:description:1-112","901:description:114-205","901:objective:1-73"},["questID"]=901,["sourceHash"]="eb92b37fd87de5b6d449950dab54e0878aa92e1e90f9ae1edce65560ffe31709",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Stopping the apparatus left another obstacle: the locked panel. Sniggles held the key to the mechanism within."},{["episodeID"]="barrens-samophlange-repair-4",["requiresAll"]={{["minimumStage"]=2,["questID"]=902}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"902:description:1-172","902:description:174-254","902:description:256-289","902:objective:1-50"},["questID"]=902,["sourceHash"]="9ed8e95795fe955aa32d8066aa57bf7c8c7142ea057eee4f6ca94d77e6b5c2df",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Beyond the panel lay wires, tubing and the device Sputtervalve wanted. Removing the samophlange would carry the company's experiment back to Ratchet."},{["episodeID"]="barrens-samophlange-repair-5",["requiresAll"]={{["minimumStage"]=2,["questID"]=3921}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"3921:description:1-45","3921:description:48-154","3921:description:157-185","3921:description:190-324","3921:description:327-361","3921:description:364-436","3921:objective:1-51"},["questID"]=3921,["sourceHash"]="1ed38bb87f58a6881af0add9b552a82b99167ebfdf096fe1a86d239aee76d431",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Sputtervalve's excitement had outpaced his care for the machine. Believing he had broken it, he turned to Wenikee Boltbucket for a repair."},{["episodeID"]="barrens-samophlange-repair-6",["requiresAll"]={{["minimumStage"]=2,["questID"]=3922}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"3922:description:1-79","3922:description:82-192","3922:description:197-256","3922:description:259-319","3922:description:322-446","3922:objective:1-59"},["questID"]=3922,["sourceHash"]="f2b999117306d6b657165cbf5b4d31f32179ca3ade5e4f2598dc533915dc7790",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Wenikee needed a particular gauge of nugget slugs. The company's tool buckets in the Sludge Fen offered a nearby source for parts."},{["episodeID"]="barrens-samophlange-repair-7",["requiresAll"]={{["minimumStage"]=2,["questID"]=3923}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"3923:description:1-23","3923:description:26-152","3923:description:155-232","3923:description:234-275","3923:description:280-330","3923:description:333-417","3923:description:422-498","3923:objective:1-74"},["questID"]=3923,["sourceHash"]="b15fb750102c051f0b136a583cfeb740003f5166cd97ac2a1176b5d27712bc85",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The added gauges revealed how poorly the samophlange was faring. Wenikee stopped altering it and recommended Rilli Greasygob, whose company experience might be more useful."},{["episodeID"]="barrens-samophlange-repair-8",["requiresAll"]={{["minimumStage"]=4,["questID"]=3924}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"3924:description:1-81","3924:description:84-262","3924:description:265-298","3924:description:303-380","3924:description:383-482","3924:objective:1-61","3924:completion:1-19","3924:completion:21-84","3924:completion:86-195","3924:completion:200-279"},["questID"]=3924,["sourceHash"]="db209163cb3dfc29c483b9d5a83cb86a787b65bf3a9ab4a18e46e407e2cec1d2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Rilli received the recovered manual and was eager to study the machine's secrets. The means of attempting a repair were at hand; a successful repair was still to come."}},["grouping"]="Source-reviewed continuing narrative; branch and source-stage gates retained.",["quests"]={894,900,901,902,3921,3922,3923,3924},["referenceStatus"]="RETAINED_QUEST_SOURCE_STAGES_NOT_CURRENT_PLAYABILITY_VERIFICATION",["sourceConflict"]=false,["title"]="The Troublesome Machine"},["barrens-witchwing-serena"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=867,["sourceHash"]="d2e5aef25236e12e33954c5eb13e4e164631100c95ebee7b4f33790c657a0b72"},{["minimumStage"]=4,["questID"]=875,["sourceHash"]="3a71ea03d3d77662114444a57dbf248acaa7cff9dd4457bef23dbd9f8214a0de"},{["minimumStage"]=4,["questID"]=876,["sourceHash"]="9a71bbfb0cef25c45d97f3db47ab26a22888a7bb8535bf386f356a121fc42ee6"},{["minimumStage"]=4,["questID"]=1060,["sourceHash"]="4fb608662e29848deec14a3c2ddf4ab856cb1b6aeb424f14a11a4f06335d46ef"}}},["interpretation"]="Every required route step needs its own recorded hand-in and exact source hash. Optional or alternative branches retain their separate rules.",["scope"]="DEFINED_OBSERVED_ROUTE_NOT_WORLD_VICTORY"},["episodes"]={{["episodeID"]="barrens-witchwing-serena-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=867}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"867:description:1-73","867:description:75-144","867:description:149-216","867:description:218-345","867:description:350-478","867:description:480-509","867:objective:1-27","867:objective:32-83"},["questID"]=867,["sourceHash"]="d2e5aef25236e12e33954c5eb13e4e164631100c95ebee7b4f33790c657a0b72",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Repeated Witchwing raids had made the caravan road dangerous. Darsok began with the harpies' lower ranks, intending to work upward through their hierarchy."},{["episodeID"]="barrens-witchwing-serena-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=875}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"875:description:1-11","875:description:13-26","875:description:28-53","875:description:58-140","875:description:142-236","875:description:238-311","875:description:313-384","875:description:389-421","875:description:423-502","875:objective:1-112"},["questID"]=875,["sourceHash"]="3a71ea03d3d77662114444a57dbf248acaa7cff9dd4457bef23dbd9f8214a0de",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The campaign next reached the command ranks in the Dry Hills. Rings would identify the Witchwing Slayers serving as lieutenants."},{["episodeID"]="barrens-witchwing-serena-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=876}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"876:description:1-98","876:description:103-208","876:description:210-292","876:description:297-353","876:description:355-407","876:description:409-452","876:objective:1-85"},["questID"]=876,["sourceHash"]="9a71bbfb0cef25c45d97f3db47ab26a22888a7bb8535bf386f356a121fc42ee6",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Darsok attributed the raids to Serena Bloodfeather's revenge for her sister. He wanted the leader confronted and proof brought back as a warning to later raiders."},{["episodeID"]="barrens-witchwing-serena-4",["requiresAll"]={{["minimumStage"]=4,["questID"]=1060}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1060:description:1-31","1060:description:33-109","1060:description:114-157","1060:description:159-229","1060:description:231-388","1060:description:393-505","1060:objective:1-80","1060:completion:1-26","1060:completion:28-67","1060:completion:72-117","1060:completion:119-231","1060:completion:233-264"},["questID"]=1060,["sourceHash"]="4fb608662e29848deec14a3c2ddf4ab856cb1b6aeb424f14a11a4f06335d46ef",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The news reached Jin'Zil in Stonetalon. His recollection of Rokhan's earlier part in the elder Bloodfeather's death connected the Barrens fighting to an older grievance."}},["grouping"]="Source-reviewed continuing narrative; branch and source-stage gates retained.",["quests"]={867,875,876,1060},["referenceStatus"]="RETAINED_QUEST_SOURCE_STAGES_NOT_CURRENT_PLAYABILITY_VERIFICATION",["sourceConflict"]=false,["title"]="Talons Above the Caravan Road"},["beggars-haunt-serum-and-silence"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=1372,["sourceHash"]="1d6085f51cc1d81b46f95e76ad879acfb533cb30fbf90003402cbe6bdc7f03fd"},{["minimumStage"]=4,["questID"]=1383,["sourceHash"]="0fecf4725a0802a60f04c94818564d91c71e0370dee02e7961541a2aa0cc1d51"},{["minimumStage"]=4,["questID"]=1388,["sourceHash"]="8334a2c98ca94c283b3e14246d291fca8f4c616e3d2045f40ebc169c7d9172ba"},{["minimumStage"]=4,["questID"]=1391,["sourceHash"]="dab9118f8103fa446fab2813c9ea7a4b01f16accf67e49e84af967099f1589cd"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="beggars-haunt-serum-and-silence-1372",["requiresAll"]={{["minimumStage"]=2,["questID"]=1372}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"1372:description:1-81","1372:description:86-159","1372:description:161-211","1372:description:213-223","1372:description:225-299","1372:description:304-315","1372:description:317-323","1372:description:325-342","1372:description:344-412","1372:description:417-454","1372:description:456-493","1372:objective:1-48"},["questID"]=1372,["sourceHash"]="1d6085f51cc1d81b46f95e76ad879acfb533cb30fbf90003402cbe6bdc7f03fd",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="An infiltrator had been watching Beggar’s Haunt before orcs took him prisoner in Stonard. Zraedus offered his allies help extracting information, but his hesitations made the proposed truth serum an uneasy kind of assistance."},{["episodeID"]="beggars-haunt-serum-and-silence-1383",["requiresAll"]={{["minimumStage"]=2,["questID"]=1383}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1383:description:1-36","1383:description:38-117","1383:description:122-198","1383:description:200-274","1383:description:276-344","1383:description:349-425","1383:description:427-484","1383:description:489-504","1383:objective:1-110"},["questID"]=1383,["sourceHash"]="0fecf4725a0802a60f04c94818564d91c71e0370dee02e7961541a2aa0cc1d51",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Faustin’s preparation demanded hearts from the swamp, fungus from the Mire Lord and a rare tumor from Desolace’s giants. The ingredients drew the errand far beyond the prisoner’s cell, while the apothecary spoke evasively about what his concoction would do."},{["episodeID"]="beggars-haunt-serum-and-silence-1388",["requiresAll"]={{["minimumStage"]=4,["questID"]=1388}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1388:description:1-47","1388:description:49-151","1388:description:153-161","1388:description:166-170","1388:objective:1-69","1388:completion:1-53","1388:completion:55-91","1388:completion:96-136"},["questID"]=1388,["sourceHash"]="8334a2c98ca94c283b3e14246d291fca8f4c616e3d2045f40ebc169c7d9172ba",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The finished mixture passed back to Zraedus. Faustin’s nearly spoken admission gave way to another insistence that it was only a serum, leaving the arrangement wrapped in deliberate secrecy."},{["episodeID"]="beggars-haunt-serum-and-silence-1391",["requiresAll"]={{["minimumStage"]=4,["questID"]=1391}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1391:description:1-55","1391:description:57-176","1391:description:181-245","1391:description:247-297","1391:description:299-386","1391:description:391-440","1391:description:442-486","1391:objective:1-54","1391:completion:1-15","1391:completion:17-25","1391:completion:27-75","1391:completion:77-143"},["questID"]=1391,["sourceHash"]="dab9118f8103fa446fab2813c9ea7a4b01f16accf67e49e84af967099f1589cd",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Zraedus mixed the draught into ale, counting on the prisoner’s thirst to overcome suspicion. Marksen accepted the drink in Stonard and promised to speak afterward. The recorded exchange ends there; it supplies neither his testimony nor proof of what the mixture ultimately did."}},["grouping"]="Four stages follow Faustin and Zraedus’s concealed purpose. The retained ending proves acceptance of the drink, not a confession or death.",["quests"]={1372,1383,1388,1391},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Price of an Answer"},["blackrock-bijou-reconnaissance"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=4981,["sourceHash"]="27fe44c7412578b6132450c84ea1ca012c83c84f787861ed90219e79a12b6f17"},{["minimumStage"]=4,["questID"]=4982,["sourceHash"]="866c1e2b10e101c9baba9018a8b785fc27e5e9a15cb93cc4ed4947b48f20d8c0"},{["minimumStage"]=4,["questID"]=4983,["sourceHash"]="675d7b2061b62d6f823b4d8e4ac62d4d1b0203fd3297d92d5f3ae3c5e5109bb4"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="blackrock-bijou-reconnaissance-4981",["requiresAll"]={{["minimumStage"]=2,["questID"]=4981}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"4981:description:1-21","4981:description:23-55","4981:description:60-113","4981:description:115-242","4981:description:244-306","4981:description:311-345","4981:description:350-392","4981:description:394-421","4981:description:426-463","4981:objective:1-62"},["questID"]=4981,["sourceHash"]="27fe44c7412578b6132450c84ea1ca012c83c84f787861ed90219e79a12b6f17",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Lexlort wanted Bijou brought back alive, accusing her of taking Horde funds while working for an exotic-pet dealer. Her disappearance into Blackrock Spire promised either a missing operative or another explanation to unravel."},{["episodeID"]="blackrock-bijou-reconnaissance-4982",["requiresAll"]={{["minimumStage"]=2,["questID"]=4982}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"4982:description:1-166","4982:description:171-220","4982:description:222-271","4982:description:273-314","4982:description:316-360","4982:description:362-404","4982:description:406-434","4982:description:439-490","4982:description:492-502","4982:objective:1-47","4982:objective:49-128"},["questID"]=4982,["sourceHash"]="866c1e2b10e101c9baba9018a8b785fc27e5e9a15cb93cc4ed4947b48f20d8c0",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Bijou claimed a tripwire had ruined a night of reconnaissance. The gear she hid while escaping contained intelligence valuable enough to change the reception awaiting her in Kargath."},{["episodeID"]="blackrock-bijou-reconnaissance-4983",["requiresAll"]={{["minimumStage"]=4,["questID"]=4983}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"4983:description:1-33","4983:description:35-93","4983:description:95-143","4983:description:148-161","4983:description:163-195","4983:description:197-251","4983:objective:1-74","4983:completion:1-92","4983:completion:94-175","4983:completion:180-230"},["questID"]=4983,["sourceHash"]="675d7b2061b62d6f823b4d8e4ac62d4d1b0203fd3297d92d5f3ae3c5e5109bb4",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The recovered report reached Lexlort while Bijou stayed behind to work. He conceded its strategic value and recognized that she had escaped another predicament, resolving the mission through information rather than an escorted prisoner."}},["grouping"]="One intelligence recovery; Bijou's defense is attributed and her return in custody is not fabricated.",["quests"]={4981,4982,4983},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="An Operative’s Way Out"},["blackrock-doomrigger-museum"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=4766,["sourceHash"]="4982204e67f6a999914831f412c903afffb34e98adb4d99ba2f32d99cc1ebe89"},{["minimumStage"]=4,["questID"]=4764,["sourceHash"]="999b37deffa1731cce5ec320f350918422fd98a89a381acdda6b39991b5e8b94"},{["minimumStage"]=4,["questID"]=4765,["sourceHash"]="0d80cf62d01233ce9b8357605fd38d22591043dbd2121758cf8a18f5115981af"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="blackrock-doomrigger-museum-4766",["requiresAll"]={{["minimumStage"]=2,["questID"]=4766}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"4766:description:1-108","4766:description:111-189","4766:description:191-243","4766:description:248-343","4766:description:346-400","4766:description:405-495","4766:objective:1-52"},["questID"]=4766,["sourceHash"]="4982204e67f6a999914831f412c903afffb34e98adb4d99ba2f32d99cc1ebe89",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Remington's search for additions to his family museum had sent Mayara to Thaurissan. What she found pointed instead into Blackrock Spire, where retrieving an old work of art would require further help."},{["episodeID"]="blackrock-doomrigger-museum-4764",["requiresAll"]={{["minimumStage"]=2,["questID"]=4764}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"4764:description:1-86","4764:description:89-170","4764:description:175-192","4764:description:195-250","4764:description:252-269","4764:description:272-334","4764:description:339-477","4764:description:482-510","4764:objective:1-69"},["questID"]=4764,["sourceHash"]="999b37deffa1731cce5ec320f350918422fd98a89a381acdda6b39991b5e8b94",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Mayara named Doomrigger's Clasp as the prize. The old Hall of Fortune had once held Dark Iron treasures, and she believed the ruined chamber might still conceal the gem-encrusted relic."},{["episodeID"]="blackrock-doomrigger-museum-4765",["requiresAll"]={{["minimumStage"]=4,["questID"]=4765}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"4765:description:1-83","4765:description:86-157","4765:description:162-208","4765:description:211-253","4765:description:256-316","4765:objective:1-60","4765:completion:1-18","4765:completion:20-42","4765:completion:44-49","4765:completion:51-79","4765:completion:81-161"},["questID"]=4765,["sourceHash"]="0d80cf62d01233ce9b8357605fd38d22591043dbd2121758cf8a18f5115981af",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The clasp reached Ridgewell in a crate prepared for its journey to Stormwind. The noble offered his thanks, bringing the object's recovery to its intended end in the family's collection."}},["grouping"]="A patron’s referral, one recovered relic and its shipment to Stormwind; rumors about the ruined hall remain qualified.",["quests"]={4766,4764,4765},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Clasp for the Family Museum"},["blackrock-moira-alliance"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=4341,["sourceHash"]="e54bd9e1f2b6975920d8a97bc84a44391fb519de4120846d67f8d91e7b3342b1"},{["minimumStage"]=4,["questID"]=4361,["sourceHash"]="d3fee9c3c29d12befc46810373a48dd7d29e049a5c06677a1f0b9a119d2523d7"},{["minimumStage"]=4,["questID"]=4362,["sourceHash"]="b13a72c1dfed8c6fd3440e9f0bff1ca5a8c8868aa2f89f357185979dbc5eb9bb"},{["minimumStage"]=4,["questID"]=4363,["sourceHash"]="d7b6ba42dc2c20e9553b99bf06822fad491603cc561ed6f4e0eef78616a5fc69"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="blackrock-moira-alliance-4341",["requiresAll"]={{["minimumStage"]=2,["questID"]=4341}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"4341:description:1-52","4341:description:54-120","4341:description:122-178","4341:description:183-198","4341:description:203-225","4341:description:230-276","4341:description:278-375","4341:description:377-410","4341:description:415-463","4341:description:465-473","4341:description:475-489","4341:objective:1-55","4341:objective:60-166"},["questID"]=4341,["sourceHash"]="e54bd9e1f2b6975920d8a97bc84a44391fb519de4120846d67f8d91e7b3342b1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Magni's search had found no certain answer about his missing daughter. Kharan's reported imprisonment offered someone who might know her fate, drawing the inquiry into Blackrock Depths."},{["episodeID"]="blackrock-moira-alliance-4361",["requiresAll"]={{["minimumStage"]=2,["questID"]=4361}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"4361:description:1-54","4361:description:56-79","4361:objective:1-71"},["questID"]=4361,["sourceHash"]="d3fee9c3c29d12befc46810373a48dd7d29e049a5c06677a1f0b9a119d2523d7",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Whatever answer had been found now belonged before the king. The report would let Magni decide the next step; the messenger could not resolve his daughter's fate from a distance."},{["episodeID"]="blackrock-moira-alliance-4362",["requiresAll"]={{["minimumStage"]=2,["questID"]=4362}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"4362:description:1-106","4362:description:111-138","4362:description:140-179","4362:description:184-282","4362:description:287-310","4362:description:312-359","4362:description:361-429","4362:objective:1-117"},["questID"]=4362,["sourceHash"]="b13a72c1dfed8c6fd3440e9f0bff1ca5a8c8868aa2f89f357185979dbc5eb9bb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Magni believed his old enemy controlled Moira through an enchantment. His order demanded Thaurissan's death but forbade harm to the princess, however she might behave during the rescue."},{["episodeID"]="blackrock-moira-alliance-4363",["requiresAll"]={{["minimumStage"]=4,["questID"]=4363}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"4363:description:1-43","4363:description:45-95","4363:description:100-208","4363:description:213-319","4363:description:324-363","4363:objective:1-58","4363:completion:1-42","4363:completion:47-94","4363:completion:99-120","4363:completion:122-187","4363:completion:192-276"},["questID"]=4363,["sourceHash"]="d7b6ba42dc2c20e9553b99bf06822fad491603cc561ed6f4e0eef78616a5fc69",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Moira's answer defied the rescue's assumptions. She defended her husband and announced their unborn Dark Iron heir. To Magni, the news made Thaurissan victorious even in death, leaving grief entwined with Ironforge's succession."}},["grouping"]="The four-step retained rescue route; Kharan's missing gossip is not reconstructed, and Moira's marriage is not revealed before her message.",["quests"]={4341,4361,4362,4363},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Father’s Rescue, a Daughter’s Answer"},["blackrock-moira-horde"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=3981,["sourceHash"]="ebb128a8947432b6cf19df35ada98da5fd1a870cafd3c603f9f751918b972aa2"},{["minimumStage"]=4,["questID"]=3982,["sourceHash"]="45ff6dacc7a990dfed455ed316db5d521eed92b570ae1459537d43164808ad75"},{["minimumStage"]=4,["questID"]=4001,["sourceHash"]="9dbb9d5e1f39086a8eb75345c7462ce43e9e4b3041b5d18d5298ffa97ca26780"},{["minimumStage"]=4,["questID"]=4002,["sourceHash"]="7360d448f0da71b9677de1a326c0f9200f6784047ae8223fe559e9152016ff44"},{["minimumStage"]=4,["questID"]=4003,["sourceHash"]="19ba92ba9ad4c207bf05686434d195f1ae101d1e1b5e40a490a87d0d589ad075"},{["minimumStage"]=4,["questID"]=4004,["sourceHash"]="a6d3fb649717b4b1f61e206ccf50c85b518b12e59c38360a757857a38d526011"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="blackrock-moira-horde-3981",["requiresAll"]={{["minimumStage"]=2,["questID"]=3981}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"3981:description:1-14","3981:description:16-41","3981:description:43-47","3981:description:49-100","3981:description:102-135","3981:description:140-158","3981:description:163-241","3981:description:243-354","3981:description:359-417","3981:description:422-436","3981:description:438-466","3981:description:468-491","3981:objective:1-44","3981:objective:49-139","3981:objective:141-192"},["questID"]=3981,["sourceHash"]="ebb128a8947432b6cf19df35ada98da5fd1a870cafd3c603f9f751918b972aa2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A prisoner's drawing reached Kargath on an arrow. Galamav suspected deception, yet Gor'shak's signature made the message too important to dismiss without searching Blackrock's cells."},{["episodeID"]="blackrock-moira-horde-3982",["requiresAll"]={{["minimumStage"]=2,["questID"]=3982}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"3982:description:1-45","3982:description:47-100","3982:description:102-169","3982:description:174-193","3982:description:198-264","3982:description:266-307","3982:description:309-371","3982:description:376-393","3982:description:398-402","3982:description:404-420","3982:description:422-435","3982:description:437-452","3982:objective:1-16"},["questID"]=3982,["sourceHash"]="45ff6dacc7a990dfed455ed316db5d521eed92b570ae1459537d43164808ad75",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Gor'shak claimed his capture had been arranged for Thrall's intelligence work. His whispered news concerned Ironforge's missing princess, but approaching guards broke off the account and forced an immediate defense."},{["episodeID"]="blackrock-moira-horde-4001",["requiresAll"]={{["minimumStage"]=2,["questID"]=4001}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"4001:description:1-95","4001:description:97-174","4001:description:179-274","4001:description:276-318","4001:description:323-461","4001:description:463-497","4001:objective:1-99","4001:objective:101-145","4001:objective:150-223"},["questID"]=4001,["sourceHash"]="9dbb9d5e1f39086a8eb75345c7462ce43e9e4b3041b5d18d5298ffa97ca26780",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Kharan, held across the hall, could explain more about Moira. Returning that knowledge to Thrall offered a way to make one captive's safe return serve a larger hope of diplomacy."},{["episodeID"]="blackrock-moira-horde-4002",["requiresAll"]={{["minimumStage"]=2,["questID"]=4002}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"4002:description:1-36","4002:description:41-100","4002:description:102-192","4002:description:197-278","4002:description:280-373","4002:description:375-411","4002:description:416-432","4002:objective:1-76"},["questID"]=4002,["sourceHash"]="7360d448f0da71b9677de1a326c0f9200f6784047ae8223fe559e9152016ff44",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Thrall saw a chance to spare future generations another hopeless war. Aid to the dwarves was to become an opening for alliances, giving the rescue a purpose beyond the prison walls."},{["episodeID"]="blackrock-moira-horde-4003",["requiresAll"]={{["minimumStage"]=2,["questID"]=4003}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"4003:description:1-112","4003:description:117-180","4003:description:182-220","4003:description:222-350","4003:description:355-370","4003:objective:1-87"},["questID"]=4003,["sourceHash"]="19ba92ba9ad4c207bf05686434d195f1ae101d1e1b5e40a490a87d0d589ad075",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The plan depended on Thrall's belief that Thaurissan had enchanted Moira. The emperor was to die, but the princess must survive even if she resisted those who had come to free her."},{["episodeID"]="blackrock-moira-horde-4004",["requiresAll"]={{["minimumStage"]=4,["questID"]=4004}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"4004:description:1-30","4004:description:32-86","4004:description:91-130","4004:description:135-210","4004:description:212-294","4004:description:299-394","4004:description:399-414","4004:description:416-492","4004:objective:1-17","4004:completion:1-69","4004:completion:74-111","4004:completion:113-222","4004:completion:227-304","4004:completion:309-325","4004:completion:327-365"},["questID"]=4004,["sourceHash"]="a6d3fb649717b4b1f61e206ccf50c85b518b12e59c38360a757857a38d526011",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Moira named the slain emperor as her husband and their unborn child as Ironforge's future heir. Thrall's intended act of diplomacy had acquired a meaning he had never planned; he withdrew to consult Cairne and Sylvanas."}},["grouping"]="The recorded Horde mission concerning Moira; magical control remains the planners' belief, not an objective diagnosis.",["quests"]={3981,3982,4001,4002,4003,4004},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Rescue That Changed Its Meaning"},["blackrock-windsor-recovered-evidence"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=4241,["sourceHash"]="e296e93ebc42510c3092bf2ed0677dc4742cb51f0bdf701d9cecd722ad2abdd8"},{["minimumStage"]=4,["questID"]=4242,["sourceHash"]="979a1796e11d8912251c00cebee0ee127f184a4d01dc5027e3a7dad4f89be8ad"},{["minimumStage"]=4,["questID"]=4264,["sourceHash"]="6c6d444a9ce7cf4164154cc6aff35e08893c7b532cbb8b5cc431d6c9ac5917b9"},{["minimumStage"]=4,["questID"]=4282,["sourceHash"]="0646bdd218397b8f280c22bdbe289f74dab7e6353bd9ae3914b97d9322dbbe11"},{["minimumStage"]=4,["questID"]=4322,["sourceHash"]="06e3c5ae668fb6cfb80072e4b1c57332f80b175ff1db11f8af900a0e9e98b0f7"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="blackrock-windsor-recovered-evidence-4241",["requiresAll"]={{["minimumStage"]=2,["questID"]=4241}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"4241:description:1-63","4241:description:68-113","4241:description:115-161","4241:description:163-189","4241:description:194-210","4241:description:215-270","4241:objective:1-73","4241:objective:75-114","4241:objective:119-193"},["questID"]=4241,["sourceHash"]="e296e93ebc42510c3092bf2ed0677dc4742cb51f0bdf701d9cecd722ad2abdd8",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Ragged John's report raised the hope that Windsor still lived. Maxwell's search allowed for either a rescue or proof of death, sending the inquiry into the Depths' prison."},{["episodeID"]="blackrock-windsor-recovered-evidence-4242",["requiresAll"]={{["minimumStage"]=2,["questID"]=4242}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"4242:description:1-17","4242:description:19-96","4242:description:101-122","4242:description:124-179","4242:description:184-209","4242:description:211-215","4242:description:217-230","4242:description:235-379","4242:description:384-396","4242:objective:1-34"},["questID"]=4242,["sourceHash"]="979a1796e11d8912251c00cebee0ee127f184a4d01dc5027e3a7dad4f89be8ad",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Windsor's anger centered on evidence he had gathered for Bolvar and lost. His bitter account reached Maxwell as an apparent dead end, leaving the marshal's accusations without the proof he needed."},{["episodeID"]="blackrock-windsor-recovered-evidence-4264",["requiresAll"]={{["minimumStage"]=2,["questID"]=4264}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"4264:description:1-41","4264:description:43-101","4264:description:106-122","4264:description:127-163","4264:description:168-282","4264:description:287-353","4264:description:358-420","4264:description:425-451","4264:objective:1-94","4264:objective:96-124"},["questID"]=4264,["sourceHash"]="6c6d444a9ce7cf4164154cc6aff35e08893c7b532cbb8b5cc431d6c9ac5917b9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A stained note changed the inquiry. Angerforge and Argelmach were deciphering Windsor's information, suggesting that the material had survived in his enemies' hands."},{["episodeID"]="blackrock-windsor-recovered-evidence-4282",["requiresAll"]={{["minimumStage"]=2,["questID"]=4282}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"4282:description:1-44","4282:description:49-83","4282:description:88-111","4282:description:113-244","4282:description:246-326","4282:description:331-361","4282:description:366-407","4282:description:409-452","4282:objective:1-42","4282:objective:47-153"},["questID"]=4282,["sourceHash"]="0646bdd218397b8f280c22bdbe289f74dab7e6353bd9ae3914b97d9322dbbe11",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Hope returned with a concrete target: recover the lost information from the two Dark Iron leaders. The search was no longer only for a prisoner, but for the evidence he could carry out."},{["episodeID"]="blackrock-windsor-recovered-evidence-4322",["requiresAll"]={{["minimumStage"]=4,["questID"]=4322}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"4322:description:1-31","4322:description:33-98","4322:description:100-194","4322:description:196-232","4322:objective:1-60","4322:objective:62-102","4322:completion:1-12","4322:completion:14-28","4322:completion:30-79","4322:completion:81-160","4322:completion:162-221","4322:completion:223-235"},["questID"]=4322,["sourceHash"]="06e3c5ae668fb6cfb80072e4b1c57332f80b175ff1db11f8af900a0e9e98b0f7",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Windsor's equipment and imprisoned friends had to be recovered before the escape. By the time Maxwell heard the report, the marshal had already passed through toward Stormwind with his evidence. The prison story ended at the threshold of a confrontation still ahead."}},["grouping"]="Windsor's prison recovery and escape, not the conclusion of the later Stormwind confrontation.",["quests"]={4241,4242,4264,4282,4322},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Evidence Behind the Prison Bars"},["darkshore-asterion-moonstone"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=954,["sourceHash"]="5567879d8ba64e634932ed384e7a7bf9807db8ff50f25ebf546ad627fc48c0e3"},{["minimumStage"]=4,["questID"]=955,["sourceHash"]="1a0170ccbb423e2e56c02d1c03167080405737f1d7e03bdab81e2b9f1a7d4cc6"},{["minimumStage"]=4,["questID"]=956,["sourceHash"]="bd5265c78a8d6a94de647f8520ac62ed0d966fd3ea90a511ca1e08f151088c13"},{["minimumStage"]=4,["questID"]=957,["sourceHash"]="c762bbd20452d4836b2705736e8a17ae2f8a7ceca131b94fbe60628591c954c8"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="darkshore-asterion-moonstone-954",["requiresAll"]={{["minimumStage"]=2,["questID"]=954}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"954:description:1-70","954:description:72-224","954:description:229-307","954:description:309-394","954:description:396-450","954:description:455-489","954:objective:1-69"},["questID"]=954,["sourceHash"]="5567879d8ba64e634932ed384e7a7bf9807db8ff50f25ebf546ad627fc48c0e3",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Demons fed upon Bashal'Aran's lingering magic, yet avoided one shrine. The blue light around it gave Thundris a question more troubling than the infestation itself."},{["episodeID"]="darkshore-asterion-moonstone-955",["requiresAll"]={{["minimumStage"]=2,["questID"]=955}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"955:description:1-103","955:description:105-218","955:description:223-259","955:description:261-400","955:description:402-501","955:objective:1-53"},["questID"]=955,["sourceHash"]="1a0170ccbb423e2e56c02d1c03167080405737f1d7e03bdab81e2b9f1a7d4cc6",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The light concealed a prisoner rather than a refuge. Asterion's spectral existence had become torment, and traces upon the grells' earrings might reveal the seal that bound him."},{["episodeID"]="darkshore-asterion-moonstone-956",["requiresAll"]={{["minimumStage"]=2,["questID"]=956}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"956:description:1-114","956:description:116-190","956:description:195-237","956:description:239-278","956:description:280-395","956:objective:1-74"},["questID"]=956,["sourceHash"]="bd5265c78a8d6a94de647f8520ac62ed0d966fd3ea90a511ca1e08f151088c13",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The trail passed from the grell to their satyr leaders. Asterion believed one held the moonstone seal, turning the search for a magical trace into the recovery of a tangible key."},{["episodeID"]="darkshore-asterion-moonstone-957",["requiresAll"]={{["minimumStage"]=4,["questID"]=957}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"957:description:1-106","957:description:108-221","957:description:223-265","957:description:270-296","957:objective:1-110","957:completion:1-15","957:completion:17-89","957:completion:91-124","957:completion:126-248","957:completion:253-318","957:completion:320-396"},["questID"]=957,["sourceHash"]="c762bbd20452d4836b2705736e8a17ae2f8a7ceca131b94fbe60628591c954c8",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The ancient flame in Ameth'Aran destroyed the seal. Freed at last, Asterion remembered a world where Azshara still held court; hope already mingled with vengeance against his former master. His freedom did not settle that older betrayal."}},["grouping"]="One release from an ancient magical prison; the later confrontation with Athrikus is a separate story.",["quests"]={954,955,956,957},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Prison Beneath the Blue Light"},["darkshore-onu-cult-investigation"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=947,["sourceHash"]="b50ced2e576c0bacb7e405c54329de95f23989f617f041ea8298134a157d5cb1"},{["minimumStage"]=4,["questID"]=948,["sourceHash"]="5bb8d121a8b54faf4f1aa9ac94c25e63b45636a9a2fc3733e0d58c47c08ddf08"},{["minimumStage"]=4,["questID"]=944,["sourceHash"]="43b6e97bdb0c66c2f11c9040830dcdda01da183b6b3644e90dc6b8cea495cb9e"},{["minimumStage"]=4,["questID"]=949,["sourceHash"]="484d6dc8a257c00e253213666d7452d6858873c6c75e7ae7ab5b60a5b4456521"},{["minimumStage"]=4,["questID"]=950,["sourceHash"]="e3524e10ac451ec7651beeef4200c4df3f579f58cd255fc5c09eb44a6d81d17e"},{["minimumStage"]=4,["questID"]=951,["sourceHash"]="3c56ec6118af122803d2f336579a713db1b2422b4baa26f8f0abde0207b46235"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="darkshore-onu-cult-investigation-947",["requiresAll"]={{["minimumStage"]=2,["questID"]=947}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"947:description:1-96","947:description:99-189","947:description:194-294","947:description:297-385","947:description:390-429","947:description:432-497","947:objective:1-74"},["questID"]=947,["sourceHash"]="b50ced2e576c0bacb7e405c54329de95f23989f617f041ea8298134a157d5cb1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Barithras's potion needed mushrooms from the cave behind Cliffspring Falls, but the Ancients warned of a new evil within. Gathering the plants would also test that warning."},{["episodeID"]="darkshore-onu-cult-investigation-948",["requiresAll"]={{["minimumStage"]=2,["questID"]=948}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"948:description:1-125","948:description:128-183","948:description:188-225","948:description:228-320","948:objective:1-44"},["questID"]=948,["sourceHash"]="5bb8d121a8b54faf4f1aa9ac94c25e63b45636a9a2fc3733e0d58c47c08ddf08",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Onu wished to hear what had been found. The summons carried the matter south to the Grove of the Ancients, where a patient guardian's urgency lent the discovery greater weight."},{["episodeID"]="darkshore-onu-cult-investigation-944",["requiresAll"]={{["minimumStage"]=2,["questID"]=944}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"944:description:1-51","944:description:54-100","944:description:103-153","944:description:156-179","944:description:184-257","944:description:262-315","944:description:320-346","944:description:349-416","944:description:419-452","944:objective:1-75","944:objective:78-108"},["questID"]=944,["sourceHash"]="43b6e97bdb0c66c2f11c9040830dcdda01da183b6b3644e90dc6b8cea495cb9e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The naga were troubling enough; the Twilight's Hammer concerned Onu more. Their worship of defeated lords of the earth drew his attention to the ancient remains beneath the Master's Glaive."},{["episodeID"]="darkshore-onu-cult-investigation-949",["requiresAll"]={{["minimumStage"]=2,["questID"]=949}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"949:description:1-68","949:description:71-90","949:description:95-136","949:description:138-194","949:description:199-255","949:objective:1-65"},["questID"]=949,["sourceHash"]="484d6dc8a257c00e253213666d7452d6858873c6c75e7ae7ab5b60a5b4456521",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The cult's presence alone did not explain its purpose. Onu asked for a clue within the camp, keeping the inquiry grounded in what could be recovered rather than guessing at its rites."},{["episodeID"]="darkshore-onu-cult-investigation-950",["requiresAll"]={{["minimumStage"]=2,["questID"]=950}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"950:description:1-44","950:description:47-165","950:description:170-264","950:objective:1-41"},["questID"]=950,["sourceHash"]="e3524e10ac451ec7651beeef4200c4df3f579f58cd255fc5c09eb44a6d81d17e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The discovered tome resisted study: its lettering swam and its ornament twisted before the reader's eyes. A single torn page was all that could be carried back for Onu to examine."},{["episodeID"]="darkshore-onu-cult-investigation-951",["requiresAll"]={{["minimumStage"]=4,["questID"]=951}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"951:description:1-97","951:description:100-272","951:description:277-391","951:description:394-496","951:objective:1-61","951:completion:1-10","951:completion:12-61","951:completion:63-141","951:completion:143-215","951:completion:220-235"},["questID"]=951,["sourceHash"]="3c56ec6118af122803d2f336579a713db1b2422b4baa26f8f0abde0207b46235",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The page pointed toward cursed elven magic, and Mathystra's surviving relics gave Onu a means to study it. He urged vigilance; the investigation had gained evidence, not proof that the cult's danger was ended."}},["grouping"]="One inquiry from cave supplies to elven relics; no resurrection, cult defeat or later revelation about the fallen being is inferred.",["quests"]={947,948,944,949,950,951},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Page Beneath the Glaive"},["darkshore-wizbang-buzzbox-road"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=983,["sourceHash"]="b040ea8bcaa26bb9c184e3faf495df2b61c4e36dd2784e0c1219144300a5b211"},{["minimumStage"]=4,["questID"]=1001,["sourceHash"]="b6ee4722ce29c3b92e4290ebcba9895e30f1f06718e95d565370ffd01e3d4034"},{["minimumStage"]=4,["questID"]=1002,["sourceHash"]="8e61711e7a78157ee89f7f80e8b8809e668cb30a120fedb789975d6e444a0ced"},{["minimumStage"]=4,["questID"]=1003,["sourceHash"]="a27a1a9496dc48c522d26a438e631b80413b6d5bc7aaa5e8dbd236a174a4cd65"}}},["interpretation"]="Every required route step needs its own recorded hand-in and exact source hash. Optional or alternative branches retain their separate rules.",["scope"]="DEFINED_OBSERVED_ROUTE_NOT_WORLD_VICTORY"},["episodes"]={{["episodeID"]="darkshore-wizbang-buzzbox-road-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=983}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"983:description:1-4","983:description:6-51","983:description:53-84","983:description:89-154","983:description:156-206","983:description:211-288","983:description:290-380","983:description:382-419","983:description:421-461","983:description:463-496","983:description:498-511","983:objective:1-53"},["questID"]=983,["sourceHash"]="b040ea8bcaa26bb9c184e3faf495df2b61c4e36dd2784e0c1219144300a5b211",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Wizbang's distant-speaking machines needed constant maintenance. The buzzbox south of Auberdine stood near crawlers whose legs could supply its repair."},{["episodeID"]="darkshore-wizbang-buzzbox-road-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=1001}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1001:description:1-51","1001:description:56-69","1001:description:71-122","1001:description:127-202","1001:description:204-230","1001:description:232-257","1001:description:259-266","1001:description:268-286","1001:description:291-375","1001:description:377-384","1001:description:386-390","1001:description:392-405","1001:objective:1-82"},["questID"]=1001,["sourceHash"]="b6ee4722ce29c3b92e4290ebcba9895e30f1f06718e95d565370ffd01e3d4034",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The voice from the box sent the work north along the beach. The next machine required eyes from the threshers offshore."},{["episodeID"]="darkshore-wizbang-buzzbox-road-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=1002}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1002:description:1-71","1002:description:76-107","1002:description:109-137","1002:description:139-154","1002:description:156-159","1002:description:161-238","1002:description:243-316","1002:description:321-357","1002:objective:1-58"},["questID"]=1002,["sourceHash"]="8e61711e7a78157ee89f7f80e8b8809e668cb30a120fedb789975d6e444a0ced",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Static and muddled instructions carried the route to the northern road bridge. Moonstalker fangs were the materials requested for the waiting buzzbox."},{["episodeID"]="darkshore-wizbang-buzzbox-road-4",["requiresAll"]={{["minimumStage"]=4,["questID"]=1003}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1003:description:1-112","1003:description:117-154","1003:description:156-183","1003:description:185-209","1003:description:211-223","1003:description:225-259","1003:description:261-269","1003:description:271-279","1003:description:281-355","1003:description:357-377","1003:description:379-391","1003:description:393-402","1003:description:407-459","1003:description:461-499","1003:objective:1-110","1003:completion:1-30","1003:completion:32-51","1003:completion:53-56","1003:completion:58-158","1003:completion:160-217","1003:completion:222-319","1003:completion:321-420","1003:completion:422-497","1003:completion:499-505"},["questID"]=1003,["sourceHash"]="a27a1a9496dc48c522d26a438e631b80413b6d5bc7aaa5e8dbd236a174a4cd65",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Four grizzled scalps supplied the last machine on the southern road. The deliveries had followed Wizbang's faltering voice along the coast, linking scattered repairs into one errand."}},["grouping"]="Source-reviewed continuing narrative; branch and source-stage gates retained.",["quests"]={983,1001,1002,1003},["referenceStatus"]="RETAINED_QUEST_SOURCE_STAGES_NOT_CURRENT_PLAYABILITY_VERIFICATION",["sourceConflict"]=false,["title"]="Voices Along the Coast"},["darrowshire-redpaths"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=5149,["sourceHash"]="82ce7b71b14eaa9115025c5cf32e3912ce40326fbe95291d989c33b3bfbef5b6"},{["minimumStage"]=4,["questID"]=5152,["sourceHash"]="5623bee13a0a4eb45f5909db17e2fb1d333c7df3b4d5c865e5f52ffabce89cc7"},{["minimumStage"]=4,["questID"]=5153,["sourceHash"]="708297736a76eeb3d51627722a71258f90d1a4878b564b10a3fd17cda291c2f3"},{["minimumStage"]=4,["questID"]=5154,["sourceHash"]="b85ed32692c2b78ced56c520a70ca8a40bbaa569753fff7b37ec205898bda53c"},{["minimumStage"]=4,["questID"]=5210,["sourceHash"]="953133e477055c82e1d1da0f0af65965fa9088178a0c07f7633e32cdd379f24a"},{["minimumStage"]=4,["questID"]=5168,["sourceHash"]="6cf2974cc56892edc355b6180a5f9ca2cd5dde67f5278365bdd62be1d9e94ec8"},{["minimumStage"]=4,["questID"]=5181,["sourceHash"]="f647db93e6b0eb22fadf462e41207796cd9970ad4d4cca82a7c86512211ab3d9"},{["minimumStage"]=4,["questID"]=5206,["sourceHash"]="dcfa45ab0c182c7ef7a2af55714d5574bcc6d044ffbada3945bab19768a0fe30"},{["minimumStage"]=4,["questID"]=5941,["sourceHash"]="06e6448ed8c763e0c91d70cf535faf3f4329812ef1ab9d83ddeed7ca013fb110"},{["minimumStage"]=4,["questID"]=5721,["sourceHash"]="7d275444d71be12ab7f4d28ac2cfad50810eaf6f53bbb5744118b6fc4df53030"},{["minimumStage"]=4,["questID"]=5942,["sourceHash"]="24a10e3b67774b7e912cec93009f715c4a2376f86398c2f6112bd7487f59bcbd"},{["anyOf"]={{["minimumStage"]=4,["questID"]=5142,["sourceHash"]="4c3fac908884e7eccff2ae3d537c61cf1f1ca8b64da61e4bd5f014a24be3c6de"},{["minimumStage"]=4,["questID"]=5601,["sourceHash"]="9b5e243e11ad720c60904cb4b069b446064f39ea4f84961f6a4db7073d77a686"}}}}},["interpretation"]="The source offers introductions through Marlene5142 and Jessica5601 to the same doll request5149. Either observed introduction satisfies this editorial route clause; it does not assert that a live client requires an introduction.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="darrowshire-redpaths-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=5142},{["minimumStage"]=2,["questID"]=5149}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"5142:description:1-48","5142:description:51-65","5142:description:67-76","5142:description:81-164","5142:description:167-242","5142:description:247-262","5142:description:265-310","5142:description:313-358","5142:objective:1-20"},["questID"]=5142,["sourceHash"]="4c3fac908884e7eccff2ae3d537c61cf1f1ca8b64da61e4bd5f014a24be3c6de",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"5149:description:1-90","5149:description:93-139","5149:description:144-205","5149:description:208-309","5149:description:314-411","5149:description:416-444","5149:objective:1-19"},["questID"]=5149,["sourceHash"]="82ce7b71b14eaa9115025c5cf32e3912ce40326fbe95291d989c33b3bfbef5b6",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Marlene sought word of the child she had hidden, while Pamela waited for the father who never returned. A doll was the first need the visitor could answer in a household held by memory."},{["episodeID"]="darrowshire-redpaths-2",["requiresAll"]={{["minimumStage"]=4,["questID"]=5153},{["minimumStage"]=4,["questID"]=5154},{["minimumStage"]=4,["questID"]=5210}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"5153:description:1-68","5153:description:71-131","5153:description:134-150","5153:description:155-189","5153:description:194-241","5153:description:244-353","5153:description:356-383","5153:description:385-425","5153:description:430-502","5153:objective:1-39","5153:completion:1-13","5153:completion:15-29","5153:completion:31-43","5153:completion:52-143","5153:completion:148-172","5153:completion:174-205","5153:completion:207-246"},["questID"]=5153,["sourceHash"]="708297736a76eeb3d51627722a71258f90d1a4878b564b10a3fd17cda291c2f3",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"5154:description:1-56","5154:description:59-147","5154:description:152-170","5154:description:173-221","5154:description:223-232","5154:objective:1-55","5154:completion:1-24","5154:completion:29-44","5154:completion:46-73","5154:completion:75-113","5154:completion:122-175","5154:completion:177-273","5154:completion:275-320","5154:completion:325-344","5154:completion:346-407"},["questID"]=5154,["sourceHash"]="b85ed32692c2b78ced56c520a70ca8a40bbaa569753fff7b37ec205898bda53c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"5210:description:1-123","5210:description:126-216","5210:description:219-290","5210:description:295-327","5210:objective:1-82","5210:completion:1-18","5210:completion:20-45","5210:completion:47-80","5210:completion:82-125","5210:completion:127-157","5210:completion:162-175","5210:completion:177-249","5210:completion:251-277","5210:completion:279-310","5210:completion:312-329","5210:completion:334-360"},["questID"]=5210,["sourceHash"]="953133e477055c82e1d1da0f0af65965fa9088178a0c07f7633e32cdd379f24a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The wedding ring led to a history that could extend beyond its own ending. Joseph's corruption became the subject of an inquiry through Carlin, a survivor of the battle."},{["episodeID"]="darrowshire-redpaths-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=5168},{["minimumStage"]=4,["questID"]=5181},{["minimumStage"]=4,["questID"]=5206},{["minimumStage"]=4,["questID"]=5941}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"5168:description:1-126","5168:description:131-237","5168:description:242-296","5168:description:299-439","5168:description:444-467","5168:description:470-505","5168:objective:1-60","5168:completion:1-35","5168:completion:40-159"},["questID"]=5168,["sourceHash"]="6cf2974cc56892edc355b6180a5f9ca2cd5dde67f5278365bdd62be1d9e94ec8",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"5181:description:1-63","5181:description:66-163","5181:description:166-255","5181:description:260-340","5181:description:343-402","5181:description:407-431","5181:description:434-491","5181:objective:1-101","5181:completion:1-15","5181:completion:17-30","5181:completion:32-117","5181:completion:122-232"},["questID"]=5181,["sourceHash"]="f647db93e6b0eb22fadf462e41207796cd9970ad4d4cca82a7c86512211ab3d9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"5206:description:1-164","5206:description:169-230","5206:description:233-360","5206:description:363-395","5206:description:409-504","5206:objective:1-90","5206:completion:1-15","5206:completion:17-26","5206:completion:31-183"},["questID"]=5206,["sourceHash"]="dcfa45ab0c182c7ef7a2af55714d5574bcc6d044ffbada3945bab19768a0fe30",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"5941:description:1-59","5941:description:62-129","5941:description:131-166","5941:description:171-262","5941:description:265-298","5941:description:303-380","5941:description:383-441","5941:objective:1-49","5941:completion:1-23","5941:completion:25-109","5941:completion:114-181"},["questID"]=5941,["sourceHash"]="06e6448ed8c763e0c91d70cf535faf3f4329812ef1ab9d83ddeed7ca013fb110",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Relics of defenders and enemies joined skulls identified by participation in the battle. The objects were no longer trophies: Chromie named them as parts of the working that could raise Darrowshire's spirits."},{["episodeID"]="darrowshire-redpaths-4",["requiresAll"]={{["minimumStage"]=4,["questID"]=5721},{["minimumStage"]=4,["questID"]=5942}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"5721:description:1-87","5721:description:92-188","5721:description:191-358","5721:description:363-426","5721:description:429-479","5721:objective:1-54","5721:objective:59-116","5721:objective:121-188","5721:objective:193-221","5721:objective:226-336","5721:completion:1-21","5721:completion:24-54","5721:completion:57-115","5721:completion:118-130","5721:completion:135-209","5721:completion:214-243"},["questID"]=5721,["sourceHash"]="7d275444d71be12ab7f4d28ac2cfad50810eaf6f53bbb5744118b6fc4df53030",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"5942:description:1-35","5942:description:38-88","5942:description:93-123","5942:description:126-152","5942:description:155-189","5942:description:194-213","5942:description:216-232","5942:description:235-244","5942:description:247-277","5942:objective:1-37","5942:completion:1-45"},["questID"]=5942,["sourceHash"]="24a10e3b67774b7e912cec93009f715c4a2376f86398c2f6112bd7487f59bcbd",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The battle's conditions were fulfilled and Pamela heard her father promise to come home. Tea and a key behind the house answered a child's gratitude after a history of betrayal had become a chance to save a soul."}},["grouping"]="Authored connected episodes with explicit source-stage gates; branches retained",["quests"]={5142,5149,5152,5153,5154,5210,5168,5181,5206,5941,5721,5942},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="A Village Remembered Twice"},["desolace-keldran-horde-and-burning-blade"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=1431,["sourceHash"]="d260ae8c10b72ddec0470d545db99b56c894f83bffdb6ce66913bc1eb9d27ba6"},{["minimumStage"]=4,["questID"]=1432,["sourceHash"]="584bee312191ade9ccc90bb19b09230b22e195d8912eaab5ba9185ec5bbf173c"},{["minimumStage"]=4,["questID"]=1433,["sourceHash"]="527b07e97fd512e84e2816910872ac3b6e81df2ad3a8c6b42c6ab229a57592f8"},{["minimumStage"]=4,["questID"]=1435,["sourceHash"]="4c797e0caf452c9e5eb4515f1c92b26bb68aa73cb2e86ca42136c30222aadbfd"},{["minimumStage"]=4,["questID"]=1436,["sourceHash"]="36f6c9550fa858f6fea00644cd4d19d8029e123c957686ccfddffdafd05cdd01"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="desolace-keldran-horde-and-burning-blade-1431",["requiresAll"]={{["minimumStage"]=2,["questID"]=1431}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"1431:description:1-101","1431:description:106-189","1431:description:191-274","1431:description:276-367","1431:description:372-470","1431:description:472-490","1431:objective:1-30"},["questID"]=1431,["sourceHash"]="d260ae8c10b72ddec0470d545db99b56c894f83bffdb6ce66913bc1eb9d27ba6",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Craven’s account of Thrall’s diplomacy led to Keldran and a quieter concern: how the Horde appeared to others. Old war and new settlements made that appearance a matter of peace as well as pride."},{["episodeID"]="desolace-keldran-horde-and-burning-blade-1432",["requiresAll"]={{["minimumStage"]=4,["questID"]=1432}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1432:description:1-148","1432:description:150-190","1432:description:192-261","1432:description:266-362","1432:description:364-451","1432:description:453-496","1432:objective:1-39","1432:completion:1-14","1432:completion:16-59","1432:completion:64-147","1432:completion:149-288","1432:completion:293-476"},["questID"]=1432,["sourceHash"]="584bee312191ade9ccc90bb19b09230b22e195d8912eaab5ba9185ec5bbf173c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="With Alliance forces advancing through Kalimdor, Keldran feared that local demon-worshipers would be mistaken for the Horde’s allies. His agents at Ghost Walker Post opposed the demonic threat for the warchief, even where their work indirectly helped the centaurs."},{["episodeID"]="desolace-keldran-horde-and-burning-blade-1433",["requiresAll"]={{["minimumStage"]=2,["questID"]=1433}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1433:description:1-170","1433:description:175-263","1433:description:268-374","1433:description:379-429","1433:objective:1-41"},["questID"]=1433,["sourceHash"]="527b07e97fd512e84e2816910872ac3b6e81df2ad3a8c6b42c6ab229a57592f8",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Takata handled Desolace’s other demonic dangers while Maurin directed the effort against the Burning Blade. His knowledge of their warlock practices supplied a plan more severe than ordinary combat."},{["episodeID"]="desolace-keldran-horde-and-burning-blade-1435",["requiresAll"]={{["minimumStage"]=4,["questID"]=1435}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1435:description:1-116","1435:description:118-213","1435:description:218-231","1435:description:233-295","1435:description:297-387","1435:description:392-453","1435:description:458-489","1435:objective:1-86","1435:completion:1-31","1435:completion:33-45","1435:completion:47-102","1435:completion:107-140","1435:completion:142-177","1435:completion:179-306"},["questID"]=1435,["sourceHash"]="4c797e0caf452c9e5eb4515f1c92b26bb68aa73cb2e86ca42136c30222aadbfd",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Maurin’s gem drew corrupted spirits from the dying cultists. The filled stones returned to his keeping for the disposal he promised, though their ultimate fate lay beyond the recorded exchange."},{["episodeID"]="desolace-keldran-horde-and-burning-blade-1436",["requiresAll"]={{["minimumStage"]=4,["questID"]=1436}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1436:description:1-24","1436:description:26-205","1436:description:210-262","1436:description:264-314","1436:description:316-420","1436:objective:1-30","1436:completion:1-57","1436:completion:59-68","1436:completion:73-145","1436:completion:147-342","1436:completion:347-367"},["questID"]=1436,["sourceHash"]="36f6c9550fa858f6fea00644cd4d19d8029e123c957686ccfddffdafd05cdd01",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Takata sent the news back to Orgrimmar. Keldran welcomed the mission’s success as a way to distinguish Thrall’s people from the Legion and avoid needless new violence, without claiming every demon in Desolace destroyed."}},["grouping"]="Five stages connect Thrall’s diplomacy to a local anti-demon mission. Maurin’s promised disposal is not independently witnessed.",["quests"]={1431,1432,1433,1435,1436},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Horde Apart from the Legion"},["desolace-malem-missing-family"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=1437,["sourceHash"]="4a3b3645e274e4b0eeacd04b1d974ec2383d52ac36e8c3b7467429f76cb5c776"},{["minimumStage"]=4,["questID"]=1465,["sourceHash"]="e0e2a6279c4ede1aa508fd323ea0b42cc74d37867305ccb904cbc9e973ef5a38"},{["minimumStage"]=4,["questID"]=1438,["sourceHash"]="fbef23ddfd832f66f3978dae2c4cd9b8a1a128ceacb6cf1acd7214d3fc385746"},{["minimumStage"]=4,["questID"]=1439,["sourceHash"]="9c33622fc19fab33cb57d82dcb7b1bf0b79bf8698985ce14b9bc2353af335c50"},{["minimumStage"]=4,["questID"]=1440,["sourceHash"]="50db17da3148b2dd9e27eced4f8e85f2cbf7767626764365c84815f780d996aa"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="desolace-malem-missing-family-1437",["requiresAll"]={{["minimumStage"]=4,["questID"]=1437}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"1437:description:1-20","1437:description:22-131","1437:description:133-234","1437:description:236-331","1437:description:336-416","1437:description:421-478","1437:objective:1-62","1437:completion:1-115","1437:completion:117-214","1437:completion:219-269"},["questID"]=1437,["sourceHash"]="4a3b3645e274e4b0eeacd04b1d974ec2383d52ac36e8c3b7467429f76cb5c776",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="House Malem’s missing children had last been reported traveling through Stonetalon. Vahlarriel’s search reached a wrecked wagon in Desolace: weapons and spells had struck it, yet neither bodies nor blood explained where its passengers had gone."},{["episodeID"]="desolace-malem-missing-family-1465",["requiresAll"]={{["minimumStage"]=4,["questID"]=1465}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1465:description:1-120","1465:description:122-180","1465:description:182-329","1465:description:334-468","1465:objective:1-63","1465:completion:1-12","1465:completion:14-32","1465:completion:37-105","1465:completion:107-133","1465:completion:135-143","1465:completion:148-196","1465:completion:198-222","1465:completion:227-370","1465:completion:372-500"},["questID"]=1465,["sourceHash"]="e0e2a6279c4ede1aa508fd323ea0b42cc74d37867305ccb904cbc9e973ef5a38",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A pendant and southward footprints offered a trail toward a fortified camp. The evidence returned to Vahlarriel, who identified the local Burning Blade as demon-serving captors rather than representatives of the Horde as a whole."},{["episodeID"]="desolace-malem-missing-family-1438",["requiresAll"]={{["minimumStage"]=4,["questID"]=1438}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1438:description:1-80","1438:description:82-116","1438:description:118-202","1438:description:207-261","1438:description:263-345","1438:description:347-421","1438:description:423-441","1438:description:443-473","1438:objective:1-31","1438:completion:1-45","1438:completion:47-75","1438:completion:77-153","1438:completion:155-211","1438:completion:216-365","1438:completion:367-453","1438:completion:458-482"},["questID"]=1438,["sourceHash"]="fbef23ddfd832f66f3978dae2c4cd9b8a1a128ceacb6cf1acd7214d3fc385746",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Dalinda was alive inside the fortress. She said their escort had been slaughtered and feared sacrifice, while Tyranis’s hunger for forbidden arcane knowledge had driven the journey. Vahlarriel’s superiors had already warned that her brother’s intentions needed scrutiny."},{["episodeID"]="desolace-malem-missing-family-1439",["requiresAll"]={{["minimumStage"]=4,["questID"]=1439}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1439:description:1-76","1439:description:78-118","1439:description:120-220","1439:description:225-259","1439:description:261-329","1439:description:331-347","1439:description:352-421","1439:description:423-477","1439:objective:1-31","1439:completion:1-17","1439:completion:19-49","1439:completion:51-126","1439:completion:128-202","1439:completion:204-221","1439:completion:226-315","1439:completion:317-397","1439:completion:402-451"},["questID"]=1439,["sourceHash"]="9c33622fc19fab33cb57d82dcb7b1bf0b79bf8698985ce14b9bc2353af335c50",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Dalinda refused to abandon Tyranis without knowing what had become of him. News of his fate brought grief and a reluctant acceptance that escape could wait no longer; the account leaves the precise circumstances unstated."},{["episodeID"]="desolace-malem-missing-family-1440",["requiresAll"]={{["minimumStage"]=4,["questID"]=1440}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1440:description:1-25","1440:description:27-175","1440:description:177-278","1440:objective:1-101","1440:completion:1-14","1440:completion:16-123","1440:completion:125-191","1440:completion:193-211","1440:completion:216-342","1440:completion:344-416"},["questID"]=1440,["sourceHash"]="50db17da3148b2dd9e27eced4f8e85f2cbf7767626764365c84815f780d996aa",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The path out of Thunder Axe Fortress finally brought Dalinda safely to Nijel’s Point. Vahlarriel welcomed her survival but mourned that both siblings had not returned. Home awaited, together with the burden of explaining Tyranis’s choices."}},["grouping"]="Five connected stages search for House Malem’s children. The brother’s fate is acknowledged without inventing missing dialogue or a particular transformation.",["quests"]={1437,1465,1438,1439,1440},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Wagon Without Its Travelers"},["dire-maul-foror-quelserrar"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=7507,["sourceHash"]="6aebf18389faea3d47ea0b75239f4983e05a6110a9941770a72b2b1ad01b43e0"},{["minimumStage"]=4,["questID"]=7508,["sourceHash"]="b616a764d6ca0590069ba27efe028971e8850f7c5e2f3fc218c1c5507e1970fb"},{["minimumStage"]=4,["questID"]=7509,["sourceHash"]="0344e12b126db83719e768a0f41f4b05c5bd52b6ad5e6ac47e5f8bc4bb8bfd30"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="dire-maul-foror-quelserrar-7507",["requiresAll"]={{["minimumStage"]=2,["questID"]=7507}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"7507:description:1-49","7507:description:51-93","7507:description:98-185","7507:description:187-232","7507:objective:1-61"},["questID"]=7507,["sourceHash"]="6aebf18389faea3d47ea0b75239f4983e05a6110a9941770a72b2b1ad01b43e0",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The broken seal on an ancient compendium had exposed knowledge of dragon slaying, although much of the writing was hard to read. Returning it to the Athenaeum placed its secrets before Lydros rather than a black-market buyer."},{["episodeID"]="dire-maul-foror-quelserrar-7508",["requiresAll"]={{["minimumStage"]=4,["questID"]=7508}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"7508:description:1-69","7508:objective:1-56","7508:completion:1-161"},["questID"]=7508,["sourceHash"]="b616a764d6ca0590069ba27efe028971e8850f7c5e2f3fc218c1c5507e1970fb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The lorekeeper’s promised reward demanded more than a book. A dull elven blade could be remade only by heating it in a dragon’s breath and tempering it in her blood, work that would carry the scholar’s bargain into Onyxia’s lair."},{["episodeID"]="dire-maul-foror-quelserrar-7509",["requiresAll"]={{["minimumStage"]=4,["questID"]=7509}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"7509:description:1-78","7509:description:83-142","7509:description:144-220","7509:description:222-316","7509:description:318-405","7509:description:410-505","7509:objective:1-65","7509:objective:67-122","7509:objective:124-213","7509:objective:218-326","7509:objective:331-368","7509:completion:1-42","7509:completion:47-88"},["questID"]=7509,["sourceHash"]="0344e12b126db83719e768a0f41f4b05c5bd52b6ad5e6ac47e5f8bc4bb8bfd30",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The treated blade returned from the dragonfire and Lydros completed his binding, naming the finished weapon Quel’Serrar. The long bargain had joined the compendium’s recovered knowledge to a weapon tempered in dragonfire."}},["grouping"]="The compendium and Quel’Serrar route; the blade’s forging belongs only to the recorded quest fulfillment, never a reference-only boss claim.",["quests"]={7507,7508,7509},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Blade Tempered in Dragonfire"},["dun-morogh-jetsteam"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=317,["sourceHash"]="51517c0ee9e912ed5f681a47e28bd128d4c72f888bb710eab657a98d0dbbc78b"},{["minimumStage"]=4,["questID"]=318,["sourceHash"]="cc3dbf5698ad2fde34741a12b71a0aa954d105cb4b672e12e61c19c947a7f781"},{["minimumStage"]=4,["questID"]=319,["sourceHash"]="8ac41e47efe533c5ac7a5fd5d0dcf7086dd6ca0f14e8d64e56eb7bec51e19687"},{["minimumStage"]=4,["questID"]=320,["sourceHash"]="cf1f4c0fc718b423931e2f130fd30512d837cccc2c538e6c099cbb17d6dc3410"}}},["interpretation"]="Requires observed fulfillment of this source-backed route, not a larger military victory, restored city or successful experiment.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="jetsteam-provisions",["requiresAll"]={{["minimumStage"]=2,["questID"]=317}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"317:description:1-55","317:description:58-136","317:description:139-212","317:description:217-271","317:description:274-326","317:description:328-395","317:objective:1-110"},["questID"]=317,["sourceHash"]="51517c0ee9e912ed5f681a47e28bd128d4c72f888bb710eab657a98d0dbbc78b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Before Jetsteam could take to the road, Bellowfiz needed enough provisions for a month with the Siege Brigade. Steelgrill had the tank in hand; meat and warm bedding had to come from the snowfields beyond the Grizzled Den."},{["episodeID"]="jetsteam-evershine",["requiresAll"]={{["minimumStage"]=2,["questID"]=318}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"318:description:1-45","318:description:48-145","318:description:150-246","318:description:249-299","318:description:304-398","318:description:401-465","318:objective:1-67"},["questID"]=318,["sourceHash"]="cc3dbf5698ad2fde34741a12b71a0aa954d105cb4b672e12e61c19c947a7f781",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Bellowfiz's provisions still lacked Rejold's Evershine. The brew could warm a traveler or burn in Jetsteam's furnace for a burst of power. Rejold lived west of Kharanos, in Brewnall Village."},{["episodeID"]="jetsteam-brewer-favor",["requiresAll"]={{["minimumStage"]=2,["questID"]=319}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"319:description:1-62","319:description:65-152","319:description:155-182","319:description:187-379","319:objective:1-121"},["questID"]=319,["sourceHash"]="8ac41e47efe533c5ac7a5fd5d0dcf7086dd6ca0f14e8d64e56eb7bec51e19687",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Rejold had a cask ready, but asked a favor in return. Bears, boars and leopards strayed close enough to disturb the village's work. Hunting them would leave its craftsmen and brewers more time at their trades."},{["episodeID"]="jetsteam-cask-delivered",["requiresAll"]={{["minimumStage"]=4,["questID"]=320}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"320:completion:1-28","320:completion:30-85"},["questID"]=320,["sourceHash"]="cf1f4c0fc718b423931e2f130fd30512d837cccc2c538e6c099cbb17d6dc3410",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The cask reached Bellowfiz at Steelgrill's Depot. He approved of the brew and considered opening a bottle at once. For all its possible use in a furnace, Evershine remained a drink worth tasting."}},["grouping"]="One pilot preparation and the brewer favor it requires; not an entire Siege Brigade campaign.",["quests"]={317,318,319,320},["referenceStatus"]="HISTORICAL_STAGE_SOURCE_CORROBORATED_BY_PUBLISHER_BETA_ACCOUNTS; NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Provisions for Jetsteam"},["durotar-darkstorm-demon-seed"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=823,["sourceHash"]="8f81beb9e2d9f0aaa56b88d14aad03e27ddb5f9b53dfa01615b5f82439482dcc"},{["minimumStage"]=4,["questID"]=806,["sourceHash"]="8355bfd2ec9fcbf184ea7d8df15c260e17bb30290c9340a65a8d857e19506da9"},{["minimumStage"]=4,["questID"]=828,["sourceHash"]="89fc29ffd99452c6e5fbab8cfeefa02a9a1394b077fc48f120a945c92fbefc61"},{["minimumStage"]=4,["questID"]=827,["sourceHash"]="1fbe49fd85177385f2cb33fa91b425982780e5bb4ec8755df945ff79a45e3301"},{["minimumStage"]=4,["questID"]=829,["sourceHash"]="87acffff1e59deb2081d3fbcdfdb8c86bc0de5fe1036e1f9a161861bb0e8371c"},{["minimumStage"]=4,["questID"]=809,["sourceHash"]="912fa453c13f3ff0cbac71e6ed3e8f206bb50d9ff66d060167c501a147ffd120"},{["minimumStage"]=4,["questID"]=924,["sourceHash"]="bb14e3a38d2959dec0778ebe96fe8967905e13073f1f2f900cc39e5a5eee5c47"}}},["interpretation"]="Every required route step needs its own recorded hand-in and exact source hash. Optional or alternative branches retain their separate rules.",["scope"]="DEFINED_OBSERVED_ROUTE_NOT_WORLD_VICTORY"},["episodes"]={{["episodeID"]="durotar-darkstorm-demon-seed-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=823}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"823:description:1-86","823:description:89-169","823:description:174-288","823:description:291-378","823:description:381-414","823:description:419-447","823:objective:1-41"},["questID"]=823,["sourceHash"]="8f81beb9e2d9f0aaa56b88d14aad03e27ddb5f9b53dfa01615b5f82439482dcc",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Gadrin's warning from the Valley concerned more than one settlement. Orgnil at Razor Hill watched for corruption threatening Durotar and needed to hear the news."},{["episodeID"]="durotar-darkstorm-demon-seed-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=806}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"806:description:1-56","806:description:59-105","806:description:110-266","806:description:269-314","806:description:319-369","806:objective:1-53"},["questID"]=806,["sourceHash"]="8355bfd2ec9fcbf184ea7d8df15c260e17bb30290c9340a65a8d857e19506da9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Orgnil's inquiry pointed toward Thunder Ridge, where Fizzle Darkstorm and his followers held another Burning Blade foothold. The investigation had found a warlock to confront."},{["episodeID"]="durotar-darkstorm-demon-seed-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=828}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"828:description:1-73","828:description:76-155","828:description:157-211","828:description:216-261","828:description:264-300","828:description:305-373","828:description:378-467","828:objective:1-18"},["questID"]=828,["sourceHash"]="89fc29ffd99452c6e5fbab8cfeefa02a9a1394b077fc48f120a945c92fbefc61",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The trail then turned to Margoz, whose knowledge might prepare a strike against Skull Rock. His camp lay between the coast and Drygulch Ravine."},{["episodeID"]="durotar-darkstorm-demon-seed-4",["requiresAll"]={{["minimumStage"]=2,["questID"]=827}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"827:description:6-83","827:description:86-175","827:description:180-263","827:description:266-335","827:description:340-416","827:description:419-469","827:objective:1-55","827:objective:60-92"},["questID"]=827,["sourceHash"]="1fbe49fd85177385f2cb33fa91b425982780e5bb4ec8755df945ff79a45e3301",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Burning collars worn in Skull Rock suggested a means of attuning the cultists to demonic power. Margoz needed examples before he could establish what they did."},{["episodeID"]="durotar-darkstorm-demon-seed-5",["requiresAll"]={{["minimumStage"]=2,["questID"]=829}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"829:description:1-68","829:description:71-137","829:description:140-176","829:description:181-221","829:description:224-354","829:description:357-435","829:description:440-494","829:objective:1-56"},["questID"]=829,["sourceHash"]="87acffff1e59deb2081d3fbcdfdb8c86bc0de5fe1036e1f9a161861bb0e8371c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The collars exceeded the shaman's knowledge. Neeru Fireblade in Orgrimmar offered another interpretation, though Margoz did not treat the warlock's claims of harmless research as settled truth."},{["episodeID"]="durotar-darkstorm-demon-seed-6",["requiresAll"]={{["minimumStage"]=2,["questID"]=809}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"809:description:1-128","809:description:131-174","809:description:179-263","809:description:266-344","809:description:347-367","809:description:372-474","809:description:477-503","809:objective:1-36"},["questID"]=809,["sourceHash"]="912fa453c13f3ff0cbac71e6ed3e8f206bb50d9ff66d060167c501a147ffd120",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Neeru named a demonic object on Dreadmist Peak as the cult's rallying point. His assistant Ak'Zeloth at Far Watch Post could explain its destruction."},{["episodeID"]="durotar-darkstorm-demon-seed-7",["requiresAll"]={{["minimumStage"]=4,["questID"]=924}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"924:description:1-57","924:description:59-126","924:description:131-232","924:description:237-318","924:description:320-363","924:description:365-394","924:description:396-447","924:description:452-508","924:objective:1-26","924:objective:29-109","924:completion:1-22","924:completion:24-70","924:completion:72-97","924:completion:102-200","924:completion:202-253","924:completion:255-304","924:completion:309-368","924:completion:370-394","924:completion:396-419","924:completion:424-437"},["questID"]=924,["sourceHash"]="bb14e3a38d2959dec0778ebe96fe8967905e13073f1f2f900cc39e5a5eee5c47",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Ak'Zeloth acknowledged the seed's destruction, but the released power troubled him. Severing the altar's link had ended this task while perhaps drawing attention from other beings."}},["grouping"]="Source-reviewed continuing narrative; branch and source-stage gates retained.",["quests"]={823,806,828,827,829,809,924},["referenceStatus"]="RETAINED_QUEST_SOURCE_STAGES_NOT_CURRENT_PLAYABILITY_VERIFICATION",["sourceConflict"]=false,["title"]="The Burning Blade Trail"},["duskwood-jitters-grual-meal"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=5,["sourceHash"]="ca90b596bee2ad106d5f3667c132f6933759382a07760345e0fd61b86fd75eb9"},{["minimumStage"]=4,["questID"]=93,["sourceHash"]="68af821c1659d3e4f9eed07a93745b8b4f9df8e6becff09ec8faa304d0d8e8dd"},{["minimumStage"]=4,["questID"]=240,["sourceHash"]="05f73e2b1a2b8cacd480bf4272161a5534fe92a834b46b21413131d18e315221"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="duskwood-jitters-grual-meal-5",["requiresAll"]={{["minimumStage"]=2,["questID"]=5}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"5:description:1-102","5:description:105-166","5:description:171-215","5:description:220-314","5:objective:1-22"},["questID"]=5,["sourceHash"]="ca90b596bee2ad106d5f3667c132f6933759382a07760345e0fd61b86fd75eb9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Weeks in the ghost town had left Jitters living on grubs and weeds. His longing for a proper meal led to Grual at Darkshire’s tavern and the promise of the cook’s celebrated crab cakes."},{["episodeID"]="duskwood-jitters-grual-meal-93",["requiresAll"]={{["minimumStage"]=2,["questID"]=93}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"93:description:1-89","93:description:92-183","93:description:186-247","93:description:252-356","93:objective:1-69"},["questID"]=93,["sourceHash"]="68af821c1659d3e4f9eed07a93745b8b4f9df8e6becff09ec8faa304d0d8e8dd",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Grual’s specialty concealed an unlikely ingredient: spider legs. The meal now depended on gathering them from the venomous spiders north of town, turning Jitters’s hunger into work along Duskwood’s dangerous river hills."},{["episodeID"]="duskwood-jitters-grual-meal-240",["requiresAll"]={{["minimumStage"]=4,["questID"]=240}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"240:description:1-41","240:objective:1-44","240:completion:1-4","240:completion:6-19","240:completion:21-46","240:completion:51-92"},["questID"]=240,["sourceHash"]="05f73e2b1a2b8cacd480bf4272161a5534fe92a834b46b21413131d18e315221",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The cooked cakes reached Jitters at last. He paid gratefully for a meal after his long privation; whatever else kept him hiding remained outside this small kindness."}},["grouping"]="Three connected steps obtain food for Jitters; nothing about his larger secrets is inferred from feeding him.",["quests"]={5,93,240},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Feast for the Man in Hiding"},["duskwood-ladimore-ring-and-rest"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=225,["sourceHash"]="f5b1a1dc1ce599da13d0cd797ac689272cff2d061ae30b44f78e7b83a44a0b28"},{["minimumStage"]=4,["questID"]=227,["sourceHash"]="f31c7b445225551cbfb2612859b6ceff48da25c9da3d000ddf66f0b86060c577"},{["minimumStage"]=4,["questID"]=228,["sourceHash"]="f11a2b54fda0646ef6cd1a1d3ce839727b9951e8efc2265c8aad3aec0553aad9"},{["minimumStage"]=4,["questID"]=229,["sourceHash"]="7943ba146402eaf4fcea327fb6d1bcc337ca6b9ceb6add4159e6c2bfe12fd806"},{["minimumStage"]=4,["questID"]=231,["sourceHash"]="5a0c561138a012847a1eff664be32c197aceb409bba984be30b99bdad9eb3ba9"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="duskwood-ladimore-ring-and-rest-225",["requiresAll"]={{["minimumStage"]=2,["questID"]=225}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"225:description:1-40","225:description:45-59","225:description:64-222","225:objective:1-39"},["questID"]=225,["sourceHash"]="f5b1a1dc1ce599da13d0cd797ac689272cff2d061ae30b44f78e7b83a44a0b28",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Freshly disturbed earth surrounded Morgan Ladimore’s weathered marker. The name led toward Darkshire and Sirra’s memories of a good man whose life had ended badly."},{["episodeID"]="duskwood-ladimore-ring-and-rest-227",["requiresAll"]={{["minimumStage"]=4,["questID"]=227}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"227:description:1-72","227:description:77-165","227:description:167-176","227:description:178-194","227:objective:1-51","227:completion:1-16","227:completion:18-34","227:completion:39-61","227:completion:63-98","227:completion:103-140","227:completion:142-213","227:completion:215-321","227:completion:323-414","227:completion:419-437","227:completion:442-504"},["questID"]=227,["sourceHash"]="f31c7b445225551cbfb2612859b6ceff48da25c9da3d000ddf66f0b86060c577",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Sirra offered an old book, but Althea knew the immediate danger: the dead man now wandered as Mor’Ladim, attacking patrols and killing travelers. A forgotten grave had become a threat the Night Watch could not ignore."},{["episodeID"]="duskwood-ladimore-ring-and-rest-228",["requiresAll"]={{["minimumStage"]=4,["questID"]=228}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"228:description:1-129","228:description:131-199","228:description:204-271","228:objective:1-81","228:completion:1-15","228:completion:17-51","228:completion:53-122","228:completion:133-169"},["questID"]=228,["sourceHash"]="f11a2b54fda0646ef6cd1a1d3ce839727b9951e8efc2265c8aad3aec0553aad9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Mor’Ladim was laid low and his skull brought to Althea. Her gratitude did not quite close the matter, for the family he believed lost had left someone still alive."},{["episodeID"]="duskwood-ladimore-ring-and-rest-229",["requiresAll"]={{["minimumStage"]=2,["questID"]=229}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"229:description:1-38","229:description:43-62","229:description:67-180","229:description:182-217","229:description:219-234","229:description:236-266","229:description:268-313","229:objective:1-47"},["questID"]=229,["sourceHash"]="7943ba146402eaf4fcea327fb6d1bcc337ca6b9ceb6add4159e6c2bfe12fd806",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Sarah Ladimore served as a Watcher in Darkshire. Bringing the news meant facing a daughter troubled by the circumstances of her father’s death, rather than leaving him only the monster known to the patrols."},{["episodeID"]="duskwood-ladimore-ring-and-rest-231",["requiresAll"]={{["minimumStage"]=4,["questID"]=231}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"231:description:1-40","231:description:42-49","231:description:51-144","231:description:149-256","231:description:261-266","231:description:268-281","231:objective:1-54","231:completion:1-39","231:completion:44-54","231:completion:56-61","231:completion:63-92","231:completion:94-135","231:completion:144-166","231:completion:168-221","231:completion:223-348","231:completion:353-367"},["questID"]=231,["sourceHash"]="5a0c561138a012847a1eff664be32c197aceb409bba984be30b99bdad9eb3ba9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Sarah’s ring returned to the grave with the hope that her father might know she lived and did not blame him. A voice on the wind recognized her name and spoke of a burden lifted, leaving Archeus behind as Morgan’s soul found rest."}},["grouping"]="The grave investigation, undead threat, surviving daughter and ring; the separate biography book is not reconstructed from an empty item reference.",["quests"]={225,227,228,229,231},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Daughter Beyond the Grave"},["duskwood-viktori-star-device"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=174,["sourceHash"]="202ca4c9bed82859626791e012ed660326457bcbd7e73bd0d35f1b28ae88ca2a"},{["minimumStage"]=4,["questID"]=175,["sourceHash"]="af8ab2dadf57e53db2c92123d594d6ed1aad716d1faf5b66ebf3374be4320399"},{["minimumStage"]=4,["questID"]=177,["sourceHash"]="1cc9dceccf85e6fcb82ea00d0db020c3cb5e015b666a55e8558c72bc758f0ca1"},{["minimumStage"]=4,["questID"]=181,["sourceHash"]="5f5645f6dd5f26fb7d6bce898331d73a92e0b6c65cc2f7d83106842af2f4ea57"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="duskwood-viktori-star-device-174",["requiresAll"]={{["minimumStage"]=2,["questID"]=174}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"174:description:1-104","174:description:107-194","174:description:199-251","174:description:254-306","174:objective:1-71"},["questID"]=174,["sourceHash"]="202ca4c9bed82859626791e012ed660326457bcbd7e73bd0d35f1b28ae88ca2a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Viktori sought an explanation for the forest’s transformation beyond the usual workings of magic. Cog’s blueprint offered a means to study the stars, beginning with an engineer’s bronze tube."},{["episodeID"]="duskwood-viktori-star-device-175",["requiresAll"]={{["minimumStage"]=2,["questID"]=175}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"175:description:1-72","175:description:75-190","175:description:193-291","175:description:294-341","175:objective:1-83"},["questID"]=175,["sourceHash"]="af8ab2dadf57e53db2c92123d594d6ed1aad716d1faf5b66ebf3374be4320399",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The instrument also needed a reflecting surface. Mary’s once-famous looking glass offered a possibility, if the woman in southern Duskwood could be found and persuaded to lend it."},{["episodeID"]="duskwood-viktori-star-device-177",["requiresAll"]={{["minimumStage"]=2,["questID"]=177}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"177:description:1-55","177:description:59-72","177:description:75-126","177:description:129-182","177:description:185-208","177:description:211-283","177:objective:1-94"},["questID"]=177,["sourceHash"]="1cc9dceccf85e6fcb82ea00d0db020c3cb5e015b666a55e8558c72bc758f0ca1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Mary had discarded the mirror after an unnamed incident. An insane ghoul was said to have taken it, turning the search for a simple optical part toward Tranquil Gardens’ dead."},{["episodeID"]="duskwood-viktori-star-device-181",["requiresAll"]={{["minimumStage"]=4,["questID"]=181}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"181:description:1-63","181:description:66-111","181:description:114-198","181:description:203-290","181:description:293-360","181:objective:1-103","181:completion:1-8","181:completion:10-43","181:completion:45-58","181:completion:60-90"},["questID"]=181,["sourceHash"]="5f5645f6dd5f26fb7d6bce898331d73a92e0b6c65cc2f7d83106842af2f4ea57",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Zzarc’Vul’s large monocle supplied the final lens. Viktori pronounced the device complete and could resume his research; the assembled tube, mirror and glass gave him a new way to ask his question, not its answer."}},["grouping"]="Four stages construct a stargazing device; its completion does not prove the mystery of Duskwood solved.",["quests"]={174,175,177,181},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Lens Turned Beyond the Forest"},["duskwood-watch-graveyard-front"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=56,["sourceHash"]="59f75d213ea4a884962af47d85c5d0152e2722dfb377a08546d1c7ee5d9109a6"},{["minimumStage"]=4,["questID"]=57,["sourceHash"]="bbf09a4e5b8e933b704bbcf8332e8cf76dd08d427295049a8ca5e946680f957a"},{["minimumStage"]=4,["questID"]=58,["sourceHash"]="6a682c0e4e29b230aaf08a2a787f92a51894d13eb8617a22c3c92c35b342a5fa"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="duskwood-watch-graveyard-front-56",["requiresAll"]={{["minimumStage"]=2,["questID"]=56}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"56:description:1-89","56:description:92-194","56:description:199-248","56:description:250-392","56:description:395-429","56:objective:1-99"},["questID"]=56,["sourceHash"]="59f75d213ea4a884962af47d85c5d0152e2722dfb377a08546d1c7ee5d9109a6",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Stormwind’s withdrawn guards left Althea and the Night Watch to protect Darkshire themselves. The dead rising in Tranquil Gardens made the danger immediate, just south of the town’s limited defenses."},{["episodeID"]="duskwood-watch-graveyard-front-57",["requiresAll"]={{["minimumStage"]=2,["questID"]=57}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"57:description:1-63","57:description:66-192","57:description:195-295","57:description:298-337","57:objective:1-101"},["questID"]=57,["sourceHash"]="bbf09a4e5b8e933b704bbcf8332e8cf76dd08d427295049a8ca5e946680f957a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Reports from the wider forest and Raven Hill showed that the threat was not confined to one cemetery. Skeletal fiends and horrors stretched the Watch’s thin patrols between the burial grounds."},{["episodeID"]="duskwood-watch-graveyard-front-58",["requiresAll"]={{["minimumStage"]=4,["questID"]=58}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"58:description:1-42","58:description:45-89","58:description:92-142","58:description:145-246","58:objective:1-114","58:completion:1-124","58:completion:126-160"},["questID"]=58,["sourceHash"]="6a682c0e4e29b230aaf08a2a787f92a51894d13eb8617a22c3c92c35b342a5fa",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Raven Hill’s eastern mausoleum became the last focus of this effort, its Plague Spreaders another burden Althea lacked enough Watchers to contain. She thanked the help given in Darkshire’s name, without claiming the forest’s curse had ended."}},["grouping"]="Three linked defenses of Darkshire and its cemeteries; local service never proves the undead permanently removed.",["quests"]={56,57,58},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Watch Left Behind"},["dustwallow-krog-blackened-shield"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=1251,["sourceHash"]="176d02134521dd2d41e7f3b94c8c3a8990b92c5aec5049145dd4c6d2aa23da70"},{["minimumStage"]=4,["questID"]=1321,["sourceHash"]="cbd1ae0572f7b302615ce16dbcef2dc90c158af0f4ae4f23809698a4e5d6d666"},{["minimumStage"]=4,["questID"]=1322,["sourceHash"]="28990e5c758f9e70a1ffa3c0880cf8f73568a61693ba6f8d3b77c230ac3fa74c"},{["minimumStage"]=4,["questID"]=1323,["sourceHash"]="69eae74eb73f8fe7259e8a88723d2b554669eb259251727899f891e43d4fe9b1"},{["minimumStage"]=4,["questID"]=1276,["sourceHash"]="6a831ef59203f801504a0410c2d861de121498c1cef338ad29db59138353997b"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="dustwallow-krog-blackened-shield-1251",["requiresAll"]={{["minimumStage"]=2,["questID"]=1251}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"1251:description:1-188","1251:description:193-248","1251:objective:1-63"},["questID"]=1251,["sourceHash"]="176d02134521dd2d41e7f3b94c8c3a8990b92c5aec5049145dd4c6d2aa23da70",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A plain iron shield hung on the ruined chimney at Shady Rest. Its survival in the fire drew Krog’s suspicion: decoration seemed unlikely, but a warning or threat remained only a possibility."},{["episodeID"]="dustwallow-krog-blackened-shield-1321",["requiresAll"]={{["minimumStage"]=2,["questID"]=1321}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1321:description:1-6","1321:description:8-65","1321:description:67-196","1321:objective:1-64"},["questID"]=1321,["sourceHash"]="cbd1ae0572f7b302615ce16dbcef2dc90c158af0f4ae4f23809698a4e5d6d666",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Nothing about the shield explained the burning. Krog sent it to Do’gol for a blacksmith’s closer examination, shifting the search from guesses about its placement to marks left by its making."},{["episodeID"]="dustwallow-krog-blackened-shield-1322",["requiresAll"]={{["minimumStage"]=4,["questID"]=1322}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1322:description:1-107","1322:description:112-140","1322:description:142-187","1322:description:189-275","1322:description:277-326","1322:objective:1-62","1322:completion:1-73","1322:completion:78-105","1322:completion:107-158"},["questID"]=1322,["sourceHash"]="28990e5c758f9e70a1ffa3c0880cf8f73568a61693ba6f8d3b77c230ac3fa74c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Do’gol found writing beneath the burned surface. Acidic venom from Darkmist Cavern’s oversized spiders stripped away the obscuring residue, offering a chance to recover the hidden name."},{["episodeID"]="dustwallow-krog-blackened-shield-1323",["requiresAll"]={{["minimumStage"]=4,["questID"]=1323}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1323:description:1-63","1323:description:65-91","1323:description:96-155","1323:description:157-175","1323:description:177-193","1323:description:195-217","1323:objective:1-38","1323:completion:1-7","1323:completion:9-26","1323:completion:28-55","1323:completion:57-85","1323:completion:90-117","1323:completion:119-174"},["questID"]=1323,["sourceHash"]="69eae74eb73f8fe7259e8a88723d2b554669eb259251727899f891e43d4fe9b1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The acid nearly spoiled the clue, but the damaged rim appeared to read Mosarn. Krog recognized something familiar in the name without immediately placing it."},{["episodeID"]="dustwallow-krog-blackened-shield-1276",["requiresAll"]={{["minimumStage"]=4,["questID"]=1276}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1276:description:1-19","1276:description:21-75","1276:description:77-122","1276:description:127-203","1276:description:205-219","1276:description:224-280","1276:description:285-381","1276:objective:1-58","1276:completion:1-31","1276:completion:33-61","1276:completion:66-124","1276:completion:126-209"},["questID"]=1276,["sourceHash"]="6a831ef59203f801504a0410c2d861de121498c1cef338ad29db59138353997b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="He finally remembered Mosarn’s work for the Earthen Ring and sent the shield to Thunder Bluff. The respected smith confirmed making it but had crafted too many pieces to trace this one further. Its maker was known; who carried it to the inn, and why, remained unanswered."}},["grouping"]="Five stages trace a fire-blackened shield to its maker. The route does not identify the arsonist or resolve the Shady Rest investigation.",["quests"]={1251,1321,1322,1323,1276},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Name Beneath the Soot"},["elwynn-bernice-billy-necklace"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=85,["sourceHash"]="069252413ee8eaa0d4766d1558ddcaaf4e7e38854f6f41748ce8c0e84a7fd31e"},{["minimumStage"]=4,["questID"]=86,["sourceHash"]="983d939713bd87453c856439f788ec6681577e59eeba21f3bc4601c9b4f6109a"},{["minimumStage"]=4,["questID"]=84,["sourceHash"]="8b1d457505c58d6c3b96fd335694709eae90d2a1e3565c68523685d7e3ac98eb"},{["minimumStage"]=4,["questID"]=87,["sourceHash"]="6dbf979583a7a30b7ed5bef0f3a43b63f7cd49bbcf16ca1adaf7bc924089945e"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="elwynn-bernice-billy-necklace-85",["requiresAll"]={{["minimumStage"]=2,["questID"]=85}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"85:description:1-69","85:description:72-147","85:description:153-218","85:objective:1-25"},["questID"]=85,["sourceHash"]="069252413ee8eaa0d4766d1558ddcaaf4e7e38854f6f41748ce8c0e84a7fd31e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Bernice suspected Billy Maclure of taking her necklace. The boy denied being a thief but suggested that food might improve his memory, drawing a missing keepsake into the quarrel between neighboring farms."},{["episodeID"]="elwynn-bernice-billy-necklace-86",["requiresAll"]={{["minimumStage"]=2,["questID"]=86}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"86:description:1-61","86:description:64-156","86:description:162-309","86:objective:1-82"},["questID"]=86,["sourceHash"]="983d939713bd87453c856439f788ec6681577e59eeba21f3bc4601c9b4f6109a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Billy wanted Bernice’s pork pie. Boar meat from the surrounding fields would persuade the widow to cook it, giving the search a price that could be paid without settling the families’ argument."},{["episodeID"]="elwynn-bernice-billy-necklace-84",["requiresAll"]={{["minimumStage"]=2,["questID"]=84}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"84:description:1-12","84:description:15-92","84:objective:1-67"},["questID"]=84,["sourceHash"]="8b1d457505c58d6c3b96fd335694709eae90d2a1e3565c68523685d7e3ac98eb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Bernice supplied the pie with sharp words for its intended eater. Billy’s satisfaction promised the answer his earlier denial had withheld."},{["episodeID"]="elwynn-bernice-billy-necklace-87",["requiresAll"]={{["minimumStage"]=4,["questID"]=87}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"87:description:1-105","87:description:108-152","87:description:157-248","87:description:251-308","87:objective:1-79","87:completion:1-17","87:completion:19-44","87:completion:49-64","87:completion:66-117","87:completion:119-167","87:completion:169-175"},["questID"]=87,["sourceHash"]="6dbf979583a7a30b7ed5bef0f3a43b63f7cd49bbcf16ca1adaf7bc924089945e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="His story finally pointed to a large, gold-toothed kobold at Fargodeep. The necklace returned to Bernice, who answered with a keepsake of her own late husband. Recovery ended the search without explaining every part Billy had played."}},["grouping"]="Four linked household steps; Billy’s evasions do not prove an unseen theft or resolve the family feud.",["quests"]={85,86,84,87},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Pie for a Missing Necklace"},["elwynn-maclure-stonefield-lovers"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=106,["sourceHash"]="fb57860687693d6223cc69493caa74ad26abc32036c2d2cf15eed5b771f2f6f3"},{["minimumStage"]=4,["questID"]=111,["sourceHash"]="c9546ec2ac48fcfae6a5f0a54f1efa0c2f229c4c21620e9474d222ac63756282"},{["minimumStage"]=4,["questID"]=107,["sourceHash"]="37c7efbca4acfb494affec51dbecf9bf30ab92b8a9eb2379c079a90a6d437fcc"},{["minimumStage"]=4,["questID"]=112,["sourceHash"]="35ae5a7096f2b635adaaf82905a874605c0095890479d17db1a0857c643aff26"},{["minimumStage"]=4,["questID"]=114,["sourceHash"]="bffeb5787f11f8c3230b575e49ec4932628d3a5affbcf489c7121c9514701739"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="elwynn-maclure-stonefield-lovers-106",["requiresAll"]={{["minimumStage"]=2,["questID"]=106}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"106:description:1-15","106:description:18-95","106:description:98-174","106:description:179-228","106:description:231-318","106:objective:1-51"},["questID"]=106,["sourceHash"]="fb57860687693d6223cc69493caa74ad26abc32036c2d2cf15eed5b771f2f6f3",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Maybell loved Tommy Joe across a family feud that kept them apart. Her letter could cross the short distance between the farms when she could not safely make the visit herself."},{["episodeID"]="elwynn-maclure-stonefield-lovers-111",["requiresAll"]={{["minimumStage"]=2,["questID"]=111}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"111:description:1-32","111:description:35-102","111:description:107-142","111:objective:1-29"},["questID"]=111,["sourceHash"]="c9546ec2ac48fcfae6a5f0a54f1efa0c2f229c4c21620e9474d222ac63756282",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Tommy Joe turned to the person he trusted to find a way through the quarrel: his grandmother. Her help offered the lovers a private chance even while their families remained enemies."},{["episodeID"]="elwynn-maclure-stonefield-lovers-107",["requiresAll"]={{["minimumStage"]=2,["questID"]=107}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"107:description:1-64","107:description:69-100","107:description:103-152","107:objective:1-48"},["questID"]=107,["sourceHash"]="37c7efbca4acfb494affec51dbecf9bf30ab92b8a9eb2379c079a90a6d437fcc",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Gramma's answer lay beyond the farm. William Pestle at Goldshire's inn might know a potion capable of bringing the two together without confronting their households openly."},{["episodeID"]="elwynn-maclure-stonefield-lovers-112",["requiresAll"]={{["minimumStage"]=2,["questID"]=112}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"112:description:1-115","112:description:118-166","112:description:171-217","112:description:219-247","112:description:250-295","112:description:298-336","112:objective:1-59"},["questID"]=112,["sourceHash"]="35ae5a7096f2b635adaaf82905a874605c0095890479d17db1a0857c643aff26",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="William proposed invisibility liquor for Maybell, but the kindness needed crystal kelp first. Murlocs near Crystal Lake sometimes gathered it, drawing the lovers' small hope into the dangerous waters east of Goldshire."},{["episodeID"]="elwynn-maclure-stonefield-lovers-114",["requiresAll"]={{["minimumStage"]=4,["questID"]=114}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"114:description:1-47","114:description:50-103","114:objective:1-48","114:completion:10-99","114:completion:104-117","114:completion:119-196","114:completion:201-214","114:completion:216-232"},["questID"]=114,["sourceHash"]="bffeb5787f11f8c3230b575e49ec4932628d3a5affbcf489c7121c9514701739",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Maybell received the liquor with gratitude and misgivings about deceiving her family. She intended to drink it and slip away when the chance came. The delivered potion opened that possibility; the meeting itself remained ahead."}},["grouping"]="One attempted meeting between Maybell and Tommy Joe; no marriage, reconciliation or witnessed rendezvous is inferred.",["quests"]={106,111,107,112,114},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Letter Between Feuding Farms"},["elwynn-missing-river-guards"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=40,["sourceHash"]="f5295cb5c6126d2c3e426d083a8f5418a5f87b812b8c100ddf3a920406210708"},{["minimumStage"]=4,["questID"]=35,["sourceHash"]="ef045029a938d9921daaae837bfbcc0347c280d6ef5f166c235d7961e180bf2f"},{["minimumStage"]=4,["questID"]=37,["sourceHash"]="d0a9dfc56711b6dc547993366dda1b26d0be847b54eab017f9cef74ccdfcd67c"},{["minimumStage"]=4,["questID"]=45,["sourceHash"]="fd4d12750b23638e88fd7373764a666eeb04c853ab5e185bffeeb6430bcc3119"},{["minimumStage"]=4,["questID"]=71,["sourceHash"]="da5213d54c1e9de1064232f94f3dd76d3c6c58b3da7865b1d3d3a7aad74299a1"},{["minimumStage"]=4,["questID"]=39,["sourceHash"]="b0fa8b9f320acfe307a7e0a77eb35d1c804e9f7f6c2945f5bc9a4622e1a3196a"},{["minimumStage"]=4,["questID"]=59,["sourceHash"]="ef9fde6e26df99e59b262f94818f449f34cbafa19849ba3df9ae44229fa45207"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="elwynn-missing-river-guards-40",["requiresAll"]={{["minimumStage"]=2,["questID"]=40}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"40:description:1-42","40:description:45-143","40:description:148-227","40:description:230-278","40:description:283-359","40:objective:1-69"},["questID"]=40,["sourceHash"]="f5295cb5c6126d2c3e426d083a8f5418a5f87b812b8c100ddf3a920406210708",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Remy had watched murlocs move upstream, frightening fish and attacking travelers. Dughan's attention remained divided between gnolls and bandits, leaving a merchant's warning short of the proof needed to move troops."},{["episodeID"]="elwynn-missing-river-guards-35",["requiresAll"]={{["minimumStage"]=2,["questID"]=35}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"35:description:1-138","35:description:141-230","35:description:235-254","35:objective:1-52"},["questID"]=35,["sourceHash"]="ef045029a938d9921daaae837bfbcc0347c280d6ef5f166c235d7961e180bf2f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The marshal's answer was to seek Guard Thomas at the eastern bridge. A week's watch there could turn rumor into the military account Dughan required."},{["episodeID"]="elwynn-missing-river-guards-37",["requiresAll"]={{["minimumStage"]=2,["questID"]=37}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"37:description:1-116","37:description:119-180","37:description:185-235","37:description:237-253","37:objective:1-105"},["questID"]=37,["sourceHash"]="d0a9dfc56711b6dc547993366dda1b26d0be847b54eab017f9cef74ccdfcd67c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Thomas's report depended on two absent men. Rolf and Malakai had gone upriver days earlier and never returned, and the search now had to allow for finding their remains."},{["episodeID"]="elwynn-missing-river-guards-45",["requiresAll"]={{["minimumStage"]=2,["questID"]=45}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"45:description:1-109","45:description:112-181","45:description:186-219","45:objective:1-58"},["questID"]=45,["sourceHash"]="fd4d12750b23638e88fd7373764a666eeb04c853ab5e185bffeeb6430bcc3119",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The search continued along Stone Cairn Lake. Webbed footprints led east toward a murloc village, where the missing Rolf might be found or his death explained."},{["episodeID"]="elwynn-missing-river-guards-71",["requiresAll"]={{["minimumStage"]=2,["questID"]=71}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"71:description:1-132","71:objective:1-83"},["questID"]=71,["sourceHash"]="da5213d54c1e9de1064232f94f3dd76d3c6c58b3da7865b1d3d3a7aad74299a1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Two medallions could give Thomas the answer he had feared. Carrying them back meant replacing the uncertainty over his missing guards with evidence he could put in the report."},{["episodeID"]="elwynn-missing-river-guards-39",["requiresAll"]={{["minimumStage"]=2,["questID"]=39}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"39:description:1-153","39:description:158-238","39:objective:1-38"},["questID"]=39,["sourceHash"]="b0fa8b9f320acfe307a7e0a77eb35d1c804e9f7f6c2945f5bc9a4622e1a3196a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The message for Goldshire was no longer only a merchant's concern. Thomas reported the guards dead and the eastern troops unable to contain the murlocs, asking Dughan to find help despite the strain elsewhere."},{["episodeID"]="elwynn-missing-river-guards-59",["requiresAll"]={{["minimumStage"]=4,["questID"]=59}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"59:description:1-88","59:description:91-160","59:description:163-222","59:description:225-286","59:description:291-357","59:objective:1-48","59:completion:1-29","59:completion:31-76","59:completion:81-102","59:completion:104-137"},["questID"]=59,["sourceHash"]="ef9fde6e26df99e59b262f94818f449f34cbafa19849ba3df9ae44229fa45207",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Sara Timberlain accepted the armor marker awarded for service to Elwynn and offered a choice of protection. Recognition closed the journey between village, river and logging camp; it did not explain why the murlocs had first come upstream."}},["grouping"]="Merchant warning becomes military evidence, a report and recognition; the murlocs’ original motive remains unknown.",["quests"]={40,35,37,45,71,39,59},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Medallions Beside the Lake"},["felwood-kroshius-reanimation"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=7601,["sourceHash"]="86b330a1d9015b87118c473c23ad074533984b936527a51cceef3d3d7cfa1b66"},{["minimumStage"]=4,["questID"]=7602,["sourceHash"]="f91b407277cd7a0c2718d8793f9486a93dcc28e8c566ae247a37be7c38103162"},{["minimumStage"]=4,["questID"]=7603,["sourceHash"]="aab63b805b5a5daffeefa7cfd688cb0b05426bb68f3828a26a454ed8f9975ca7"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="felwood-kroshius-reanimation-7601",["requiresAll"]={{["minimumStage"]=2,["questID"]=7601}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"7601:description:1-149","7601:description:151-193","7601:description:195-237","7601:description:239-297","7601:description:299-379","7601:description:384-424","7601:objective:1-28"},["questID"]=7601,["sourceHash"]="86b330a1d9015b87118c473c23ad074533984b936527a51cceef3d3d7cfa1b66",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Niby promised infernal instruction for Kroshius's core, but the fallen creature had burned nearly out. Impsy would first have to supply a fire capable of awakening it."},{["episodeID"]="felwood-kroshius-reanimation-7602",["requiresAll"]={{["minimumStage"]=2,["questID"]=7602}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"7602:description:1-69","7602:description:71-132","7602:description:137-220","7602:description:225-399","7602:description:404-509","7602:objective:1-116","7602:objective:121-196","7602:objective:198-281","7602:objective:283-371","7602:objective:376-441"},["questID"]=7602,["sourceHash"]="f91b407277cd7a0c2718d8793f9486a93dcc28e8c566ae247a37be7c38103162",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The necessary essences lay with demons in three distant regions. Legashi satyrs, Jaedenar legionnaires and felguard sentries each supplied a part of the fire Impsy intended to combine."},{["episodeID"]="felwood-kroshius-reanimation-7603",["requiresAll"]={{["minimumStage"]=4,["questID"]=7603}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"7603:description:1-67","7603:description:69-113","7603:description:115-160","7603:description:165-226","7603:description:231-323","7603:objective:1-64","7603:objective:66-148","7603:objective:150-237","7603:objective:242-304","7603:completion:1-17","7603:completion:19-57","7603:completion:59-76","7603:completion:78-112"},["questID"]=7603,["sourceHash"]="aab63b805b5a5daffeefa7cfd688cb0b05426bb68f3828a26a454ed8f9975ca7",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The fire woke Kroshius in Shatter Scar Vale, allowing his defeat and the core's recovery. Niby honored the bargain, though his own impending conjuration left little time for ceremony."}},["grouping"]="The three-step reanimation and core recovery; Niby's later conjuration is not inferred as successful.",["quests"]={7601,7602,7603},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Fire for the Fallen Infernal"},["fenris-alaric"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=460,["sourceHash"]="428e6f01462674b8a1a6fde7f9751dd88183765026507e643eaea03405fbd50d"},{["minimumStage"]=4,["questID"]=461,["sourceHash"]="4a143a93e7917f4067e60ee7c00ca4f38e5376dd6d2f6f1647cbd6834ae04964"},{["minimumStage"]=4,["questID"]=491,["sourceHash"]="adbdd8d8291119316a5e7b848b0c4c8e81b02e81f0c248710c424e2297b25a4a"}}},["interpretation"]="Every listed leaf requires its own observed completion. This authored route clause is not a claim that the source previousID array encodes all-of gameplay prerequisites.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="fenris-alaric-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=460}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"460:description:1-31","460:description:34-38","460:description:41-58","460:description:63-131","460:description:134-262","460:description:265-331","460:description:333-378","460:description:383-409","460:description:412-501","460:objective:1-33"},["questID"]=460,["sourceHash"]="428e6f01462674b8a1a6fde7f9751dd88183765026507e643eaea03405fbd50d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Alaric's account exposed the cost of Thule's protection: unlife, beheading and a body he believed still buried in the keep. His request began with reunion rather than revenge."},{["episodeID"]="fenris-alaric-2",["requiresAll"]={{["minimumStage"]=4,["questID"]=461}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"461:description:1-98","461:description:101-146","461:description:149-162","461:description:167-240","461:description:245-277","461:description:280-306","461:objective:1-33","461:completion:1-24","461:completion:26-39","461:completion:41-148","461:completion:153-228","461:completion:233-250","461:completion:252-268"},["questID"]=461,["sourceHash"]="4a143a93e7917f4067e60ee7c00ca4f38e5376dd6d2f6f1647cbd6834ae04964",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The recovered servant opened a place known from the best days of his life. He chose to remain concealed there, asking only that the Rot Hides be kept from finding him."},{["episodeID"]="fenris-alaric-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=491}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"491:description:1-140","491:description:143-287","491:description:290-337","491:description:342-346","491:description:349-421","491:description:424-448","491:objective:1-77","491:completion:1-16","491:completion:18-42","491:completion:44-126","491:completion:131-203","491:completion:205-244","491:completion:249-273","491:completion:275-322"},["questID"]=491,["sourceHash"]="adbdd8d8291119316a5e7b848b0c4c8e81b02e81f0c248710c424e2297b25a4a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The room's relic restored another lost connection. Bethor recognized the apprentices' woven wand and the friendship Thule had broken, receiving an object he had believed lost."}},["grouping"]="Authored connected episodes with explicit source-stage gates; branches retained",["quests"]={460,461,491},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The Keeper of the Hidden Room"},["fordring-reminders"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=5542,["sourceHash"]="d069f8c79d2675c408689b93759d59ab8898c8bb5fd99b0bead5942b193b195d"},{["minimumStage"]=4,["questID"]=5543,["sourceHash"]="2c01ebfa6940e0663b4884d5e95e19111f5c171accffe9638a0ed1f2ec8e2801"},{["minimumStage"]=4,["questID"]=5544,["sourceHash"]="29b331552c49cb21ba21b97eeda9d042c10ac86378468d8691e5d146f8dd1c83"},{["minimumStage"]=4,["questID"]=5742,["sourceHash"]="697ddaa0a4cf87cf78547c469cb5d789dd43baba8ff23d8ce3b3aa751a90e501"},{["minimumStage"]=4,["questID"]=5781,["sourceHash"]="ef3aa0bb09208932143be71a304b6710ce6a9631fe329b248068e59eb7ea279a"},{["minimumStage"]=4,["questID"]=5845,["sourceHash"]="3c5cf5179f3921f883601e9f43d0b9803ea57699b15b8d643b0eb48819d15f54"},{["minimumStage"]=4,["questID"]=5846,["sourceHash"]="bb49f1cbecf5243da752892d6a532d52b8bb7ac49f629e0a2670a6058d239a09"},{["minimumStage"]=4,["questID"]=5861,["sourceHash"]="88684f4b91ab9d42e73d6edb34c5209dbb2967a21dd6b88b90853e38c90c931e"},{["minimumStage"]=4,["questID"]=5944,["sourceHash"]="e103e67caaf6a3b7ccdf3498990073c50032a82d8296667bb6cf841a2364922f"},{["minimumStage"]=4,["questID"]=5848,["sourceHash"]="fdf2906a551283f98f1c0c9c11fd8adc2f8c45137eb56bb57faa5ef665ce2a4e"},{["minimumStage"]=4,["questID"]=5862,["sourceHash"]="e68a9df5aee6d9e89b2b53b5cf742e161a7d3f1b77a13e427699d536e8b859cb"}}},["interpretation"]="The collected painting5848 and illusion/delivery5862 are explicit links between the authored portions.5944 is the tragic conclusion; completion must not imply Taelan survived.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="fordring-reminders-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=5742},{["minimumStage"]=2,["questID"]=5781}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"5742:description:1-29","5742:description:31-94","5742:objective:1-42"},["questID"]=5742,["sourceHash"]="697ddaa0a4cf87cf78547c469cb5d789dd43baba8ff23d8ce3b3aa751a90e501",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"5781:description:1-76","5781:description:81-148","5781:description:150-243","5781:description:248-317","5781:description:319-426","5781:description:431-493","5781:objective:1-112","5781:objective:114-173"},["questID"]=5781,["sourceHash"]="ef3aa0bb09208932143be71a304b6710ce6a9631fe329b248068e59eb7ea279a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Service around the old man's stead gave way to the Fordring story. The first reminder lay at a false grave, where a son had buried a toy because he was told his banished father had died."},{["episodeID"]="fordring-reminders-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=5845},{["minimumStage"]=2,["questID"]=5846}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"5845:description:1-72","5845:description:77-117","5845:description:119-186","5845:description:191-255","5845:description:260-369","5845:description:371-427","5845:description:432-498","5845:objective:1-113","5845:objective:115-174"},["questID"]=5845,["sourceHash"]="3c5cf5179f3921f883601e9f43d0b9803ea57699b15b8d643b0eb48819d15f54",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"5846:description:1-77","5846:description:79-182","5846:description:184-235","5846:description:237-364","5846:description:369-416","5846:description:421-508","5846:objective:1-142"},["questID"]=5846,["sourceHash"]="bb49f1cbecf5243da752892d6a532d52b8bb7ac49f629e0a2670a6058d239a09",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The search moved through what Taelan had abandoned and what Tirion treasured: a discarded standard and a painted moment beside wife and child. Honor and affection formed different arguments for reaching the son."},{["episodeID"]="fordring-reminders-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=5861}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"5861:description:1-49","5861:description:51-100","5861:description:105-160","5861:description:162-234","5861:description:239-332","5861:description:337-376","5861:description:378-457","5861:description:459-501","5861:objective:1-60","5861:objective:62-96"},["questID"]=5861,["sourceHash"]="88684f4b91ab9d42e73d6edb34c5209dbb2967a21dd6b88b90853e38c90c931e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Those reminders still could not cross a hostile camp openly. Myranda's deception was needed to carry a father's message past the son and soldiers who would otherwise attack."},{["episodeID"]="fordring-reminders-4",["requiresAll"]={{["minimumStage"]=4,["questID"]=5944}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"5944:description:1-56","5944:description:58-132","5944:description:134-243","5944:description:248-271","5944:description:273-309","5944:description:311-371","5944:description:373-414","5944:description:416-460","5944:description:465-492","5944:description:497-511","5944:objective:1-41","5944:completion:1-82","5944:completion:84-131","5944:completion:136-203","5944:completion:208-299","5944:completion:301-387","5944:completion:392-461","5944:completion:463-484","5944:completion:486-501"},["questID"]=5944,["sourceHash"]="e103e67caaf6a3b7ccdf3498990073c50032a82d8296667bb6cf841a2364922f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The attempt ended with Taelan's death and Tirion's grief. Tirion answered the loss with a vow to renew the Order under his own leadership."}},["grouping"]="Authored connected episodes with explicit source-stage gates; branches retained",["quests"]={5542,5543,5544,5742,5781,5845,5846,5861,5944},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The Son Beyond the False Grave"},["forever-northshire-stolen-library"]={["authored"]=true,["branchHandling"]={{["questID"]=92124,["relationship"]="OPTIONAL_INVENTORY_SIDEPATH",["requiredForCoreCompletion"]=false},{["questIDs"]={91772,91775,91777},["relationship"]="CANONICAL_TURNIN_REPLY_SOURCE_BLOCKED; RECORDED_FULFILLMENT_ONLY"}},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=91741,["sourceHash"]="da7a1d73f5ee239c0303044a76b91e5f90dbc7c646e5f6d1cf8a06d7a8df40e4"},{["minimumStage"]=4,["questID"]=91743,["sourceHash"]="cbc94586d0b73bbf375d195b7ff4d306da87f10d85032176a70672f02e4df707"},{["minimumStage"]=4,["questID"]=91745,["sourceHash"]="d053d991f39a5e7826d80c5b2f4930db4c14b6247879a7148d60f03ea42e2d01"},{["minimumStage"]=4,["questID"]=91752,["sourceHash"]="f8c506d43331bacc57dd9416bd1ea93b42c30d27b94233877a95ce297467cb7b"},{["minimumStage"]=4,["questID"]=91758,["sourceHash"]="7a8c7e96d34e8cd8f33b2a34f910c94818f902e6f81c9f2dbce96253fb0c2dfa"},{["minimumStage"]=4,["questID"]=91772,["sourceHash"]="713bb5d3f53311adf9439c90701c0e03b133db96efaebae9da90104a339dce8b"},{["minimumStage"]=4,["questID"]=91775,["sourceHash"]="dc3a7411625ff022ded0ffcf52f984ad3cbabd58e61bcf048252c11b7862674d"},{["minimumStage"]=4,["questID"]=91777,["sourceHash"]="07c5d945fd4c1a8de140e95d848da4b3c1e5e2b56063329415539a1684234582"}}},["interpretation"]="Observed fulfillment of all8named source stages; optional inventory is not required. No inferred group, killing blow, loot award or native prerequisite dependency.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="northshire-books-1",["requiresAll"]={{["minimumStage"]=4,["questID"]=91741}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"91741:completion:1-169"},["questID"]=91741,["sourceHash"]="da7a1d73f5ee239c0303044a76b91e5f90dbc7c646e5f6d1cf8a06d7a8df40e4",["sourceURL"]="https://www.foreverdb.app/en/forever/quests/91741/nibbled-on-book"}},["text"]="A damaged volume first brought the thefts to light. Paxton recognized a book that should have been on his shelves, but its return left the rest of his collection missing. What looked like a kobold's meal had opened a larger inquiry."},{["episodeID"]="northshire-books-2",["requiresAll"]={{["minimumStage"]=4,["questID"]=91743}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"91743:completion:1-208"},["questID"]=91743,["sourceHash"]="cbc94586d0b73bbf375d195b7ff4d306da87f10d85032176a70672f02e4df707",["sourceURL"]="https://www.foreverdb.app/en/forever/quests/91743/rascally-rodents"}},["text"]="Recovering more volumes changed the question. Paxton no longer thought the kobolds were simply eating them. The books had some other value to the thieves, and the abbey's librarian could not yet explain it."},{["episodeID"]="northshire-books-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=91745}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"91745:completion:1-182"},["questID"]=91745,["sourceHash"]="d053d991f39a5e7826d80c5b2f4930db4c14b6247879a7148d60f03ea42e2d01",["sourceURL"]="https://www.foreverdb.app/en/forever/quests/91745/mining-consultant"}},["text"]="Kelsey Fargo had seen the traffic outside Echo Ridge Mine: kobolds carrying books and shouting to one another. Her observations drew the search away from the library shelves and toward the creatures moving its contents through the mine."},{["episodeID"]="northshire-books-4",["requiresAll"]={{["minimumStage"]=4,["questID"]=91752}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"91752:completion:1-125"},["questID"]=91752,["sourceHash"]="f8c506d43331bacc57dd9416bd1ea93b42c30d27b94233877a95ce297467cb7b",["sourceURL"]="https://www.foreverdb.app/en/forever/quests/91752/the-big-picture"}},["text"]="Narf's sack of picture books passed into Marshal McBride's keeping. He promised to return it to Paxton. The recovery had connected the library's troubles with Northshire's defenders."},{["episodeID"]="northshire-books-5",["requiresAll"]={{["minimumStage"]=2,["questID"]=91758}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"91758:description:1-248","91758:objective:1-70"},["questID"]=91758,["sourceHash"]="7a8c7e96d34e8cd8f33b2a34f910c94818f902e6f81c9f2dbce96253fb0c2dfa",["sourceURL"]="https://www.foreverdb.app/en/forever/quests/91758/follow-that-kobold"}},["text"]="Word of a kobold leaving the mine with another sack kept the pursuit alive. McBride sought the help of Tordrin Sternblade, the newly arrived hunter trainer behind the abbey, to follow where the thief had gone."},{["episodeID"]="northshire-books-6",["requiresAll"]={{["minimumStage"]=2,["questID"]=91772}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"91772:description:1-225","91772:objective:1-111"},["questID"]=91772,["sourceHash"]="713bb5d3f53311adf9439c90701c0e03b133db96efaebae9da90104a339dce8b",["sourceURL"]="https://www.foreverdb.app/en/forever/quests/91772/shhh-we-re-hunting-kobolds"}},["text"]="Tordrin's tracking kit was meant to carry the investigation beyond Northshire. The trail and its findings were to be taken to Dughan in Goldshire, where a wider search could continue."},{["episodeID"]="northshire-books-7",["requiresAll"]={{["minimumStage"]=2,["questID"]=91775}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"91775:description:1-277","91775:objective:1-90"},["questID"]=91775,["sourceHash"]="dc3a7411625ff022ded0ffcf52f984ad3cbabd58e61bcf048252c11b7862674d",["sourceURL"]="https://www.foreverdb.app/en/forever/quests/91775/book-return"}},["text"]="Dughan's concern was no longer only the number of books missing. A guide to elementals might teach even a kobold to summon a servant. Recovering it from Fargodeep meant keeping the library's knowledge from becoming a weapon."},{["episodeID"]="northshire-books-8",["requiresAll"]={{["minimumStage"]=2,["questID"]=91777}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"91777:description:1-259","91777:objective:1-131"},["questID"]=91777,["sourceHash"]="07c5d945fd4c1a8de140e95d848da4b3c1e5e2b56063329415539a1684234582",["sourceURL"]="https://www.foreverdb.app/en/forever/quests/91777/rare-books"}},["text"]="The remaining works were believed to be at Jasperlode: one on geomancy and another explaining arcane magic. If an apprentice had managed to summon an elemental, Dughan feared what a master might do with more instruction. The search for Paxton's books had become a search for dangerous knowledge."},{["episodeID"]="northshire-books-9",["requiresAll"]={{["minimumStage"]=4,["questID"]=91741},{["minimumStage"]=4,["questID"]=91743},{["minimumStage"]=4,["questID"]=91745},{["minimumStage"]=4,["questID"]=91752},{["minimumStage"]=4,["questID"]=91758},{["minimumStage"]=4,["questID"]=91772},{["minimumStage"]=4,["questID"]=91775},{["minimumStage"]=4,["questID"]=91777}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"91741:completion:1-169"},["questID"]=91741,["sourceHash"]="da7a1d73f5ee239c0303044a76b91e5f90dbc7c646e5f6d1cf8a06d7a8df40e4",["sourceURL"]="https://www.foreverdb.app/en/forever/quests/91741/nibbled-on-book"},{["atomIDs"]={"91743:completion:1-208"},["questID"]=91743,["sourceHash"]="cbc94586d0b73bbf375d195b7ff4d306da87f10d85032176a70672f02e4df707",["sourceURL"]="https://www.foreverdb.app/en/forever/quests/91743/rascally-rodents"},{["atomIDs"]={"91745:completion:1-182"},["questID"]=91745,["sourceHash"]="d053d991f39a5e7826d80c5b2f4930db4c14b6247879a7148d60f03ea42e2d01",["sourceURL"]="https://www.foreverdb.app/en/forever/quests/91745/mining-consultant"},{["atomIDs"]={"91752:completion:1-125"},["questID"]=91752,["sourceHash"]="f8c506d43331bacc57dd9416bd1ea93b42c30d27b94233877a95ce297467cb7b",["sourceURL"]="https://www.foreverdb.app/en/forever/quests/91752/the-big-picture"},{["atomIDs"]={"91758:completion:1-90"},["questID"]=91758,["sourceHash"]="7a8c7e96d34e8cd8f33b2a34f910c94818f902e6f81c9f2dbce96253fb0c2dfa",["sourceURL"]="https://www.foreverdb.app/en/forever/quests/91758/follow-that-kobold"},{["atomIDs"]={"91772:objective:1-111"},["questID"]=91772,["sourceHash"]="713bb5d3f53311adf9439c90701c0e03b133db96efaebae9da90104a339dce8b",["sourceURL"]="https://www.foreverdb.app/en/forever/quests/91772/shhh-we-re-hunting-kobolds"},{["atomIDs"]={"91775:objective:1-90"},["questID"]=91775,["sourceHash"]="dc3a7411625ff022ded0ffcf52f984ad3cbabd58e61bcf048252c11b7862674d",["sourceURL"]="https://www.foreverdb.app/en/forever/quests/91775/book-return"},{["atomIDs"]={"91777:objective:1-131"},["questID"]=91777,["sourceHash"]="07c5d945fd4c1a8de140e95d848da4b3c1e5e2b56063329415539a1684234582",["sourceURL"]="https://www.foreverdb.app/en/forever/quests/91777/rare-books"}},["text"]="The two remaining works were returned to Paxton. From a damaged volume at Northshire to the mines beyond Goldshire, the investigation had followed the stolen library's growing danger. Its final delivery brought those books back to their keeper."}},["grouping"]="Source-ordered narrative investigation across Northshire and Goldshire; visual chain display is not converted to native unlock prerequisites.",["quests"]={91741,91743,91745,91752,91758,91772,91775,91777},["referenceStatus"]="PUBLIC_FOREVER_QUEST_ACCOUNTS; PER_FIELD_BUILD_AND_NATIVE_PREREQUISITES_UNVERIFIED",["sourceConflict"]=false,["title"]="The Stolen Library"},["gnomeregan-togglevolt-cure"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=2927,["sourceHash"]="4c26d2a0d5365e5e27429f907691de4bb821661cd457b62bdcc4e2b1157a16d1"},{["minimumStage"]=4,["questID"]=2926,["sourceHash"]="0abd98d52add0a7cec943974f9830aa4653f75c22c53cb97f8ffd54319b181f0"},{["minimumStage"]=4,["questID"]=2962,["sourceHash"]="c598c2308c1108357b708900b47ef3b39689bbfcfbfa59a75a2c0aa07579cfff"}}},["interpretation"]="Requires observed fulfillment of this source-backed route, not a larger military victory, restored city or successful experiment.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="togglevolt-gnoarn",["requiresAll"]={{["minimumStage"]=2,["questID"]=2927}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"2927:description:1-42","2927:description:44-60","2927:description:62-135","2927:description:137-195","2927:description:200-235","2927:description:240-287","2927:description:292-321","2927:description:323-372","2927:description:374-411","2927:description:413-464","2927:objective:1-40"},["questID"]=2927,["sourceHash"]="4c26d2a0d5365e5e27429f907691de4bb821661cd457b62bdcc4e2b1157a16d1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="For Gnoarn, the disaster at Gnomeregan was both a city's loss and a painfully personal memory. Radiation had taken his remarkable hair; the troggs bore the weight of his anger. Ozzie Togglevolt and Razzle offered a more practical hope: a solution still being worked out in Kharanos."},{["episodeID"]="togglevolt-first-sample",["requiresAll"]={{["minimumStage"]=2,["questID"]=2926}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"2926:description:1-164","2926:description:169-275","2926:description:277-304","2926:description:306-436","2926:description:438-494","2926:objective:1-116","2926:objective:118-179"},["questID"]=2926,["sourceHash"]="0abd98d52add0a7cec943974f9830aa4653f75c22c53cb97f8ffd54319b181f0",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Ozzie's proposal needed material from the very sickness it sought to treat. Fallout drawn from Gnomeregan's irradiated troggs would supply the first sample. Until it was tested, even the inventors could not say whether they were approaching a cure or something closer to potent rum."},{["episodeID"]="togglevolt-stronger-sample",["requiresAll"]={{["minimumStage"]=2,["questID"]=2962}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"2962:description:1-70","2962:description:75-109","2962:description:111-184","2962:description:186-284","2962:description:286-345","2962:description:347-410","2962:description:412-503","2962:objective:1-69","2962:objective:71-138","2962:objective:143-227"},["questID"]=2962,["sourceHash"]="c598c2308c1108357b708900b47ef3b39689bbfcfbfa59a75a2c0aa07579cfff",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Ozzie found the earlier material too weak and impure. He now wanted fallout from irradiated slimes, lurkers and horrors inside Gnomeregan. The stronger substance was harder to contain, turning the return to Kharanos into a race against its instability."},{["episodeID"]="togglevolt-second-trial",["requiresAll"]={{["minimumStage"]=4,["questID"]=2962}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"2962:completion:1-67","2962:completion:69-112"},["questID"]=2962,["sourceHash"]="c598c2308c1108357b708900b47ef3b39689bbfcfbfa59a75a2c0aa07579cfff",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The stronger fallout reached Ozzie, who first noted that the courier still had every limb. Another trial could begin. A filled phial was a step in the search, rather than an answer to everything Gnomeregan had suffered."}},["grouping"]="Gnoarn referral, first irradiated sample, stronger replacement sample; ends at preparation for a trial, not a proven cure.",["quests"]={2927,2926,2962},["referenceStatus"]="HISTORICAL_STAGE_SOURCE_CORROBORATED_BY_PUBLISHER_BETA_ACCOUNTS; NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Cure in the Green Glow"},["gorge-kalaran"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=3442,["sourceHash"]="435ce67d3925e68b316076b435242a88d000194838fc0f4933d67a2b56cad417"},{["minimumStage"]=4,["questID"]=3443,["sourceHash"]="920954f6a931ab1faabc1effae90b5bf5d37a115b14d5216481eb92df340ee9c"},{["minimumStage"]=4,["questID"]=3452,["sourceHash"]="1d84d249c1dfafc825aef1775ef154a68611a8af8b39c224377ad37612915e06"},{["minimumStage"]=4,["questID"]=3453,["sourceHash"]="1f00eda01c09df8eac04d9f16267765a6a0b00b1ca642f82166254d5f0acb4f6"},{["minimumStage"]=4,["questID"]=3454,["sourceHash"]="6e920b0c89c8801149296f00fded7565309942f9a3b8375ef410b6a6fe7c7151"},{["minimumStage"]=4,["questID"]=3462,["sourceHash"]="dbae2a5bae885e51c4d9afabeed4abddcee4b53eb0a5ac76620bb0d10a296e73"},{["minimumStage"]=4,["questID"]=3463,["sourceHash"]="c0c1eeb82ec2e7702867041712be138e307f8b0affeff55980c2a13c3404518f"}}},["interpretation"]="The defined outcome is the four-tower operation at3463.3481 is a following reward chest and4022 begins another linked undertaking; neither is claimed completed here.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="gorge-kalaran-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=3442}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"3442:description:1-37","3442:description:42-113","3442:description:118-209","3442:description:214-268","3442:description:270-310","3442:description:315-409","3442:description:414-482","3442:objective:1-94"},["questID"]=3442,["sourceHash"]="435ce67d3925e68b316076b435242a88d000194838fc0f4933d67a2b56cad417",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Kalaran proposed four fires as the opening of an offensive. The weapon for that plan had to be made from the same dangerous landscape before any tower could be reached."},{["episodeID"]="gorge-kalaran-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=3443},{["minimumStage"]=2,["questID"]=3452}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"3443:description:1-62","3443:description:64-100","3443:description:105-218","3443:description:220-312","3443:objective:1-52"},["questID"]=3443,["sourceHash"]="920954f6a931ab1faabc1effae90b5bf5d37a115b14d5216481eb92df340ee9c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"3452:description:1-42","3452:description:47-134","3452:description:136-212","3452:description:214-297","3452:description:299-406","3452:objective:1-58"},["questID"]=3452,["sourceHash"]="1d84d249c1dfafc825aef1775ef154a68611a8af8b39c224377ad37612915e06",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Dark Iron thorium could supply a shaft, while a cult symbol might provide the casing's enchantment. Kalaran sought the two materials to complete the torch around the flame."},{["episodeID"]="gorge-kalaran-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=3454},{["minimumStage"]=4,["questID"]=3462},{["minimumStage"]=4,["questID"]=3463}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"3454:description:1-41","3454:description:43-64","3454:objective:1-30","3454:completion:1-87"},["questID"]=3454,["sourceHash"]="6e920b0c89c8801149296f00fded7565309942f9a3b8375ef410b6a6fe7c7151",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"3462:description:1-37","3462:description:39-109","3462:objective:1-27","3462:completion:1-37"},["questID"]=3462,["sourceHash"]="dbae2a5bae885e51c4d9afabeed4abddcee4b53eb0a5ac76620bb0d10a296e73",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"3463:description:1-16","3463:description:18-194","3463:description:199-324","3463:description:329-415","3463:description:417-465","3463:objective:1-122","3463:completion:1-15","3463:completion:17-42"},["questID"]=3463,["sourceHash"]="c0c1eeb82ec2e7702867041712be138e307f8b0affeff55980c2a13c3404518f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The torch was taken and Maltrake's directions carried out inside all four defenses. His plan denied their use by fire rather than destroying towers he said could never be destroyed."}},["grouping"]="Authored connected episodes with explicit source-stage gates; branches retained",["quests"]={3442,3443,3452,3453,3454,3462,3463},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The Torch and the Towers"},["hakkar-six-tablets-and-egg"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=3520,["sourceHash"]="79a7cd0a92add0e26661b2830affb43f76001f4da25bb98edff5c26552762952"},{["minimumStage"]=4,["questID"]=3527,["sourceHash"]="4fa7b05044c3f512d4097904f04f71689e60c21d5c8fef1366fd2e2ab017a9d5"},{["minimumStage"]=4,["questID"]=4787,["sourceHash"]="2a28491591be75f7ab10dbf673c8001e7215170c3153e9c9efc1a2d145dceab6"},{["minimumStage"]=4,["questID"]=3528,["sourceHash"]="60fae1411ca356f80705bbf72d6a4a937532ab7fee3087e91d89180445485c6b"},{["minimumStage"]=4,["questID"]=5065,["sourceHash"]="324d16c5f42a50a7fae1bffa5ad9ed687a5918e50892e245eb2e97267f28342a"},{["minimumStage"]=4,["questID"]=4788,["sourceHash"]="533bac36a0d3a4eec403b1ad794f18e71cc1a18bcdf7a006e9aa0cbf898a30da"},{["minimumStage"]=4,["questID"]=8181,["sourceHash"]="7df296cab5525fe01bba308bb1e277e5d57a3984b97c1eba9e0793e89a74ab10"},{["minimumStage"]=4,["questID"]=8182,["sourceHash"]="ce76b4cea7eb5473b40fa35ecf7cdc049bc52f47a49fe10101c76485b9b80a9e"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="hakkar-six-tablets-and-egg-3520",["requiresAll"]={{["minimumStage"]=2,["questID"]=3520}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"3520:description:1-53","3520:description:56-132","3520:description:137-177","3520:description:180-290","3520:description:293-337","3520:description:340-380","3520:description:385-502","3520:objective:1-94"},["questID"]=3520,["sourceHash"]="79a7cd0a92add0e26661b2830affb43f76001f4da25bb98edff5c26552762952",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Yeh’kinya began with the spirits of Feralas’s vale screechers, claiming an ancient kinship linked them to a forgotten god. His bramble wand was to draw out their spirits and gather the essence for further study."},{["episodeID"]="hakkar-six-tablets-and-egg-3527",["requiresAll"]={{["minimumStage"]=2,["questID"]=3527}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"3527:description:1-85","3527:description:88-178","3527:description:183-212","3527:description:217-281","3527:description:284-368","3527:description:373-462","3527:description:467-510","3527:objective:1-68"},["questID"]=3527,["sourceHash"]="4fa7b05044c3f512d4097904f04f71689e60c21d5c8fef1366fd2e2ab017a9d5",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The inquiry acquired a name: Hakkar the Soulflayer. Yeh’kinya said the prophecy of Mosh’aru described how to contain his essence. Its first two tablets lay in Zul’Farrak, one with Theka and another with Velratha near Gahz’rilla’s pool."},{["episodeID"]="hakkar-six-tablets-and-egg-4787",["requiresAll"]={{["minimumStage"]=2,["questID"]=4787}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"4787:description:1-50","4787:description:53-159","4787:description:162-221","4787:description:226-254","4787:description:257-382","4787:objective:1-46"},["questID"]=4787,["sourceHash"]="2a28491591be75f7ab10dbf673c8001e7215170c3153e9c9efc1a2d145dceab6",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The tablets pointed to an egg from the age of the great troll empires. Yeh’kinya called it a vessel that might keep the world safe, hidden in a cave behind the amphitheater high in Jintha’Alor."},{["episodeID"]="hakkar-six-tablets-and-egg-3528",["requiresAll"]={{["minimumStage"]=4,["questID"]=3528}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"3528:description:1-62","3528:description:67-154","3528:description:157-200","3528:description:205-241","3528:description:244-370","3528:description:373-442","3528:description:447-505","3528:objective:1-55","3528:completion:1-41","3528:completion:43-75","3528:completion:77-110","3528:completion:115-195","3528:completion:197-267","3528:completion:272-308","3528:completion:310-394"},["questID"]=3528,["sourceHash"]="60fae1411ca356f80705bbf72d6a4a937532ab7fee3087e91d89180445485c6b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The vessel returned filled from the Sunken Temple. Yeh’kinya accepted Hakkar’s stirring essence and promised to keep it from evil hands, though his own account admitted fear of what a reborn god might do."},{["episodeID"]="hakkar-six-tablets-and-egg-5065",["requiresAll"]={{["minimumStage"]=2,["questID"]=5065}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"5065:description:1-53","5065:description:56-166","5065:description:169-247","5065:description:250-253","5065:description:258-320","5065:description:325-370","5065:description:373-438","5065:description:440-471","5065:objective:1-78"},["questID"]=5065,["sourceHash"]="324d16c5f42a50a7fae1bffa5ad9ed687a5918e50892e245eb2e97267f28342a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Ironboot challenged the assurance of safety. Mosh’aru’s prophecy had six tablets, not two, and the missing words might change the meaning of everything gathered so far. The third and fourth lay with the Mossflayers in the Eastern Plaguelands."},{["episodeID"]="hakkar-six-tablets-and-egg-4788",["requiresAll"]={{["minimumStage"]=2,["questID"]=4788}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"4788:description:1-94","4788:description:97-185","4788:description:188-274","4788:description:279-292","4788:description:295-340","4788:objective:1-77"},["questID"]=4788,["sourceHash"]="533bac36a0d3a4eec403b1ad794f18e71cc1a18bcdf7a006e9aa0cbf898a30da",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="While Ironboot studied those fragments, the search continued to the Smolderthorn trolls in Blackrock Spire for the final pair. Recovering the whole prophecy now mattered more than trusting the explanation that had begun the work."},{["episodeID"]="hakkar-six-tablets-and-egg-8181",["requiresAll"]={{["minimumStage"]=4,["questID"]=8181}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"8181:description:1-57","8181:description:60-163","8181:description:166-237","8181:description:240-268","8181:description:273-316","8181:description:319-371","8181:objective:1-21","8181:completion:1-106","8181:completion:109-135","8181:completion:140-149","8181:completion:152-185","8181:completion:188-241","8181:completion:243-289","8181:completion:292-303","8181:completion:306-342","8181:completion:347-360","8181:completion:363-410"},["questID"]=8181,["sourceHash"]="7df296cab5525fe01bba308bb1e277e5d57a3984b97c1eba9e0793e89a74ab10",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The complete text revealed that the egg could restore Hakkar rather than imprison him. Confronted with that discovery, Yeh’kinya abandoned his disguise of concern and proclaimed the Soulflayer’s return in Zul’Gurub. The promised safeguard had served the danger it claimed to contain."},{["episodeID"]="hakkar-six-tablets-and-egg-8182",["requiresAll"]={{["minimumStage"]=4,["questID"]=8182}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"8182:description:1-30","8182:description:33-147","8182:description:150-230","8182:description:235-321","8182:description:324-420","8182:description:423-495","8182:objective:1-36","8182:completion:1-42","8182:completion:45-172","8182:completion:177-299"},["questID"]=8182,["sourceHash"]="ce76b4cea7eb5473b40fa35ecf7cdc049bc52f47a49fe10101c76485b9b80a9e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Ironboot’s warning led to Molthor and the Zandalarian camp on Yojamba Isle. They offered knowledge for the struggle ahead. The gathering of spirits, tablets and egg had become a call to resist Hakkar, with the confrontation itself still beyond this account."}},["grouping"]="Eight retained steps connect Feralas, ZulFarrak, JinthaAlor, the Sunken Temple, Mossflayer territory, Blackrock Spire and Yojamba; the ending is a warning and alliance, never an inferred Hakkar kill.",["quests"]={3520,3527,4787,3528,5065,4788,8181,8182},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Egg That Held More Than a Secret"},["hammerfall-gormul"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=655,["sourceHash"]="21b0adeffa1a0dc36b715971724ff8f18a7e258b5ec0832c7438d237c169af83"},{["minimumStage"]=4,["questID"]=672,["sourceHash"]="a016075743568389b8205f28fe1bbad19db338c33e6eea32a360adea11d7e031"},{["minimumStage"]=4,["questID"]=674,["sourceHash"]="743431e9575c0242419c11b9ed18cec6934e59733194d7c0870549e245784442"},{["minimumStage"]=4,["questID"]=675,["sourceHash"]="586058fbe5f55de67cb151fa649cc8316542abd29ac13214592bd2a8c069877c"},{["minimumStage"]=4,["questID"]=701,["sourceHash"]="51b93bf342c0285922dfb8cd1ec63ef75b78108293f9fb1aa38dbcc9bd494960"},{["minimumStage"]=4,["questID"]=702,["sourceHash"]="80a839797b70ffe7f71827c4e35a307778d4112c811887b74a7903a6f89e6ee9"},{["minimumStage"]=4,["questID"]=847,["sourceHash"]="5934459767c68e3787b186d3ef03ff8e2b3db33809331cc7ff35b92ed4b86594"}}},["interpretation"]="Every listed leaf requires its own observed completion. This authored route clause is not a claim that the source previousID array encodes all-of gameplay prerequisites.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="hammerfall-gormul-1",["requiresAll"]={{["minimumStage"]=4,["questID"]=655},{["minimumStage"]=2,["questID"]=672}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"655:description:1-42","655:description:44-125","655:description:127-148","655:description:150-172","655:description:174-231","655:description:236-244","655:description:246-260","655:description:262-323","655:description:325-398","655:description:400-418","655:description:420-439","655:description:441-461","655:objective:1-33","655:completion:1-25","655:completion:27-111","655:completion:116-258","655:completion:260-383"},["questID"]=655,["sourceHash"]="21b0adeffa1a0dc36b715971724ff8f18a7e258b5ec0832c7438d237c169af83",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"672:description:1-133","672:description:138-217","672:description:219-233","672:description:235-242","672:description:244-320","672:description:322-339","672:description:344-387","672:description:389-444","672:objective:1-104"},["questID"]=672,["sourceHash"]="a016075743568389b8205f28fe1bbad19db338c33e6eea32a360adea11d7e031",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Tor'gan traced Gor'mul's despair to Doomhammer's death and the years spent wandering after the camp's liberation. Stories of Orgrimmar and Thrall had failed to move him, so Tor'gan turned toward a demonstration of shamanic power."},{["episodeID"]="hammerfall-gormul-2",["requiresAll"]={{["minimumStage"]=4,["questID"]=674},{["minimumStage"]=4,["questID"]=675}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"674:description:1-139","674:objective:1-40","674:completion:1-13","674:completion:15-28","674:completion:30-63","674:completion:65-110"},["questID"]=674,["sourceHash"]="743431e9575c0242419c11b9ed18cec6934e59733194d7c0870549e245784442",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"675:description:1-44","675:description:49-76","675:description:78-81","675:description:83-140","675:description:142-218","675:description:220-252","675:objective:1-19","675:completion:1-23","675:completion:25-140","675:completion:142-212"},["questID"]=675,["sourceHash"]="586058fbe5f55de67cb151fa649cc8316542abd29ac13214592bd2a8c069877c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The first amulet failed. Gor'mul saw only polished bone, and Tor'gan accepted that the demonstration had been too weak while refusing to abandon the attempt."},{["episodeID"]="hammerfall-gormul-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=701},{["minimumStage"]=2,["questID"]=702}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"701:description:1-116","701:description:118-244","701:description:249-307","701:objective:1-65"},["questID"]=701,["sourceHash"]="51b93bf342c0285922dfb8cd1ec63ef75b78108293f9fb1aa38dbcc9bd494960",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"702:description:1-75","702:description:77-148","702:description:150-303","702:objective:1-30"},["questID"]=702,["sourceHash"]="80a839797b70ffe7f71827c4e35a307778d4112c811887b74a7903a6f89e6ee9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The second working drew on raptor hearts and an orb rather than another argument. Tor'gan hoped an encounter with shamanic power would create the opening that stories could not."},{["episodeID"]="hammerfall-gormul-4",["requiresAll"]={{["minimumStage"]=4,["questID"]=847}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"847:description:1-7","847:description:9-22","847:description:24-86","847:description:88-117","847:description:119-158","847:description:160-178","847:description:180-215","847:objective:1-19","847:completion:1-58","847:completion:60-137","847:completion:139-184"},["questID"]=847,["sourceHash"]="5934459767c68e3787b186d3ef03ff8e2b3db33809331cc7ff35b92ed4b86594",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Gor'mul agreed to listen for the time being. Tor'gan planned to speak after the enchantment faded, leaving the hard conversation ahead rather than declaring every wound healed."}},["grouping"]="Authored connected episodes with explicit source-stage gates; branches retained",["quests"]={655,672,674,675,701,702,847},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="A Warrior Who Would Listen"},["hillsbrad-captives-and-pendant"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=498,["sourceHash"]="2811d557acd056545ecc6d3cfc8ede8fe612b64533fe4b83c18fe1df8e2d9f24"},{["minimumStage"]=4,["questID"]=533,["sourceHash"]="29ce08787210d10fc888bbf8133feba517866917e5dd2aab88a8461706bbf67c"},{["minimumStage"]=4,["questID"]=503,["sourceHash"]="f3a6b4cc94fd3fda4f9e3a06d85adb29f1ed8271c322e0c496c24b9c08fc9b5c"},{["minimumStage"]=4,["questID"]=506,["sourceHash"]="39e672ae61ceb220eeeb796e202c2fda501957da2b8901a5fd0f79cd9a579671"},{["minimumStage"]=4,["questID"]=507,["sourceHash"]="60b7d1f63fff2a0de19e111f3748f38e4e0e878243d7ffab9cd56021e18c0107"},{["minimumStage"]=4,["questID"]=508,["sourceHash"]="153863ce03d1cbe18ae05455d5bd7a0e56e2b62f1d42446f573f910c1b0441fd"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="hillsbrad-captives-and-pendant-498",["requiresAll"]={{["minimumStage"]=4,["questID"]=498}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"498:description:1-134","498:description:139-244","498:description:246-313","498:description:315-370","498:description:375-428","498:description:430-498","498:objective:1-78","498:completion:1-65","498:completion:67-82","498:completion:87-162","498:completion:164-195","498:completion:197-240","498:completion:245-296"},["questID"]=498,["sourceHash"]="2811d557acd056545ecc6d3cfc8ede8fe612b64533fe4b83c18fe1df8e2d9f24",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Krusk’s expedition to Durnholde had ended in captivity instead of recovering the object the Warchief wanted. Drull and Tog’thar were freed, but their leader Gol’dir had been moved elsewhere, leaving the rescue unfinished."},{["episodeID"]="hillsbrad-captives-and-pendant-533",["requiresAll"]={{["minimumStage"]=4,["questID"]=533}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"533:description:1-80","533:description:82-218","533:description:223-298","533:objective:1-74","533:completion:1-45","533:completion:47-191"},["questID"]=533,["sourceHash"]="29ce08787210d10fc888bbf8133feba517866917e5dd2aab88a8461706bbf67c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Rumors drew the search toward a Syndicate camp north of Tarren Mill. Documents gathered there finally gave Krusk a place to seek Gol’dir rather than another uncertain trail."},{["episodeID"]="hillsbrad-captives-and-pendant-503",["requiresAll"]={{["minimumStage"]=4,["questID"]=503}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"503:description:1-151","503:description:153-208","503:objective:1-49","503:completion:1-14","503:completion:16-127","503:completion:129-220","503:completion:225-269","503:completion:271-355"},["questID"]=503,["sourceHash"]="f3a6b4cc94fd3fda4f9e3a06d85adb29f1ed8271c322e0c496c24b9c08fc9b5c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Gol’dir described the forced labor of his captivity and the expedition he had led from Durotar. His first concern after being found was not his own suffering, but information that needed to reach the remaining warriors."},{["episodeID"]="hillsbrad-captives-and-pendant-506",["requiresAll"]={{["minimumStage"]=2,["questID"]=506}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"506:description:1-64","506:description:66-133","506:description:135-285","506:description:290-367","506:description:369-421","506:description:426-495","506:objective:1-67"},["questID"]=506,["sourceHash"]="39e672ae61ceb220eeeb796e202c2fda501957da2b8901a5fd0f79cd9a579671",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Aliden Perenolde had visited Gol’dir with plans to enslave opposing orcs, following the example of his father and Blackmoore. More immediately, the woman accompanying him wore the pendant sought by the Warchief."},{["episodeID"]="hillsbrad-captives-and-pendant-507",["requiresAll"]={{["minimumStage"]=4,["questID"]=507}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"507:description:1-79","507:description:81-156","507:description:158-244","507:objective:1-80","507:completion:1-28","507:completion:30-93","507:completion:95-103","507:completion:105-113"},["questID"]=507,["sourceHash"]="60b7d1f63fff2a0de19e111f3748f38e4e0e878243d7ffab9cd56021e18c0107",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Krusk ordered the attack on Aliden’s manor by Lordamere Lake. There Elysa begged for mercy, saying she had been held against her will and had intended no harm to the orcs."},{["episodeID"]="hillsbrad-captives-and-pendant-508",["requiresAll"]={{["minimumStage"]=4,["questID"]=508}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"508:description:1-12","508:description:14-41","508:description:43-50","508:description:52-77","508:description:79-115","508:objective:1-49","508:completion:1-77","508:completion:79-157","508:completion:159-235"},["questID"]=508,["sourceHash"]="153863ce03d1cbe18ae05455d5bd7a0e56e2b62f1d42446f573f910c1b0441fd",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Elysa surrendered the pendant and asked only to be left in peace. Krusk received it with thanks, still puzzled that the Warchief had committed so much effort to so small an object."}},["grouping"]="Rescue, Syndicate investigation and pendant handover; Elysa’s account remains attributed and no later meeting with Thrall is invented.",["quests"]={498,533,503,506,507,508},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Pendant at the End of the Search"},["hillsbrad-lydon-tainted-keg"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=509,["sourceHash"]="853940e629ed6d4972616dadbb93f63947720d7ceedfb00d2a5086a1f9e4b6e9"},{["minimumStage"]=4,["questID"]=513,["sourceHash"]="68a4d35365d2ec3c2962a0a5ed2af4ecfb729efd09f50b2c7c95eb9080b5cb3e"},{["minimumStage"]=4,["questID"]=515,["sourceHash"]="7119e748b112968127c7715bd16565aa1ba49852ac0b6d857e98932247ce1e81"},{["minimumStage"]=4,["questID"]=517,["sourceHash"]="bd325734c6b4cc6e0bee5d989538931266362255391bb95a8a2ff0029b09de43"},{["minimumStage"]=4,["questID"]=524,["sourceHash"]="64e93d8c61448745b39e78be36de34b00f5765502273217ec6e79fc241025f43"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="hillsbrad-lydon-tainted-keg-509",["requiresAll"]={{["minimumStage"]=2,["questID"]=509}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"509:description:1-39","509:description:41-119","509:description:122-164","509:description:169-319","509:description:324-433","509:description:435-503","509:objective:1-61"},["questID"]=509,["sourceHash"]="853940e629ed6d4972616dadbb93f63947720d7ceedfb00d2a5086a1f9e4b6e9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Lydon’s next elixir began with Mudsnout blossoms from Nethander Stead. He spoke openly of hastening the deaths of humans and Scourge alike, finding amusement in the work of disease."},{["episodeID"]="hillsbrad-lydon-tainted-keg-513",["requiresAll"]={{["minimumStage"]=4,["questID"]=513}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"513:description:1-118","513:description:123-171","513:description:174-318","513:description:323-403","513:objective:1-75","513:completion:1-26","513:completion:28-53","513:completion:58-155","513:completion:160-198","513:completion:200-248","513:completion:250-278","513:completion:280-370"},["questID"]=513,["sourceHash"]="68a4d35365d2ec3c2962a0a5ed2af4ecfb729efd09f50b2c7c95eb9080b5cb3e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The blossoms became a composite sent to Faranell in the Undercity. The master apothecary recognized Lydon’s purpose at once and praised his contribution toward the new plague."},{["episodeID"]="hillsbrad-lydon-tainted-keg-515",["requiresAll"]={{["minimumStage"]=2,["questID"]=515}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"515:description:1-21","515:description:24-44","515:description:47-73","515:description:78-137","515:description:142-357","515:description:360-423","515:description:426-482","515:objective:1-135"},["questID"]=515,["sourceHash"]="7119e748b112968127c7715bd16565aa1ba49852ac0b6d857e98932247ce1e81",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Faranell added his colloid of decay, then named the remaining reagents needed to activate the mixture. Troll’s blood potion, coastal naga scales and murloc eyes would bring the brew back into Lydon’s hands."},{["episodeID"]="hillsbrad-lydon-tainted-keg-517",["requiresAll"]={{["minimumStage"]=2,["questID"]=517}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"517:description:1-46","517:description:49-137","517:description:140-196","517:description:201-223","517:description:226-295","517:description:298-338","517:description:341-402","517:objective:1-67"},["questID"]=517,["sourceHash"]="bd325734c6b4cc6e0bee5d989538931266362255391bb95a8a2ff0029b09de43",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The finished elixir needed a disguise. Rather than test it on an animal, Lydon asked for a keg of the dwarves’ Shindigger Stout from Dun Garok, calling the next step a party."},{["episodeID"]="hillsbrad-lydon-tainted-keg-524",["requiresAll"]={{["minimumStage"]=4,["questID"]=524}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"524:description:1-69","524:description:72-182","524:description:185-258","524:description:261-349","524:description:354-402","524:description:405-433","524:description:438-485","524:description:488-508","524:objective:1-58","524:completion:1-42"},["questID"]=524,["sourceHash"]="64e93d8c61448745b39e78be36de34b00f5765502273217ec6e79fc241025f43",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The guests were captive farmers left at Lydon’s disposal after Darthalia’s search for a military strategist proved fruitless. The tainted keg was placed on their dusty rug, bringing Lydon’s mock hospitality into the room where the farmers were held."}},["grouping"]="A poisonous preparation and observed keg placement; no prisoner deaths, outbreak or subsequent military effect are inferred.",["quests"]={509,513,515,517,524},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="An Apothecary’s Hospitality"},["hinterlands-otho-feathered-warning"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=7841,["sourceHash"]="90029f3b72c4d9ac9863592e796bd284d58807611958e5e0e4e424b3c73d4343"},{["minimumStage"]=4,["questID"]=7842,["sourceHash"]="68136594cbe3ebec85eaad3ae46b67a72a302278b2ca0b217fb32178fc337f00"},{["minimumStage"]=4,["questID"]=7843,["sourceHash"]="8f4600ff36c31f4e22c79e3600aef80f7b4e821dc06b962bd4e551a8b7de98b5"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="hinterlands-otho-feathered-warning-7841",["requiresAll"]={{["minimumStage"]=2,["questID"]=7841}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"7841:description:1-76","7841:description:78-129","7841:description:134-146","7841:description:151-247","7841:description:249-336","7841:description:341-363","7841:objective:1-165","7841:objective:167-207","7841:objective:212-318"},["questID"]=7841,["sourceHash"]="90029f3b72c4d9ac9863592e796bd284d58807611958e5e0e4e424b3c73d4343",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Otho saw the Wildhammer’s dealings with the Highvale elves as a growing alliance against his people. He demanded violence against the elves to make the dwarves fear the cost of that friendship."},{["episodeID"]="hinterlands-otho-feathered-warning-7842",["requiresAll"]={{["minimumStage"]=2,["questID"]=7842}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"7842:description:1-81","7842:description:83-143","7842:description:145-173","7842:description:178-250","7842:description:252-287","7842:objective:1-148","7842:objective:150-190","7842:objective:195-256"},["questID"]=7842,["sourceHash"]="68136594cbe3ebec85eaad3ae46b67a72a302278b2ca0b217fb32178fc337f00",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The warning then turned upon the Wildhammer’s gryphons. Their closeness to their riders gave Otho another means of cruelty: feathers from the fallen creatures would become part of his final message."},{["episodeID"]="hinterlands-otho-feathered-warning-7843",["requiresAll"]={{["minimumStage"]=4,["questID"]=7843}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"7843:description:1-83","7843:description:88-106","7843:description:108-168","7843:description:170-182","7843:description:184-214","7843:description:216-259","7843:description:261-287","7843:description:289-318","7843:objective:1-208","7843:objective:210-250","7843:objective:255-324","7843:completion:1-63","7843:completion:65-95","7843:completion:97-109","7843:completion:114-131","7843:completion:133-142","7843:completion:144-177"},["questID"]=7843,["sourceHash"]="8f4600ff36c31f4e22c79e3600aef80f7b4e821dc06b962bd4e551a8b7de98b5",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A bloodied spear wrapped in gryphon feathers was planted by Aerie Peak’s central well. Otho welcomed the messenger’s return with a reward, asking whether the dwarves had begun to pack their bags. His questions about their response went unanswered."}},["grouping"]="The Revantusk warning to the Wildhammer; the final exchange does not establish evacuation, diplomatic success or a witnessed enemy response.",["quests"]={7841,7842,7843},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Spear at the Well"},["hinterlands-sharpbeak"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=2988,["sourceHash"]="46e7583269dad21a27e70fb96b44a624d45724db799bdead7cf51fe04c6ff83a"},{["minimumStage"]=4,["questID"]=2989,["sourceHash"]="24dfe6e75283cb2c46622df004a4ca30dd079fe0fecbcc3cb91b192a6bd255b7"},{["minimumStage"]=4,["questID"]=2990,["sourceHash"]="2a4d2fec1daf94e740a7cbddf4b17490a6affe7984c7fea881b9ef94219073cb"},{["minimumStage"]=4,["questID"]=2992,["sourceHash"]="a76dcab078ebe4bb3bbdec4122842b07b0414d528cd285290dca73916647bd27"},{["minimumStage"]=4,["questID"]=2993,["sourceHash"]="502a7e305d75ca93649883bf0ad863c9c2d2a4a524956f7d09f2dde7cd7678d2"},{["minimumStage"]=4,["questID"]=2994,["sourceHash"]="96b66b79ab09a282cabf7812d518c820bcd85475cf89c9e31415fdf66939fb5f"},{["minimumStage"]=4,["questID"]=2991,["sourceHash"]="003e44fca7f79927721fd9c831e419d9b0ecadba378cc6bcd4aa91ec98668e12"}}},["interpretation"]="2991 supplies the medallion that precedes2992; it is an explicit observed route step, never inferred completed from a later quest.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="hinterlands-sharpbeak-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=2988}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"2988:description:1-41","2988:description:43-173","2988:description:178-193","2988:description:196-278","2988:objective:1-88"},["questID"]=2988,["sourceHash"]="46e7583269dad21a27e70fb96b44a624d45724db799bdead7cf51fe04c6ff83a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Sharpbeak had vanished while hunting with his parents. Talonaxe suspected troll capture and began the search with the cages in the Witherbark villages."},{["episodeID"]="hinterlands-sharpbeak-2",["requiresAll"]={{["minimumStage"]=4,["questID"]=2988},{["minimumStage"]=4,["questID"]=2989}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"2988:description:1-41","2988:description:43-173","2988:description:178-193","2988:description:196-278","2988:objective:1-88","2988:completion:1-33","2988:completion:42-59","2988:completion:62-126","2988:completion:129-206"},["questID"]=2988,["sourceHash"]="46e7583269dad21a27e70fb96b44a624d45724db799bdead7cf51fe04c6ff83a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"2989:description:1-45","2989:description:48-86","2989:description:89-188","2989:objective:1-74","2989:completion:1-23","2989:completion:26-69","2989:completion:74-182","2989:completion:187-268"},["questID"]=2989,["sourceHash"]="24dfe6e75283cb2c46622df004a4ca30dd079fe0fecbcc3cb91b192a6bd255b7",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Two searches brought absence rather than rescue. Not finding Sharpbeak at the sacrificial altar supplied a narrow relief while leaving the central question open."},{["episodeID"]="hinterlands-sharpbeak-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=2992},{["minimumStage"]=4,["questID"]=2993}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"2992:description:1-52","2992:description:55-179","2992:description:184-193","2992:description:195-231","2992:description:234-256","2992:description:258-284","2992:objective:1-55","2992:completion:1-25","2992:completion:28-82"},["questID"]=2992,["sourceHash"]="a76dcab078ebe4bb3bbdec4122842b07b0414d528cd285290dca73916647bd27",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"2993:description:1-90","2993:description:93-194","2993:description:199-204","2993:description:207-226","2993:description:229-264","2993:objective:1-35","2993:completion:1-29","2993:completion:32-47","2993:completion:52-59","2993:completion:62-98","2993:completion:101-118","2993:completion:121-161"},["questID"]=2993,["sourceHash"]="502a7e305d75ca93649883bf0ad863c9c2d2a4a524956f7d09f2dde7cd7678d2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A feather gave the diviner a personal link. His successful ritual named a cage high above Jintha'Alor and a priestess's key, turning uncertainty into a route for rescue."},{["episodeID"]="hinterlands-sharpbeak-4",["requiresAll"]={{["minimumStage"]=4,["questID"]=2994}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"2994:description:1-23","2994:description:28-202","2994:objective:1-110","2994:completion:1-104","2994:completion:107-190","2994:completion:195-248","2994:completion:251-338"},["questID"]=2994,["sourceHash"]="96b66b79ab09a282cabf7812d518c820bcd85475cf89c9e31415fdf66939fb5f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The parents returned with their child. Talonaxe thanked the rescuer for the young gryphon's release and the family's reunion."}},["grouping"]="Authored connected episodes with explicit source-stage gates; branches retained",["quests"]={2988,2989,2990,2992,2993,2994},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The Missing Heir"},["horde-observed-agamand-crypt"]={["authored"]=true,["branchHandling"]={{["detail"]="Captured player names, races, and class-address tokens are not universal eligibility rules; runtime retains exact per-quest source masks.",["kind"]="EXACT_SOURCE_ELIGIBILITY",["quests"]={{["classMask"]="?",["questID"]=354,["raceMask"]="178"},{["classMask"]="?",["questID"]=355,["raceMask"]="178"},{["classMask"]="?",["questID"]=408,["raceMask"]="178"}}},{["detail"]="Retained as individual entries; not required for this narrative outcome and not expanded into separate short arcs.",["kind"]="STRUCTURAL_NEIGHBORS_OUTSIDE_NARRATIVE_SCOPE",["questIDs"]={}}},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=354,["sourceHash"]="11ffa69f5957ec55cc1834bae4f2ac052b7bd3e6d9beb6e542e4ed19c56b044c"},{["minimumStage"]=4,["questID"]=355,["sourceHash"]="34d420441a8642ca47c7211b87c220c2ff735b3022cc1ec4ddab974b80b0db3e"},{["minimumStage"]=4,["questID"]=408,["sourceHash"]="c5872f4277712947be70f3a0f9f3eb136b08038928e6a7dafff14a910262f653"}}},["interpretation"]="Agamand revenge develops into the attack on the family crypt; the outcome is the reported defeat of its Scourge force, not the end of the wider war. Every listed quest needs its own source-matching native stage4 observation. Structural neighboring errands and future promises are not inferred completed.",["scope"]="OBSERVED_REVIEWED_NARRATIVE_ROUTE_AND_STATED_OUTCOME"},["episodes"]={{["episodeID"]="horde-observed-agamand-crypt-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=354}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"354:description:1-69","354:description:72-118","354:description:123-252","354:description:255-302","354:description:307-357","354:description:360-399","354:description:404-471","354:description:474-511","354:objective:1-91"},["questID"]=354,["sourceHash"]="11ffa69f5957ec55cc1834bae4f2ac052b7bd3e6d9beb6e542e4ed19c56b044c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Coleman remembered the mills before the Plague and the family who persuaded their workers to stay and defend them. He blamed that loyalty for the undeath that followed, joining service against the Scourge to his own demand for the family's remains."},{["episodeID"]="horde-observed-agamand-crypt-2",["requiresAll"]={{["minimumStage"]=4,["questID"]=354}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"354:description:1-69","354:description:72-118","354:description:123-252","354:description:255-302","354:description:307-357","354:description:360-399","354:description:404-471","354:description:474-511","354:objective:1-91","354:completion:1-43","354:completion:45-125","354:completion:127-136","354:completion:138-198","354:completion:203-231","354:completion:233-270"},["questID"]=354,["sourceHash"]="11ffa69f5957ec55cc1834bae4f2ac052b7bd3e6d9beb6e542e4ed19c56b044c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The remains satisfied Coleman's revenge, but he still wondered whether the Agamands had understood their end. His hope that some trace of free will had known fear remained his own bitter speculation."},{["episodeID"]="horde-observed-agamand-crypt-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=355}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"355:description:1-83","355:description:86-157","355:description:162-267","355:objective:1-38"},["questID"]=355,["sourceHash"]="34d420441a8642ca47c7211b87c220c2ff735b3022cc1ec4ddab974b80b0db3e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Coleman distinguished his private grievance from the danger still held at the mills. He sent the successful agent to Sevren, whose concern extended beyond one former worker's revenge."},{["episodeID"]="horde-observed-agamand-crypt-4",["requiresAll"]={{["minimumStage"]=2,["questID"]=408}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"408:description:1-61","408:description:64-199","408:description:202-294","408:description:299-337","408:description:340-414","408:description:419-460","408:objective:1-49","408:objective:54-124"},["questID"]=408,["sourceHash"]="c5872f4277712947be70f3a0f9f3eb136b08038928e6a7dafff14a910262f653",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The threat had a headquarters beneath the family estate. Dargol had raised the Agamands' ancestors in their crypt, turning a household's dead into a force against the Forsaken."},{["episodeID"]="horde-observed-agamand-crypt-5",["requiresAll"]={{["minimumStage"]=4,["questID"]=408}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"408:description:1-61","408:description:64-199","408:description:202-294","408:description:299-337","408:description:340-414","408:description:419-460","408:objective:1-49","408:objective:54-124","408:completion:1-55","408:completion:57-137","408:completion:142-242"},["questID"]=408,["sourceHash"]="c5872f4277712947be70f3a0f9f3eb136b08038928e6a7dafff14a910262f653",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Sevren welcomed the blow against the crypt's forces and Dargol. He expected the victory to be noticed by allies and enemies alike, while placing the Lich King's eventual defeat in the struggle still ahead."}},["grouping"]="SOURCE_REVIEWED_NARRATIVE_CHAIN_3PLUS",["quests"]={354,355,408},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="From the mills to the crypt"},["horde-observed-braelyn"]={["authored"]=true,["branchHandling"]={{["detail"]="Captured player names, races, and class-address tokens are not universal eligibility rules; runtime retains exact per-quest source masks.",["kind"]="EXACT_SOURCE_ELIGIBILITY",["quests"]={{["classMask"]="?",["questID"]=1087,["raceMask"]="178"},{["classMask"]="?",["questID"]=1088,["raceMask"]="178"},{["classMask"]="?",["questID"]=1089,["raceMask"]="178"}}},{["detail"]="Retained as individual entries; not required for this narrative outcome and not expanded into separate short arcs.",["kind"]="STRUCTURAL_NEIGHBORS_OUTSIDE_NARRATIVE_SCOPE",["questIDs"]={}}},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=1087,["sourceHash"]="84847d6d24083b9acddd807f684fa6bbf2082b563f8487584d2efefa2bbb796c"},{["minimumStage"]=4,["questID"]=1088,["sourceHash"]="ea384b164f4650991b56fc6577692812f80b5c92bf53b48eaa540a78d4ba97f3"},{["minimumStage"]=4,["questID"]=1089,["sourceHash"]="782a9709f8954ba30eb220c7849138c96a2484a53cd69defc0f42766f08bd007"}}},["interpretation"]="Braelyn opposition, Ordanus, and the guarded hoard form a source-linked plot. Claims about magical power remain attributed to Braelyn. Every listed quest needs its own source-matching native stage4 observation. Structural neighboring errands and future promises are not inferred completed.",["scope"]="OBSERVED_REVIEWED_NARRATIVE_ROUTE_AND_STATED_OUTCOME"},["episodes"]={{["episodeID"]="horde-observed-braelyn-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=1087}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"1087:description:1-63","1087:description:65-225","1087:description:227-248","1087:description:253-386","1087:description:391-463","1087:description:465-509","1087:objective:1-117"},["questID"]=1087,["sourceHash"]="84847d6d24083b9acddd807f684fa6bbf2082b563f8487584d2efefa2bbb796c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Braelyn resented the druids she believed were stifling the flow of magic. Kept from returning to Jaedenar until her master's work was finished, she sought help against Cenarius's followers on the peak."},{["episodeID"]="horde-observed-braelyn-2",["requiresAll"]={{["minimumStage"]=4,["questID"]=1087}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1087:description:1-63","1087:description:65-225","1087:description:227-248","1087:description:253-386","1087:description:391-463","1087:description:465-509","1087:objective:1-117","1087:completion:1-24","1087:completion:26-31","1087:completion:33-49","1087:completion:51-68","1087:completion:70-199","1087:completion:204-259"},["questID"]=1087,["sourceHash"]="84847d6d24083b9acddd807f684fa6bbf2082b563f8487584d2efefa2bbb796c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Braelyn greeted the attacks with a rush of power she claimed to feel. Her delight lay in the magic she accused the kaldorei of rejecting, revealing how closely the work served her own appetite."},{["episodeID"]="horde-observed-braelyn-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=1088}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1088:description:1-52","1088:description:54-72","1088:description:74-141","1088:description:146-172","1088:description:174-179","1088:description:181-192","1088:description:194-208","1088:description:210-256","1088:description:258-266","1088:description:268-277","1088:description:279-319","1088:description:321-406","1088:description:411-465","1088:objective:1-62"},["questID"]=1088,["sourceHash"]="ea384b164f4650991b56fc6577692812f80b5c92bf53b48eaa540a78d4ba97f3",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Her next demand reached beyond Stonetalon. She claimed a magical sight of Ordanus at Raynewood and offered a powerful gift for his head."},{["episodeID"]="horde-observed-braelyn-4",["requiresAll"]={{["minimumStage"]=4,["questID"]=1088}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1088:description:1-52","1088:description:54-72","1088:description:74-141","1088:description:146-172","1088:description:174-179","1088:description:181-192","1088:description:194-208","1088:description:210-256","1088:description:258-266","1088:description:268-277","1088:description:279-319","1088:description:321-406","1088:description:411-465","1088:objective:1-62","1088:completion:1-30","1088:completion:32-106","1088:completion:111-158","1088:completion:163-209","1088:completion:211-223"},["questID"]=1088,["sourceHash"]="ea384b164f4650991b56fc6577692812f80b5c92bf53b48eaa540a78d4ba97f3",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The returned head belonged to someone Braelyn had known long before. She treated it as the reversal of an old arrogance, then directed attention toward the reward she had promised."},{["episodeID"]="horde-observed-braelyn-5",["requiresAll"]={{["minimumStage"]=2,["questID"]=1089}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1089:description:1-87","1089:description:92-168","1089:description:173-196","1089:description:198-235","1089:description:240-384","1089:description:386-485","1089:objective:1-37","1089:objective:39-98","1089:objective:100-143"},["questID"]=1089,["sourceHash"]="782a9709f8954ba30eb220c7849138c96a2484a53cd69defc0f42766f08bd007",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="That reward lay among the druids' guarded possessions. A key hidden by the den's entrance would open caches, whose contents in turn would unlock the central hoard."},{["episodeID"]="horde-observed-braelyn-6",["requiresAll"]={{["minimumStage"]=4,["questID"]=1089}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1089:description:1-87","1089:description:92-168","1089:description:173-196","1089:description:198-235","1089:description:240-384","1089:description:386-485","1089:objective:1-37","1089:objective:39-98","1089:objective:100-143","1089:completion:1-117"},["questID"]=1089,["sourceHash"]="782a9709f8954ba30eb220c7849138c96a2484a53cd69defc0f42766f08bd007",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Three matching keys completed the final opening. Items appeared within the glow of the unlocked hoard, bringing Braelyn's promised access to a tangible end."}},["grouping"]="SOURCE_REVIEWED_NARRATIVE_CHAIN_3PLUS",["quests"]={1087,1088,1089},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The gift that led into the den"},["horde-observed-burning-blade-cover"]={["authored"]=true,["branchHandling"]={{["detail"]="Captured player names, races, and class-address tokens are not universal eligibility rules; runtime retains exact per-quest source masks.",["kind"]="EXACT_SOURCE_ELIGIBILITY",["quests"]={{["classMask"]="?",["questID"]=5726,["raceMask"]="178"},{["classMask"]="?",["questID"]=5727,["raceMask"]="178"},{["classMask"]="?",["questID"]=5728,["raceMask"]="178"},{["classMask"]="?",["questID"]=5729,["raceMask"]="178"},{["classMask"]="?",["questID"]=5730,["raceMask"]="178"}}},{["detail"]="Retained as individual entries; not required for this narrative outcome and not expanded into separate short arcs.",["kind"]="STRUCTURAL_NEIGHBORS_OUTSIDE_NARRATIVE_SCOPE",["questIDs"]={}}},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=5726,["sourceHash"]="2adef08248c0c01707c1b8d31319bd42bcdca398d7c8754b01103e4da26b242e"},{["minimumStage"]=4,["questID"]=5727,["sourceHash"]="7a5b987b9c75b9adb2e5d30b525ac01bbeb1c48668ecd1a08272da8ecb456297"},{["minimumStage"]=4,["questID"]=5728,["sourceHash"]="b6c1e931a94e1951d3640ba834fe8307397f5cc49fe61c96ae4066d2468b60dc"},{["minimumStage"]=4,["questID"]=5729,["sourceHash"]="8b8184f0d0eacbf50d4e4e57d293d4b5198c48afaac235e65aeda5d26326308b"},{["minimumStage"]=4,["questID"]=5730,["sourceHash"]="4983fafd069a4a805f6262655d2c2081acff45daf007226d82e211ca27f36f50"}}},["interpretation"]="The infiltration reaches Neeru lieutenant status and the report of an Ashenvale network; future investigations and total defeat of the Shadow Council are not declared completed. Every listed quest needs its own source-matching native stage4 observation. Structural neighboring errands and future promises are not inferred completed.",["scope"]="OBSERVED_REVIEWED_NARRATIVE_ROUTE_AND_STATED_OUTCOME"},["episodes"]={{["episodeID"]="horde-observed-burning-blade-cover-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=5726}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"5726:description:1-60","5726:description:62-214","5726:description:219-285","5726:description:287-310","5726:description:312-349","5726:description:354-508","5726:objective:1-53"},["questID"]=5726,["sourceHash"]="2adef08248c0c01707c1b8d31319bd42bcdca398d7c8754b01103e4da26b242e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Thrall wanted the traitors' true reach exposed before a premature strike drove the corruption deeper. An insignia from Skull Rock would let a less familiar agent approach where his known servants could not."},{["episodeID"]="horde-observed-burning-blade-cover-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=5727}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"5727:description:1-62","5727:description:67-130","5727:description:132-192","5727:description:194-239","5727:description:241-342","5727:description:347-497","5727:objective:1-67","5727:objective:69-166"},["questID"]=5727,["sourceHash"]="7a5b987b9c75b9adb2e5d30b525ac01bbeb1c48668ecd1a08272da8ecb456297",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The insignia offered a way into Neeru's confidence. Thrall already knew the warlock's loyalty lay with the Burning Blade, but wanted that hidden allegiance used against the network around him."},{["episodeID"]="horde-observed-burning-blade-cover-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=5727}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"5727:description:1-62","5727:description:67-130","5727:description:132-192","5727:description:194-239","5727:description:241-342","5727:description:347-497","5727:objective:1-67","5727:objective:69-166","5727:completion:1-10","5727:completion:12-30","5727:completion:35-206","5727:completion:211-232","5727:completion:234-303"},["questID"]=5727,["sourceHash"]="7a5b987b9c75b9adb2e5d30b525ac01bbeb1c48668ecd1a08272da8ecb456297",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The first report gave Thrall an opening into a larger undertaking against the Shadow Council. He asked for every word of Neeru's account, treating the conversation as intelligence to be examined."},{["episodeID"]="horde-observed-burning-blade-cover-4",["requiresAll"]={{["minimumStage"]=2,["questID"]=5728}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"5728:description:1-36","5728:description:38-59","5728:description:61-140","5728:description:142-154","5728:description:156-235","5728:description:240-298","5728:description:300-358","5728:description:360-420","5728:description:422-493","5728:objective:1-78"},["questID"]=5728,["sourceHash"]="b6c1e931a94e1951d3640ba834fe8307397f5cc49fe61c96ae4066d2468b60dc",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Neeru's interest in Bazzalan and Jergosh made those Searing Blade leaders the next targets. Their defeat had to leave the agent's cover intact so the work could continue beyond Ragefire."},{["episodeID"]="horde-observed-burning-blade-cover-5",["requiresAll"]={{["minimumStage"]=4,["questID"]=5729}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"5729:description:1-66","5729:description:68-142","5729:description:144-328","5729:description:330-437","5729:description:442-509","5729:objective:1-38","5729:completion:1-12","5729:completion:14-27","5729:completion:29-41","5729:completion:43-86","5729:completion:88-118","5729:completion:120-230","5729:completion:232-326","5729:completion:328-403"},["questID"]=5729,["sourceHash"]="8b8184f0d0eacbf50d4e4e57d293d4b5198c48afaac235e65aeda5d26326308b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Neeru's anger confirmed how sharply the losses had struck. He blamed Thrall's helpers for the leaders' deaths, while still receiving the visitor as someone within his own circle."},{["episodeID"]="horde-observed-burning-blade-cover-6",["requiresAll"]={{["minimumStage"]=2,["questID"]=5730}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"5730:description:1-30","5730:description:32-52","5730:description:54-79","5730:description:84-224","5730:description:226-292","5730:description:294-393","5730:description:395-412","5730:objective:1-62"},["questID"]=5730,["sourceHash"]="4983fafd069a4a805f6262655d2c2081acff45daf007226d82e211ca27f36f50",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Neeru now addressed the agent as a lieutenant. He planned to salvage what remained in Ragefire while directing other agents toward the Barrens and Ashenvale, exposing a wider agenda through his growing trust."},{["episodeID"]="horde-observed-burning-blade-cover-7",["requiresAll"]={{["minimumStage"]=4,["questID"]=5730}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"5730:description:1-30","5730:description:32-52","5730:description:54-79","5730:description:84-224","5730:description:226-292","5730:description:294-393","5730:description:395-412","5730:objective:1-62","5730:completion:1-10","5730:completion:12-97","5730:completion:99-128","5730:completion:130-148","5730:completion:153-211","5730:completion:213-244","5730:completion:249-261"},["questID"]=5730,["sourceHash"]="4983fafd069a4a805f6262655d2c2081acff45daf007226d82e211ca27f36f50",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Ashenvale was new information to Thrall. He planned to have his spies investigate and released the agent to other work for the time being, keeping the exposed network as a task still unfolding."}},["grouping"]="SOURCE_REVIEWED_NARRATIVE_CHAIN_3PLUS",["quests"]={5726,5727,5728,5729,5730},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="A place close to the hidden enemy"},["horde-observed-fizziks"]={["authored"]=true,["branchHandling"]={{["detail"]="Captured player names, races, and class-address tokens are not universal eligibility rules; runtime retains exact per-quest source masks.",["kind"]="EXACT_SOURCE_ELIGIBILITY",["quests"]={{["classMask"]="?",["questID"]=1483,["raceMask"]="?"},{["classMask"]="?",["questID"]=1093,["raceMask"]="?"},{["classMask"]="?",["questID"]=1094,["raceMask"]="?"},{["classMask"]="?",["questID"]=1095,["raceMask"]="?"},{["classMask"]="?",["questID"]=1096,["raceMask"]="?"}}},{["detail"]="Retained as individual entries; not required for this narrative outcome and not expanded into separate short arcs.",["kind"]="STRUCTURAL_NEIGHBORS_OUTSIDE_NARRATIVE_SCOPE",["questIDs"]={}}},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=1483,["sourceHash"]="cc9e9b19abfd05de20d65db0da526da24cae5de7f47b0648b0de3dbdaaefaa77"},{["minimumStage"]=4,["questID"]=1093,["sourceHash"]="eea6532f591d0368f44f2c08ef09aa907cd21b836f1902a15ee62cbf6afe4cbb"},{["minimumStage"]=4,["questID"]=1094,["sourceHash"]="9571c31a15494153ab6ab006c5cf9351db787f09c059ebb057348569f7f7f2c8"},{["minimumStage"]=4,["questID"]=1095,["sourceHash"]="68a2b5aa4ea5c04a487f377410fa8064b114349cb80557ef880dd297d407c850"},{["minimumStage"]=4,["questID"]=1096,["sourceHash"]="4be8fb62cfddf6ad28cf584821e84354f65ec086d345d9b5a8be84e440ebbaeb"}}},["interpretation"]="The employment dispute develops through plans, internal orders, and the Gerenzo mission. The suspected trade-prince mandate and hoped-for promotion remain qualified. Every listed quest needs its own source-matching native stage4 observation. Structural neighboring errands and future promises are not inferred completed.",["scope"]="OBSERVED_REVIEWED_NARRATIVE_ROUTE_AND_STATED_OUTCOME"},["episodes"]={{["episodeID"]="horde-observed-fizziks-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=1483}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"1483:description:1-122","1483:description:127-231","1483:description:233-365","1483:description:367-415","1483:description:420-457","1483:description:459-511","1483:objective:1-41"},["questID"]=1483,["sourceHash"]="cc9e9b19abfd05de20d65db0da526da24cae5de7f47b0648b0de3dbdaaefaa77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Gerenzo's hiring had driven Fizziks to seek work with the Tinkers' Union. Sputtervalve saw an opportunity to reclaim a useful goblin mind from the Venture Company and sent help to his new recruit."},{["episodeID"]="horde-observed-fizziks-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=1093}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1093:description:1-52","1093:description:54-77","1093:description:79-108","1093:description:113-171","1093:description:173-212","1093:description:217-317","1093:description:319-381","1093:description:383-421","1093:description:423-480","1093:objective:1-81"},["questID"]=1093,["sourceHash"]="eea6532f591d0368f44f2c08ef09aa907cd21b836f1902a15ee62cbf6afe4cbb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Fizziks's new work still depended on the company that had expelled him. Sputtervalve wanted the enormous woodcutter's plans, but Gerenzo's hostility kept Fizziks from obtaining them himself."},{["episodeID"]="horde-observed-fizziks-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=1093}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1093:description:1-52","1093:description:54-77","1093:description:79-108","1093:description:113-171","1093:description:173-212","1093:description:217-317","1093:description:319-381","1093:description:383-421","1093:description:423-480","1093:objective:1-81","1093:completion:1-32","1093:completion:34-39","1093:completion:44-58","1093:completion:60-65","1093:completion:67-111","1093:completion:113-150","1093:completion:152-259"},["questID"]=1093,["sourceHash"]="eea6532f591d0368f44f2c08ef09aa907cd21b836f1902a15ee62cbf6afe4cbb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The recovered blueprints were harder for Fizziks to read than to welcome. He struggled with the gnomish design, leaving the documents' use to the employer waiting in Ratchet."},{["episodeID"]="horde-observed-fizziks-4",["requiresAll"]={{["minimumStage"]=2,["questID"]=1094}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1094:description:1-92","1094:description:94-162","1094:description:164-214","1094:description:219-280","1094:description:282-349","1094:objective:1-59"},["questID"]=1094,["sourceHash"]="9571c31a15494153ab6ab006c5cf9351db787f09c059ebb057348569f7f7f2c8",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The plans joined manuals and internal papers Fizziks had salvaged during his dismissal. Their sealed envelope carried both his work and his claim to usefulness back to Sputtervalve."},{["episodeID"]="horde-observed-fizziks-5",["requiresAll"]={{["minimumStage"]=2,["questID"]=1095}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1095:description:1-108","1095:description:110-184","1095:description:189-316","1095:description:318-361","1095:description:363-392","1095:description:397-504","1095:objective:1-64"},["questID"]=1095,["sourceHash"]="68a2b5aa4ea5c04a487f377410fa8064b114349cb80557ef880dd297d407c850",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Sputtervalve's reply turned technical theft into an order against Gerenzo. He had been asked to address the problem by Riddlevox and suspected the trade princes stood behind it, though that higher authority remained his hunch."},{["episodeID"]="horde-observed-fizziks-6",["requiresAll"]={{["minimumStage"]=2,["questID"]=1096}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1096:description:1-67","1096:description:69-204","1096:description:209-322","1096:description:324-402","1096:description:404-450","1096:description:455-508","1096:objective:1-88"},["questID"]=1096,["sourceHash"]="4be8fb62cfddf6ad28cf584821e84354f65ec086d345d9b5a8be84e440ebbaeb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Fizziks placed Gerenzo above Cragpool Lake, watching the operation from near its water wheel. His account of grafted machinery made the foreman's arm a distinctive proof of the dangerous work he could not undertake himself."},{["episodeID"]="horde-observed-fizziks-7",["requiresAll"]={{["minimumStage"]=4,["questID"]=1096}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1096:description:1-67","1096:description:69-204","1096:description:209-322","1096:description:324-402","1096:description:404-450","1096:description:455-508","1096:objective:1-88","1096:completion:1-21","1096:completion:23-76","1096:completion:78-199","1096:completion:204-224","1096:completion:229-265","1096:completion:267-409"},["questID"]=1096,["sourceHash"]="4be8fb62cfddf6ad28cf584821e84354f65ec086d345d9b5a8be84e440ebbaeb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The mechanical arm convinced Fizziks that Gerenzo was out of commission. He hoped that proof would earn a workshop assignment in Gadgetzan or Undermine, still looking toward a position that had not yet been granted."}},["grouping"]="SOURCE_REVIEWED_NARRATIVE_CHAIN_3PLUS",["quests"]={1483,1093,1094,1095,1096},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="Employment in the shadow of the Reaper"},["horde-observed-gann"]={["authored"]=true,["branchHandling"]={{["detail"]="Captured player names, races, and class-address tokens are not universal eligibility rules; runtime retains exact per-quest source masks.",["kind"]="EXACT_SOURCE_ELIGIBILITY",["quests"]={{["classMask"]="?",["questID"]=843,["raceMask"]="178"},{["classMask"]="?",["questID"]=846,["raceMask"]="178"},{["classMask"]="?",["questID"]=849,["raceMask"]="178"}}},{["detail"]="Retained as individual entries; not required for this narrative outcome and not expanded into separate short arcs.",["kind"]="STRUCTURAL_NEIGHBORS_OUTSIDE_NARRATIVE_SCOPE",["questIDs"]={}}},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=843,["sourceHash"]="0aef90184dc89e6a5f2d6337f0bbae811acf6cda08a05ebb4b7c249f02110d2f"},{["minimumStage"]=4,["questID"]=846,["sourceHash"]="16d0af1731f3c22e2d576a05795279f662ff0a9e46feae05c272e2408d3b2fd0"},{["minimumStage"]=4,["questID"]=849,["sourceHash"]="5d31a6d4c46f6e386b3774c784bd1c8ce43af5dad4ba06bbff51c2dd446daaee"}}},["interpretation"]="The local outcome is destruction of the flying machine, not expulsion of every dwarf or restoration of the entire tribal homeland. Every listed quest needs its own source-matching native stage4 observation. Structural neighboring errands and future promises are not inferred completed.",["scope"]="OBSERVED_REVIEWED_NARRATIVE_ROUTE_AND_STATED_OUTCOME"},["episodes"]={{["episodeID"]="horde-observed-gann-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=843}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"843:description:1-33","843:description:38-91","843:description:93-181","843:description:183-280","843:description:285-341","843:description:343-378","843:description:383-505","843:objective:1-80","843:objective:85-128"},["questID"]=843,["sourceHash"]="0aef90184dc89e6a5f2d6337f0bbae811acf6cda08a05ebb4b7c249f02110d2f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Gann saw Bael Modan's blasts and machinery cutting into land that had sustained his tribe. He said attempts at diplomacy had failed, and demanded force against the excavation along with its leader's journal."},{["episodeID"]="horde-observed-gann-2",["requiresAll"]={{["minimumStage"]=4,["questID"]=843}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"843:description:1-33","843:description:38-91","843:description:93-181","843:description:183-280","843:description:285-341","843:description:343-378","843:description:383-505","843:objective:1-80","843:objective:85-128","843:completion:1-32","843:completion:34-64","843:completion:66-98","843:completion:103-188","843:completion:193-249"},["questID"]=843,["sourceHash"]="0aef90184dc89e6a5f2d6337f0bbae811acf6cda08a05ebb4b7c249f02110d2f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Khazgorm's death satisfied Gann's anger, but the journal offered more than a trophy. He turned to its pages while expecting the dwarves to replace their lost leader."},{["episodeID"]="horde-observed-gann-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=846}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"846:description:1-99","846:description:101-146","846:description:151-207","846:description:209-329","846:description:331-409","846:description:414-454","846:description:456-509","846:objective:1-121"},["questID"]=846,["sourceHash"]="16d0af1731f3c22e2d576a05795279f662ff0a9e46feae05c272e2408d3b2fd0",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The plans showed how the excavation relied on explosives. Gann wanted the dwarves' own supplies collected so he could make a charge against the operation they had built."},{["episodeID"]="horde-observed-gann-4",["requiresAll"]={{["minimumStage"]=2,["questID"]=849}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"849:description:1-81","849:description:86-101","849:description:106-160","849:description:162-242","849:description:247-351","849:description:353-432","849:description:437-507","849:objective:1-71"},["questID"]=849,["sourceHash"]="5d31a6d4c46f6e386b3774c784bd1c8ce43af5dad4ba06bbff51c2dd446daaee",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The flying machine was both equipment and a weapon in Gann's eyes. It also embodied the power that had displaced his tribe, making its destruction a target with personal as well as practical meaning."},{["episodeID"]="horde-observed-gann-5",["requiresAll"]={{["minimumStage"]=4,["questID"]=849}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"849:description:1-81","849:description:86-101","849:description:106-160","849:description:162-242","849:description:247-351","849:description:353-432","849:description:437-507","849:objective:1-71","849:completion:1-23","849:completion:25-130"},["questID"]=849,["sourceHash"]="5d31a6d4c46f6e386b3774c784bd1c8ce43af5dad4ba06bbff51c2dd446daaee",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="With the flying machine destroyed, Gann praised a defender of the sacred ground. His thanks bound the attack to the memory of his lost tribe."}},["grouping"]="SOURCE_REVIEWED_NARRATIVE_CHAIN_3PLUS",["quests"]={843,846,849},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The machine above the stolen ground"},["horde-observed-gunther"]={["authored"]=true,["branchHandling"]={{["detail"]="Captured player names, races, and class-address tokens are not universal eligibility rules; runtime retains exact per-quest source masks.",["kind"]="EXACT_SOURCE_ELIGIBILITY",["quests"]={{["classMask"]="?",["questID"]=358,["raceMask"]="178"},{["classMask"]="?",["questID"]=405,["raceMask"]="178"},{["classMask"]="?",["questID"]=357,["raceMask"]="178"},{["classMask"]="?",["questID"]=366,["raceMask"]="178"},{["classMask"]="?",["questID"]=409,["raceMask"]="178"},{["classMask"]="?",["questID"]=411,["raceMask"]="178"}}},{["detail"]="Retained as individual entries; not required for this narrative outcome and not expanded into separate short arcs.",["kind"]="STRUCTURAL_NEIGHBORS_OUTSIDE_NARRATIVE_SCOPE",["questIDs"]={359,360}}},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=358,["sourceHash"]="7c3638dc209abb8f3c3dda4bb2e067720eca598ab527860c47646dfcd8ed7474"},{["minimumStage"]=4,["questID"]=405,["sourceHash"]="eb7062ff5d382ea2d38d62b975e8bc803e0bcf43b7ef3ca1baec1fd73cbd5425"},{["minimumStage"]=4,["questID"]=357,["sourceHash"]="2e7415c68edbdd92878cd5776d7c3577d0298ca7d5bd3928b2bb1792979ffe23"},{["minimumStage"]=4,["questID"]=366,["sourceHash"]="21b9adc98b126a046d74e2343a80c121899bbd03f17e0288a234563d8a5aaa2e"},{["minimumStage"]=4,["questID"]=409,["sourceHash"]="90ec6819e62c17a47cf4895c3414c90306510d6ea81551a90b61c6e613b13c14"},{["minimumStage"]=4,["questID"]=411,["sourceHash"]="a7ce8f6fb6b7bffa8bf30a104374fd76778cb5fcb9247a178608be9d3471e0fb"}}},["interpretation"]="The grave-defense introduction leads to Gunther recruitment. The separate two-step Bulwark report359/360 is outside this plot. Every listed quest needs its own source-matching native stage4 observation. Structural neighboring errands and future promises are not inferred completed.",["scope"]="OBSERVED_REVIEWED_NARRATIVE_ROUTE_AND_STATED_OUTCOME"},["episodes"]={{["episodeID"]="horde-observed-gunther-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=358}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"358:description:1-165","358:description:172-334","358:description:337-359","358:description:364-504","358:objective:1-49","358:objective:56-110"},["questID"]=358,["sourceHash"]="7c3638dc209abb8f3c3dda4bb2e067720eca598ab527860c47646dfcd8ed7474",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Sevren feared the Scourge would turn Tirisfal's crowded mass graves into another army. The Rot Hides gathering bodies also carried an ichor the apothecaries could study, making the defense of the dead a test of usefulness against their captors."},{["episodeID"]="horde-observed-gunther-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=405}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"405:description:1-152","405:description:155-182","405:description:187-217","405:description:220-261","405:description:264-333","405:description:336-360","405:description:365-386","405:description:389-406","405:description:411-468","405:objective:1-60"},["questID"]=405,["sourceHash"]="eb7062ff5d382ea2d38d62b975e8bc803e0bcf43b7ef3ca1baec1fd73cbd5425",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="That service led to a different task: Bethor wanted an agent capable of approaching a free-willed lich. Sevren knew the mission concerned recruitment, but left its particulars to the mage in the Undercity."},{["episodeID"]="horde-observed-gunther-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=357}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"357:description:1-74","357:description:77-216","357:description:221-272","357:description:275-359","357:description:364-430","357:description:433-486","357:objective:1-63","357:completion:1-14","357:completion:16-78","357:completion:80-111","357:completion:116-182","357:completion:187-198","357:completion:200-267","357:completion:272-376","357:completion:378-444","357:completion:449-487"},["questID"]=357,["sourceHash"]="2e7415c68edbdd92878cd5776d7c3577d0298ca7d5bd3928b2bb1792979ffe23",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The stolen spellbook changed an unnamed lich into Gunther Arcanus, Bethor's old comrade. Bethor recognized a necromancer whose power had grown in death and whose allegiance could matter to the Forsaken."},{["episodeID"]="horde-observed-gunther-4",["requiresAll"]={{["minimumStage"]=2,["questID"]=366}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"366:description:1-159","366:description:164-287","366:description:290-319","366:description:324-340","366:description:343-449","366:description:452-506","366:objective:1-70"},["questID"]=366,["sourceHash"]="21b9adc98b126a046d74e2343a80c121899bbd03f17e0288a234563d8a5aaa2e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Bethor answered Gunther's isolation through the book itself. Its new enchantment was meant to show that another former Kirin Tor student had escaped the Lich King, offering reunion where a stranger's approach had met hostility."},{["episodeID"]="horde-observed-gunther-5",["requiresAll"]={{["minimumStage"]=2,["questID"]=409}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"409:description:1-121","409:description:124-200","409:description:205-277","409:description:280-334","409:description:339-386","409:description:389-433","409:description:436-499","409:objective:1-29","409:objective:34-68","409:objective:73-104"},["questID"]=409,["sourceHash"]="90ec6819e62c17a47cf4895c3414c90306510d6ea81551a90b61c6e613b13c14",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The enchanted message was evidence, but Gunther still demanded action. Defeating the Scourge agent at the island's altar would test whether the visitor truly opposed the power he feared."},{["episodeID"]="horde-observed-gunther-6",["requiresAll"]={{["minimumStage"]=4,["questID"]=409}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"409:description:1-121","409:description:124-200","409:description:205-277","409:description:280-334","409:description:339-386","409:description:389-433","409:description:436-499","409:objective:1-29","409:objective:34-68","409:objective:73-104","409:completion:1-74","409:completion:76-86","409:completion:91-225"},["questID"]=409,["sourceHash"]="90ec6819e62c17a47cf4895c3414c90306510d6ea81551a90b61c6e613b13c14",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Lillith's defeat persuaded Gunther that he was not alone in possessing free will. The test changed his account of the world beyond the island, opening communication with the people he had mistaken for slaves."},{["episodeID"]="horde-observed-gunther-7",["requiresAll"]={{["minimumStage"]=4,["questID"]=411}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"411:description:1-46","411:description:49-78","411:description:80-107","411:objective:1-57","411:completion:1-29","411:completion:31-78","411:completion:80-110"},["questID"]=411,["sourceHash"]="a7ce8f6fb6b7bffa8bf30a104374fd76778cb5fcb9247a178608be9d3471e0fb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The Nether Gem reopened communication between old comrades. Bethor welcomed Gunther's agreement to join the Forsaken and planned to inform the Dark Lady."}},["grouping"]="SOURCE_REVIEWED_NARRATIVE_CHAIN_3PLUS",["quests"]={358,405,357,366,409,411},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="A book carried between old comrades"},["horde-observed-johaan"]={["authored"]=true,["branchHandling"]={{["detail"]="Captured player names, races, and class-address tokens are not universal eligibility rules; runtime retains exact per-quest source masks.",["kind"]="EXACT_SOURCE_ELIGIBILITY",["quests"]={{["classMask"]="?",["questID"]=367,["raceMask"]="16"},{["classMask"]="?",["questID"]=368,["raceMask"]="16"},{["classMask"]="?",["questID"]=369,["raceMask"]="16"},{["classMask"]="?",["questID"]=492,["raceMask"]="178"}}},{["detail"]="Retained as individual entries; not required for this narrative outcome and not expanded into separate short arcs.",["kind"]="STRUCTURAL_NEIGHBORS_OUTSIDE_NARRATIVE_SCOPE",["questIDs"]={}}},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=367,["sourceHash"]="0f5b9777793f36d6e8963dfa322b12b9fb292703ff39d0b901519250d0b7fde3"},{["minimumStage"]=4,["questID"]=368,["sourceHash"]="6a426a36c8bb4d28e1ffb8746262f7c1ae15e73864e445a53fbc07d8288639dd"},{["minimumStage"]=4,["questID"]=369,["sourceHash"]="1afb471e5cba60be8cb9d011af0a99fe663993e303ec054c420e9d64993e1c50"},{["minimumStage"]=4,["questID"]=492,["sourceHash"]="391e78ddf5bfbb24954b9096aba1b1209a2f7ca969970f34a4b29abe79ddd6d0"}}},["interpretation"]="The outcome is delivery of the experimental drink and the prisoner response. No successful plague, spread, death, or cure is asserted. Every listed quest needs its own source-matching native stage4 observation. Structural neighboring errands and future promises are not inferred completed.",["scope"]="OBSERVED_REVIEWED_NARRATIVE_ROUTE_AND_STATED_OUTCOME"},["episodes"]={{["episodeID"]="horde-observed-johaan-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=367}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"367:description:1-59","367:description:61-169","367:description:172-264","367:description:266-323","367:description:328-394","367:description:396-458","367:objective:1-87"},["questID"]=367,["sourceHash"]="0f5b9777793f36d6e8963dfa322b12b9fb292703ff39d0b901519250d0b7fde3",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Johaan pursued the plague Sylvanas had demanded from the apothecaries. His first theory concerned beast blood, beginning an experiment he hoped would threaten Arthas's army."},{["episodeID"]="horde-observed-johaan-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=368}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"368:description:1-151","368:description:153-198","368:description:200-260","368:description:265-323","368:description:326-397","368:objective:1-95"},["questID"]=368,["sourceHash"]="6a426a36c8bb4d28e1ffb8746262f7c1ae15e73864e445a53fbc07d8288639dd",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The problem widened from poisoning one victim to spreading an illness. Johaan's experiments called for murloc scales, another reagent in a preparation whose reach remained the ambition of its maker."},{["episodeID"]="horde-observed-johaan-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=369}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"369:description:1-153","369:description:156-268","369:description:273-352","369:description:355-442","369:description:445-509","369:objective:1-113"},["questID"]=369,["sourceHash"]="1afb471e5cba60be8cb9d011af0a99fe663993e303ec054c420e9d64993e1c50",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="An old account of a devastating plague pointed Johaan toward spider venom. He wanted to test whether its contagious element would work in the new mixture, turning a historical clue into the next experiment."},{["episodeID"]="horde-observed-johaan-4",["requiresAll"]={{["minimumStage"]=4,["questID"]=369}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"369:description:1-153","369:description:156-268","369:description:273-352","369:description:355-442","369:description:445-509","369:objective:1-113","369:completion:1-37","369:completion:39-102","369:completion:104-152"},["questID"]=369,["sourceHash"]="1afb471e5cba60be8cb9d011af0a99fe663993e303ec054c420e9d64993e1c50",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The venom completed Johaan's collected ingredients. With the rest of the mixture already boiled down, he declared himself ready to try the new agent."},{["episodeID"]="horde-observed-johaan-5",["requiresAll"]={{["minimumStage"]=2,["questID"]=492}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"492:description:1-102","492:description:105-232","492:description:237-327","492:description:330-413","492:objective:1-57"},["questID"]=492,["sourceHash"]="391e78ddf5bfbb24954b9096aba1b1209a2f7ca969970f34a4b29abe79ddd6d0",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The proposed trial moved to the tavern cellar, where the Deathguard held a captured mountaineer. Johaan sent a special drink and described it as a hint of what the Dark Lady intended for Azeroth."},{["episodeID"]="horde-observed-johaan-6",["requiresAll"]={{["minimumStage"]=4,["questID"]=492}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"492:description:1-102","492:description:105-232","492:description:237-327","492:description:330-413","492:objective:1-57","492:completion:1-20","492:completion:23-114"},["questID"]=492,["sourceHash"]="391e78ddf5bfbb24954b9096aba1b1209a2f7ca969970f34a4b29abe79ddd6d0",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The captive accepted the offer of a drink, comparing it with the ale he would rather have had. Johaan's experimental mixture had reached the prisoner's cell."}},["grouping"]="SOURCE_REVIEWED_NARRATIVE_CHAIN_3PLUS",["quests"]={367,368,369,492},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The first trial of a new contagion"},["horde-observed-oases"]={["authored"]=true,["branchHandling"]={{["detail"]="Captured player names, races, and class-address tokens are not universal eligibility rules; runtime retains exact per-quest source masks.",["kind"]="EXACT_SOURCE_ELIGIBILITY",["quests"]={{["classMask"]="?",["questID"]=886,["raceMask"]="178"},{["classMask"]="?",["questID"]=870,["raceMask"]="178"},{["classMask"]="?",["questID"]=877,["raceMask"]="178"},{["classMask"]="?",["questID"]=880,["raceMask"]="178"},{["classMask"]="?",["questID"]=1489,["raceMask"]="178"},{["classMask"]="?",["questID"]=1490,["raceMask"]="178"},{["classMask"]="?",["questID"]=914,["raceMask"]="178"}}},{["detail"]="Retained as individual entries; not required for this narrative outcome and not expanded into separate short arcs.",["kind"]="STRUCTURAL_NEIGHBORS_OUTSIDE_NARRATIVE_SCOPE",["questIDs"]={3301}}},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=886,["sourceHash"]="abc2a96af52b194c04af390558bb2614353021dd9c022babbb454f8d9fba6d98"},{["minimumStage"]=4,["questID"]=870,["sourceHash"]="8c5577974efcdd2a8211b4da6b215fc3213c995034915637cd58aa669965a87a"},{["minimumStage"]=4,["questID"]=877,["sourceHash"]="47983cff1a1d488c583e01d6b8cd6dad527cebb73faf7745fe083ea607067419"},{["minimumStage"]=4,["questID"]=880,["sourceHash"]="8fc1dc00613ef4cae327b7f3f3d94a91abab2a3fc163ee7eeb591c5cedfeb7c9"},{["minimumStage"]=4,["questID"]=1489,["sourceHash"]="fdd5b767e4e7adcae2e094246c0537061272f254f9c4ef0fc64fc652a41c98a2"},{["minimumStage"]=4,["questID"]=1490,["sourceHash"]="addb81a59f046eb68717bf246a2afbc7f17f1e8ec37b2ccbc999c86e33fc6d7e"},{["minimumStage"]=4,["questID"]=914,["sourceHash"]="ee035e44c082ec6a1f4106cc8f287c206cdeeb55327b720a0e177912a53965f0"}}},["interpretation"]="The oasis investigation develops into the Druids of the Fang confrontation. Mura sample3301 remains a separate individual inquiry; no permanent ecological restoration is declared. Every listed quest needs its own source-matching native stage4 observation. Structural neighboring errands and future promises are not inferred completed.",["scope"]="OBSERVED_REVIEWED_NARRATIVE_ROUTE_AND_STATED_OUTCOME"},["episodes"]={{["episodeID"]="horde-observed-oases-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=870},{["minimumStage"]=2,["questID"]=886}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"886:description:1-92","886:description:97-188","886:description:193-235","886:description:238-266","886:description:269-328","886:description:331-385","886:description:388-436","886:description:441-503","886:objective:1-45"},["questID"]=886,["sourceHash"]="abc2a96af52b194c04af390558bb2614353021dd9c022babbb454f8d9fba6d98",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"870:description:1-58","870:description:61-141","870:description:144-194","870:description:199-282","870:description:285-354","870:description:359-382","870:description:385-443","870:description:446-503","870:objective:1-50"},["questID"]=870,["sourceHash"]="8c5577974efcdd2a8211b4da6b215fc3213c995034915637cd58aa669965a87a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The new oases troubled the druids with a mystery of renewal. A land remembered as lush had become a dry expanse, yet water and life were returning where Tonga sensed an unfamiliar power beneath the ground."},{["episodeID"]="horde-observed-oases-2",["requiresAll"]={{["minimumStage"]=4,["questID"]=870}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"870:description:1-58","870:description:61-141","870:description:144-194","870:description:199-282","870:description:285-354","870:description:359-382","870:description:385-443","870:description:446-503","870:objective:1-50","870:completion:1-62","870:completion:64-71","870:completion:73-138","870:completion:143-159","870:completion:161-196"},["questID"]=870,["sourceHash"]="8c5577974efcdd2a8211b4da6b215fc3213c995034915637cd58aa669965a87a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A fissure releasing bubbles in the Forgotten Pools gave Tonga his first physical clue. He welcomed the report as a possible answer, but remained unsure what lay beneath the oases."},{["episodeID"]="horde-observed-oases-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=877}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"877:description:1-103","877:description:106-168","877:description:173-190","877:description:195-217","877:description:220-301","877:description:304-377","877:objective:1-74"},["questID"]=877,["sourceHash"]="47983cff1a1d488c583e01d6b8cd6dad527cebb73faf7745fe083ea607067419",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Tonga sent dead seeds to another oasis to test whether the fissures were connected to the new life. The question moved from finding a source to watching what that source could do."},{["episodeID"]="horde-observed-oases-4",["requiresAll"]={{["minimumStage"]=4,["questID"]=877}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"877:description:1-103","877:description:106-168","877:description:173-190","877:description:195-217","877:description:220-301","877:description:304-377","877:objective:1-74","877:completion:1-26","877:completion:28-69","877:completion:71-132","877:completion:137-162"},["questID"]=877,["sourceHash"]="47983cff1a1d488c583e01d6b8cd6dad527cebb73faf7745fe083ea607067419",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The seeds' response astonished Tonga. He read their revival as evidence of extraordinary power beneath the oases and wanted the inquiry carried further."},{["episodeID"]="horde-observed-oases-5",["requiresAll"]={{["minimumStage"]=2,["questID"]=880}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"880:description:1-33","880:description:36-101","880:description:104-128","880:description:133-223","880:description:228-283","880:description:286-329","880:objective:1-68"},["questID"]=880,["sourceHash"]="8fc1dc00613ef4cae327b7f3f3d94a91abab2a3fc163ee7eeb591c5cedfeb7c9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The next specimens came from the creatures drinking the water. Shells from the altered snapjaws could show how the same force was working through the oases' animals."},{["episodeID"]="horde-observed-oases-6",["requiresAll"]={{["minimumStage"]=2,["questID"]=1489}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1489:description:1-69","1489:description:72-172","1489:description:175-219","1489:description:224-275","1489:description:278-347","1489:description:350-401","1489:description:404-441","1489:description:446-499","1489:objective:1-28"},["questID"]=1489,["sourceHash"]="fdd5b767e4e7adcae2e094246c0537061272f254f9c4ef0fc64fc652a41c98a2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Tonga found a taint in the shells and described the land as dreaming without waking. He believed the Wailing Caverns were its source, but sent the question first to Hamuul's counsel in Thunder Bluff."},{["episodeID"]="horde-observed-oases-7",["requiresAll"]={{["minimumStage"]=2,["questID"]=1490}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1490:description:1-95","1490:description:98-166","1490:description:169-231","1490:description:236-266","1490:description:269-357","1490:description:360-402","1490:description:405-445","1490:description:450-465","1490:description:468-499","1490:objective:1-25"},["questID"]=1490,["sourceHash"]="addb81a59f046eb68717bf246a2afbc7f17f1e8ec37b2ccbc999c86e33fc6d7e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Hamuul's own dreaming had shown druids who had lost their way. He had been unable to remain there long; Nara had stayed, and her knowledge became the next guide into the caverns."},{["episodeID"]="horde-observed-oases-8",["requiresAll"]={{["minimumStage"]=2,["questID"]=914}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"914:description:1-77","914:description:80-226","914:description:231-303","914:description:306-335","914:description:338-418","914:description:432-490","914:objective:1-93"},["questID"]=914,["sourceHash"]="ee035e44c082ec6a1f4106cc8f287c206cdeeb55327b720a0e177912a53965f0",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Nara traced the danger to four leaders who had turned a plan to heal the Barrens toward their own distorted dreams. Each held a gem that would serve as proof of the strike against them."},{["episodeID"]="horde-observed-oases-9",["requiresAll"]={{["minimumStage"]=4,["questID"]=914}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"914:description:1-77","914:description:80-226","914:description:231-303","914:description:306-335","914:description:338-418","914:description:432-490","914:objective:1-93","914:completion:1-21","914:completion:23-71","914:completion:73-176","914:completion:181-196","914:completion:198-271"},["questID"]=914,["sourceHash"]="ee035e44c082ec6a1f4106cc8f287c206cdeeb55327b720a0e177912a53965f0",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Nara's dreams were free of the leaders' faces at last. She thanked the victor for helping to save the Barrens from the future she had feared, joining her personal relief to the land's larger struggle."}},["grouping"]="SOURCE_REVIEWED_NARRATIVE_CHAIN_3PLUS",["quests"]={886,870,877,880,1489,1490,914},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The life beneath the dry earth"},["horde-observed-ratchet-cargo"]={["authored"]=true,["branchHandling"]={{["detail"]="Captured player names, races, and class-address tokens are not universal eligibility rules; runtime retains exact per-quest source masks.",["kind"]="EXACT_SOURCE_ELIGIBILITY",["quests"]={{["classMask"]="?",["questID"]=887,["raceMask"]="?"},{["classMask"]="?",["questID"]=890,["raceMask"]="?"},{["classMask"]="?",["questID"]=892,["raceMask"]="?"},{["classMask"]="?",["questID"]=888,["raceMask"]="?"}}},{["detail"]="Retained as individual entries; not required for this narrative outcome and not expanded into separate short arcs.",["kind"]="STRUCTURAL_NEIGHBORS_OUTSIDE_NARRATIVE_SCOPE",["questIDs"]={}}},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=887,["sourceHash"]="079db2b0cffad3c255b5b326de75d0b2bc8af802952c5a7f6fe3cdf9fb186165"},{["minimumStage"]=4,["questID"]=890,["sourceHash"]="410d660c1c1808fcbfb1b7bc284a680256ca73eaf349e766f00626905b4a7046"},{["minimumStage"]=4,["questID"]=892,["sourceHash"]="97e3db419c0eb203bdb701c9b51a3546ba651a40700c7e2d1d4df67e4377ae60"},{["minimumStage"]=4,["questID"]=888,["sourceHash"]="6fe2f834d510609a1ad680e23bac240fd3def2871e6580e596e0fa8cc4dcbd68"}}},["interpretation"]="The neutral Ratchet plot follows raids, inventory inquiry, and recovery of the lens and boots. It does not imply permanent safety of the trade fleets. Every listed quest needs its own source-matching native stage4 observation. Structural neighboring errands and future promises are not inferred completed.",["scope"]="OBSERVED_REVIEWED_NARRATIVE_ROUTE_AND_STATED_OUTCOME"},["episodes"]={{["episodeID"]="horde-observed-ratchet-cargo-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=887}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"887:description:1-100","887:description:102-271","887:description:276-351","887:description:353-474","887:objective:1-75"},["questID"]=887,["sourceHash"]="079db2b0cffad3c255b5b326de75d0b2bc8af802952c5a7f6fe3cdf9fb186165",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Pirate attacks had made Gazlowe impatient with the protection his trading fleets received. The camp south of Ratchet threatened both his ships and the goods on which his operation depended."},{["episodeID"]="horde-observed-ratchet-cargo-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=890}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"890:description:1-71","890:description:73-279","890:description:284-385","890:objective:1-47"},["questID"]=890,["sourceHash"]="410d660c1c1808fcbfb1b7bc284a680256ca73eaf349e766f00626905b4a7046",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Gazlowe suspected the missing cargo had gone to the freebooters, but first wanted the dock records checked. His ledger could reveal whether an unnoticed delivery had spared him another loss."},{["episodeID"]="horde-observed-ratchet-cargo-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=892}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"892:description:1-44","892:description:46-90","892:description:92-161","892:description:166-195","892:description:203-320","892:objective:1-46"},["questID"]=892,["sourceHash"]="97e3db419c0eb203bdb701c9b51a3546ba651a40700c7e2d1d4df67e4377ae60",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Dizzywig found no discrepancy in his logs and sent the ledger back. His account left the pirates as a likely explanation, while Gazlowe still had to decide what could be recovered."},{["episodeID"]="horde-observed-ratchet-cargo-4",["requiresAll"]={{["minimumStage"]=2,["questID"]=888}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"888:description:1-69","888:description:71-126","888:description:131-216","888:description:218-312","888:description:314-375","888:description:380-437","888:objective:1-74"},["questID"]=888,["sourceHash"]="6fe2f834d510609a1ad680e23bac240fd3def2871e6580e596e0fa8cc4dcbd68",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Gazlowe narrowed the search to what he most needed: the missing lens for his observatory and a shipment of boots from Booty Bay. He had already accepted that the pirates' other takings might be lost."},{["episodeID"]="horde-observed-ratchet-cargo-5",["requiresAll"]={{["minimumStage"]=4,["questID"]=888}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"888:description:1-69","888:description:71-126","888:description:131-216","888:description:218-312","888:description:314-375","888:description:380-437","888:objective:1-74","888:completion:1-70","888:completion:72-142","888:completion:144-229"},["questID"]=888,["sourceHash"]="6fe2f834d510609a1ad680e23bac240fd3def2871e6580e596e0fa8cc4dcbd68",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The returned goods relieved Gazlowe and reopened the prospect of future work. His thanks followed the recovery of the essentials on which his unfinished operation had been waiting."}},["grouping"]="SOURCE_REVIEWED_NARRATIVE_CHAIN_3PLUS",["quests"]={887,890,892,888},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="A ledger before a recovery"},["horde-observed-scarlet-officers"]={["authored"]=true,["branchHandling"]={{["detail"]="Captured player names, races, and class-address tokens are not universal eligibility rules; runtime retains exact per-quest source masks.",["kind"]="EXACT_SOURCE_ELIGIBILITY",["quests"]={{["classMask"]="?",["questID"]=381,["raceMask"]="178"},{["classMask"]="?",["questID"]=382,["raceMask"]="178"},{["classMask"]="?",["questID"]=383,["raceMask"]="178"},{["classMask"]="?",["questID"]=427,["raceMask"]="178"},{["classMask"]="?",["questID"]=370,["raceMask"]="178"},{["classMask"]="?",["questID"]=371,["raceMask"]="178"},{["classMask"]="?",["questID"]=372,["raceMask"]="178"}}},{["detail"]="Retained as individual entries; not required for this narrative outcome and not expanded into separate short arcs.",["kind"]="STRUCTURAL_NEIGHBORS_OUTSIDE_NARRATIVE_SCOPE",["questIDs"]={376,380,3902,6395,374}}},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=381,["sourceHash"]="b6378b2a389bf1a2678c46f0aebaf3dd2f8ae6452d4abd6a86009086bc32f2f4"},{["minimumStage"]=4,["questID"]=382,["sourceHash"]="ad774deacfcd9f660bffe652c669491590f546d8262719991decf2eab8dc475a"},{["minimumStage"]=4,["questID"]=383,["sourceHash"]="e22955a51cd4281cfad785606a12bcce68a29494f75e0d4a3440fc23409445ce"},{["minimumStage"]=4,["questID"]=427,["sourceHash"]="d0e18c0727635879e5d46d07d10cc3895d30652d2862761a9e86093b70cddd48"},{["minimumStage"]=4,["questID"]=370,["sourceHash"]="81bf4e2b810d47f749e57f27a00de3ba7f748c45d4810c1bf4eb0c7368fee04e"},{["minimumStage"]=4,["questID"]=371,["sourceHash"]="52db2e170f5c95ef5884bef10f4df1f917576353dbd5e4f7db1a7b3fee4738ff"},{["minimumStage"]=4,["questID"]=372,["sourceHash"]="bb18eecfadd4df05cd262dcba4dcabc87129f287613a68e687ca99949ac1fdf7"}}},["interpretation"]="The reviewed plot begins at the Scarlet camp and ends after the three officer attacks. Deathknell supply, mine, burial and ring errands are not fused into it. Every listed quest needs its own source-matching native stage4 observation. Structural neighboring errands and future promises are not inferred completed.",["scope"]="OBSERVED_REVIEWED_NARRATIVE_ROUTE_AND_STATED_OUTCOME"},["episodes"]={{["episodeID"]="horde-observed-scarlet-officers-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=381}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"381:description:1-109","381:description:112-154","381:description:159-262","381:description:264-410","381:description:412-432","381:description:437-499","381:objective:1-85"},["questID"]=381,["sourceHash"]="b6378b2a389bf1a2678c46f0aebaf3dd2f8ae6452d4abd6a86009086bc32f2f4",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Arren turned his attention to the Scarlet camp southeast of Deathknell. Its hunters made no distinction between Scourge and free undead, so their presence threatened people already struggling to establish themselves."},{["episodeID"]="horde-observed-scarlet-officers-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=382}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"382:description:1-151","382:description:153-238","382:description:240-306","382:description:311-362","382:description:364-430","382:objective:1-111"},["questID"]=382,["sourceHash"]="ad774deacfcd9f660bffe652c669491590f546d8262719991decf2eab8dc475a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Word from Brill identified a messenger sent from the monastery. Arren did not know what he carried, only that the information was important enough to recover from the Crusade's camp."},{["episodeID"]="horde-observed-scarlet-officers-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=382}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"382:description:1-151","382:description:153-238","382:description:240-306","382:description:311-362","382:description:364-430","382:objective:1-111","382:completion:1-6","382:completion:8-35","382:completion:40-96","382:completion:101-141","382:completion:143-152","382:completion:154-172","382:completion:174-272","382:completion:274-289","382:completion:291-361","382:completion:363-378"},["questID"]=382,["sourceHash"]="ad774deacfcd9f660bffe652c669491590f546d8262719991decf2eab8dc475a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Much of the messenger's paperwork told Arren little he did not already know. A map of field commanders and agents stood out among the routine reports, giving the scattered enemy positions practical value."},{["episodeID"]="horde-observed-scarlet-officers-4",["requiresAll"]={{["minimumStage"]=2,["questID"]=383}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"383:description:1-70","383:description:72-155","383:description:157-315","383:description:320-357","383:description:359-419","383:description:421-463","383:description:465-508","383:objective:1-66"},["questID"]=383,["sourceHash"]="e22955a51cd4281cfad785606a12bcce68a29494f75e0d4a3440fc23409445ce",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The map belonged with Zygand in Brill. Arren sent it onward as intelligence for a larger strike, passing the work from a local camp to the officer responsible for the wider campaign."},{["episodeID"]="horde-observed-scarlet-officers-5",["requiresAll"]={{["minimumStage"]=2,["questID"]=427}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"427:description:1-115","427:description:118-178","427:description:183-221","427:description:224-271","427:description:274-363","427:description:368-509","427:objective:1-63"},["questID"]=427,["sourceHash"]="d0e18c0727635879e5d46d07d10cc3895d30652d2862761a9e86093b70cddd48",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Zygand knew where the Crusade's forces stood, but still required proof that his new agent could serve in the offensive. The warriors west of Brill were the first target before the command posts themselves."},{["episodeID"]="horde-observed-scarlet-officers-6",["requiresAll"]={{["minimumStage"]=2,["questID"]=370}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"370:description:1-121","370:description:124-255","370:description:260-334","370:objective:1-105"},["questID"]=370,["sourceHash"]="81bf4e2b810d47f749e57f27a00de3ba7f748c45d4810c1bf4eb0c7368fee04e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The documents named Perrine at a ruined tower southwest of Brill. Zygand's order paired the captain with the missionaries and zealots around him, turning the map into a specific assault."},{["episodeID"]="horde-observed-scarlet-officers-7",["requiresAll"]={{["minimumStage"]=2,["questID"]=371}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"371:description:1-62","371:description:65-253","371:description:258-297","371:description:299-354","371:objective:1-90"},["questID"]=371,["sourceHash"]="52db2e170f5c95ef5884bef10f4df1f917576353dbd5e4f7db1a7b3fee4738ff",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The same intelligence led toward Balnir Farmstead, where Vachon's force had been raiding from another tower. Zygand sought to slow the Crusade's advance by striking its local command and friars."},{["episodeID"]="horde-observed-scarlet-officers-8",["requiresAll"]={{["minimumStage"]=4,["questID"]=370},{["minimumStage"]=4,["questID"]=371},{["minimumStage"]=4,["questID"]=372}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"370:description:1-121","370:description:124-255","370:description:260-334","370:objective:1-105","370:completion:1-62","370:completion:64-101"},["questID"]=370,["sourceHash"]="81bf4e2b810d47f749e57f27a00de3ba7f748c45d4810c1bf4eb0c7368fee04e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"371:description:1-62","371:description:65-253","371:description:258-297","371:description:299-354","371:objective:1-90","371:completion:1-96","371:completion:98-120"},["questID"]=371,["sourceHash"]="52db2e170f5c95ef5884bef10f4df1f917576353dbd5e4f7db1a7b3fee4738ff",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"372:description:1-97","372:description:100-212","372:description:217-277","372:description:280-346","372:objective:1-102","372:completion:1-33","372:completion:35-170","372:completion:172-212"},["questID"]=372,["sourceHash"]="bb18eecfadd4df05cd262dcba4dcabc87129f287613a68e687ca99949ac1fdf7",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Perrine's defeat won Zygand's approval, and he expected Vachon's loss to hinder the Crusade's advance. After the final strike against Melrache and his guards, he praised another step in the Forsaken's war; the greater conflict remained ahead."}},["grouping"]="SOURCE_REVIEWED_NARRATIVE_CHAIN_3PLUS",["quests"]={381,382,383,427,370,371,372},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The map behind the raids"},["horde-observed-shattered-hand"]={["authored"]=true,["branchHandling"]={{["detail"]="Captured player names, races, and class-address tokens are not universal eligibility rules; runtime retains exact per-quest source masks.",["kind"]="EXACT_SOURCE_ELIGIBILITY",["quests"]={{["classMask"]="8",["questID"]=2460,["raceMask"]="178"},{["classMask"]="8",["questID"]=2458,["raceMask"]="178"},{["classMask"]="8",["questID"]=2478,["raceMask"]="178"},{["classMask"]="8",["questID"]=2479,["raceMask"]="178"},{["classMask"]="8",["questID"]=2480,["raceMask"]="178"}}},{["detail"]="Retained as individual entries; not required for this narrative outcome and not expanded into separate short arcs.",["kind"]="STRUCTURAL_NEIGHBORS_OUTSIDE_NARRATIVE_SCOPE",["questIDs"]={}}},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=2460,["sourceHash"]="899b61445e89495f9bfcb30fa7ce0c03f9a775a62cc6607696d5e2c864158cfa"},{["minimumStage"]=4,["questID"]=2458,["sourceHash"]="7e9501224671c082c85e0f19b1d172332be349b3a5e4650d79036741def10c56"},{["minimumStage"]=4,["questID"]=2478,["sourceHash"]="94536c93e5ec7c09ae1758abfd22c5f982cb0d614be54df13758a5961dafe458"},{["minimumStage"]=4,["questID"]=2479,["sourceHash"]="9a6c76204e08710a44e2a1119cbb45c1832b5686fb830575711176974486702f"},{["minimumStage"]=4,["questID"]=2480,["sourceHash"]="01c3f443255c1a6db93525d7582a7eab7d8cd68c1c579608b61a23cb1861d303"}}},["interpretation"]="The Horde rogue route ends with Hinott preparing the antidote. It does not assert that a dose was consumed or that recovery was personally observed. Every listed quest needs its own source-matching native stage4 observation. Structural neighboring errands and future promises are not inferred completed.",["scope"]="OBSERVED_REVIEWED_NARRATIVE_ROUTE_AND_STATED_OUTCOME"},["episodes"]={{["episodeID"]="horde-observed-shattered-hand-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=2460}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"2460:description:1-87","2460:description:89-152","2460:description:157-177","2460:objective:1-41"},["questID"]=2460,["sourceHash"]="899b61445e89495f9bfcb30fa7ce0c03f9a775a62cc6607696d5e2c864158cfa",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The Shattered Hand began with a sign its agents could recognize. Shenthul required the salute to be learned and repeated before entrusting the next contact to the field."},{["episodeID"]="horde-observed-shattered-hand-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=2458}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"2458:description:1-22","2458:description:24-54","2458:description:59-131","2458:description:133-190","2458:description:195-240","2458:description:242-281","2458:description:283-327","2458:description:329-387","2458:description:392-504","2458:objective:1-25","2458:objective:27-127","2458:objective:132-222","2458:objective:224-311","2458:objective:316-439"},["questID"]=2458,["sourceHash"]="7e9501224671c082c85e0f19b1d172332be349b3a5e4650d79036741def10c56",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A year of covert work had placed Fizzule inside the Venture Company. Reaching him required a careful order of flares and salute, because a stranger who failed recognition would be treated as an enemy."},{["episodeID"]="horde-observed-shattered-hand-first-contact",["requiresAll"]={{["minimumStage"]=4,["questID"]=2458}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"2458:description:1-22","2458:description:24-54","2458:description:59-131","2458:description:133-190","2458:description:195-240","2458:description:242-281","2458:description:283-327","2458:description:329-387","2458:description:392-504","2458:objective:1-25","2458:objective:27-127","2458:objective:132-222","2458:objective:224-311","2458:objective:316-439","2458:completion:1-120","2458:completion:125-220"},["questID"]=2458,["sourceHash"]="7e9501224671c082c85e0f19b1d172332be349b3a5e4650d79036741def10c56",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Fizzule accepted the recognition and offered a whistle for later meetings. Two blasts would identify an ally without repeating the flare signal he had found excessive."},{["episodeID"]="horde-observed-shattered-hand-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=2478}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"2478:description:1-62","2478:description:64-143","2478:description:148-206","2478:description:208-276","2478:description:278-308","2478:description:313-436","2478:description:438-509","2478:objective:1-81","2478:objective:83-105","2478:objective:107-137","2478:objective:139-147","2478:objective:152-294","2478:objective:296-384"},["questID"]=2478,["sourceHash"]="94536c93e5ec7c09ae1758abfd22c5f982cb0d614be54df13758a5961dafe458",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Fizzule directed the operation toward a tower already weakened by poison. Its key, Gallywix's lockbox, and the cache of altered mixture turned the contact into a dangerous recovery for Shenthul."},{["episodeID"]="horde-observed-shattered-hand-4",["requiresAll"]={{["minimumStage"]=4,["questID"]=2478}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"2478:description:1-62","2478:description:64-143","2478:description:148-206","2478:description:208-276","2478:description:278-308","2478:description:313-436","2478:description:438-509","2478:objective:1-81","2478:objective:83-105","2478:objective:107-137","2478:objective:139-147","2478:objective:152-294","2478:objective:296-384","2478:completion:1-53","2478:completion:55-87","2478:completion:89-148","2478:completion:153-190","2478:completion:192-249"},["questID"]=2478,["sourceHash"]="94536c93e5ec7c09ae1758abfd22c5f982cb0d614be54df13758a5961dafe458",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Shenthul spoke of Fizzule as a lost agent and praised the completed mission. His concern now turned to whether the returning operative would survive to serve again."},{["episodeID"]="horde-observed-shattered-hand-5",["requiresAll"]={{["minimumStage"]=2,["questID"]=2479}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"2479:description:1-60","2479:description:65-99","2479:description:101-177","2479:objective:1-104","2479:objective:109-233","2479:objective:235-251"},["questID"]=2479,["sourceHash"]="9a6c76204e08710a44e2a1119cbb45c1832b5686fb830575711176974486702f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A sample of the mixture was bound for Hinott in Tarren Mill. Shenthul trusted him as the best hope of a cure, placing recovery before the promised lessons in the making and use of poisons."},{["episodeID"]="horde-observed-shattered-hand-6",["requiresAll"]={{["minimumStage"]=4,["questID"]=2480}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"2480:description:1-54","2480:description:56-70","2480:description:72-154","2480:description:159-236","2480:description:241-287","2480:objective:1-43","2480:completion:1-18","2480:completion:20-136"},["questID"]=2480,["sourceHash"]="01c3f443255c1a6db93525d7582a7eab7d8cd68c1c579608b61a23cb1861d303",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The wait ended with an antidote ready. Hinott promised that drinking it would stop the creeping madness, though he could offer no remedy for the smell."}},["grouping"]="SOURCE_REVIEWED_NARRATIVE_CHAIN_3PLUS",["quests"]={2460,2458,2478,2479,2480},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="Recognition and the cost of the mission"},["horde-observed-wolf-heart-research"]={["authored"]=true,["branchHandling"]={{["detail"]="Captured player names, races, and class-address tokens are not universal eligibility rules; runtime retains exact per-quest source masks.",["kind"]="EXACT_SOURCE_ELIGIBILITY",["quests"]={{["classMask"]="?",["questID"]=3221,["raceMask"]="178"},{["classMask"]="?",["questID"]=1359,["raceMask"]="178"},{["classMask"]="?",["questID"]=1358,["raceMask"]="178"}}},{["detail"]="Retained as individual entries; not required for this narrative outcome and not expanded into separate short arcs.",["kind"]="STRUCTURAL_NEIGHBORS_OUTSIDE_NARRATIVE_SCOPE",["questIDs"]={435,449}}},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=3221,["sourceHash"]="8307e72331c45ff04cd7694469c692990ab5b934dd0e92d3c0bab4eaf53fbfce"},{["minimumStage"]=4,["questID"]=1359,["sourceHash"]="a185bcb63ae6775084397e03559c664ee5094a1f6fbf7a3cb4ab648fd9231977"},{["minimumStage"]=4,["questID"]=1358,["sourceHash"]="f94abb1bbb72dc0900825c34c2cfe3acf7c0ed29ae2b90740f2f4022b8e9e437"}}},["interpretation"]="The three-step sample investigation is separate from Erland escort435 and the Deathstalker report449. Earlier heart collection is disclosed by these sources, not inferred personally completed. Every listed quest needs its own source-matching native stage4 observation. Structural neighboring errands and future promises are not inferred completed.",["scope"]="OBSERVED_REVIEWED_NARRATIVE_ROUTE_AND_STATED_OUTCOME"},["episodes"]={{["episodeID"]="horde-observed-wolf-heart-research-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=3221}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"3221:description:1-86","3221:description:89-188","3221:objective:1-49"},["questID"]=3221,["sourceHash"]="8307e72331c45ff04cd7694469c692990ab5b934dd0e92d3c0bab4eaf53fbfce",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Renferrel's summons concerned the wolf hearts already brought to his laboratory. Hadrec could provide no details, leaving the apothecary to explain why the old samples demanded new attention."},{["episodeID"]="horde-observed-wolf-heart-research-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=1359}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1359:description:1-75","1359:description:78-171","1359:description:176-227","1359:description:230-273","1359:description:276-319","1359:description:322-376","1359:objective:1-66"},["questID"]=1359,["sourceHash"]="a185bcb63ae6775084397e03559c664ee5094a1f6fbf7a3cb4ab648fd9231977",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The hearts carried a toxicity Renferrel thought should have killed the wolves that bore them. He kept material for his own work and sent further samples to Zinge, turning an unexpected survival into a question for the society's researchers."},{["episodeID"]="horde-observed-wolf-heart-research-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=1359}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1359:description:1-75","1359:description:78-171","1359:description:176-227","1359:description:230-273","1359:description:276-319","1359:description:322-376","1359:objective:1-66","1359:completion:1-51","1359:completion:53-90","1359:completion:92-188"},["questID"]=1359,["sourceHash"]="a185bcb63ae6775084397e03559c664ee5094a1f6fbf7a3cb4ab648fd9231977",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Zinge welcomed the unusual toxin as material for experiment. Her interest continued the inquiry rather than resolving why the wolves had lived with it."},{["episodeID"]="horde-observed-wolf-heart-research-4",["requiresAll"]={{["minimumStage"]=2,["questID"]=1358}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1358:description:1-118","1358:description:121-197","1358:description:202-275","1358:description:278-392","1358:description:395-461","1358:objective:1-65"},["questID"]=1358,["sourceHash"]="f94abb1bbb72dc0900825c34c2cfe3acf7c0ed29ae2b90740f2f4022b8e9e437",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Zinge extended the comparison across the sea. Helbrim was studying Lordaeron toxins in Kalimdor's beasts, and a sample from Silverpine could join that work at the Crossroads."},{["episodeID"]="horde-observed-wolf-heart-research-5",["requiresAll"]={{["minimumStage"]=4,["questID"]=1358}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1358:description:1-118","1358:description:121-197","1358:description:202-275","1358:description:278-392","1358:description:395-461","1358:objective:1-65","1358:completion:1-14","1358:completion:16-137","1358:completion:142-172","1358:completion:174-200"},["questID"]=1358,["sourceHash"]="f94abb1bbb72dc0900825c34c2cfe3acf7c0ed29ae2b90740f2f4022b8e9e437",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Helbrim welcomed the sample for the possibilities suggested by the initial reports. He hoped its toxicity could advance the study of poisons and accepted the delivery at the Crossroads."}},["grouping"]="SOURCE_REVIEWED_NARRATIVE_CHAIN_3PLUS",["quests"]={3221,1359,1358},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="A toxin that should have killed its host"},["horde-rogue-wrenix-training"]={["authored"]=true,["branchHandling"]={"Either Shenthul introduction is sufficient; do not require both."},["completionRequirements"]={["expression"]={["allOf"]={{["anyOf"]={{["minimumStage"]=4,["questID"]=2378,["sourceHash"]="7d902df78d98cde721c3e5fae46e091bf1c09c0c6f1125da4288417c61ba6f04"},{["minimumStage"]=4,["questID"]=2380,["sourceHash"]="01e0b316a855c90ebff5b300583224ade2fe0a74ea41b29253b513ebb7c5ae58"}}},{["minimumStage"]=4,["questID"]=2379,["sourceHash"]="16ec6752c7638692564f6eeb1fac3ada7511598b3fa43b0d0e1afdbf2d3a6fbe"},{["minimumStage"]=4,["questID"]=2382,["sourceHash"]="929374783120fd5759e80c8a9b4f85991aad040b03740b75d18c91842bd4ee2a"},{["minimumStage"]=4,["questID"]=2381,["sourceHash"]="5c1fbcf44b5f726de5abc10ed62f6fbd72a91324d71bcb4aa76e5c069ec177af"}}},["interpretation"]="Every required route step needs its own recorded hand-in and exact source hash. Optional or alternative branches retain their separate rules.",["scope"]="DEFINED_OBSERVED_ROUTE_NOT_WORLD_VICTORY"},["episodes"]={{["episodeID"]="horde-rogue-wrenix-training-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=2378}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"2378:description:1-94","2378:description:96-195","2378:description:200-255","2378:description:257-321","2378:objective:1-68"},["questID"]=2378,["sourceHash"]="7d902df78d98cde721c3e5fae46e091bf1c09c0c6f1125da4288417c61ba6f04",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Carkad directed a promising operative toward the Deathstalkers' Shattered Hand allies. Shenthul in Orgrimmar offered a more demanding school of stealth."},{["episodeID"]="horde-rogue-wrenix-training-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=2380}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"2380:description:1-88","2380:description:90-205","2380:description:210-297","2380:objective:1-56"},["questID"]=2380,["sourceHash"]="01e0b316a855c90ebff5b300583224ade2fe0a74ea41b29253b513ebb7c5ae58",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Kaplak relayed Shenthul's request from Orgrimmar. Whatever he thought of the novice's skill, the summons offered further training in deception."},{["episodeID"]="horde-rogue-wrenix-training-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=2379}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"2379:description:1-86","2379:description:91-172","2379:description:177-301","2379:objective:1-44"},["questID"]=2379,["sourceHash"]="16ec6752c7638692564f6eeb1fac3ada7511598b3fa43b0d0e1afdbf2d3a6fbe",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Shenthul demanded practice as well as determination. Zando'zan would begin teaching the stealth and theft required for the Hand's work."},{["episodeID"]="horde-rogue-wrenix-training-4",["requiresAll"]={{["minimumStage"]=2,["questID"]=2382}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"2382:description:1-22","2382:description:24-42","2382:description:44-60","2382:description:62-128","2382:description:130-157","2382:description:166-193","2382:description:195-280","2382:objective:1-53"},["questID"]=2382,["sourceHash"]="929374783120fd5759e80c8a9b4f85991aad040b03740b75d18c91842bd4ee2a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Zando'zan's disturbing vision gave way to a concrete destination: Wrenix in Ratchet. The visit would lead from an unsettling prophecy into practical work."},{["episodeID"]="horde-rogue-wrenix-training-5",["requiresAll"]={{["minimumStage"]=4,["questID"]=2381}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"2381:description:1-121","2381:description:126-202","2381:description:204-261","2381:description:263-362","2381:description:367-427","2381:description:429-503","2381:objective:1-67","2381:objective:69-100","2381:objective:102-156","2381:objective:158-216","2381:objective:221-295","2381:completion:1-11","2381:completion:13-23","2381:completion:25-39","2381:completion:41-62","2381:completion:64-117","2381:completion:122-151","2381:completion:153-214"},["questID"]=2381,["sourceHash"]="5c1fbcf44b5f726de5abc10ed62f6fbd72a91324d71bcb4aa76e5c069ec177af",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The Southsea treasure reached Wrenix despite the danger that had claimed earlier thieves. He marveled at the success and offered a share, uncertain how much belonged to talent and how much to luck."}},["grouping"]="Source-reviewed continuing narrative; branch and source-stage gates retained.",["quests"]={2378,2380,2379,2382,2381},["referenceStatus"]="RETAINED_QUEST_SOURCE_STAGES_NOT_CURRENT_PLAYABILITY_VERIFICATION",["sourceConflict"]=false,["title"]="Lessons in the Shadows"},["ironforge-sully-balloo-memorial"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=637,["sourceHash"]="a1e92517f7d045907b359ead31f88d21261617971c93dc52dd1cc716df57e06a"},{["minimumStage"]=4,["questID"]=683,["sourceHash"]="a99f1146ef2abf8b289325ffb1ec9a4969fd266c808b376b67e5683ae2b54fe5"},{["minimumStage"]=4,["questID"]=686,["sourceHash"]="649ec407f53157887d3dc2e45cf012e4a90d4a27967dfe3437c3e89ac1543d57"},{["minimumStage"]=4,["questID"]=689,["sourceHash"]="ce883697c253c8a06d5767ebba77672dabe8855c2748a06b37cc7a8bedf7428d"},{["minimumStage"]=4,["questID"]=700,["sourceHash"]="3c9b86eb20397b2ed193c4a0bdbbe3b87db77095038fcc9eca42f9b0f29f58d6"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="ironforge-sully-balloo-memorial-637",["requiresAll"]={{["minimumStage"]=4,["questID"]=637}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"637:description:1-149","637:description:154-186","637:description:188-242","637:objective:1-45","637:completion:1-55","637:completion:57-72","637:completion:77-105"},["questID"]=637,["sourceHash"]="a1e92517f7d045907b359ead31f88d21261617971c93dc52dd1cc716df57e06a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Water had nearly destroyed Sully’s envelope, but the careful words inside still reached Sara in Ironforge. News of her husband beneath the icy water left her to read his words under the weight of his death."},{["episodeID"]="ironforge-sully-balloo-memorial-683",["requiresAll"]={{["minimumStage"]=2,["questID"]=683}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"683:description:1-45","683:description:50-138","683:description:140-261","683:description:266-359","683:description:362-383","683:objective:1-63"},["questID"]=683,["sourceHash"]="a99f1146ef2abf8b289325ffb1ec9a4969fd266c808b376b67e5683ae2b54fe5",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Sara prepared a plea for King Magni but could not bear to bring it before him in her grief. The letter that had crossed from the battlefield now gave way to another, asking that her loss be heard in the royal chamber."},{["episodeID"]="ironforge-sully-balloo-memorial-686",["requiresAll"]={{["minimumStage"]=2,["questID"]=686}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"686:description:1-38","686:description:40-137","686:description:139-256","686:description:261-349","686:description:354-443","686:description:448-472","686:description:474-510","686:objective:1-70"},["questID"]=686,["sourceHash"]="649ec407f53157887d3dc2e45cf012e4a90d4a27967dfe3437c3e89ac1543d57",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Magni could not restore Sully’s life. He could commission a tribute, and Grand Mason Marblesten was to receive the order for a memorial that might carry the soldier’s name beyond the war."},{["episodeID"]="ironforge-sully-balloo-memorial-689",["requiresAll"]={{["minimumStage"]=4,["questID"]=689}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"689:description:1-86","689:description:89-151","689:description:156-196","689:description:201-266","689:description:268-362","689:description:364-437","689:objective:1-70","689:completion:1-8","689:completion:10-43","689:completion:48-90"},["questID"]=689,["sourceHash"]="ce883697c253c8a06d5767ebba77672dabe8855c2748a06b37cc7a8bedf7428d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Marblesten wanted fine Alterac granite for a work worthy of the king’s commission. Stone from Darrow Hill arrived to give the promised remembrance its substance, turning a widow’s appeal into the mason’s craft."},{["episodeID"]="ironforge-sully-balloo-memorial-700",["requiresAll"]={{["minimumStage"]=4,["questID"]=700}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"700:description:1-41","700:description:44-85","700:description:90-126","700:description:128-180","700:description:185-276","700:objective:1-33","700:completion:1-69","700:completion:71-122","700:completion:127-237","700:completion:239-343"},["questID"]=700,["sourceHash"]="3c9b86eb20397b2ed193c4a0bdbbe3b87db77095038fcc9eca42f9b0f29f58d6",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The mason reported the memorial complete and sent word back to Magni. The king regarded the granite as a small return for a dwarf’s life, yet hoped future generations would remember the people whose sacrifices had made their world possible."}},["grouping"]="The letter, widow’s petition and commissioned memorial; the finished monument is reported by its mason, not an invented personal visit or promise of eternity.",["quests"]={637,683,686,689,700},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Stone for a Soldier"},["jaedenar-banehollow-stardust"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=7623,["sourceHash"]="f6e7503b62c3181697b40bdfa028a91dc3d1977b3819297eafa1622723787538"},{["minimumStage"]=4,["questID"]=7624,["sourceHash"]="2df178147cfe60d7bf6885aa519683bd97c7ed579d1e63b73ab5c96399ef3c06"},{["minimumStage"]=4,["questID"]=7625,["sourceHash"]="2232b036584d6150a4fa5b512347f03aa9959dac1bce1be3b0e684621692d060"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="jaedenar-banehollow-stardust-7623",["requiresAll"]={{["minimumStage"]=2,["questID"]=7623}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"7623:description:1-54","7623:description:57-99","7623:description:102-136","7623:description:141-240","7623:description:243-293","7623:description:298-408","7623:description:411-481","7623:objective:1-62","7623:objective:67-141"},["questID"]=7623,["sourceHash"]="f6e7503b62c3181697b40bdfa028a91dc3d1977b3819297eafa1622723787538",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Opening Xoroth required stardust rarely found on Azeroth. Gorzeeki pointed toward Banehollow, but reaching the dreadlord first required a disguise steeped in the Shadow Council's corruption."},{["episodeID"]="jaedenar-banehollow-stardust-7624",["requiresAll"]={{["minimumStage"]=2,["questID"]=7624}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"7624:description:1-33","7624:description:36-52","7624:description:57-169","7624:description:172-237","7624:description:242-283","7624:description:286-350","7624:description:353-412","7624:description:415-449","7624:objective:1-80"},["questID"]=7624,["sourceHash"]="2df178147cfe60d7bf6885aa519683bd97c7ed579d1e63b73ab5c96399ef3c06",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The audience became a demand for blood. Banehollow accused Ulathek of serving his Xorothian rival and made the suspected spy's heart the price of proving loyalty."},{["episodeID"]="jaedenar-banehollow-stardust-7625",["requiresAll"]={{["minimumStage"]=4,["questID"]=7625}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"7625:description:1-45","7625:description:48-118","7625:description:121-187","7625:description:192-201","7625:description:204-256","7625:description:259-287","7625:description:289-313","7625:objective:1-40","7625:objective:43-95","7625:completion:1-12","7625:completion:14-45","7625:completion:47-132","7625:completion:137-306"},["questID"]=7625,["sourceHash"]="2232b036584d6150a4fa5b512347f03aa9959dac1bce1be3b0e684621692d060",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="With Banehollow appeased, Ur'dan's costly stardust could be carried back to Gorzeeki. The rival's loss served the dreadlord's interests; the purchased dust served the separate purpose of preparing a portal."}},["grouping"]="One bargain with Banehollow, not the entire parallel preparation for the dreadsteed ritual.",["quests"]={7623,7624,7625},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Price of a Rival’s Stardust"},["lakeshire-parker-darcy-daffodils"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=129,["sourceHash"]="83ffed488e627b37c6f6aa8d512a2128908afdc36d25c4f8690afcd804c1d41f"},{["minimumStage"]=4,["questID"]=130,["sourceHash"]="801b86e17b95b0a0429985cf52bdb4336cae6fee04d2c06567f8364f6a718c40"},{["minimumStage"]=4,["questID"]=131,["sourceHash"]="bbd4a3f61452930d6f38dd279640da0661a13742d2568562110c69add1e1eaa3"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="lakeshire-parker-darcy-daffodils-129",["requiresAll"]={{["minimumStage"]=2,["questID"]=129}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"129:description:1-22","129:description:25-212","129:description:217-303","129:description:306-360","129:objective:1-37","129:objective:40-80"},["questID"]=129,["sourceHash"]="83ffed488e627b37c6f6aa8d512a2128908afdc36d25c4f8690afcd804c1d41f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Darcy had prepared lunch for Parker, but the patrol road was too dangerous for her to carry it herself. Delivering the meal meant a small comfort for a guard working against Lakeshire’s orcs and gnolls."},{["episodeID"]="lakeshire-parker-darcy-daffodils-130",["requiresAll"]={{["minimumStage"]=2,["questID"]=130}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"130:description:1-67","130:description:70-151","130:description:156-261","130:objective:1-51"},["questID"]=130,["sourceHash"]="801b86e17b95b0a0429985cf52bdb4336cae6fee04d2c06567f8364f6a718c40",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Parker answered the kindness with a request for flowers. The herbalist Martie could supply them, but he insisted that neither sender nor recipient be named to her."},{["episodeID"]="lakeshire-parker-darcy-daffodils-131",["requiresAll"]={{["minimumStage"]=4,["questID"]=131}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"131:description:1-21","131:description:24-49","131:description:52-71","131:objective:1-32","131:completion:1-21","131:completion:23-61","131:completion:66-107","131:completion:109-181","131:completion:183-229","131:completion:231-292","131:completion:297-324","131:completion:326-357"},["questID"]=131,["sourceHash"]="bbd4a3f61452930d6f38dd279640da0661a13742d2568562110c69add1e1eaa3",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Martie chose her favorite daffodils, and Darcy immediately recognized the choice. Her pleasure mingled with suspicion of the herbalist’s jealousy, explaining Parker’s secrecy without proving her darker fears about the bouquet. The flowers and the promised lunch completed the exchange."}},["grouping"]="A lunch delivery becomes a discreet gift; Darcy’s jealousy claim does not prove poison or a wider romantic history.",["quests"]={129,130,131},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Lunch and a Carefully Chosen Bouquet"},["loch-daryl-vyrin-hunting-rivalry"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=257,["sourceHash"]="5e000e97fe9a1b4e066cd82def054250754d5b19cb11f555c7dc501dbb383735"},{["minimumStage"]=4,["questID"]=258,["sourceHash"]="c88e9dd39b1ec9b15625a80a7ef34f5d4393ab7024d1d9e5383f44f2d9444a29"},{["minimumStage"]=4,["questID"]=271,["sourceHash"]="c58369da9e18e0e5a6d4640c941bea5b9929ceec41cf162274f46ae3d173f21c"},{["minimumStage"]=4,["questID"]=531,["sourceHash"]="03ecb7aa57cd6f67b2dfa2ebbc87c7a4af891257020784fca474c8582d92322f"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="loch-daryl-vyrin-hunting-rivalry-257",["requiresAll"]={{["minimumStage"]=2,["questID"]=257}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"257:description:1-50","257:description:52-70","257:description:72-114","257:description:116-229","257:description:234-283","257:description:285-334","257:description:336-423","257:description:428-460","257:description:465-507","257:objective:1-101"},["questID"]=257,["sourceHash"]="5e000e97fe9a1b4e066cd82def054250754d5b19cb11f555c7dc501dbb383735",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Daryl’s greeting was a challenge rather than a welcome. He wagered a weapon on a swift buzzard hunt, confident that the visitor could not equal the skill behind his own boasts."},{["episodeID"]="loch-daryl-vyrin-hunting-rivalry-258",["requiresAll"]={{["minimumStage"]=2,["questID"]=258}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"258:description:1-13","258:description:15-87","258:description:89-129","258:description:134-174","258:description:176-260","258:description:262-305","258:description:310-336","258:description:338-389","258:description:394-463","258:description:469-491","258:objective:1-104"},["questID"]=258,["sourceHash"]="c88e9dd39b1ec9b15625a80a7ef34f5d4393ab7024d1d9e5383f44f2d9444a29",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Success only brought another test: tougher boars and less time. Daryl dismissed the first result while drawing attention to his famous scar, leaving his pride as much the subject as the hunting."},{["episodeID"]="loch-daryl-vyrin-hunting-rivalry-271",["requiresAll"]={{["minimumStage"]=4,["questID"]=271}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"271:description:1-73","271:description:75-121","271:description:126-241","271:description:243-290","271:description:292-357","271:description:362-429","271:description:434-511","271:objective:1-87","271:completion:7-18","271:completion:20-53","271:completion:58-105","271:completion:110-172","271:completion:174-212","271:completion:217-261","271:completion:266-297","271:completion:299-332"},["questID"]=271,["sourceHash"]="c58369da9e18e0e5a6d4640c941bea5b9929ceec41cf162274f46ae3d173f21c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Vyrin supplied the scar’s uncomfortable explanation: Ol’ Sooty had defeated Daryl during an earlier hunt. The bear’s head, presented after the new confrontation, made him touch the old wound and demand that the trophy be taken away."},{["episodeID"]="loch-daryl-vyrin-hunting-rivalry-531",["requiresAll"]={{["minimumStage"]=4,["questID"]=531}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"531:description:1-6","531:description:8-53","531:description:55-89","531:description:97-107","531:description:112-145","531:description:147-200","531:objective:1-66","531:completion:1-50","531:completion:52-159","531:completion:161-194"},["questID"]=531,["sourceHash"]="03ecb7aa57cd6f67b2dfa2ebbc87c7a4af891257020784fca474c8582d92322f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Vyrin received the head and paid with satisfaction. Her scheme had found the fear beneath Daryl’s practiced superiority, closing the rivalry’s little lesson rather than proving him incapable of hunting."}},["grouping"]="Four linked wagers and the bear trophy; conflicting recollections of the scar’s date are deliberately not reconciled.",["quests"]={257,258,271,531},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Hunter Behind the Boast"},["loch-mountaineers-stonesplinter-command"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=224,["sourceHash"]="25af1add7edc17ab4fcda47789626d341226e29fae63bff6b4290e17e6f02d74"},{["minimumStage"]=4,["questID"]=237,["sourceHash"]="ec6e18f252c110b3f42e145af442baad9b54e0aaff37a403312a565ce667a24b"},{["minimumStage"]=4,["questID"]=263,["sourceHash"]="f7c6359cfc5cb537ed68b9c4aad6a80c9e5868c477c1446bb2c8c30d65e43368"},{["minimumStage"]=4,["questID"]=217,["sourceHash"]="74a02ef17462e061ddbbf2b6549aec433f1d18a78f65dc9bee14678584b15378"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="loch-mountaineers-stonesplinter-command-224",["requiresAll"]={{["minimumStage"]=2,["questID"]=224}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"224:description:1-32","224:description:35-156","224:description:159-201","224:description:204-263","224:description:266-308","224:description:313-394","224:description:397-469","224:objective:1-122"},["questID"]=224,["sourceHash"]="25af1add7edc17ab4fcda47789626d341226e29fae63bff6b4290e17e6f02d74",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="With dwarven soldiers fighting far away, Cobbleflint’s Mountaineers faced troggs tunneling into the Loch. The southern tower needed outside help before its defenders were overwhelmed."},{["episodeID"]="loch-mountaineers-stonesplinter-command-237",["requiresAll"]={{["minimumStage"]=2,["questID"]=237}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"237:description:1-73","237:description:76-153","237:description:156-267","237:description:272-372","237:description:375-409","237:description:412-453","237:objective:1-149"},["questID"]=237,["sourceHash"]="ec6e18f252c110b3f42e145af442baad9b54e0aaff37a403312a565ce667a24b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Gravelgaw sought continued pressure in the hills to buy time for troops returning from the Alliance front. The attacks served a delaying defense, rather than a claim that the invaders were nearly gone."},{["episodeID"]="loch-mountaineers-stonesplinter-command-263",["requiresAll"]={{["minimumStage"]=2,["questID"]=263}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"263:description:1-61","263:description:64-97","263:description:100-142","263:description:145-216","263:description:219-285","263:description:290-363","263:description:366-423","263:objective:1-125"},["questID"]=263,["sourceHash"]="f7c6359cfc5cb537ed68b9c4aad6a80c9e5868c477c1446bb2c8c30d65e43368",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The expected relief did not come. Reserves were needed at the distant front, leaving Wallbang’s remaining force to continue the struggle against the Stonesplinter’s shamans and fighters."},{["episodeID"]="loch-mountaineers-stonesplinter-command-217",["requiresAll"]={{["minimumStage"]=4,["questID"]=217}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"217:description:1-73","217:description:76-170","217:description:173-208","217:description:211-282","217:description:287-393","217:description:396-501","217:objective:1-138","217:completion:1-19","217:completion:21-56","217:completion:58-147"},["questID"]=217,["sourceHash"]="74a02ef17462e061ddbbf2b6549aec433f1d18a78f65dc9bee14678584b15378",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Scouts identified Grawmug and the two guards who never left his side. Their fall gave Rugelfuss hope of driving the troggs back underground, while the distinction remained between removing this leadership and securing the whole land."}},["grouping"]="Four defenses culminate in the named chieftain; reinforcements and permanent removal of the troggs are not inferred.",["quests"]={224,237,263,217},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Holding the Loch Without Reserves"},["mulgore-melor-distant-hunts"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=1130,["sourceHash"]="d724ff8dca5cbb09d7b0e30779c33fe671aadf7e48665d585f077b082c4ab0dc"},{["minimumStage"]=4,["questID"]=1131,["sourceHash"]="a08d23077fca21d8ed9d82737de3569244340f113977f1b0fc419c7726023be9"},{["minimumStage"]=4,["questID"]=1136,["sourceHash"]="5738e3767ee316402a726abd8fccaa1bd366bcb69db85d3862911402b56f386f"}}},["interpretation"]="Every required route step needs its own recorded hand-in and exact source hash. Optional or alternative branches retain their separate rules.",["scope"]="DEFINED_OBSERVED_ROUTE_NOT_WORLD_VICTORY"},["episodes"]={{["episodeID"]="mulgore-melor-distant-hunts-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=1130}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"1130:description:1-75","1130:description:80-149","1130:description:152-186","1130:objective:1-44"},["questID"]=1130,["sourceHash"]="d724ff8dca5cbb09d7b0e30779c33fe671aadf7e48665d585f077b082c4ab0dc",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Word of earlier deeds had reached Melor on Hunter's Rise. Jorn passed on the invitation to a different kind of hunt."},{["episodeID"]="mulgore-melor-distant-hunts-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=1131}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1131:description:1-26","1131:description:29-55","1131:description:58-114","1131:description:119-174","1131:description:177-236","1131:description:241-309","1131:description:312-418","1131:description:423-441","1131:description:444-468","1131:objective:1-58"},["questID"]=1131,["sourceHash"]="a08d23077fca21d8ed9d82737de3569244340f113977f1b0fc419c7726023be9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Melor saw Steelsnap's terror over peaceful beasts as something beyond ordinary hunting for food or honor. The hyena's rib would be proof that this taint had been confronted."},{["episodeID"]="mulgore-melor-distant-hunts-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=1136}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1136:description:1-54","1136:description:57-70","1136:description:75-129","1136:description:132-206","1136:description:209-232","1136:description:237-292","1136:description:295-317","1136:description:320-366","1136:description:371-381","1136:description:384-436","1136:description:439-508","1136:objective:1-58","1136:completion:1-70","1136:completion:72-85","1136:completion:90-185","1136:completion:187-282"},["questID"]=1136,["sourceHash"]="5738e3767ee316402a726abd8fccaa1bd366bcb69db85d3862911402b56f386f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Frostmaw's mane brought the distant mountain hunt back to Melor. He acknowledged the cunning as well as the long journey, joining the snowbound trial to the work begun in the valleys."}},["grouping"]="Source-reviewed continuing narrative; branch and source-stage gates retained.",["quests"]={1130,1131,1136},["referenceStatus"]="RETAINED_QUEST_SOURCE_STAGES_NOT_CURRENT_PLAYABILITY_VERIFICATION",["sourceConflict"]=false,["title"]="The Hunter Beyond the Plains"},["mulgore-venture-caravan-papers"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=749,["sourceHash"]="2472b9c3e3b2787c3545eb4df3521eacb0c6ed0ad7a67ce1b47d9a32695f3664"},{["minimumStage"]=4,["questID"]=751,["sourceHash"]="269b082a6a55a6941851a2921b85edd0f20044ca4597595b05eac3bca35880bb"},{["minimumStage"]=4,["questID"]=764,["sourceHash"]="ce4d0e000756ef3eba5024c94a6811ac1014fcb5787c80cf90a222ef79e593b7"},{["minimumStage"]=4,["questID"]=765,["sourceHash"]="3693db2505943a0c608a3ef03a71694558d3fe523773eaa16670ecfde840a9f6"}}},["interpretation"]="Every required route step needs its own recorded hand-in and exact source hash. Optional or alternative branches retain their separate rules.",["scope"]="DEFINED_OBSERVED_ROUTE_NOT_WORLD_VICTORY"},["episodes"]={{["episodeID"]="mulgore-venture-caravan-papers-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=749}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"749:description:1-38","749:description:40-109","749:description:111-216","749:description:221-334","749:description:336-407","749:description:412-486","749:objective:1-94"},["questID"]=749,["sourceHash"]="2472b9c3e3b2787c3545eb4df3521eacb0c6ed0ad7a67ce1b47d9a32695f3664",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A Venture Company caravan lay burned after fighting that had cost Morin's party two lives. Salvagers still worked around the wreck, suggesting that its crates had survived."},{["episodeID"]="mulgore-venture-caravan-papers-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=751}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"751:description:1-140","751:description:142-219","751:description:224-335","751:objective:1-22","751:objective:24-78"},["questID"]=751,["sourceHash"]="269b082a6a55a6941851a2921b85edd0f20044ca4597595b05eac3bca35880bb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Ore, minerals and documents inside the crate pointed beyond a single ruined wagon. Smoke and work in the eastern foothills gave the papers a place in the company's wider operation."},{["episodeID"]="mulgore-venture-caravan-papers-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=764}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"764:description:1-40","764:description:42-87","764:description:89-104","764:description:106-163","764:description:165-254","764:description:259-289","764:description:291-404","764:description:406-479","764:objective:1-19","764:objective:21-45","764:objective:47-102"},["questID"]=764,["sourceHash"]="ce4d0e000756ef3eba5024c94a6811ac1014fcb5787c80cf90a222ef79e593b7",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Morin read the growing workforce and equipment as signs of an expanding mine. The company's extraction in tauren lands now called for a direct response."},{["episodeID"]="mulgore-venture-caravan-papers-4",["requiresAll"]={{["minimumStage"]=4,["questID"]=765}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"765:description:1-73","765:description:75-193","765:description:198-279","765:description:281-328","765:description:330-401","765:description:403-435","765:description:437-504","765:objective:1-96","765:completion:1-79","765:completion:81-192","765:completion:194-220","765:completion:222-252"},["questID"]=765,["sourceHash"]="3693db2505943a0c608a3ef03a71694558d3fe523773eaa16670ecfde840a9f6",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Fizsprocket's clipboard reached Morin, who intended to study it for further company plans. The recovered papers widened the inquiry; they did not establish that the company had abandoned Mulgore."}},["grouping"]="Source-reviewed continuing narrative; branch and source-stage gates retained.",["quests"]={749,751,764,765},["referenceStatus"]="RETAINED_QUEST_SOURCE_STAGES_NOT_CURRENT_PLAYABILITY_VERIFICATION",["sourceConflict"]=false,["title"]="Papers in the Burned Caravan"},["northshire-echo-ridge-kobolds"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=7,["sourceHash"]="730f34c2bae9f83a3f719c35da6df15614a973a1afc2a3e69a64fdf83351a924"},{["minimumStage"]=4,["questID"]=15,["sourceHash"]="1df8e6166fda022ef00b9cc823dc4a47d3f72f71d24024dc63e1760ab411f3d7"},{["minimumStage"]=4,["questID"]=21,["sourceHash"]="3cdd14a1eb633382f6c90249a3dba2c08de418e6722e17b41f0b7ce4a9ffdd84"}}},["interpretation"]="Requires all three observed fulfillments. McBride may send others against remaining kobolds; no permanent mine clear is implied.",["scope"]="OBSERVED_THREE_STAGE_ROUTE_NOT_PERMANENT_KOBOLD_ERADICATION"},["episodes"]={{["episodeID"]="echo-woods",["requiresAll"]={{["minimumStage"]=2,["questID"]=7}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"7:description:1-40","7:description:43-97","7:description:100-145","7:description:148-218","7:objective:1-54"},["questID"]=7,["sourceHash"]="730f34c2bae9f83a3f719c35da6df15614a973a1afc2a3e69a64fdf83351a924"}},["text"]="A kobold clan had spread into the woods north of Northshire Abbey. McBride hoped that reducing its numbers would give the defenders a chance to drive it away."},{["episodeID"]="echo-workers",["requiresAll"]={{["minimumStage"]=2,["questID"]=15}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"15:description:1-80","15:description:83-157","15:description:162-192","15:description:195-224","15:description:227-283","15:objective:1-60"},["questID"]=15,["sourceHash"]="1df8e6166fda022ef00b9cc823dc4a47d3f72f71d24024dc63e1760ab411f3d7"}},["text"]="The scouts found the infestation larger than expected. Kobold workers had made camp around Echo Ridge Mine, where the trouble reached beyond the woods north of the abbey."},{["episodeID"]="echo-laborers",["requiresAll"]={{["minimumStage"]=2,["questID"]=21}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"21:description:1-78","21:description:81-128","21:description:133-150","21:description:153-254","21:objective:1-76"},["questID"]=21,["sourceHash"]="3cdd14a1eb633382f6c90249a3dba2c08de418e6722e17b41f0b7ce4a9ffdd84"}},["text"]="The kobolds' foothold at Echo Ridge grew more dangerous the longer it lasted. McBride wanted the laborers driven from the mine before they could settle deeper into Northshire."},{["episodeID"]="echo-limited-success",["requiresAll"]={{["minimumStage"]=4,["questID"]=21}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"21:completion:1-80","21:completion:82-158","21:completion:160-189"},["questID"]=21,["sourceHash"]="3cdd14a1eb633382f6c90249a3dba2c08de418e6722e17b41f0b7ce4a9ffdd84"}},["text"]="McBride acknowledged the service to Stormwind, but the mine was not declared empty. He would send others against any remaining kobolds while the adventurer took up further duties."}},["grouping"]="A three-step escalating kobold investigation; excludes unrelated human class introductions in the larger prerequisite component.",["quests"]={7,15,21},["referenceStatus"]="SOURCE_BACKED_CLASSIC_ROUTE; FOREVER_IDENTITY_AND_STAGE_REQUIRED",["sourceConflict"]=false,["title"]="The Trouble at Echo Ridge"},["orgrimmar-onyxia-trophy-and-scales"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=7490,["sourceHash"]="19430c68dba3a7a7e83c9d423f6dcd37e41a497168ecbd5eb81dfe8ae46bce30"},{["minimumStage"]=4,["questID"]=7491,["sourceHash"]="fd70b6bcd0f07ffdd8e706350f245d1cc01475f3e4fbae25e30eef6b903a75e4"},{["minimumStage"]=4,["questID"]=7493,["sourceHash"]="a00382118cf286d80280f8af28967de2ee41caee00d2d3f775bd2d4021e4051d"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="orgrimmar-onyxia-trophy-and-scales-7490",["requiresAll"]={{["minimumStage"]=4,["questID"]=7490}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"7490:description:1-37","7490:description:39-104","7490:description:106-151","7490:objective:1-47","7490:completion:1-42","7490:completion:44-88","7490:completion:90-130"},["questID"]=7490,["sourceHash"]="19430c68dba3a7a7e83c9d423f6dcd37e41a497168ecbd5eb81dfe8ae46bce30",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Onyxia’s head brought the news of victory before Thrall. The warchief answered the service with honor, turning a trophy from the black brood mother into a public occasion for the Horde."},{["episodeID"]="orgrimmar-onyxia-trophy-and-scales-7491",["requiresAll"]={{["minimumStage"]=4,["questID"]=7491}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"7491:description:1-63","7491:description:68-88","7491:description:93-130","7491:objective:1-52","7491:completion:1-74"},["questID"]=7491,["sourceHash"]="fd70b6bcd0f07ffdd8e706350f245d1cc01475f3e4fbae25e30eef6b903a75e4",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Runthak waited in the Valley of Strength to receive the celebrated traveler. A choice of reward preceded the gathering’s festivities, carrying Thrall’s recognition into the city’s streets."},{["episodeID"]="orgrimmar-onyxia-trophy-and-scales-7493",["requiresAll"]={{["minimumStage"]=4,["questID"]=7493}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"7493:completion:1-45","7493:completion:47-81","7493:completion:83-95","7493:completion:100-142","7493:completion:144-247","7493:completion:252-304","7493:completion:306-398","7493:completion:400-408"},["questID"]=7493,["sourceHash"]="a00382118cf286d80280f8af28967de2ee41caee00d2d3f775bd2d4021e4051d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The recognition opened another possibility for an experienced leatherworker: knowledge of a cloak made from the brood mother’s scales. Its promised protection against Nefarian’s fiery breath pointed beyond the celebration, toward the dangers still waiting in Blackrock."}},["grouping"]="The Horde trophy celebration and a leatherworker’s offered instruction; no cloak crafting, personal kill credit or further dragon clear inferred.",["quests"]={7490,7491,7493},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Trophy Before the Warchief"},["paladin-fallen-charger-redemption"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=7637,["sourceHash"]="f3c85fa5416cdff98688395933055a8f8dfb3de8d4768b7f6fe7eb0ddb738fdb"},{["minimumStage"]=4,["questID"]=7639,["sourceHash"]="407f99a693b0628f2e56d934a4878af34dbe4d6ae1d7289a9851d8cb9fa323d4"},{["minimumStage"]=4,["questID"]=7640,["sourceHash"]="5922a689d7c235a6ef04f6643c0ddbcd6eb9d6c0a5d6ff74382907c0580835f2"},{["minimumStage"]=4,["questID"]=7641,["sourceHash"]="2e6d7bcbf2672691e301f672cf0704a8016b92f47d27bb5aa5cd4f8bf3f0a7f0"},{["minimumStage"]=4,["questID"]=7642,["sourceHash"]="a7d3a86bcf7cdb6fe5ed336e3c986985fb4786926151c9cf7e50064f299338ca"},{["minimumStage"]=4,["questID"]=7643,["sourceHash"]="b652d6f4d95c9769bcfed3f90b9aa7d7874d5b9462f4868cb703af257f39873f"},{["minimumStage"]=4,["questID"]=7644,["sourceHash"]="76418579e06da38d381bf87a0a29962791776b3e63e77e71c61b410cc48d6cb2"},{["minimumStage"]=4,["questID"]=7646,["sourceHash"]="834433d036546e6626f907e6c768b9dc6553d98294c867fb5c70d02cb884b8e2"},{["minimumStage"]=4,["questID"]=7647,["sourceHash"]="db046d5646a961ae4c786b068073c8bac5b3270d5cf83e0e4fd929fc177d3513"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="paladin-fallen-charger-redemption-7637",["requiresAll"]={{["minimumStage"]=2,["questID"]=7637}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"7637:description:1-93","7637:description:95-124","7637:description:129-195","7637:description:198-290","7637:description:295-346","7637:description:349-451","7637:description:456-489","7637:objective:1-64","7637:objective:67-133"},["questID"]=7637,["sourceHash"]="f3c85fa5416cdff98688395933055a8f8dfb3de8d4768b7f6fe7eb0ddb738fdb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Grayson began with sacrifice: even a righteous exorcism required compensation for Rohan's censer. The donation made another person's loss part of the paladin's responsibility."},{["episodeID"]="paladin-fallen-charger-redemption-7639",["requiresAll"]={{["minimumStage"]=2,["questID"]=7639}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"7639:description:1-35","7639:description:38-147","7639:description:152-209","7639:description:212-241","7639:objective:1-96"},["questID"]=7639,["sourceHash"]="407f99a693b0628f2e56d934a4878af34dbe4d6ae1d7289a9851d8cb9fa323d4",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Rohan's experienced censer returned to Grayson, ready to become a means of judgment. The next burden lay with spirits tormenting lands the living had lost."},{["episodeID"]="paladin-fallen-charger-redemption-7640",["requiresAll"]={{["minimumStage"]=2,["questID"]=7640}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"7640:description:1-108","7640:description:111-212","7640:description:215-377","7640:description:382-473","7640:objective:1-73","7640:objective:76-194"},["questID"]=7640,["sourceHash"]="5922a689d7c235a6ef04f6643c0ddbcd6eb9d6c0a5d6ff74382907c0580835f2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Terrordale's green disturbances marked wounds between the spirit realm and the physical ground. Using the attuned censer would expose the spirits that had to be confronted before the greater rescue."},{["episodeID"]="paladin-fallen-charger-redemption-7641",["requiresAll"]={{["minimumStage"]=2,["questID"]=7641}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"7641:description:1-85","7641:description:88-274","7641:description:279-331","7641:description:334-425","7641:description:428-487","7641:description:490-504","7641:objective:1-58"},["questID"]=7641,["sourceHash"]="2e6d7bcbf2672691e301f672cf0704a8016b92f47d27bb5aa5cd4f8bf3f0a7f0",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The future companion needed more than an ordinary harness. Grayson sent the commission to Grimand, whose barding could be prepared for the passage between life and spirit."},{["episodeID"]="paladin-fallen-charger-redemption-7642",["requiresAll"]={{["minimumStage"]=2,["questID"]=7642}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"7642:description:1-197","7642:description:200-232","7642:description:234-249","7642:description:252-324","7642:description:329-390","7642:description:393-499","7642:objective:1-154"},["questID"]=7642,["sourceHash"]="a7d3a86bcf7cdb6fe5ed336e3c986985fb4786926151c9cf7e50064f299338ca",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Cloth and arcanite would form the barding, while Arthas' Tears and Stratholme's holy water prepared its spiritual qualities. Craftsmanship and payment joined the earlier sacrifice in making the rescue possible."},{["episodeID"]="paladin-fallen-charger-redemption-7643",["requiresAll"]={{["minimumStage"]=2,["questID"]=7643}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"7643:description:1-78","7643:description:81-137","7643:description:140-198","7643:description:201-239","7643:description:244-283","7643:description:286-342","7643:description:345-383","7643:description:386-454","7643:description:456-486","7643:objective:1-59","7643:objective:62-131","7643:objective:136-204","7643:objective:207-251","7643:objective:254-313","7643:objective:316-372"},["questID"]=7643,["sourceHash"]="b652d6f4d95c9769bcfed3f90b9aa7d7874d5b9462f4868cb703af257f39873f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="An equine spirit held by Tendris in Dire Maul could grant the necessary blessing. Its freedom came first, followed by special feed to soothe it before the barding was offered."},{["episodeID"]="paladin-fallen-charger-redemption-7644",["requiresAll"]={{["minimumStage"]=2,["questID"]=7644}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"7644:description:1-89","7644:description:92-233","7644:description:238-285","7644:description:288-379","7644:objective:1-110"},["questID"]=7644,["sourceHash"]="76418579e06da38d381bf87a0a29962791776b3e63e77e71c61b410cc48d6cb2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The blessed barding returned to Stormwind, but it was a preparation rather than the charger itself. Grayson still needed an instrument able to reach the soul in its darkness."},{["episodeID"]="paladin-fallen-charger-redemption-7646",["requiresAll"]={{["minimumStage"]=2,["questID"]=7646}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"7646:description:1-118","7646:description:121-158","7646:description:161-276","7646:description:281-333","7646:description:336-436","7646:description:439-511","7646:objective:1-126"},["questID"]=7646,["sourceHash"]="834433d036546e6626f907e6c768b9dc6553d98294c867fb5c70d02cb884b8e2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The censer became the catalyst of that scryer. Contrasting diamonds would serve as its beacon, joining the first act of sacrifice to the final trial."},{["episodeID"]="paladin-fallen-charger-redemption-7647",["requiresAll"]={{["minimumStage"]=4,["questID"]=7647}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"7647:description:1-68","7647:description:73-195","7647:description:198-288","7647:description:291-391","7647:description:394-480","7647:description:485-494","7647:objective:1-90","7647:objective:93-145","7647:objective:148-213","7647:objective:216-274","7647:objective:279-376","7647:completion:1-112","7647:completion:114-233","7647:completion:235-317","7647:completion:319-418","7647:completion:423-461","7647:completion:463-478"},["questID"]=7647,["sourceHash"]="db046d5646a961ae4c786b068073c8bac5b3270d5cf83e0e4fd929fc177d3513",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The scryer drew the ossuary's accursed spirits and then Darkreaver. With the death knight defeated, soul and blessed barding could be returned to his charger. A glimmer of life in its eyes and a nuzzle of the hand marked a companion's redemption rather than the taking of another trophy."}},["grouping"]="The connected censer-to-redemption route; separate referrals and barding inspection are not imposed as additional prerequisite edges.",["quests"]={7637,7639,7640,7641,7642,7643,7644,7646,7647},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Companion Returned to the Light"},["redridge-marris-blackrock"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=20,["sourceHash"]="6e4ebe91765f1e6daa10ec8d6ce3f8c46a9323efe40a1ac1fada8d508a82b43b"},{["minimumStage"]=4,["questID"]=19,["sourceHash"]="ce86264a823f491954fef6ceb0e5042afc9a26497146de83c3a6a70d9795f0af"},{["minimumStage"]=4,["questID"]=115,["sourceHash"]="5f1531b63834329e8399eea4e7c0fb7f7fb4e7300fe70f42520bd1693f08b00b"}}},["interpretation"]="Every required route step needs its own recorded hand-in and exact source hash. Optional or alternative branches retain their separate rules.",["scope"]="DEFINED_OBSERVED_ROUTE_NOT_WORLD_VICTORY"},["episodes"]={{["episodeID"]="redridge-marris-blackrock-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=20}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"20:description:1-100","20:description:103-204","20:description:209-242","20:description:245-321","20:description:326-447","20:description:450-503","20:objective:1-56"},["questID"]=20,["sourceHash"]="6e4ebe91765f1e6daa10ec8d6ce3f8c46a9323efe40a1ac1fada8d508a82b43b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Blackrock raiders from the Burning Steppes had occupied Stonewatch Keep and hemmed Lakeshire's people inside the town. Marris needed help confronting the force beyond its roads."},{["episodeID"]="redridge-marris-blackrock-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=19}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"19:description:1-89","19:description:92-165","19:description:168-199","19:objective:1-54"},["questID"]=19,["sourceHash"]="ce86264a823f491954fef6ceb0e5042afc9a26497146de83c3a6a70d9795f0af",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The danger included ambushes along the approach to Stonewatch. Marris singled out Tharil'zun, leader of the Blackrock Outrunners, for a separate strike."},{["episodeID"]="redridge-marris-blackrock-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=115}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"115:description:1-145","115:description:148-286","115:description:291-362","115:description:365-451","115:objective:1-53","115:completion:1-14","115:completion:16-59"},["questID"]=115,["sourceHash"]="5f1531b63834329e8399eea4e7c0fb7f7fb4e7300fe70f42520bd1693f08b00b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Three Midnight Orbs were delivered to Marris for disposal. Removing the shadowcasters' devices answered another part of Lakeshire's defense, without establishing that Stonewatch had been reclaimed."}},["grouping"]="Source-reviewed continuing narrative; branch and source-stage gates retained.",["quests"]={20,19,115},["referenceStatus"]="RETAINED_QUEST_SOURCE_STAGES_NOT_CURRENT_PLAYABILITY_VERIFICATION",["sourceConflict"]=false,["title"]="The Roads Beneath Stonewatch"},["redridge-solomon-three-appeals"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=120,["sourceHash"]="ae0fd9daac2bb3bbea0182ac688c1811938445515ab48818196850cc9eea5756"},{["minimumStage"]=4,["questID"]=121,["sourceHash"]="a941f0f69a93a921392893cdd1b6b19d83cdc90687251af41d7bbc59cb718057"},{["minimumStage"]=4,["questID"]=143,["sourceHash"]="d4884feac081e6479bfecf8f23f64ba946d6c037059643596a702bd5d28a5e92"},{["minimumStage"]=4,["questID"]=144,["sourceHash"]="f2127a3c0763b16554b97f1790040625b7258f5ed4135ad41da77b6b2a4aec77"},{["minimumStage"]=4,["questID"]=145,["sourceHash"]="4a273b42ffb4144de6b7e7bbe62a898ac4f2576a7d085ce3ba0758716b56bc1c"},{["minimumStage"]=4,["questID"]=146,["sourceHash"]="67aa1d4fcbe03279757f63f2f3c0b4aa89f8d722adfebbcb7c202cdf338abd68"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="redridge-solomon-three-appeals-120",["requiresAll"]={{["minimumStage"]=2,["questID"]=120}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"120:description:1-27","120:description:30-66","120:description:69-122","120:description:125-181","120:description:184-251","120:description:254-335","120:description:341-355","120:objective:1-106","120:objective:109-183"},["questID"]=120,["sourceHash"]="ae0fd9daac2bb3bbea0182ac688c1811938445515ab48818196850cc9eea5756",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Constant siege left Lakeshire facing defeat without reinforcements. Solomon’s urgent report went to Marcus Jonathan in Stormwind, seeking the army’s aid before the town’s strength failed."},{["episodeID"]="redridge-solomon-three-appeals-121",["requiresAll"]={{["minimumStage"]=2,["questID"]=121}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"121:description:1-96","121:description:102-115","121:objective:1-85"},["questID"]=121,["sourceHash"]="a941f0f69a93a921392893cdd1b6b19d83cdc90687251af41d7bbc59cb718057",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Jonathan’s answer promised support once the king gave word. The letter returned to Lakeshire while the general waited, carrying assurance rather than an arriving force."},{["episodeID"]="redridge-solomon-three-appeals-143",["requiresAll"]={{["minimumStage"]=2,["questID"]=143}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"143:description:1-47","143:description:50-92","143:description:95-134","143:description:137-242","143:description:245-302","143:description:307-356","143:description:359-441","143:objective:1-87"},["questID"]=143,["sourceHash"]="d4884feac081e6479bfecf8f23f64ba946d6c037059643596a702bd5d28a5e92",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="When troops still failed to appear, Solomon appealed west to Stoutmantle. A neighboring militia might provide the relief that the royal army had not yet sent."},{["episodeID"]="redridge-solomon-three-appeals-144",["requiresAll"]={{["minimumStage"]=4,["questID"]=144}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"144:description:1-43","144:description:46-176","144:description:179-263","144:description:268-317","144:description:320-385","144:objective:1-63","144:completion:1-34","144:completion:36-120","144:completion:122-203","144:completion:205-235","144:completion:240-255","144:completion:257-320","144:completion:322-349"},["questID"]=144,["sourceHash"]="f2127a3c0763b16554b97f1790040625b7258f5ed4135ad41da77b6b2a4aec77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Westfall had no soldiers to spare. Stoutmantle’s reply described his own abandonment and losses, revealing another frontier whose local defense existed because Stormwind had left it to fend for itself."},{["episodeID"]="redridge-solomon-three-appeals-145",["requiresAll"]={{["minimumStage"]=2,["questID"]=145}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"145:description:1-37","145:description:40-168","145:description:171-224","145:description:227-260","145:description:263-324","145:description:327-354","145:objective:1-77"},["questID"]=145,["sourceHash"]="4a273b42ffb4144de6b7e7bbe62a898ac4f2576a7d085ce3ba0758716b56bc1c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The next plea crossed into Duskwood, asking Ebonlocke to send the trained Night Watch. Lakeshire’s need was now being carried between towns already struggling to survive."},{["episodeID"]="redridge-solomon-three-appeals-146",["requiresAll"]={{["minimumStage"]=4,["questID"]=146}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"146:description:1-82","146:description:85-148","146:description:151-245","146:description:248-357","146:description:362-418","146:objective:1-70","146:completion:1-13","146:completion:15-57","146:completion:59-101","146:completion:103-133","146:completion:135-155","146:completion:161-199","146:completion:201-220","146:completion:222-235","146:completion:237-303"},["questID"]=146,["sourceHash"]="67aa1d4fcbe03279757f63f2f3c0b4aa89f8d722adfebbcb7c202cdf338abd68",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Ebonlocke refused to leave Darkshire undefended: the town would fall before its Watchers reached Lakeshire. The returned letters left Solomon suspecting treachery in Stormwind, but they established only the desperate condition of all three frontiers, not who had caused it."}},["grouping"]="Six connected appeals expose three strained defenses; Solomon’s suspicion of treachery remains unproven here.",["quests"]={120,121,143,144,145,146},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Letters Without Reinforcements"},["redridge-theocritus-rival-eyes"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=94,["sourceHash"]="4d71889f9c4c99d6c7aa6fac59e944e533be455e84eaabe5b06b7fb651bdcc74"},{["minimumStage"]=4,["questID"]=248,["sourceHash"]="96716abfac3be16fda5a82a813497662be783c8643b83b98af95511e31ab777a"},{["minimumStage"]=4,["questID"]=249,["sourceHash"]="c678aed984412dad316027c5f70ebd91cf4e22386b1eb4b23831731a2d0f8230"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="redridge-theocritus-rival-eyes-94",["requiresAll"]={{["minimumStage"]=2,["questID"]=94}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"94:description:1-99","94:description:102-193","94:description:198-226","94:description:228-249","94:description:254-325","94:description:328-372","94:description:377-460","94:objective:1-81"},["questID"]=94,["sourceHash"]="4d71889f9c4c99d6c7aa6fac59e944e533be455e84eaabe5b06b7fb651bdcc74",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Theocritus could watch his rival Morganth through the Eye of Azora, but sight alone did not reveal his plans. A glyph placed by Ilgalar’s lion statue would bring the rival’s thoughts within reach."},{["episodeID"]="redridge-theocritus-rival-eyes-248",["requiresAll"]={{["minimumStage"]=2,["questID"]=248}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"248:description:1-120","248:description:123-218","248:description:223-319","248:description:324-374","248:description:377-467","248:objective:1-52","248:objective:57-110"},["questID"]=248,["sourceHash"]="96716abfac3be16fda5a82a813497662be783c8643b83b98af95511e31ab777a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The first watch exposed contention with the orcs at Stonewatch without explaining its cause. A second glyph, hidden in a container on the intact watchtower, extended the inquiry to the other side of that quarrel."},{["episodeID"]="redridge-theocritus-rival-eyes-249",["requiresAll"]={{["minimumStage"]=4,["questID"]=249}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"249:description:1-59","249:description:64-126","249:description:129-228","249:description:233-319","249:description:322-378","249:description:383-429","249:description:432-474","249:objective:1-16","249:objective:21-101","249:completion:1-23","249:completion:25-97","249:completion:102-137","249:completion:139-194","249:completion:199-284"},["questID"]=249,["sourceHash"]="c678aed984412dad316027c5f70ebd91cf4e22386b1eb4b23831731a2d0f8230",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Theocritus had traced Morganth’s ambition to the Scythe of Elune and feared the mage might already possess it. The confrontation ended with Morganth’s Pendant of Shadow brought back to Azora. The threatened attack was checked, without establishing that the Scythe itself had ever been found."}},["grouping"]="Theocritus investigates Morganth through two glyph placements; possession of the Scythe remains his fear, never confirmed loot.",["quests"]={94,248,249},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Two Eyes Upon a Rival"},["redridge-verner-argus-horseshoes"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=118,["sourceHash"]="392dd314ca36b473b11b3e01f8e1399bf113c507ecd9decd624f52fd71bba7e1"},{["minimumStage"]=4,["questID"]=119,["sourceHash"]="1599e58a77aa13b77f039ed4ce39e1f72617222abc17754facc729a236b6ce7e"},{["minimumStage"]=4,["questID"]=122,["sourceHash"]="edae885689ceccf27eb52f4a730fdda18ed23612ac19daea94f687d6f3f397c4"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="redridge-verner-argus-horseshoes-118",["requiresAll"]={{["minimumStage"]=2,["questID"]=118}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"118:description:1-130","118:description:135-182","118:description:185-252","118:objective:1-47"},["questID"]=118,["sourceHash"]="392dd314ca36b473b11b3e01f8e1399bf113c507ecd9decd624f52fd71bba7e1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The iron keeping Stormwind’s guards equipped could no longer shoe Verner’s horses as well. His note to Argus in Goldshire sought a shipment for the Lakeshire stable, joining the town’s small necessity to the army’s larger demands."},{["episodeID"]="redridge-verner-argus-horseshoes-119",["requiresAll"]={{["minimumStage"]=4,["questID"]=119}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"119:description:1-38","119:description:43-86","119:description:89-187","119:objective:1-36","119:objective:39-71","119:completion:1-36","119:completion:41-56","119:completion:58-98","119:completion:100-125","119:completion:127-130","119:completion:135-168"},["questID"]=119,["sourceHash"]="1599e58a77aa13b77f039ed4ce39e1f72617222abc17754facc729a236b6ce7e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Argus sent fifty horseshoes in a crate, with a note Verner had not expected. Gratitude for the delivery gave way to indignation when he discovered that the smith intended to be paid."},{["episodeID"]="redridge-verner-argus-horseshoes-122",["requiresAll"]={{["minimumStage"]=4,["questID"]=122}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"122:description:1-105","122:description:108-173","122:description:175-224","122:description:229-316","122:description:319-389","122:objective:1-103","122:completion:1-7","122:completion:9-49"},["questID"]=122,["sourceHash"]="edae885689ceccf27eb52f4a730fdda18ed23612ac19daea94f687d6f3f397c4",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The debt drew attention to the black dragon whelps wandering south of Lakeshire. Their underbelly scales supplied Verner with something Argus would accept, and the smith thanked his helper for a way out of the obligation."}},["grouping"]="One horseshoe requisition and its payment; no general end to Redridge’s shortages or witnessed hunt inferred.",["quests"]={118,119,122},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Iron That Could Not Serve Twice"},["revantusk-torntusk"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=7845,["sourceHash"]="4017e983314306a744d1de2d47f2a8eb58bc3e35a2650cd4d9cae1360a6d566c"},{["minimumStage"]=4,["questID"]=7846,["sourceHash"]="16b8ace9578de359100dc3e617b27850ad0866682c16be5ed5551708d7f5846e"},{["minimumStage"]=4,["questID"]=7847,["sourceHash"]="80fee43ec1eef261df3fada27c093cff3317b0e0af38f69ffb689cf6890dcfff"}}},["interpretation"]="Every listed leaf requires its own observed completion. This authored route clause is not a claim that the source previousID array encodes all-of gameplay prerequisites.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="revantusk-torntusk-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=7845}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"7845:description:1-79","7845:description:81-167","7845:description:169-270","7845:description:275-296","7845:description:298-343","7845:objective:1-119","7845:objective:124-269"},["questID"]=7845,["sourceHash"]="4017e983314306a744d1de2d47f2a8eb58bc3e35a2650cd4d9cae1360a6d566c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Spies still placed the kidnapped elder among the living, but sacrifice threatened the village's loss. Primal's appeal led to the summit of the Vilebranch city."},{["episodeID"]="revantusk-torntusk-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=7846}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"7846:description:1-54","7846:description:56-81","7846:description:83-122","7846:description:127-180","7846:description:182-221","7846:objective:1-107","7846:objective:109-165"},["questID"]=7846,["sourceHash"]="16b8ace9578de359100dc3e617b27850ad0866682c16be5ed5551708d7f5846e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Reaching the elder did not remove his bindings. The keeper in the nearby cave held a separate key, making the recovery of that object the condition for going home."},{["episodeID"]="revantusk-torntusk-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=7846},{["minimumStage"]=4,["questID"]=7847}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"7846:description:1-54","7846:description:56-81","7846:description:83-122","7846:description:127-180","7846:description:182-221","7846:objective:1-107","7846:objective:109-165","7846:completion:1-16","7846:completion:18-31","7846:completion:33-63"},["questID"]=7846,["sourceHash"]="16b8ace9578de359100dc3e617b27850ad0866682c16be5ed5551708d7f5846e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"7847:description:1-56","7847:description:58-88","7847:description:90-115","7847:objective:1-114","7847:completion:1-48","7847:completion:50-86"},["questID"]=7847,["sourceHash"]="80fee43ec1eef261df3fada27c093cff3317b0e0af38f69ffb689cf6890dcfff",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The elder declared his freedom and sent the news ahead. Primal received word that he was coming home and thanked the courier for the service to the Revantusk."}},["grouping"]="Authored connected episodes with explicit source-stage gates; branches retained",["quests"]={7845,7846,7847},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="News Ahead of the Elder"},["scarlet-anton-raleigh-reversal"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=261,["sourceHash"]="e0058dfb5aa4fd0c187207456db9da75b302d07ba330dcfc5fd9b25962eed42b"},{["minimumStage"]=4,["questID"]=1052,["sourceHash"]="d732b198e55aac212f34139a15e0eced6d97bca8fde1daa0e6c0668011eb5ccd"},{["minimumStage"]=4,["questID"]=1053,["sourceHash"]="993e1204bfe5f91c4e937c1cc9d97326687b9712fd6dc81c8777a86b6fc3453f"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="scarlet-anton-raleigh-reversal-261",["requiresAll"]={{["minimumStage"]=2,["questID"]=261}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"261:description:1-16","261:description:19-49","261:description:52-111","261:description:114-188","261:description:191-267","261:description:272-420","261:description:425-466","261:objective:1-74"},["questID"]=261,["sourceHash"]="e0058dfb5aa4fd0c187207456db9da75b302d07ba330dcfc5fd9b25962eed42b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Brother Anton presented the Scarlet cause as a defense of the living against the Scourge. The undead ravagers in Desolace’s Valley of Bones were his test of those seeking the Crusade’s acceptance."},{["episodeID"]="scarlet-anton-raleigh-reversal-1052",["requiresAll"]={{["minimumStage"]=2,["questID"]=1052}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1052:description:1-86","1052:description:88-156","1052:description:161-216","1052:description:218-269","1052:description:274-331","1052:description:333-377","1052:description:379-499","1052:objective:1-80"},["questID"]=1052,["sourceHash"]="d732b198e55aac212f34139a15e0eced6d97bca8fde1daa0e6c0668011eb5ccd",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A letter of commendation carried that promise across the sea to Raleigh in Southshore. Anton spoke proudly of Lordaeron’s Scarlet strongholds and expected the introduction to lead toward a place of honor in the monastery."},{["episodeID"]="scarlet-anton-raleigh-reversal-1053",["requiresAll"]={{["minimumStage"]=4,["questID"]=1053}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1053:description:1-64","1053:description:66-136","1053:description:141-248","1053:description:250-327","1053:description:329-402","1053:description:408-468","1053:description:470-511","1053:objective:1-169","1053:completion:1-174","1053:completion:179-254","1053:completion:256-278"},["questID"]=1053,["sourceHash"]="993e1204bfe5f91c4e937c1cc9d97326687b9712fd6dc81c8777a86b6fc3453f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Raleigh’s testimony had overturned that welcome: the Crusade now treated those outside its tabard as infected, torturing innocents in the name of safety. After the confrontation with the monastery’s leaders, he honored the lives spared by opposing them. The defense of the Light had become a reason to reject the zealots claiming it."}},["grouping"]="One three-step Scarlet referral that becomes a rejection of the Crusade; no universal end to the organization is inferred.",["quests"]={261,1052,1053},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Tabard and the Innocent"},["shadowglen-iverron-antidote"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=4495,["sourceHash"]="8223f442e23a027d7076df293a2591f6689ccdf79d80490b4da813910a2ca311"},{["minimumStage"]=4,["questID"]=3519,["sourceHash"]="e5c489424f37178c7e5a66d9b768d4de683df3e704275e0f3503531ee8bd5a91"},{["minimumStage"]=4,["questID"]=3521,["sourceHash"]="ece3cb3cfe44f735fa181bd0e9da1012ba75e3083e02c9c38c217f308e1ee8a9"},{["minimumStage"]=4,["questID"]=3522,["sourceHash"]="35b0bd62f2800c92fa3e455b5e01d139762551fadc1acd396c7bed34d82765cc"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="shadowglen-iverron-antidote-4495",["requiresAll"]={{["minimumStage"]=2,["questID"]=4495}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"4495:description:1-76","4495:description:78-170","4495:description:175-209","4495:description:211-341","4495:description:346-422","4495:objective:1-38"},["questID"]=4495,["sourceHash"]="8223f442e23a027d7076df293a2591f6689ccdf79d80490b4da813910a2ca311",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Iverron's daily visit was hours overdue. Dirania knew his fondness for the northern cave, and the spiders around it made an ordinary absence cause for fear."},{["episodeID"]="shadowglen-iverron-antidote-3519",["requiresAll"]={{["minimumStage"]=2,["questID"]=3519}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"3519:description:1-8","3519:description:10-120","3519:description:122-180","3519:description:185-216","3519:description:218-245","3519:description:250-257","3519:description:259-273","3519:objective:1-43"},["questID"]=3519,["sourceHash"]="e5c489424f37178c7e5a66d9b768d4de683df3e704275e0f3503531ee8bd5a91",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Iverron's account explained the delay: Githyiss had bitten him during his exploration. Dizzy with poison, he placed his hope in Dirania's knowledge rather than trying to find his own way home."},{["episodeID"]="shadowglen-iverron-antidote-3521",["requiresAll"]={{["minimumStage"]=2,["questID"]=3521}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"3521:description:1-90","3521:description:92-150","3521:description:155-183","3521:description:185-319","3521:description:321-389","3521:description:394-442","3521:description:444-510","3521:objective:1-107"},["questID"]=3521,["sourceHash"]="ece3cb3cfe44f735fa181bd0e9da1012ba75e3083e02c9c38c217f308e1ee8a9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The remedy joined the glade's gentler growth to a dangerous ingredient. Mushrooms and moonpetal lilies were needed alongside ichor from the very spiders responsible for the poisoning."},{["episodeID"]="shadowglen-iverron-antidote-3522",["requiresAll"]={{["minimumStage"]=4,["questID"]=3522}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"3522:description:1-26","3522:description:28-61","3522:description:66-165","3522:description:167-197","3522:description:202-223","3522:objective:1-64","3522:objective:66-111","3522:completion:1-17","3522:completion:22-65","3522:completion:70-98","3522:completion:103-193","3522:completion:198-302","3522:completion:304-398"},["questID"]=3522,["sourceHash"]="35b0bd62f2800c92fa3e455b5e01d139762551fadc1acd396c7bed34d82765cc",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The antidote reached Iverron before it spoiled. After drinking, he felt better but chose to rest beside the cave until his strength returned. The rescue ended in relief, not a claim that the spider-haunted path had been cleared."}},["grouping"]="One search and time-sensitive antidote delivery; recovery is narrated only from the recorded completion.",["quests"]={4495,3519,3521,3522},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Friend Overdue"},["silithus-demitrian-thunderfury"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=7785,["sourceHash"]="c7de2fb45ac0d94fa6206939e2d20dff1540c191da1598a4d532daffae3d066d"},{["minimumStage"]=4,["questID"]=7786,["sourceHash"]="ca675488a539a708e258162500d9dcb875a4d0f6220a9c6f2cbc1bcfc69d9c35"},{["minimumStage"]=4,["questID"]=7787,["sourceHash"]="7a5a3bb7fd5f0adec3ede6486d83878c618d32b5146bed0dce951f9716e14380"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="silithus-demitrian-thunderfury-7785",["requiresAll"]={{["minimumStage"]=2,["questID"]=7785}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"7785:description:1-42","7785:description:44-95","7785:objective:1-66"},["questID"]=7785,["sourceHash"]="c7de2fb45ac0d94fa6206939e2d20dff1540c191da1598a4d532daffae3d066d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Demitrian presented the Vessel of Rebirth as the means by which the Windseeker would return. His blessing concealed a bargain whose meaning would become clear only after the prison was opened."},{["episodeID"]="silithus-demitrian-thunderfury-7786",["requiresAll"]={{["minimumStage"]=4,["questID"]=7786}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"7786:description:1-36","7786:description:38-72","7786:description:74-130","7786:description:135-178","7786:objective:1-218","7786:completion:1-47","7786:completion:52-66","7786:completion:71-108","7786:completion:113-156","7786:completion:161-175","7786:completion:177-198"},["questID"]=7786,["sourceHash"]="ca675488a539a708e258162500d9dcb875a4d0f6220a9c6f2cbc1bcfc69d9c35",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Both bindings, elementium and the Firelord’s essence supplied the release Demitrian desired. He hailed Thunderaan as his master and called him to rise, revealing that the promised blessing served a purpose of its own."},{["episodeID"]="silithus-demitrian-thunderfury-7787",["requiresAll"]={{["minimumStage"]=4,["questID"]=7787}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"7787:description:1-34","7787:description:36-168","7787:objective:1-60","7787:completion:1-22","7787:completion:24-31","7787:completion:33-47","7787:completion:49-93"},["questID"]=7787,["sourceHash"]="7a5a3bb7fd5f0adec3ede6486d83878c618d32b5146bed0dce951f9716e14380",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="After the Windseeker’s defeat, the dormant blade was carried back to the servant who had betrayed the bargain. Demitrian begged for his life and yielded Thunderfury, leaving the once-grand ritual to end in fear rather than triumph."}},["grouping"]="Demitrian’s vessel, release and betrayed bargain; no broader elemental victory or unrecorded loot ownership is inferred.",["quests"]={7785,7786,7787},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Windseeker’s Broken Bonds"},["silithus-noggle-poison-and-satchel"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=8277,["sourceHash"]="7dbc3f4442ee3fae210ea9d4acff5d42dd42acb84d5caf133be8fa6e5a40221c"},{["minimumStage"]=4,["questID"]=8278,["sourceHash"]="6dc277c3cee08471651e5989533a47ebb9c9ded487ba43cdee1564bc0e5d9581"},{["minimumStage"]=4,["questID"]=8282,["sourceHash"]="d73e31e0dbfc1a2108cb2674a976b296db3a7f2971fc627abb846cc033fdbfa5"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="silithus-noggle-poison-and-satchel-8277",["requiresAll"]={{["minimumStage"]=2,["questID"]=8277}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"8277:description:1-36","8277:description:39-120","8277:description:123-141","8277:description:144-221","8277:description:226-335","8277:description:340-435","8277:description:438-511","8277:objective:1-125","8277:objective:127-173"},["questID"]=8277,["sourceHash"]="7dbc3f4442ee3fae210ea9d4acff5d42dd42acb84d5caf133be8fa6e5a40221c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Noggle’s herb gathering for Cenarion Hold ended with poison in his veins. Beetix had slowed it, but still needed samples from the creatures he might have met on the northern road to attempt an antidote."},{["episodeID"]="silithus-noggle-poison-and-satchel-8278",["requiresAll"]={{["minimumStage"]=4,["questID"]=8278}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"8278:description:1-8","8278:description:11-35","8278:description:38-113","8278:description:118-184","8278:description:187-263","8278:description:266-405","8278:objective:1-151","8278:completion:1-4","8278:completion:7-50","8278:completion:53-71"},["questID"]=8278,["sourceHash"]="6dc277c3cee08471651e5989533a47ebb9c9ded487ba43cdee1564bc0e5d9581",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The first remedy failed. Stronger venom from the south gave Beetix another chance, and this time Noggle began to recover. The alchemist’s relief left one part of the journey unexplained: what had happened to his cousin’s supplies."},{["episodeID"]="silithus-noggle-poison-and-satchel-8282",["requiresAll"]={{["minimumStage"]=4,["questID"]=8282}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"8282:description:1-11","8282:description:14-28","8282:description:30-103","8282:description:106-174","8282:description:179-242","8282:description:245-331","8282:description:334-426","8282:description:431-510","8282:objective:1-108","8282:completion:1-4","8282:completion:7-34","8282:completion:37-70","8282:completion:73-109"},["questID"]=8282,["sourceHash"]="d73e31e0dbfc1a2108cb2674a976b296db3a7f2971fc627abb846cc033fdbfa5",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Noggle remembered fleeing Deathclasp into a nest of stonelash flayers. His recovered satchel still held its rare reagents, restoring the materials he and Beetix needed for the Hold’s potions while he remained too weak to fetch them himself."}},["grouping"]="An antidote and the recovery of one herb-gatherer’s supplies; no general eradication of Silithus’s poisonous creatures.",["quests"]={8277,8278,8282},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Reagents Left Behind"},["silverpine-ambermill"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=477,["sourceHash"]="f483ebcaf4ef2ba39aa736a43cfd7109a6b5e69800d825292a34787cc0dac9d0"},{["minimumStage"]=4,["questID"]=478,["sourceHash"]="585da75eab1f0b693777ffbf1a8a1a219d041ef24228802ed4b58e9f5d4c63a2"},{["minimumStage"]=4,["questID"]=481,["sourceHash"]="35f2a9c534879bcfba43c30eb815f20a9e72f1e807bb951122986dab3092fc55"},{["minimumStage"]=4,["questID"]=482,["sourceHash"]="da845d5dd9985173047a46c8dad57961d6de9e131fd5a9bb23eeff40e8f72eca"},{["minimumStage"]=4,["questID"]=479,["sourceHash"]="d37e6f8cacf21757409c737ac3ba86329647a114bd201f7849bc31f4100a539b"},{["minimumStage"]=4,["questID"]=480,["sourceHash"]="d748d3cfafb355ad91120faf62452c6e72416a20f587688a6d7c5b08cd0e2dc1"}}},["interpretation"]="Every listed leaf requires its own observed completion. This authored route clause is not a claim that the source previousID array encodes all-of gameplay prerequisites.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="silverpine-ambermill-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=477}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"477:description:1-145","477:description:150-302","477:description:307-363","477:description:365-436","477:description:438-492","477:objective:1-60","477:objective:62-105"},["questID"]=477,["sourceHash"]="f483ebcaf4ef2ba39aa736a43cfd7109a6b5e69800d825292a34787cc0dac9d0",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Wagonloads from Hillsbrad suggested Ambermill mattered more than its size. Allister sought evidence from one crate before deciding what the shipments meant."},{["episodeID"]="silverpine-ambermill-2",["requiresAll"]={{["minimumStage"]=4,["questID"]=481},{["minimumStage"]=4,["questID"]=482}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"481:description:1-91","481:objective:1-69","481:completion:1-63","481:completion:65-92","481:completion:94-181","481:completion:186-298","481:completion:303-370"},["questID"]=481,["sourceHash"]="35f2a9c534879bcfba43c30eb815f20a9e72f1e807bb951122986dab3092fc55",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"482:description:1-10","482:description:12-38","482:description:43-151","482:description:153-250","482:description:255-287","482:description:292-428","482:description:433-502","482:objective:1-51","482:completion:1-23","482:completion:25-106","482:completion:111-155","482:completion:157-214"},["questID"]=482,["sourceHash"]="da845d5dd9985173047a46c8dad57961d6de9e131fd5a9bb23eeff40e8f72eca",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The pendant led Dalar from an unfamiliar shipment to familiar Kirin Tor methods. Ambermill's dormant ley node offered a reason for so many energy-channeling artifacts."},{["episodeID"]="silverpine-ambermill-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=479},{["minimumStage"]=2,["questID"]=480}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"479:description:1-70","479:description:72-134","479:description:139-209","479:description:211-235","479:description:240-300","479:objective:1-70"},["questID"]=479,["sourceHash"]="d37e6f8cacf21757409c737ac3ba86329647a114bd201f7849bc31f4100a539b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"480:description:1-81","480:description:83-165","480:description:167-245","480:description:250-296","480:description:298-340","480:description:342-348","480:objective:1-95"},["questID"]=480,["sourceHash"]="d748d3cfafb355ad91120faf62452c6e72416a20f587688a6d7c5b08cd0e2dc1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Delay became the first tactic, then a direct strike at the archmage guiding the weaving. Taking pendants could slow the project, but Allister judged its leader the remaining way to stop it."},{["episodeID"]="silverpine-ambermill-4",["requiresAll"]={{["minimumStage"]=4,["questID"]=480}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"480:description:1-81","480:description:83-165","480:description:167-245","480:description:250-296","480:description:298-340","480:description:342-348","480:objective:1-95","480:completion:1-77","480:completion:79-204","480:completion:209-292","480:completion:294-327"},["questID"]=480,["sourceHash"]="d748d3cfafb355ad91120faf62452c6e72416a20f587688a6d7c5b08cd0e2dc1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Allister reported the energies returning to dormancy. The immediate working ended, while knowledge of a powerful source so close at hand became a reason for vigilance."}},["grouping"]="Authored connected episodes with explicit source-stage gates; branches retained",["quests"]={477,478,481,482,479,480},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The Dormant Node"},["silverpine-arugal"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=421,["sourceHash"]="2bd29c0b15a3cd5d80c45e76e609f8c25e6dda5410c6c6a1dd018257b5323179"},{["minimumStage"]=4,["questID"]=422,["sourceHash"]="520a917b250b793a3b889b1d3dd20a29495762355682699d1ac7627a26ecf17d"},{["minimumStage"]=4,["questID"]=423,["sourceHash"]="b7a2eb34ae461028d2fd30bc479542bb969acabffe92e47c9e7f4baca09a22ab"},{["minimumStage"]=4,["questID"]=424,["sourceHash"]="6108fae2461625eb8c45eb203ca58382f4ce9b8122383b9f6aa5b07819f47570"},{["minimumStage"]=4,["questID"]=99,["sourceHash"]="0a4181e9754cccb5c3c0abe6b4f908b62b7eee206c225cda68f4a02d5e7acc1d"}}},["interpretation"]="Every listed leaf requires its own observed completion. This authored route clause is not a claim that the source previousID array encodes all-of gameplay prerequisites.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="silverpine-arugal-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=421}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"421:description:1-102","421:description:107-281","421:description:286-361","421:description:364-418","421:description:421-498","421:objective:1-75"},["questID"]=421,["sourceHash"]="2bd29c0b15a3cd5d80c45e76e609f8c25e6dda5410c6c6a1dd018257b5323179",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Silverpine mattered to a campaign directed southward by Sylvanas and Varimathras. Dalar made opposition to Arugal a test of usefulness before opening his research to an aide."},{["episodeID"]="silverpine-arugal-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=422},{["minimumStage"]=2,["questID"]=423}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"422:description:1-63","422:description:66-139","422:description:144-288","422:description:293-355","422:description:358-440","422:description:443-510","422:objective:1-68"},["questID"]=422,["sourceHash"]="520a917b250b793a3b889b1d3dd20a29495762355682699d1ac7627a26ecf17d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"423:description:1-65","423:description:68-187","423:description:190-195","423:description:200-255","423:description:258-298","423:description:301-439","423:description:442-497","423:objective:1-86"},["questID"]=423,["sourceHash"]="b7a2eb34ae461028d2fd30bc479542bb969acabffe92e47c9e7f4baca09a22ab",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The inquiry moved from a spellbook at the wheat farm to enchanted shackles carried by the worgen. Dalar's contempt for the caster did not supply an answer: the reinforcing objects themselves had to be examined."},{["episodeID"]="silverpine-arugal-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=99},{["minimumStage"]=2,["questID"]=424}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"424:description:1-118","424:description:123-219","424:description:222-315","424:description:320-389","424:description:394-464","424:description:467-505","424:objective:1-78"},["questID"]=424,["sourceHash"]="6108fae2461625eb8c45eb203ca58382f4ce9b8122383b9f6aa5b07819f47570",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"99:description:1-84","99:description:87-147","99:description:152-272","99:description:275-314","99:description:317-383","99:description:388-457","99:description:460-507","99:objective:1-63"},["questID"]=99,["sourceHash"]="0a4181e9754cccb5c3c0abe6b4f908b62b7eee206c225cda68f4a02d5e7acc1d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Research took longer than expected. The mine offered a military diversion while Pyrewood's changing villagers supplied another form of the enchantment Dalar sought."},{["episodeID"]="silverpine-arugal-4",["requiresAll"]={{["minimumStage"]=4,["questID"]=99}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"99:description:1-84","99:description:87-147","99:description:152-272","99:description:275-314","99:description:317-383","99:description:388-457","99:description:460-507","99:objective:1-63","99:completion:1-32","99:completion:34-130","99:completion:132-149"},["questID"]=99,["sourceHash"]="0a4181e9754cccb5c3c0abe6b4f908b62b7eee206c225cda68f4a02d5e7acc1d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Dalar welcomed the completed research and planned to use its lessons against Arugal's curse."}},["grouping"]="Authored connected episodes with explicit source-stage gates; branches retained",["quests"]={421,422,423,424,99},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The Remedy and the Shackles"},["silverpine-fenris"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=437,["sourceHash"]="75dc52c2dd51c80c5284aa0fdd3252d58096e277d579cad537dda936679b31c6"},{["minimumStage"]=4,["questID"]=438,["sourceHash"]="80acf1b91d68e88a24f5b93c1ce0d25344cb30c4d3c974c5c47865ebaf9435f2"},{["minimumStage"]=4,["questID"]=443,["sourceHash"]="29ecd187696965b4b79e5dd1bbda3841db6d1b36b6f015b5f9432b28e3df2e56"},{["minimumStage"]=4,["questID"]=444,["sourceHash"]="f322aad1a76dfa9d5f925126f6996a819588b2c84688cd2d332751d23ec47760"},{["minimumStage"]=4,["questID"]=446,["sourceHash"]="356fbca8ee022cbce697a622ce58b2c0f9c9b6bd83645bedfde623a3eda3393f"},{["minimumStage"]=4,["questID"]=448,["sourceHash"]="c26277c3a0a41c3edbb1618153c09d1256cffc8cb53342bc0306703902598f56"},{["minimumStage"]=4,["questID"]=442,["sourceHash"]="94c55ed092fb0f61aee40236b548a533b1d33c70ffc4c89203a116bf0e148ca8"}}},["interpretation"]="The final assault is the outcome. Ring investigation439 and identity inquiry440 form a separately gated side episode; the source also links438 directly to443. Further ring follow-up441 is outside this arc.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="silverpine-fenris-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=437}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"437:description:1-119","437:description:122-261","437:description:266-293","437:description:298-345","437:description:348-433","437:description:438-467","437:description:470-497","437:objective:1-40","437:objective:45-77","437:objective:82-153"},["questID"]=437,["sourceHash"]="75dc52c2dd51c80c5284aa0fdd3252d58096e277d579cad537dda936679b31c6",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Nightlash's interventions had preserved the gnolls' foothold at the Dead Fields. Hadrec's investigation began by challenging the magic that turned small assaults back."},{["episodeID"]="silverpine-fenris-2",["requiresAll"]={{["minimumStage"]=4,["questID"]=438},{["minimumStage"]=4,["questID"]=439},{["minimumStage"]=4,["questID"]=440}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"438:description:1-68","438:description:71-163","438:description:168-231","438:description:234-297","438:objective:1-25","438:objective:30-73","438:completion:1-53","438:completion:55-138","438:completion:143-190"},["questID"]=438,["sourceHash"]="80acf1b91d68e88a24f5b93c1ce0d25344cb30c4d3c974c5c47865ebaf9435f2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"439:description:1-46","439:description:49-123","439:description:130-151","439:description:154-210","439:description:215-226","439:objective:1-61","439:completion:1-60","439:completion:65-139","439:completion:141-204"},["questID"]=439,["sourceHash"]="6a10e726d9629e8beb3b6acbec6c66bbd42200dc30f5b54a4011e6db3099a2c0",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"440:description:1-70","440:description:72-114","440:description:117-199","440:description:204-223","440:description:226-268","440:description:271-329","440:objective:1-50","440:completion:1-40","440:completion:42-181","440:completion:186-240","440:completion:242-290"},["questID"]=440,["sourceHash"]="b7ccbff139d2355ff85781b68bb74a2e2155ff796c8a19291360c21aef846153",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Sevren recognized Deliah as a former Brill resident buried in the mass grave. The ring's engraving connected the corpse shipment to Hadrec's suspicion that bodies were being taken from Tirisfal."},{["episodeID"]="silverpine-fenris-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=444},{["minimumStage"]=2,["questID"]=446}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"444:description:1-82","444:description:85-208","444:description:213-313","444:description:316-420","444:description:430-488","444:objective:1-59"},["questID"]=444,["sourceHash"]="f322aad1a76dfa9d5f925126f6996a819588b2c84688cd2d332751d23ec47760",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"446:description:1-68","446:description:71-214","446:description:219-311","446:description:316-388","446:description:391-436","446:description:439-484","446:objective:1-74"},["questID"]=446,["sourceHash"]="356fbca8ee022cbce697a622ce58b2c0f9c9b6bd83645bedfde623a3eda3393f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Ichor passed from the apothecary's uncertain analysis to Bethor's recognition. A former colleague, Thule, emerged behind the manufacture of the Rot Hides, and knowledge of his spells offered a countermeasure."},{["episodeID"]="silverpine-fenris-4",["requiresAll"]={{["minimumStage"]=4,["questID"]=442}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"442:description:1-86","442:description:91-148","442:description:151-166","442:description:171-218","442:description:221-238","442:objective:1-60","442:completion:1-52","442:completion:54-163","442:completion:168-219","442:completion:221-243"},["questID"]=442,["sourceHash"]="94c55ed092fb0f61aee40236b548a533b1d33c70ffc4c89203a116bf0e148ca8",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Thule's defeat was felt beyond the island. Hadrec reported energies reaching the Sepulcher, closing the assault while the wider contest against the Scourge continued."}},["grouping"]="Authored connected episodes with explicit source-stage gates; branches retained",["quests"]={437,438,439,440,443,444,446,448,442},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="Bodies Across the Lake"},["silverpine-renferrel-berard"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=447,["sourceHash"]="700fe7a441184859d9b621943ece3481e69c1f8195a5fd424b89a6aa8f2cb626"},{["minimumStage"]=4,["questID"]=450,["sourceHash"]="9b755730afa19a8595d1232a52a2ea237e1b8b13ed68b22510b7efd3517bd7a1"},{["minimumStage"]=4,["questID"]=451,["sourceHash"]="1062e09a782881ff295c27276df27575cb7ab5fd2bce58d17afc1683b2243126"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="silverpine-renferrel-berard-447",["requiresAll"]={{["minimumStage"]=2,["questID"]=447}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"447:description:1-34","447:description:36-141","447:description:146-270","447:description:272-402","447:description:404-503","447:objective:1-129"},["questID"]=447,["sourceHash"]="700fe7a441184859d9b621943ece3481e69c1f8195a5fd424b89a6aa8f2cb626",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Renferrel’s answer to the Scourge’s growing strength was another plague, one intended for humans as well as undead enemies. Spider blood and the toxin of grizzled bear hearts were to pass to Faranell for study."},{["episodeID"]="silverpine-renferrel-berard-450",["requiresAll"]={{["minimumStage"]=2,["questID"]=450}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"450:description:1-66","450:description:71-184","450:description:187-244","450:description:247-290","450:description:293-390","450:description:395-499","450:objective:1-112"},["questID"]=450,["sourceHash"]="9b755730afa19a8595d1232a52a2ea237e1b8b13ed68b22510b7efd3517bd7a1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A lost colleague offered the next lead. Arugal’s curse had reduced Apothecary Berard to a mindless servant, but his journal might preserve the study of an ancient sickness that had emptied Lake Lordamere of aquatic life."},{["episodeID"]="silverpine-renferrel-berard-451",["requiresAll"]={{["minimumStage"]=4,["questID"]=451}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"451:description:1-125","451:description:128-191","451:description:196-279","451:description:282-348","451:description:353-476","451:objective:1-137","451:completion:1-59","451:completion:61-196","451:completion:201-247","451:completion:249-354"},["questID"]=451,["sourceHash"]="1062e09a782881ff295c27276df27575cb7ab5fd2bce58d17afc1683b2243126",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Berard’s notes guided the search toward lake-creature moss and a rare tumor from the Vile Fin murlocs. Faranell accepted the recovered materials as a means of continuing the lost apothecary’s work. The Society had gained research, rather than a demonstrated cure or finished weapon."}},["grouping"]="A reagent search and recovery of Berard’s research; later plague deployment and outcomes are excluded.",["quests"]={447,450,451},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Research Left in Pyrewood"},["silverpine-sepulcher-supply-flight"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=6321,["sourceHash"]="51a5a8cab93e7f1fe79f0297a14642dc88107f4cc718aa69f4a8e2ef52c3671b"},{["minimumStage"]=4,["questID"]=6323,["sourceHash"]="d3e02722ab1b4a4cf8c30715bf58c354e6d363c3143c037668ccdad36c756db8"},{["minimumStage"]=4,["questID"]=6322,["sourceHash"]="62cffdd0d1da81962870f77d9eee3366d3231a8ea6d68e68d90096cb0ed6287d"},{["minimumStage"]=4,["questID"]=6324,["sourceHash"]="9290f7c7fcd422d167ec7824201d778d061a4d0d0bb50b2f9d9b0040ab169e13"}}},["interpretation"]="Requires observed fulfillment of this source-backed route, not a larger military victory, restored city or successful experiment.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="sepulcher-requisition",["requiresAll"]={{["minimumStage"]=2,["questID"]=6321}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"6321:description:1-73","6321:description:76-187","6321:description:192-301","6321:description:306-406","6321:description:409-507","6321:objective:1-36"},["questID"]=6321,["sourceHash"]="51a5a8cab93e7f1fe79f0297a14642dc88107f4cc718aa69f4a8e2ef52c3671b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Podrig's stocktaking exposed a small but dangerous shortage. Weapons lost in the field needed replacing before the Deathguards faced the threats in Silverpine again. The requisition was bound for Gordon Wendham in the Undercity, with Karos Razok arranging the way there."},{["episodeID"]="sepulcher-bat-outbound",["requiresAll"]={{["minimumStage"]=2,["questID"]=6323}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"6323:description:1-62","6323:description:65-141","6323:description:146-212","6323:description:215-262","6323:objective:1-125"},["questID"]=6323,["sourceHash"]="d3e02722ab1b4a4cf8c30715bf58c354e6d363c3143c037668ccdad36c756db8",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Karos's bats landed in the Undercity's Trade Quarter, where Gordon kept his shop. A small fare would carry the requisition to the dealer who could fill it."},{["episodeID"]="sepulcher-crate",["requiresAll"]={{["minimumStage"]=2,["questID"]=6322}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"6322:description:1-55","6322:description:58-169","6322:description:174-228","6322:description:231-277","6322:objective:1-40"},["questID"]=6322,["sourceHash"]="62cffdd0d1da81962870f77d9eee3366d3231a8ea6d68e68d90096cb0ed6287d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Gordon packed the supplies into a crate. Getting it back to Silverpine meant taking it to Michael Garrett, the Undercity's bat master."},{["episodeID"]="sepulcher-weapons-home",["requiresAll"]={{["minimumStage"]=4,["questID"]=6324}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"6324:completion:1-14","6324:completion:16-85","6324:completion:90-140"},["questID"]=6324,["sourceHash"]="9290f7c7fcd422d167ec7824201d778d061a4d0d0bb50b2f9d9b0040ab169e13",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Podrig received the weapons and thanked the courier for serving the Dark Lady. The Sepulcher's guards would have replacements for the arms they had lost. A journey through the bat masters' network had answered a need left by the fighting in the woods."}},["grouping"]="One weapon requisition through the Forsaken bat route, returning the crate to Podrig.",["quests"]={6321,6323,6322,6324},["referenceStatus"]="HISTORICAL_STAGE_SOURCE_CORROBORATED_BY_PUBLISHER_BETA_ACCOUNTS; NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Weapons for the Sepulcher"},["silverpine-yorick"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=428,["sourceHash"]="3ee67c043849cad3b90a2e17813eb027492e5c9e8c671176c7c5d17ba5320880"},{["minimumStage"]=4,["questID"]=429,["sourceHash"]="0dcf30803e23dbba8882744a91db7ee711d1461b16e450126471d33c6d208323"},{["minimumStage"]=4,["questID"]=430,["sourceHash"]="5228451dd571833fb3a1b89d23270544df27fe84825431fa1bf2fdff3bcb7cdb"},{["minimumStage"]=4,["questID"]=425,["sourceHash"]="0a87f028bc39eed5cb7b26c0938646de1b204df731974c4817e63671191cc488"}}},["interpretation"]="Every listed leaf requires its own observed completion. This authored route clause is not a claim that the source previousID array encodes all-of gameplay prerequisites.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="silverpine-yorick-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=428}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"428:description:1-134","428:description:137-164","428:description:169-260","428:description:263-287","428:description:292-359","428:description:362-396","428:objective:1-45"},["questID"]=428,["sourceHash"]="3ee67c043849cad3b90a2e17813eb027492e5c9e8c671176c7c5d17ba5320880",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Hadrec had no report and no confirmed fate for the two missing scouts. Their intended search of northern farms supplied the only beginning for another search."},{["episodeID"]="silverpine-yorick-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=429}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"429:description:1-236","429:objective:1-76"},["questID"]=429,["sourceHash"]="0dcf30803e23dbba8882744a91db7ee711d1461b16e450126471d33c6d208323",["sourceURL"]="https://warcraftforever.games/quests/429"}},["text"]="The mystery became an injured brother and a sister keeping watch. Rane could name the potion's ingredients, but its making belonged to Renferrel, drawing a supply route between the farm and the Sepulcher."},{["episodeID"]="silverpine-yorick-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=425},{["minimumStage"]=4,["questID"]=430}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"430:description:1-53","430:description:58-125","430:objective:1-79","430:completion:1-38","430:completion:43-69","430:completion:71-100","430:completion:105-139"},["questID"]=430,["sourceHash"]="5228451dd571833fb3a1b89d23270544df27fe84825431fa1bf2fdff3bcb7cdb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"425:description:1-97","425:description:100-198","425:description:203-254","425:description:257-341","425:description:346-387","425:description:390-454","425:objective:1-75","425:completion:1-14","425:completion:16-41","425:completion:46-105"},["questID"]=425,["sourceHash"]="0a87f028bc39eed5cb7b26c0938646de1b204df731974c4817e63671191cc488",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Quinn felt the treatment working and expected to travel. With Ivar's threat answered as well, Rane could include the assistance in her report while her brother continued to recover."}},["grouping"]="Authored connected episodes with explicit source-stage gates; branches retained",["quests"]={428,429,430,425},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The Scouts at the Farm"},["stonetalon-albagorm-charred-vale"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=1056,["sourceHash"]="cc407b6f78f514198a917636f7feb866c5f3064580f276afb3dca7989ee0f798"},{["minimumStage"]=4,["questID"]=1057,["sourceHash"]="5a0f2b26705a03f82bc6bb3de0a8e5c4012a6754dec8f46b2beb587743ab8635"},{["minimumStage"]=4,["questID"]=1059,["sourceHash"]="6ae7ef206544461590f51844fc2206ad4ac6e7402f4681389e81730905b3cf5d"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="stonetalon-albagorm-charred-vale-1056",["requiresAll"]={{["minimumStage"]=2,["questID"]=1056}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"1056:description:1-63","1056:description:68-153","1056:description:155-251","1056:description:253-375","1056:description:380-408","1056:description:410-430","1056:description:435-463","1056:objective:1-45"},["questID"]=1056,["sourceHash"]="cc407b6f78f514198a917636f7feb866c5f3064580f276afb3dca7989ee0f798",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Faldreas sent word from the forest spirits toward Stonetalon Peak. The route through Talondeep and Windshear brought the traveler to Keeper Albagorm above hills already scarred by destruction."},{["episodeID"]="stonetalon-albagorm-charred-vale-1057",["requiresAll"]={{["minimumStage"]=4,["questID"]=1057}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1057:description:1-80","1057:description:85-145","1057:description:147-208","1057:description:210-264","1057:description:269-360","1057:description:362-460","1057:description:465-499","1057:objective:1-147","1057:completion:1-115"},["questID"]=1057,["sourceHash"]="5a0f2b26705a03f82bc6bb3de0a8e5c4012a6754dec8f46b2beb587743ab8635",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Albagorm blamed the mechanized industrialists for burning the Charred Vale. Bloodfury harpies now barred the way to begin regrowth, making their removal a means to reach the wounded land rather than an end in itself."},{["episodeID"]="stonetalon-albagorm-charred-vale-1059",["requiresAll"]={{["minimumStage"]=4,["questID"]=1059}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1059:description:1-34","1059:description:36-92","1059:description:97-159","1059:description:161-298","1059:description:303-430","1059:description:435-456","1059:description:458-478","1059:objective:1-76","1059:completion:1-55","1059:completion:60-172"},["questID"]=1059,["sourceHash"]="6ae7ef206544461590f51844fc2206ad4ac6e7402f4681389e81730905b3cf5d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The harpies might regroup unless help followed quickly. Word went south to Falfindel at Feralas’s edge, where a druid capable of calling great forest spirits could seek aid. The effort opened a possibility of restoration; it did not record a forest already healed."}},["grouping"]="Three stages link the mountain pilgrimage to clearing access and seeking restoration. Calling for aid is not proof the Vale regrew.",["quests"]={1056,1057,1059},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Room for the Forest to Return"},["stonetalon-venture-company-spirit-aid"]={["authored"]=true,["branchHandling"]={"The shredder operation is an optional parallel branch; completion is scoped to the toxin route."},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=1062,["sourceHash"]="1faa271a72cbef5ee863e99435762437e2c3f3f6f127e48779978e05ca2f71cc"},{["minimumStage"]=4,["questID"]=1063,["sourceHash"]="023ba41cddf386dbef8ab90448763893369d753af92f4daca6ee88bb5ee92366"},{["minimumStage"]=4,["questID"]=1064,["sourceHash"]="8911865c385b1511b9287748f46c036ea2fdfb4da70f5e0b6b566761b008a99f"},{["minimumStage"]=4,["questID"]=1065,["sourceHash"]="57879fa371d4576ba896c2fae657295e44b014f7b44ae0dcea7e8a877e775e9d"},{["minimumStage"]=4,["questID"]=1066,["sourceHash"]="14add2df218ac80173c44f81659df9f6fd50a0b2dc6ea8b16df926ddce58d5f2"},{["minimumStage"]=4,["questID"]=1067,["sourceHash"]="024911661ec480e99d3aa743d68cc9f7dec583aaaa54415e5ac8c1ab0826b324"},{["minimumStage"]=4,["questID"]=1086,["sourceHash"]="3a3cf2baefeca86bd4e748e043f0529bd1b42b21c499632784781e519f720c3a"}}},["interpretation"]="Every required route step needs its own recorded hand-in and exact source hash. Optional or alternative branches retain their separate rules.",["scope"]="DEFINED_OBSERVED_ROUTE_NOT_WORLD_VICTORY"},["episodes"]={{["episodeID"]="stonetalon-venture-company-spirit-aid-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=1062}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"1062:description:1-125","1062:description:128-189","1062:description:192-224","1062:description:229-298","1062:description:301-420","1062:description:423-471","1062:description:476-484","1062:objective:1-19","1062:objective:21-107"},["questID"]=1062,["sourceHash"]="1faa271a72cbef5ee863e99435762437e2c3f3f6f127e48779978e05ca2f71cc",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Seereth linked the spirits' suffering to the Venture Company's logging in Windshear Crag. Confronting the workforce was a first response to the destruction."},{["episodeID"]="stonetalon-venture-company-spirit-aid-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=1068}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1068:description:1-85","1068:description:88-156","1068:description:159-240","1068:description:245-370","1068:description:373-407","1068:description:412-471","1068:description:476-489","1068:objective:1-126"},["questID"]=1068,["sourceHash"]="e652912abc4fe0789ca90ee06e64fcafb8995e0fb68f8e63e9216b3dbf489432",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Two machines stood clearly in Seereth's visions of falling trees: XT:4 and XT:9. They offered a separate target within the same damage to the crag."},{["episodeID"]="stonetalon-venture-company-spirit-aid-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=1063}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1063:description:1-74","1063:description:79-152","1063:description:155-208","1063:description:211-273","1063:description:278-380","1063:description:383-452","1063:objective:1-36"},["questID"]=1063,["sourceHash"]="023ba41cddf386dbef8ab90448763893369d753af92f4daca6ee88bb5ee92366",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Force could not by itself tend the wounded spirits. Seereth sought the knowledge of the elder Magatha in Thunder Bluff."},{["episodeID"]="stonetalon-venture-company-spirit-aid-4",["requiresAll"]={{["minimumStage"]=2,["questID"]=1064}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1064:description:1-85","1064:description:88-162","1064:description:167-230","1064:description:233-258","1064:description:261-353","1064:description:358-385","1064:description:388-436","1064:description:439-501","1064:objective:1-68"},["questID"]=1064,["sourceHash"]="8911865c385b1511b9287748f46c036ea2fdfb4da70f5e0b6b566761b008a99f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Magatha proposed Forsaken knowledge of disease as a possible aid. The appeal to the emissary also offered a chance to strengthen trust between allied peoples."},{["episodeID"]="stonetalon-venture-company-spirit-aid-5",["requiresAll"]={{["minimumStage"]=2,["questID"]=1065}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1065:description:1-72","1065:description:75-105","1065:description:110-160","1065:description:163-279","1065:description:284-352","1065:description:355-436","1065:description:441-475","1065:description:478-505","1065:objective:1-54"},["questID"]=1065,["sourceHash"]="57879fa371d4576ba896c2fae657295e44b014f7b44ae0dcea7e8a877e775e9d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Zamah's proposed measure required help from Tarren Mill. Her note would explain to Lydon why a toxin was being sought for the company."},{["episodeID"]="stonetalon-venture-company-spirit-aid-6",["requiresAll"]={{["minimumStage"]=2,["questID"]=1066}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1066:description:1-101","1066:description:104-158","1066:description:163-256","1066:description:261-349","1066:description:351-422","1066:description:427-501","1066:objective:1-67"},["questID"]=1066,["sourceHash"]="14add2df218ac80173c44f81659df9f6fd50a0b2dc6ea8b16df926ddce58d5f2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Lydon described a concoction meant to leave the workforce weak and docile. Blood already collected by Syndicate shadow mages was the difficult ingredient he required."},{["episodeID"]="stonetalon-venture-company-spirit-aid-7",["requiresAll"]={{["minimumStage"]=2,["questID"]=1067}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1067:description:1-18","1067:description:21-124","1067:description:127-195","1067:description:200-248","1067:description:251-321","1067:objective:1-57"},["questID"]=1067,["sourceHash"]="024911661ec480e99d3aa743d68cc9f7dec583aaaa54415e5ac8c1ab0826b324",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="With the toxin prepared, the problem became delivery. It had to return to Zamah before any attempt to put it into the company's supply route."},{["episodeID"]="stonetalon-venture-company-spirit-aid-8",["requiresAll"]={{["minimumStage"]=4,["questID"]=1086}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1086:description:1-19","1086:description:22-54","1086:description:57-89","1086:description:94-225","1086:description:228-324","1086:description:327-440","1086:description:443-485","1086:description:490-507","1086:objective:1-41","1086:objective:43-84","1086:completion:1-19","1086:completion:21-34","1086:completion:36-97","1086:completion:99-157","1086:completion:162-283","1086:completion:285-316","1086:completion:321-403","1086:completion:408-436","1086:completion:438-468"},["questID"]=1086,["sourceHash"]="3a3cf2baefeca86bd4e748e043f0529bd1b42b21c499632784781e519f720c3a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Zamah welcomed the discovery of the company's sky port. She hoped the planted fogger would carry the toxin toward its headquarters, but that wider effect remained a hope rather than a witnessed result."}},["grouping"]="Source-reviewed continuing narrative; branch and source-stage gates retained.",["quests"]={1062,1068,1063,1064,1065,1066,1067,1086},["referenceStatus"]="RETAINED_QUEST_SOURCE_STAGES_NOT_CURRENT_PLAYABILITY_VERIFICATION",["sourceConflict"]=false,["title"]="The Wounded Crag"},["stormwind-alterac-books"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=337,["sourceHash"]="f7ad914e1944ddc0d34a4d22d2096f9de3f491aa53da0da847dc173867344c41"},{["minimumStage"]=4,["questID"]=538,["sourceHash"]="068b1ed81db4460b848bfc07a61627f081216811ec7081bd7fdc2cf575bdb728"},{["minimumStage"]=4,["questID"]=540,["sourceHash"]="946c2d728f425a6deef1259f4e99f70fd4fa9bcca379f1bda3f7eb747e70c084"},{["minimumStage"]=4,["questID"]=542,["sourceHash"]="2e87f5815860ac8abf9ee62c2f25e6cd4826eca9046d73b652eaf8943f56f9d4"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="stormwind-alterac-books-337",["requiresAll"]={{["minimumStage"]=2,["questID"]=337}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"337:description:1-146","337:description:149-249","337:description:254-322","337:objective:1-68"},["questID"]=337,["sourceHash"]="f7ad914e1944ddc0d34a4d22d2096f9de3f491aa53da0da847dc173867344c41",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Mud and scratches could not hide the library seal inside the old volume. A lost history of Stormwind offered a small opportunity to return part of the city’s memory to its shelves."},{["episodeID"]="stormwind-alterac-books-538",["requiresAll"]={{["minimumStage"]=2,["questID"]=538}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"538:description:6-107","538:description:112-203","538:description:206-297","538:description:300-327","538:description:332-386","538:description:389-429","538:description:432-500","538:objective:1-42"},["questID"]=538,["sourceHash"]="068b1ed81db4460b848bfc07a61627f081216811ec7081bd7fdc2cf575bdb728",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Milton’s concern reached beyond his own collection. Alterac’s fall had left books in a ruined city, and Loremaster Dibbs at Southshore could guide an effort to save them before more knowledge vanished."},{["episodeID"]="stormwind-alterac-books-540",["requiresAll"]={{["minimumStage"]=2,["questID"]=540}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"540:description:1-133","540:description:136-165","540:description:170-237","540:description:240-348","540:description:351-484","540:objective:1-114"},["questID"]=540,["sourceHash"]="946c2d728f425a6deef1259f4e99f70fd4fa9bcca379f1bda3f7eb747e70c084",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Ogres now occupied the ruins. Among the threatened tomes, Dibbs particularly wanted an intact work of ancient troll lore, making the search both an act of preservation and a scholar’s personal pursuit."},{["episodeID"]="stormwind-alterac-books-542",["requiresAll"]={{["minimumStage"]=4,["questID"]=542}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"542:description:1-168","542:description:173-253","542:description:256-330","542:objective:1-56","542:completion:11-24","542:completion:26-80","542:completion:82-105","542:completion:110-123","542:completion:125-142","542:completion:144-247"},["questID"]=542,["sourceHash"]="2e87f5815860ac8abf9ee62c2f25e6cd4826eca9046d73b652eaf8943f56f9d4",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Dibbs kept the troll volume to study and packed the other recovered books for Stormwind. Milton received them with astonishment that they had survived both the kingdom’s ruin and its new occupants; the Royal Library gained knowledge that might otherwise have been lost."}},["grouping"]="The recovery of library holdings, not a restoration of Alterac or the full recovery of its learning.",["quests"]={337,538,540,542},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Books Beyond a Fallen Kingdom"},["stormwind-defias-unsent-letter"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=373,["sourceHash"]="149aaeed8ef8951d80d85525bb8fa3e9e9fdd66913d07c7f2ad7c9cae399c118"},{["minimumStage"]=4,["questID"]=389,["sourceHash"]="73bfdf066e57bcaf71594b5e6813863f134f8a247111db521b64bf8430e1e0f1"},{["minimumStage"]=4,["questID"]=391,["sourceHash"]="8471649e1a584af1309f6b5ad7d46a561493fab65b20c1836d0ee90085519bc7"},{["minimumStage"]=4,["questID"]=392,["sourceHash"]="8519baeb606b428f0f8526bfcb8aaa173d05deb44c3014edbde4b509d5d14ce9"},{["minimumStage"]=4,["questID"]=393,["sourceHash"]="59f58bfecee8d676ecc841f73ff3320797ab31c1979f666125dbd11ded74bea3"},{["minimumStage"]=4,["questID"]=350,["sourceHash"]="25382028bce1d5658f18aae6e030bc6617d1c616561e8013e29ad506235ff358"},{["minimumStage"]=4,["questID"]=2745,["sourceHash"]="1e597bf876edd1ac98bc475d52db65c3ceafb2973ed7a3ad8a0a4f8eef4da5ba"},{["minimumStage"]=4,["questID"]=2746,["sourceHash"]="058894b1737fe8ca29cea8b92119f34183932b6e325989ec00f5bbbd561abfa4"},{["minimumStage"]=4,["questID"]=434,["sourceHash"]="d202eaa40829edf1f4fdb3efb864375ad658d5001c59c885af04c943472db28c"},{["minimumStage"]=4,["questID"]=394,["sourceHash"]="602d3b26db9c8cd517ec32f523fb52fd70cfedf61bf5cab3b6ee3478ac5d861b"},{["minimumStage"]=4,["questID"]=395,["sourceHash"]="f5b00e83b61a411a9ef28341397ef2452e3a14dcbf2639a59635266f029f5bf9"},{["minimumStage"]=4,["questID"]=396,["sourceHash"]="3ef0d6bf56ed36c89369dcf391521db25def2f6b9c992410c6ee72895915d764"}}},["interpretation"]="Every required route step needs its own recorded hand-in and exact source hash. Optional or alternative branches retain their separate rules.",["scope"]="DEFINED_OBSERVED_ROUTE_NOT_WORLD_VICTORY"},["episodes"]={{["episodeID"]="stormwind-defias-unsent-letter-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=373}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"373:description:1-86","373:description:88-183","373:description:188-232","373:objective:1-72"},["questID"]=373,["sourceHash"]="149aaeed8ef8951d80d85525bb8fa3e9e9fdd66913d07c7f2ad7c9cae399c118",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="An unsent letter among VanCleef's belongings named Stormwind's city architect. Baros Alexston was the next reader for a message its author had never sent."},{["episodeID"]="stormwind-defias-unsent-letter-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=389}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"389:description:1-53","389:description:55-110","389:description:115-163","389:description:165-206","389:description:208-344","389:description:346-395","389:description:400-468","389:description:470-510","389:objective:1-44"},["questID"]=389,["sourceHash"]="73bfdf066e57bcaf71594b5e6813863f134f8a247111db521b64bf8430e1e0f1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Baros remembered the Stonemasons' unpaid work rebuilding Stormwind. Bazil Thredd, now in the Stockade, might know how VanCleef's grievance had become a plan for revenge."},{["episodeID"]="stormwind-defias-unsent-letter-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=391}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"391:description:1-52","391:description:54-124","391:description:129-205","391:description:207-292","391:description:294-354","391:description:356-419","391:objective:1-78"},["questID"]=391,["sourceHash"]="8471649e1a584af1309f6b5ad7d46a561493fab65b20c1836d0ee90085519bc7",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The inquiry reached a prison already in revolt. Thelwater demanded proof against Thredd before he would trust the visitor's professed allegiance."},{["episodeID"]="stormwind-defias-unsent-letter-4",["requiresAll"]={{["minimumStage"]=2,["questID"]=392}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"392:description:1-75","392:description:77-157","392:description:162-240","392:description:242-266","392:description:268-304","392:description:306-357","392:description:362-427","392:description:429-482","392:objective:1-80"},["questID"]=392,["sourceHash"]="8519baeb606b428f0f8526bfcb8aaa173d05deb44c3014edbde4b509d5d14ce9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Thredd's recent visitor was the new lead: a quiet man whose papers named him Maelik. A sealed description could carry that uncertainty back to the architect."},{["episodeID"]="stormwind-defias-unsent-letter-5",["requiresAll"]={{["minimumStage"]=2,["questID"]=393}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"393:description:1-28","393:description:30-159","393:description:161-229","393:description:231-307","393:description:312-340","393:objective:1-85"},["questID"]=393,["sourceHash"]="59f58bfecee8d676ecc841f73ff3320797ab31c1979f666125dbd11ded74bea3",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Baros could not name the visitor. Mathias Shaw's knowledge of Stormwind's concealed dealings made SI:7 the next place to examine the description."},{["episodeID"]="stormwind-defias-unsent-letter-6",["requiresAll"]={{["minimumStage"]=2,["questID"]=350}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"350:description:1-83","350:description:88-236","350:description:238-319","350:description:321-359","350:description:364-386","350:description:388-451","350:description:453-504","350:objective:1-35"},["questID"]=350,["sourceHash"]="25382028bce1d5658f18aae6e030bc6617d1c616561e8013e29ad506235ff358",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The trail had reached Lescovar, but his noble connections made ordinary justice doubtful. Shaw turned to Elling Trias, an old contact whose help required the whole account."},{["episodeID"]="stormwind-defias-unsent-letter-7",["requiresAll"]={{["minimumStage"]=2,["questID"]=2745}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"2745:description:1-58","2745:description:60-149","2745:description:151-198","2745:description:203-257","2745:description:259-302","2745:description:307-317","2745:description:319-408","2745:description:410-460","2745:description:462-500","2745:objective:1-36"},["questID"]=2745,["sourceHash"]="1e597bf876edd1ac98bc475d52db65c3ceafb2973ed7a3ad8a0a4f8eef4da5ba",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Trias proposed an approach outside ordinary law. Tyrion had watched Lescovar for weeks and could prepare the next move inside the castle."},{["episodeID"]="stormwind-defias-unsent-letter-8",["requiresAll"]={{["minimumStage"]=2,["questID"]=2746}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"2746:description:1-46","2746:description:48-87","2746:description:89-203","2746:description:205-209","2746:description:214-293","2746:description:295-358","2746:description:363-401","2746:description:403-500","2746:objective:1-72"},["questID"]=2746,["sourceHash"]="058894b1737fe8ca29cea8b92119f34183932b6e325989ec00f5bbbd561abfa4",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Tyrion's deception needed simple materials before it could pass the guards: silk and fresh apples for Spybot's disguise. The hidden inquiry depended on a small delivery."},{["episodeID"]="stormwind-defias-unsent-letter-9",["requiresAll"]={{["minimumStage"]=2,["questID"]=434}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"434:description:1-68","434:description:70-111","434:description:116-240","434:description:242-279","434:description:284-359","434:description:361-422","434:description:424-475","434:description:477-509","434:objective:1-104","434:objective:106-178"},["questID"]=434,["sourceHash"]="d202eaa40829edf1f4fdb3efb864375ad658d5001c59c885af04c943472db28c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A false message and disguise were meant to draw Lescovar into a private meeting with Marzon. Their conversation had to reveal the Defias connection before the confrontation."},{["episodeID"]="stormwind-defias-unsent-letter-10",["requiresAll"]={{["minimumStage"]=2,["questID"]=394}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"394:description:1-22","394:description:24-145","394:description:147-218","394:description:223-302","394:description:304-337","394:description:339-435","394:objective:1-35"},["questID"]=394,["sourceHash"]="602d3b26db9c8cd517ec32f523fb52fd70cfedf61bf5cab3b6ee3478ac5d861b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Trias directed the outcome back to Shaw. His warning about noble power accompanied a report that might finally reach the court."},{["episodeID"]="stormwind-defias-unsent-letter-11",["requiresAll"]={{["minimumStage"]=2,["questID"]=395}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"395:description:1-20","395:description:22-84","395:description:86-168","395:description:173-288","395:description:290-298","395:description:308-320","395:description:322-350","395:description:355-411","395:description:413-419","395:description:421-439","395:objective:1-39"},["questID"]=395,["sourceHash"]="f5b00e83b61a411a9ef28341397ef2452e3a14dcbf2639a59635266f029f5bf9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Shaw asked for discretion about Lescovar and Trias while the public account returned to Baros. Not every participant in the hidden operation would be named."},{["episodeID"]="stormwind-defias-unsent-letter-12",["requiresAll"]={{["minimumStage"]=4,["questID"]=396}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"396:description:1-38","396:description:40-132","396:description:134-237","396:description:242-334","396:objective:1-97","396:completion:1-72","396:completion:74-223","396:completion:228-280","396:completion:282-408"},["questID"]=396,["sourceHash"]="3ef0d6bf56ed36c89369dcf391521db25def2f6b9c992410c6ee72895915d764",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The Defias report reached Stormwind Keep, where Prestor conveyed royal appreciation. The king was said to be away on a diplomatic mission, so the audience ended through his representative."}},["grouping"]="Source-reviewed continuing narrative; branch and source-stage gates retained.",["quests"]={373,389,391,392,393,350,2745,2746,434,394,395,396},["referenceStatus"]="RETAINED_QUEST_SOURCE_STAGES_NOT_CURRENT_PLAYABILITY_VERIFICATION",["sourceConflict"]=false,["title"]="The Letter Beyond the Deadmines"},["stormwind-fragrance-conspiracy"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=8903,["sourceHash"]="9b3d5dd69c0ca265aef329dffdd8d5129d09681ef7e03d52f4c65c2999ee31f6"},{["minimumStage"]=4,["questID"]=9024,["sourceHash"]="032b3f41817bee010e8af2217e2246387a28c11bf0332819f2dc5580308d2e4b"},{["minimumStage"]=4,["questID"]=9025,["sourceHash"]="d84497b09aa859fbda4c09014d7f25c4add713d59a13a4139811571af38fa281"},{["minimumStage"]=4,["questID"]=9026,["sourceHash"]="3a2971be894d6cac4dab8490746bcc11cb9dbfe35485a2c9f802cfaae9752914"},{["minimumStage"]=4,["questID"]=9027,["sourceHash"]="69cd2bbc5bd3d7ea7907519f8fbf4783b9bbdb3d5cdc26f9ef4cd01659821ffa"},{["minimumStage"]=4,["questID"]=9028,["sourceHash"]="c5fe4d7fd1e04ee50e06c2380810e3c89a4f66155b69f77245d1ef9e2ea92f6b"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="stormwind-fragrance-conspiracy-8903",["requiresAll"]={{["minimumStage"]=2,["questID"]=8903}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"8903:description:1-56","8903:description:58-167","8903:description:172-248","8903:description:250-272","8903:description:277-372","8903:objective:1-74"},["questID"]=8903,["sourceHash"]="9b3d5dd69c0ca265aef329dffdd8d5129d09681ef7e03d52f4c65c2999ee31f6",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Aristan feared that the city's sudden infatuation had reached its guards. A card from the watch would test whether the strange behavior threatened more than his sense of propriety."},{["episodeID"]="stormwind-fragrance-conspiracy-9024",["requiresAll"]={{["minimumStage"]=2,["questID"]=9024}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"9024:description:1-12","9024:description:14-60","9024:description:62-119","9024:description:121-171","9024:description:176-244","9024:description:249-366","9024:description:368-423","9024:objective:1-96"},["questID"]=9024,["sourceHash"]="032b3f41817bee010e8af2217e2246387a28c11bf0332819f2dc5580308d2e4b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The new fragrances offered a cause that could be examined. Samples went to Morgan, replacing accusation with a test of the alchemy in the bottles."},{["episodeID"]="stormwind-fragrance-conspiracy-9025",["requiresAll"]={{["minimumStage"]=2,["questID"]=9025}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"9025:description:1-14","9025:description:16-72","9025:description:74-160","9025:description:165-261","9025:description:263-275","9025:objective:1-72"},["questID"]=9025,["sourceHash"]="d84497b09aa859fbda4c09014d7f25c4add713d59a13a4139811571af38fa281",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Morgan's findings changed the question: ingredients associated with mind-altering draughts were present. Aristan's suspicion now had evidence, but the maker still had to be found."},{["episodeID"]="stormwind-fragrance-conspiracy-9026",["requiresAll"]={{["minimumStage"]=2,["questID"]=9026}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"9026:description:1-29","9026:description:31-125","9026:description:127-142","9026:description:144-204","9026:objective:1-78"},["questID"]=9026,["sourceHash"]="3a2971be894d6cac4dab8490746bcc11cb9dbfe35485a2c9f802cfaae9752914",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The Gilded Rose's extraordinary trade made Allison the next witness. The inn's supply led beyond the counter to the merchant who had delivered it."},{["episodeID"]="stormwind-fragrance-conspiracy-9027",["requiresAll"]={{["minimumStage"]=2,["questID"]=9027}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"9027:description:1-34","9027:description:36-49","9027:description:51-109","9027:description:114-175","9027:description:177-231","9027:description:233-249","9027:description:254-329","9027:objective:1-71"},["questID"]=9027,["sourceHash"]="69cd2bbc5bd3d7ea7907519f8fbf4783b9bbdb3d5cdc26f9ef4cd01659821ffa",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Evert had sold out and was delivering goods along the canals. Questioning him moved the trail from Stormwind's busy shops toward an apothecary outside the city."},{["episodeID"]="stormwind-fragrance-conspiracy-9028",["requiresAll"]={{["minimumStage"]=4,["questID"]=9028}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"9028:description:1-5","9028:description:7-14","9028:description:24-75","9028:description:80-157","9028:description:159-181","9028:description:186-250","9028:description:255-327","9028:description:329-351","9028:description:356-467","9028:description:469-499","9028:objective:1-83","9028:completion:1-29","9028:completion:31-56","9028:completion:58-70","9028:completion:75-223","9028:completion:228-261","9028:completion:263-324","9028:completion:329-355","9028:completion:357-399","9028:completion:401-441","9028:completion:443-497"},["questID"]=9028,["sourceHash"]="c5fe4d7fd1e04ee50e06c2380810e3c89a4f66155b69f77245d1ef9e2ea92f6b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Beyond Ravenholdt, Staffron admitted the design: distract both armies through the heart and leave them unready for the Shadow Council. Finding the maker exposed the plot without proving that every love in the city was false."}},["grouping"]="The Stormwind supplier investigation, not a claim that every sincere affection was caused by the potion.",["quests"]={8903,9024,9025,9026,9027,9028},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="An Unnatural Affection in Stormwind"},["stormwind-kristoff-iron-book"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=343,["sourceHash"]="8c53d2926b455e395e6b918cbd0d975e54e117239bd1c9a3645fce177a754356"},{["minimumStage"]=4,["questID"]=344,["sourceHash"]="6c8b08f2e132f156a8a10159a0c11e151dd10e7fa71da342ca74485054e69a4d"},{["minimumStage"]=4,["questID"]=345,["sourceHash"]="22c203d384c2c88041e080ed1285070092606a6349008b95615d382dddaf0a4d"},{["minimumStage"]=4,["questID"]=347,["sourceHash"]="c2ffb56e8ca463d461b1216c3e32cf1b02ff78de4fdc22099fb9ca949b29e88b"},{["minimumStage"]=4,["questID"]=346,["sourceHash"]="ea158561c02ab2bdb66b664ce14eeb08ed83e9c208f8169746c2cfb49017d986"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="stormwind-kristoff-iron-book-343",["requiresAll"]={{["minimumStage"]=2,["questID"]=343}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"343:description:1-222","343:description:225-251","343:description:254-308","343:description:313-424","343:description:427-472","343:objective:1-70","343:objective:73-158"},["questID"]=343,["sourceHash"]="8c53d2926b455e395e6b918cbd0d975e54e117239bd1c9a3645fce177a754356",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Brother Kristoff wanted a miner’s writing on iron to illuminate a sermon about spiritual endurance. The Royal Library seemed a simple place to find it, with Milton Sheaf ready to search his familiar shelves."},{["episodeID"]="stormwind-kristoff-iron-book-344",["requiresAll"]={{["minimumStage"]=2,["questID"]=344}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"344:description:1-21","344:description:24-44","344:description:47-127","344:description:130-201","344:description:204-216","344:description:221-236","344:description:239-267","344:description:270-323","344:description:326-433","344:description:438-461","344:description:464-502","344:objective:1-50"},["questID"]=344,["sourceHash"]="6c8b08f2e132f156a8a10159a0c11e151dd10e7fa71da342ca74485054e69a4d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The book had gone to Northshire Abbey months earlier. Brother Paxton wanted a copy for his own library and was embarrassed to admit that the original still could not be returned."},{["episodeID"]="stormwind-kristoff-iron-book-345",["requiresAll"]={{["minimumStage"]=2,["questID"]=345}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"345:description:1-67","345:description:72-120","345:description:123-230","345:description:233-340","345:description:345-409","345:description:412-459","345:objective:1-71"},["questID"]=345,["sourceHash"]="22c203d384c2c88041e080ed1285070092606a6349008b95615d382dddaf0a4d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Paxton’s own quick-drying ink had dried before he finished the work. Replacing it required Rethban ore from Redridge, but Lakeshire’s foreman had little time for a scribe’s needs while repairing orc damage and strengthening the town’s defenses."},{["episodeID"]="stormwind-kristoff-iron-book-347",["requiresAll"]={{["minimumStage"]=2,["questID"]=347}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"347:description:1-68","347:description:71-182","347:description:185-238","347:description:243-332","347:description:335-454","347:description:459-510","347:objective:1-87"},["questID"]=347,["sourceHash"]="c2ffb56e8ca463d461b1216c3e32cf1b02ff78de4fdc22099fb9ca949b29e88b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The ore’s dark color made it useful for ink even though it produced a metal weaker than iron. Gnoll drudgers now gathered it in Rethban Caverns, tying the abbey’s unfinished page to the troubles around Lakeshire."},{["episodeID"]="stormwind-kristoff-iron-book-346",["requiresAll"]={{["minimumStage"]=4,["questID"]=346}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"346:description:1-78","346:description:81-176","346:objective:1-51","346:objective:54-92","346:completion:1-15","346:completion:17-30","346:completion:32-91"},["questID"]=346,["sourceHash"]="ea158561c02ab2bdb66b664ce14eeb08ed83e9c208f8169746c2cfb49017d986",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="With fresh dye, Paxton finished his copy and released the borrowed original. Kristoff received the book for his speech, and the small chain of favors ended with a blessing rather than a battle."}},["grouping"]="One borrowed book and the material needed to finish copying it; no delivery route or mining action is inferred without a record.",["quests"]={343,344,345,347,346},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Ink for a Lesson in Fortitude"},["stormwind-missing-diplomat-secret-route"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=1274,["sourceHash"]="97fa62279538a1ed9039443854fb7477c64205657a46c86c1b8489057473b2fe"},{["minimumStage"]=4,["questID"]=1241,["sourceHash"]="10e4fb4c4a0ef00fb787d9d46c8156015fb8c7247dbc6eeae003e66cad94866b"},{["minimumStage"]=4,["questID"]=1242,["sourceHash"]="04911e74bda3513fc40c9d8c9daddf7409f1b6bc6a7c107a6722b99ce85f7a93"},{["minimumStage"]=4,["questID"]=1243,["sourceHash"]="9f5e4341d19735192ecd1bceacffcc268990af3a42be4f4a16caccc055c05e9e"},{["minimumStage"]=4,["questID"]=1244,["sourceHash"]="2b3e763f1ce2fffec429ef90641488f5818b5a7f1f9a9069267596ebdd7f8c69"},{["minimumStage"]=4,["questID"]=1245,["sourceHash"]="41e2ffd996b47a7ca5291a5d8a14aad9ee0bc6c79eca774bba9ffdd3b1a21b1b"},{["minimumStage"]=4,["questID"]=1246,["sourceHash"]="5e1cb3ed7a2474e80b61d7c43612a94a978a1e60177e95f8892b5971f27d91c9"},{["minimumStage"]=4,["questID"]=1447,["sourceHash"]="de0be4a5cc6893fc08abd5049f9a752641f97ca6b3abaa90211abce57414fd66"},{["minimumStage"]=4,["questID"]=1247,["sourceHash"]="9c1ba78a65bae846fb6936eaf014c7666f171d0228965c5f12c7a904eb9fd45f"},{["minimumStage"]=4,["questID"]=1248,["sourceHash"]="ee4f143fb467ecfcd771df6e5759da7340324c3c1ed16b4096407c905f0c5906"},{["minimumStage"]=4,["questID"]=1249,["sourceHash"]="34166f0d9c7340d87888a22f9b4e1983ad7566754411984ef21b5be40924731d"},{["minimumStage"]=4,["questID"]=1250,["sourceHash"]="f2184947b043f2d2eff0237fedafae6961946d7fc1e4a382cbeadabf1c458396"},{["minimumStage"]=4,["questID"]=1264,["sourceHash"]="7b9b9795b96d6b8bc5540704707f10edfc25ae43a153410c987b6880f47515d9"},{["minimumStage"]=4,["questID"]=1265,["sourceHash"]="67b7c513447f8a7363beef2ff64e7b5606fa6b362833406f23a0b02f433bbd6a"},{["minimumStage"]=4,["questID"]=1266,["sourceHash"]="c05b16ef5e646d7834a12ab71f82b89acfd46a3bb40a1f36081c6b3177850a4a"},{["minimumStage"]=4,["questID"]=1324,["sourceHash"]="214bbba840e0d82531b18cfcea7222f68521a6a439f940cf609fa0fc117b393e"},{["minimumStage"]=4,["questID"]=1267,["sourceHash"]="ab3ee8973b9d1a5e187e8b2d94e9e70d2806e1fb15d8b056e8e2013c32768b65"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="stormwind-missing-diplomat-secret-route-1274",["requiresAll"]={{["minimumStage"]=2,["questID"]=1274}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"1274:description:1-27","1274:description:29-130","1274:description:135-264","1274:description:266-291","1274:description:293-326","1274:objective:1-38"},["questID"]=1274,["sourceHash"]="97fa62279538a1ed9039443854fb7477c64205657a46c86c1b8489057473b2fe",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Thomas quietly sought help for Bishop DeLavey, asking that the visit to Stormwind Keep draw little attention. The matter belonged to the kingdom, but secrecy came before explanation."},{["episodeID"]="stormwind-missing-diplomat-secret-route-1241",["requiresAll"]={{["minimumStage"]=2,["questID"]=1241}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1241:description:1-72","1241:description:74-101","1241:description:106-174","1241:description:176-273","1241:description:278-386","1241:description:391-452","1241:description:454-511","1241:objective:1-30"},["questID"]=1241,["sourceHash"]="10e4fb4c4a0ef00fb787d9d46c8156015fb8c7247dbc6eeae003e66cad94866b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A diplomat bound for Jaina in Theramore had never arrived. DeLavey suspected the Defias without knowing their exact part and turned to his old friend Jorgen while royal agents pursued their own inquiries."},{["episodeID"]="stormwind-missing-diplomat-secret-route-1242",["requiresAll"]={{["minimumStage"]=2,["questID"]=1242}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1242:description:1-36","1242:description:38-67","1242:description:69-111","1242:description:113-137","1242:description:142-245","1242:description:250-324","1242:description:326-335","1242:objective:1-64"},["questID"]=1242,["sourceHash"]="04911e74bda3513fc40c9d8c9daddf7409f1b6bc6a7c107a6722b99ce85f7a93",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Jorgen’s sealed note led to Elling Trias behind the ordinary business of his cheese shop. He insisted on discretion: a polite delivery was enough, and the rest should never become tavern talk."},{["episodeID"]="stormwind-missing-diplomat-secret-route-1243",["requiresAll"]={{["minimumStage"]=2,["questID"]=1243}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1243:description:1-26","1243:description:28-64","1243:description:69-100","1243:description:102-154","1243:description:159-189","1243:description:191-283","1243:description:288-398","1243:description:400-511","1243:objective:1-51"},["questID"]=1243,["sourceHash"]="9f5e4341d19735192ecd1bceacffcc268990af3a42be4f4a16caccc055c05e9e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Trias brought his contacts into the search and sent the inquiry beyond Stormwind. Backus’s patrol outside Darkshire offered a way to learn what the Defias had been doing near the southern roads."},{["episodeID"]="stormwind-missing-diplomat-secret-route-1244",["requiresAll"]={{["minimumStage"]=4,["questID"]=1244}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1244:description:1-16","1244:description:18-111","1244:description:116-190","1244:description:192-288","1244:description:290-342","1244:description:347-414","1244:description:419-494","1244:objective:1-67","1244:completion:1-27","1244:completion:29-76","1244:completion:81-113","1244:completion:115-182","1244:completion:184-271"},["questID"]=1244,["sourceHash"]="2b3e763f1ce2fffec429ef90641488f5818b5a7f1f9a9069267596ebdd7f8c69",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="An unusual gathering at Addle’s Stead pointed to a docket. Backus first considered the recovered papers a possible false trail, then recognized a plan too elaborate to dismiss."},{["episodeID"]="stormwind-missing-diplomat-secret-route-1245",["requiresAll"]={{["minimumStage"]=4,["questID"]=1245}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1245:description:1-73","1245:description:75-116","1245:description:118-169","1245:description:171-207","1245:description:209-231","1245:description:233-280","1245:description:285-338","1245:description:340-444","1245:objective:1-53","1245:completion:1-7","1245:completion:9-36","1245:completion:38-90","1245:completion:95-172","1245:completion:174-179","1245:completion:181-192","1245:completion:194-198","1245:completion:200-222"},["questID"]=1245,["sourceHash"]="41e2ffd996b47a7ca5291a5d8a14aad9ee0bc6c79eca774bba9ffdd3b1a21b1b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The docket returned to Trias because its implications exceeded Backus’s authority. Among the arrangements, a familiar nickname stood out: Fist."},{["episodeID"]="stormwind-missing-diplomat-secret-route-1246",["requiresAll"]={{["minimumStage"]=2,["questID"]=1246}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1246:description:1-34","1246:description:36-44","1246:description:46-64","1246:description:66-83","1246:description:85-89","1246:description:91-107","1246:description:109-195","1246:description:200-273","1246:description:275-289","1246:description:291-379","1246:description:381-399","1246:description:401-507","1246:objective:1-39"},["questID"]=1246,["sourceHash"]="5e1cb3ed7a2474e80b61d7c43612a94a978a1e60177e95f8892b5971f27d91c9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Trias connected the name to Dashel Stonefist, an Old Town brawler unlikely to explain such business willingly. The investigation had reached someone inside the plan rather than another distant witness."},{["episodeID"]="stormwind-missing-diplomat-secret-route-1447",["requiresAll"]={{["minimumStage"]=4,["questID"]=1447}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1447:description:1-124","1447:description:129-152","1447:objective:1-37","1447:completion:1-32","1447:completion:34-53"},["questID"]=1447,["sourceHash"]="de0be4a5cc6893fc08abd5049f9a752641f97ca6b3abaa90211abce57414fd66",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Dashel answered the intrusion with threats and friends ready to fight. Defeat changed his manner enough for questions to resume, without making him a willing ally."},{["episodeID"]="stormwind-missing-diplomat-secret-route-1247",["requiresAll"]={{["minimumStage"]=4,["questID"]=1247}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1247:description:1-10","1247:description:18-76","1247:description:78-111","1247:description:113-148","1247:description:150-187","1247:description:189-205","1247:description:210-287","1247:description:289-334","1247:objective:1-35","1247:completion:1-35","1247:completion:37-75","1247:completion:80-297","1247:completion:302-428"},["questID"]=1247,["sourceHash"]="9c1ba78a65bae846fb6936eaf014c7666f171d0228965c5f12c7a904eb9fd45f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="He pointed to a backup plan and a man called Slim from Menethil. Trias’s reading agreed that an earlier capture attempt had failed, but the papers still withheld the diplomat’s name and intended destination after abduction."},{["episodeID"]="stormwind-missing-diplomat-secret-route-1248",["requiresAll"]={{["minimumStage"]=2,["questID"]=1248}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1248:description:1-73","1248:description:75-160","1248:description:162-181","1248:description:183-257","1248:description:262-367","1248:description:369-435","1248:description:437-510","1248:objective:1-33"},["questID"]=1248,["sourceHash"]="ee4f143fb467ecfcd771df6e5759da7340324c3c1ed16b4096407c905f0c5906",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A retired contact named Mikhail kept a tavern in Menethil. Trias’s name could open that door, carrying the inquiry north toward the harbor where Slim had entered the scheme."},{["episodeID"]="stormwind-missing-diplomat-secret-route-1249",["requiresAll"]={{["minimumStage"]=4,["questID"]=1249}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1249:description:1-29","1249:description:31-84","1249:description:86-113","1249:description:115-143","1249:description:148-166","1249:description:168-236","1249:description:241-316","1249:description:318-398","1249:description:400-485","1249:objective:1-77","1249:completion:1-16","1249:completion:18-30","1249:completion:32-59","1249:completion:64-170","1249:completion:172-199","1249:completion:201-317","1249:completion:322-404","1249:completion:406-441"},["questID"]=1249,["sourceHash"]="34166f0d9c7340d87888a22f9b4e1983ad7566754411984ef21b5be40924731d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Mikhail noticed a listener too interested in their conversation and too close to the exit. The man was subdued before he could flee, exposing Slim without leaving the trail to vanish into the harbor."},{["episodeID"]="stormwind-missing-diplomat-secret-route-1250",["requiresAll"]={{["minimumStage"]=4,["questID"]=1250}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1250:description:1-60","1250:description:62-80","1250:description:82-134","1250:description:136-243","1250:description:245-291","1250:description:293-321","1250:description:323-366","1250:description:371-456","1250:description:458-483","1250:description:485-502","1250:description:504-511","1250:objective:1-33","1250:completion:1-10","1250:completion:12-20","1250:completion:22-30","1250:completion:32-45","1250:completion:47-61","1250:completion:63-124","1250:completion:126-206","1250:completion:211-246","1250:completion:248-286","1250:completion:291-367","1250:completion:369-430","1250:completion:435-469","1250:completion:471-503"},["questID"]=1250,["sourceHash"]="f2184947b043f2d2eff0237fedafae6961946d7fc1e4a382cbeadabf1c458396",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Slim’s account changed the scale of the affair: the missing diplomat was Stormwind’s king. He admitted arranging Hendel’s passage onto the royal ship and said the Defias worked with an unidentified partner. Mikhail sent word to Trias as the search turned toward Theramore."},{["episodeID"]="stormwind-missing-diplomat-secret-route-1264",["requiresAll"]={{["minimumStage"]=2,["questID"]=1264}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1264:description:1-111","1264:description:113-184","1264:description:186-287","1264:description:292-390","1264:description:392-484","1264:description:486-496","1264:objective:1-42"},["questID"]=1264,["sourceHash"]="7b9b9795b96d6b8bc5540704707f10edfc25ae43a153410c987b6880f47515d9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Mikhail recognized Hendel among the marines who visited after payday. Commander Samaul’s loyalty to Proudmoore and acquaintance with Trias made him the next discreet contact across the sea."},{["episodeID"]="stormwind-missing-diplomat-secret-route-1265",["requiresAll"]={{["minimumStage"]=4,["questID"]=1265}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1265:description:1-7","1265:description:9-28","1265:description:30-71","1265:description:76-103","1265:description:105-140","1265:description:142-217","1265:description:219-324","1265:description:326-414","1265:description:419-489","1265:description:491-502","1265:objective:1-51","1265:completion:1-55","1265:completion:57-145","1265:completion:147-209","1265:completion:211-309"},["questID"]=1265,["sourceHash"]="67b7c513447f8a7363beef2ff64e7b5606fa6b362833406f23a0b02f433bbd6a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Samaul knew Hendel as one of his soldiers and directed the search toward Sentry Point. There Tervosh reported that Jaina had learned enough from other sources to send aid, although Hendel himself was elsewhere."},{["episodeID"]="stormwind-missing-diplomat-secret-route-1266",["requiresAll"]={{["minimumStage"]=2,["questID"]=1266}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1266:description:1-38","1266:description:40-128","1266:description:130-249","1266:description:254-332","1266:description:337-412","1266:description:414-492","1266:objective:1-40"},["questID"]=1266,["sourceHash"]="c05b16ef5e646d7834a12ab71f82b89acfd46a3bb40a1f36081c6b3177850a4a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Tervosh placed Hendel west along the road, guarding infiltrators watching the swamp’s threats. The next questions would reach the soldier himself, with Theramore’s assistance now behind the inquiry."},{["episodeID"]="stormwind-missing-diplomat-secret-route-1324",["requiresAll"]={{["minimumStage"]=4,["questID"]=1324}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1324:description:1-6","1324:description:8-113","1324:description:115-172","1324:objective:1-42","1324:completion:1-160","1324:completion:165-229","1324:completion:231-266"},["questID"]=1324,["sourceHash"]="214bbba840e0d82531b18cfcea7222f68521a6a439f940cf609fa0fc117b393e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Hendel met the accusation with violence. After his defeat, Tervosh arranged to take him back for questioning, hoping his answers would lead to the king. Capturing a suspect brought progress, but no recorded rescue."},{["episodeID"]="stormwind-missing-diplomat-secret-route-1267",["requiresAll"]={{["minimumStage"]=4,["questID"]=1267}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1267:objective:1-45","1267:completion:1-27","1267:completion:29-89"},["questID"]=1267,["sourceHash"]="ab3ee8973b9d1a5e187e8b2d94e9e70d2806e1fb15d8b056e8e2013c32768b65",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Jaina offered thanks and a token for the help given. The confidential route ended with Theramore pursuing the matter further: the supposed diplomat had been identified, a participant detained, and the larger partner behind the Defias still unnamed."}},["grouping"]="Seventeen retained stages follow the confidential inquiry. The missing traveler’s identity is revealed only at the confession; the ending is thanks and further questioning, not a royal rescue.",["quests"]={1274,1241,1242,1243,1244,1245,1246,1447,1247,1248,1249,1250,1264,1265,1266,1324,1267},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Letters Carried in Confidence"},["stormwind-onyxia-trophy-and-scales"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=7495,["sourceHash"]="21f85af36e596ea7292af59b4f9aa263b9705afc0fc9eb5bb980aba703f29b6d"},{["minimumStage"]=4,["questID"]=7496,["sourceHash"]="417399a4e23254a7bb00d8a653ed43a255619bf4707d6e34207c900ac84bfcac"},{["minimumStage"]=4,["questID"]=7497,["sourceHash"]="23e735f42da0d41720d9093283a2bd1e4c93b27a11c85c2db862add0c5bab071"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="stormwind-onyxia-trophy-and-scales-7495",["requiresAll"]={{["minimumStage"]=4,["questID"]=7495}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"7495:description:1-37","7495:description:39-104","7495:description:106-150","7495:objective:1-66","7495:completion:1-56","7495:completion:58-123","7495:completion:125-166"},["questID"]=7495,["sourceHash"]="21f85af36e596ea7292af59b4f9aa263b9705afc0fc9eb5bb980aba703f29b6d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Bolvar received Onyxia’s head with relief for Stormwind’s restored honor. He spoke of years beneath her captivating gaze, giving the city’s celebration a personal meaning beyond the dragon’s death."},{["episodeID"]="stormwind-onyxia-trophy-and-scales-7496",["requiresAll"]={{["minimumStage"]=4,["questID"]=7496}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"7496:description:1-53","7496:description:55-81","7496:objective:1-49","7496:completion:1-38","7496:completion:40-103"},["questID"]=7496,["sourceHash"]="417399a4e23254a7bb00d8a653ed43a255619bf4707d6e34207c900ac84bfcac",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Major Mattingly awaited the honored visitor in the Valley of Heroes. The offered reward began a ceremony granted to few, bringing the news from the Highlord’s chamber into public view."},{["episodeID"]="stormwind-onyxia-trophy-and-scales-7497",["requiresAll"]={{["minimumStage"]=4,["questID"]=7497}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"7497:completion:1-45","7497:completion:47-81","7497:completion:83-95","7497:completion:100-142","7497:completion:144-247","7497:completion:252-304","7497:completion:306-398","7497:completion:400-408"},["questID"]=7497,["sourceHash"]="23e735f42da0d41720d9093283a2bd1e4c93b27a11c85c2db862add0c5bab071",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="For a seasoned leatherworker, the aftermath also brought an offer of instruction: a cloak made with Onyxia’s scales, intended to resist Nefarian’s incendiary breath. The offered craft turned the victory’s spoils toward a future defense against the Lord of Blackrock."}},["grouping"]="The Alliance trophy celebration and conditional leatherworking instruction; no automatic cloak acquisition or Blackrock victory.",["quests"]={7495,7496,7497},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The City’s Day of Celebration"},["stormwind-wishock-black-claw"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=335,["sourceHash"]="fda8565b2928bea69003f4daac3140870444d5659ac49ffd72bbe98267aae1af"},{["minimumStage"]=4,["questID"]=336,["sourceHash"]="f49f7c3a764d772f507b2081dd9af2348844096e5f7378f99300ddb60720d213"},{["minimumStage"]=4,["questID"]=397,["sourceHash"]="92d66cd704bfae019677bc55137fc7fe6de8c244f80e919a7ce33c5c57dd89ae"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="stormwind-wishock-black-claw-335",["requiresAll"]={{["minimumStage"]=2,["questID"]=335}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"335:description:1-65","335:description:68-166","335:description:169-237","335:description:243-323","335:description:326-380","335:description:383-506","335:objective:1-116"},["questID"]=335,["sourceHash"]="fda8565b2928bea69003f4daac3140870444d5659ac49ffd72bbe98267aae1af",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Lord Wishock’s demand for an investigation threatened the warlocks’ establishment beneath the tavern. Rather than confront him in the House of Nobles, they sought a white flower from Stalvan’s garden and a root from beneath Stonewrought Dam."},{["episodeID"]="stormwind-wishock-black-claw-336",["requiresAll"]={{["minimumStage"]=2,["questID"]=336}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"336:description:1-47","336:description:50-89","336:description:92-119","336:description:122-261","336:description:264-358","336:description:361-386","336:description:391-429","336:description:432-497","336:objective:1-69"},["questID"]=336,["sourceHash"]="f49f7c3a764d772f507b2081dd9af2348844096e5f7378f99300ddb60720d213",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The ingredients became a special stout for a man whose fondness for liquor sat awkwardly beside his public campaign against the tavern. Wishock was expected near the Hall of Petitioners, where the drink could be offered without revealing its purpose."},{["episodeID"]="stormwind-wishock-black-claw-397",["requiresAll"]={{["minimumStage"]=4,["questID"]=397}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"397:description:1-41","397:description:48-75","397:description:78-172","397:description:175-231","397:description:234-284","397:objective:1-76","397:completion:1-28","397:completion:30-102"},["questID"]=397,["sourceHash"]="92d66cd704bfae019677bc55137fc7fe6de8c244f80e919a7ce33c5c57dd89ae",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Word that Wishock had enjoyed the drink satisfied the warlocks’ master. He believed their practice could now continue undisturbed and sent the helper to Zggi for a reward. What the brew had done to Wishock was left unsaid."}},["grouping"]="A warlock’s covert response to a noble’s investigation; no unsupported diagnosis or death of Wishock is inferred.",["quests"]={335,336,397},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Drink for the Petitioner"},["stranglethorn-kaleb-krazek-pot"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=210,["sourceHash"]="26504aa9771b68723781987106ec0440a4e85d60720e14ea2b9307f1dd234da6"},{["minimumStage"]=4,["questID"]=627,["sourceHash"]="1e0d4b6f9e804d5842473f1d8ece06495c4cf6c09487e420a09f3d9c005a5e76"},{["minimumStage"]=4,["questID"]=622,["sourceHash"]="a5bb55d010d1b72d0b68b33856970cb9c378b14177e1f7a00fe06dc0d0a712c8"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="stranglethorn-kaleb-krazek-pot-210",["requiresAll"]={{["minimumStage"]=2,["questID"]=210}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"210:description:1-37","210:description:40-148","210:description:151-170","210:description:173-217","210:description:222-285","210:description:288-306","210:objective:1-46"},["questID"]=210,["sourceHash"]="26504aa9771b68723781987106ec0440a4e85d60720e14ea2b9307f1dd234da6",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Corporal Kaleb had come to rely on a mechanical pot for the camp’s meals. Once it broke, the hours it had saved became another burden; Krazek, its seller in Booty Bay, was the person who might put it right."},{["episodeID"]="stranglethorn-kaleb-krazek-pot-627",["requiresAll"]={{["minimumStage"]=2,["questID"]=627}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"627:description:1-87","627:description:90-126","627:description:129-231","627:description:233-270","627:description:275-292","627:description:297-348","627:description:350-380","627:description:383-430","627:description:435-483","627:description:485-506","627:objective:1-62"},["questID"]=627,["sourceHash"]="1e0d4b6f9e804d5842473f1d8ece06495c4cf6c09487e420a09f3d9c005a5e76",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The repair came with a bargain reaching far beyond the kitchen. Krazek wanted bloodstone from Drywhisker Gorge in Arathi, even the lesser grade found there. The mineral had value to him whether the courier mined it personally or obtained it from another miner."},{["episodeID"]="stranglethorn-kaleb-krazek-pot-622",["requiresAll"]={{["minimumStage"]=4,["questID"]=622}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"622:description:1-51","622:description:54-99","622:description:102-167","622:description:172-222","622:description:225-261","622:objective:1-61","622:completion:1-11","622:completion:13-56","622:completion:58-76","622:completion:81-114","622:completion:116-154","622:completion:156-277","622:completion:279-301"},["questID"]=622,["sourceHash"]="a5bb55d010d1b72d0b68b33856970cb9c378b14177e1f7a00fe06dc0d0a712c8",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The repaired pot reached Kaleb with an extra steam whistle and a new chopping blade. His immediate thought was dinner. For the camp, the long exchange of favors ended in the return of an everyday convenience."}},["grouping"]="The camp’s broken cooking pot, the repair bargain and its return; the captain’s rumors about Booty Bay are not established as history.",["quests"]={210,627,622},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Dinner by Clockwork"},["stranglethorn-mokthardin-ceremonial-choker"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=570,["sourceHash"]="ca96140b9ec6241de141c85df79f6495aef7feaadfb3726a7e8f3fcf887295fb"},{["minimumStage"]=4,["questID"]=572,["sourceHash"]="a761171c3f3f37b6fe0bd61fd646e78a2cb93ad9d9ed522362a0f769f701ca7c"},{["minimumStage"]=4,["questID"]=571,["sourceHash"]="9fcc05d1415f4d8036be78e48154510e6084d07ecb13635d2de8d360272e05ac"},{["minimumStage"]=4,["questID"]=573,["sourceHash"]="9bb04429e3762a19913574c57a963f9198d6642648b85a4a41997cf5c70cc704"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="stranglethorn-mokthardin-ceremonial-choker-570",["requiresAll"]={{["minimumStage"]=2,["questID"]=570}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"570:description:1-81","570:description:84-124","570:description:127-164","570:description:167-220","570:description:225-291","570:description:294-319","570:description:322-354","570:description:359-486","570:objective:1-99"},["questID"]=570,["sourceHash"]="ca96140b9ec6241de141c85df79f6495aef7feaadfb3726a7e8f3fcf887295fb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Mok’thardin wanted the jungle’s power turned to the Horde’s service. The enchantment began with Shadowmaw claws and an unspoiled tigress fang, chosen specimens for a shaman’s work rather than trophies gathered without purpose."},{["episodeID"]="stranglethorn-mokthardin-ceremonial-choker-572",["requiresAll"]={{["minimumStage"]=2,["questID"]=572}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"572:description:1-119","572:description:122-260","572:description:265-324","572:description:327-394","572:description:397-490","572:objective:1-83"},["questID"]=572,["sourceHash"]="a761171c3f3f37b6fe0bd61fd646e78a2cb93ad9d9ed522362a0f769f701ca7c",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The feline reagents were only a beginning. Jungle Stalkers wore feathers upon their armbands; Mok’thardin called for these as the next pieces of the enchanted choker."},{["episodeID"]="stranglethorn-mokthardin-ceremonial-choker-571",["requiresAll"]={{["minimumStage"]=2,["questID"]=571}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"571:description:1-58","571:description:63-154","571:description:157-193","571:description:198-260","571:description:263-312","571:description:317-342","571:description:345-447","571:objective:1-64"},["questID"]=571,["sourceHash"]="9fcc05d1415f4d8036be78e48154510e6084d07ecb13635d2de8d360272e05ac",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The collected feathers, claws and fang still needed a magical tether. An aged sinew from an Elder Mistvale Gorilla could bind them, but only a perfect specimen would serve the ritual."},{["episodeID"]="stranglethorn-mokthardin-ceremonial-choker-573",["requiresAll"]={{["minimumStage"]=4,["questID"]=573}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"573:description:1-66","573:description:71-153","573:description:156-240","573:description:243-328","573:description:333-387","573:description:390-399","573:description:402-463","573:description:466-505","573:objective:1-57","573:objective:60-103","573:completion:1-75","573:completion:80-168"},["questID"]=573,["sourceHash"]="9bb04429e3762a19913574c57a963f9198d6642648b85a4a41997cf5c70cc704",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The last ingredient came from a holy spring above Stranglethorn’s western bluffs, a sacred place claimed by many peoples and approached by naga explorers. With its water delivered, Mok’thardin pronounced the ceremonial choker ready and charged its bearer to wear it proudly in the Horde’s defense."}},["grouping"]="One ceremonial choker assembled through sourced reagents and a final handover; religious claims concerning the spring remain attributed.",["quests"]={570,572,571,573},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Jungle Gathered into an Enchantment"},["stranglethorn-nesingwary-three-teachers"]={["authored"]=true,["branchHandling"]={"Tiger, panther and raptor lessons may interleave. Each episode requires its own recorded quest stage. An unrecorded track is not silently supplied by another track or by208."},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=583,["sourceHash"]="1cee3b603eefbbbd933d95806f1b2d0d04ffd3ba0735ccc6072752765ca442f2"},{["minimumStage"]=4,["questID"]=185,["sourceHash"]="1227828b43733ca3ed83380bf39557dac4cfb0c7ec0b49fcb11948aa86756f2a"},{["minimumStage"]=4,["questID"]=186,["sourceHash"]="4adada6f9f738d9e484ed6244ff210943f8d3eea32ae5d29731d8debaeecd6bf"},{["minimumStage"]=4,["questID"]=187,["sourceHash"]="a61bab442dbdc251c2de34e266819c4b0c9ba720461c0e93d809b8948906472d"},{["minimumStage"]=4,["questID"]=188,["sourceHash"]="275b9140dc3b2fac155dc2bfdd2b7867fa7f9ba64197571eb3c10077eca2f093"},{["minimumStage"]=4,["questID"]=190,["sourceHash"]="0d7a0cf7e1dcf528bb6c64fadd001424b0f2accb1159308b5d0949582e882b00"},{["minimumStage"]=4,["questID"]=191,["sourceHash"]="c7450dc093ad9fb080b3b14b86e78df60b7556997e8191a5d3bd1286cbc96690"},{["minimumStage"]=4,["questID"]=192,["sourceHash"]="4146ead3514b2306ff2c1c592001c5db1a220f0cde108c661eeb139642f3503b"},{["minimumStage"]=4,["questID"]=193,["sourceHash"]="6ab13131644d2002ed84a4351154223b265d2b41fd74695693127326f485edbf"},{["minimumStage"]=4,["questID"]=194,["sourceHash"]="4febd41fc7b8e45c54d23c015fb0511e548da66dd976c78e816e7e075329567a"},{["minimumStage"]=4,["questID"]=195,["sourceHash"]="83c3e0bf2a51a5a95e16b34a4ec0dbd5880a6e69927d60eef2ffbb73bc797be0"},{["minimumStage"]=4,["questID"]=196,["sourceHash"]="46866c1cd052e345a47e147f842a6760c7b71ee6edb271f1bb0f8ba8c9311d61"},{["minimumStage"]=4,["questID"]=197,["sourceHash"]="4016eaad99fb67f9cc905680b725f91ece982528e46462fdf290756a5c93c47d"},{["minimumStage"]=4,["questID"]=208,["sourceHash"]="07b4e77ff16d26c42ebf5e2bdecaf0472cb03756c179432beca22c4d4489e4d5"}}},["interpretation"]="All defined expedition lessons and the final handover must be recorded for the complete treatment; no unobserved kill, route, trophy acquisition or skipped training inferred.",["scope"]="OBSERVED_THREE_TRACKS_AND_FINAL_TROPHY"},["episodes"]={{["episodeID"]="stranglethorn-nesingwary-three-teachers-583",["requiresAll"]={{["minimumStage"]=4,["questID"]=583}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"583:description:1-25","583:description:30-188","583:description:191-310","583:description:315-407","583:description:412-433","583:description:436-481","583:objective:1-27","583:completion:1-41","583:completion:43-93","583:completion:98-187","583:completion:189-304","583:completion:309-356","583:completion:358-397","583:completion:399-447","583:completion:452-504"},["questID"]=583,["sourceHash"]="1cee3b603eefbbbd933d95806f1b2d0d04ffd3ba0735ccc6072752765ca442f2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Nesingwary had come into the jungle for one elusive prize, but newcomers first had to earn a place in his company. Ajeck would teach tiger hunting, Sir Erlgadin the tracking of panthers, and Hemet himself the pursuit of raptors."},{["episodeID"]="stranglethorn-nesingwary-three-teachers-185",["requiresAll"]={{["minimumStage"]=2,["questID"]=185}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"185:description:1-78","185:description:83-142","185:description:145-186","185:description:189-245","185:description:250-323","185:objective:1-88"},["questID"]=185,["sourceHash"]="1227828b43733ca3ed83380bf39557dac4cfb0c7ec0b49fcb11948aa86756f2a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Ajeck began where her own father had begun teaching her: with young tigers near the camp. Finding the animals mattered as much as confronting them; tracking was the first lesson."},{["episodeID"]="stranglethorn-nesingwary-three-teachers-186",["requiresAll"]={{["minimumStage"]=2,["questID"]=186}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"186:description:1-21","186:description:24-72","186:description:74-116","186:objective:1-82"},["questID"]=186,["sourceHash"]="4adada6f9f738d9e484ed6244ff210943f8d3eea32ae5d29731d8debaeecd6bf",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Mature tigers replaced the young cats in Ajeck’s next test. Her instruction grew more demanding as she assessed whether her pupil was ready to follow the jungle’s fiercest quarry."},{["episodeID"]="stranglethorn-nesingwary-three-teachers-187",["requiresAll"]={{["minimumStage"]=2,["questID"]=187}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"187:description:1-64","187:description:67-121","187:description:124-261","187:description:266-370","187:objective:1-88"},["questID"]=187,["sourceHash"]="a61bab442dbdc251c2de34e266819c4b0c9ba720461c0e93d809b8948906472d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The elder tigers were harder to find and more dangerous to face. Ajeck made them the last test before the hunt by which she would recognize mastery before Nesingwary."},{["episodeID"]="stranglethorn-nesingwary-three-teachers-188",["requiresAll"]={{["minimumStage"]=4,["questID"]=188}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"188:description:1-50","188:description:53-99","188:description:102-128","188:description:131-204","188:description:207-255","188:description:260-298","188:objective:1-91","188:completion:1-26","188:completion:29-67"},["questID"]=188,["sourceHash"]="275b9140dc3b2fac155dc2bfdd2b7867fa7f9ba64197571eb3c10077eca2f093",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Sin’Dall had eluded the expedition’s trackers for weeks. The returned paw finally gave Ajeck the proof she sought, and she welcomed a new master tiger hunter."},{["episodeID"]="stranglethorn-nesingwary-three-teachers-190",["requiresAll"]={{["minimumStage"]=2,["questID"]=190}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"190:description:1-147","190:description:150-193","190:description:196-241","190:description:246-293","190:objective:1-6","190:objective:11-82"},["questID"]=190,["sourceHash"]="0d7a0cf7e1dcf528bb6c64fadd001424b0f2accb1159308b5d0949582e882b00",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Sir Erlgadin measured a newcomer’s place among the hunters through a different quarry. Young panthers offered the beginning of a test in which locating the cats was already half the difficulty."},{["episodeID"]="stranglethorn-nesingwary-three-teachers-191",["requiresAll"]={{["minimumStage"]=2,["questID"]=191}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"191:description:1-39","191:description:42-186","191:description:191-217","191:description:220-282","191:objective:1-6","191:objective:11-76"},["questID"]=191,["sourceHash"]="c7450dc093ad9fb080b3b14b86e78df60b7556997e8191a5d3bd1286cbc96690",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The next panthers were tougher than the young animals of the first lesson. Erlgadin’s invitation to share the expedition’s company still depended on showing skill beyond that early success."},{["episodeID"]="stranglethorn-nesingwary-three-teachers-192",["requiresAll"]={{["minimumStage"]=2,["questID"]=192}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"192:description:1-18","192:description:21-120","192:description:123-171","192:description:176-250","192:objective:1-6","192:objective:11-86"},["questID"]=192,["sourceHash"]="4146ead3514b2306ff2c1c592001c5db1a220f0cde108c661eeb139642f3503b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Erlgadin reserved the Shadowmaw panthers for the harder trial. He called them Stranglethorn’s deadliest panthers, difficult both to track and to confront."},{["episodeID"]="stranglethorn-nesingwary-three-teachers-193",["requiresAll"]={{["minimumStage"]=4,["questID"]=193}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"193:description:1-64","193:description:67-131","193:description:134-162","193:description:165-224","193:description:229-294","193:objective:1-6","193:objective:11-92","193:completion:1-32","193:completion:34-51","193:completion:53-79"},["questID"]=193,["sourceHash"]="6ab13131644d2002ed84a4351154223b265d2b41fd74695693127326f485edbf",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Bhag’thera had continued prowling beyond the expedition’s reach. The great panther’s fang brought Erlgadin’s test to its conclusion and earned his respect."},{["episodeID"]="stranglethorn-nesingwary-three-teachers-194",["requiresAll"]={{["minimumStage"]=2,["questID"]=194}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"194:description:1-54","194:description:57-94","194:description:97-156","194:description:159-211","194:description:216-264","194:description:267-308","194:objective:1-60"},["questID"]=194,["sourceHash"]="4febd41fc7b8e45c54d23c015fb0511e548da66dd976c78e816e7e075329567a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Hemet refused to give away the hunting grounds for his own first trial. Stranglethorn’s raptors had to be found as well as overcome before he would judge a newcomer’s skill."},{["episodeID"]="stranglethorn-nesingwary-three-teachers-195",["requiresAll"]={{["minimumStage"]=2,["questID"]=195}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"195:description:1-59","195:description:62-138","195:description:141-166","195:objective:1-55"},["questID"]=195,["sourceHash"]="83c3e0bf2a51a5a95e16b34a4ec0dbd5880a6e69927d60eef2ffbb73bc797be0",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Lashtail raptors followed the first quarry. Hemet raised the challenge while keeping the same expectation: a hunter had to bring more than confidence into the jungle."},{["episodeID"]="stranglethorn-nesingwary-three-teachers-196",["requiresAll"]={{["minimumStage"]=2,["questID"]=196}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"196:description:1-45","196:description:48-90","196:description:93-121","196:description:124-228","196:description:231-299","196:objective:1-54"},["questID"]=196,["sourceHash"]="46866c1cd052e345a47e147f842a6760c7b71ee6edb271f1bb0f8ba8c9311d61",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The cagey Jungle Stalkers promised a harder search than the earlier raptor breeds. Hemet kept his finest quarry in reserve until this test had proved the hunter ready."},{["episodeID"]="stranglethorn-nesingwary-three-teachers-197",["requiresAll"]={{["minimumStage"]=4,["questID"]=197}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"197:description:1-139","197:description:142-182","197:description:187-266","197:description:269-334","197:objective:1-89","197:completion:1-29","197:completion:34-59"},["questID"]=197,["sourceHash"]="4016eaad99fb67f9cc905680b725f91ece982528e46462fdf290756a5c93c47d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Even Hemet had failed to claim Tethis, the wily raptor Ajeck had named. The returned talon answered that final challenge, and Hemet greeted its bearer as a master raptor slayer."},{["episodeID"]="stranglethorn-nesingwary-three-teachers-208",["requiresAll"]={{["minimumStage"]=4,["questID"]=208}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"208:description:1-43","208:description:46-179","208:description:184-272","208:description:275-323","208:description:326-366","208:description:369-418","208:description:421-496","208:objective:1-90","208:completion:1-17","208:completion:19-26","208:completion:28-88","208:completion:93-163","208:completion:165-226","208:completion:231-251","208:completion:253-259"},["questID"]=208,["sourceHash"]="07b4e77ff16d26c42ebf5e2bdecaf0472cb03756c179432beca22c4d4489e4d5",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The trials led to the white tiger that had drawn Hemet to Stranglethorn: King Bangalash. With the great beast’s head brought back, Hemet offered a jubilant welcome into the company of his hunting expedition."}},["grouping"]="One expedition with three independent training tracks.208 explicitly names their three final quarry in its description but has no retained prerequisite metadata; dialogue connection is not claimed as a verified technical edge.",["quests"]={583,185,186,187,188,190,191,192,193,194,195,196,197,208},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Three Teachers and the White Tiger"},["swamp-biggs-caravan-to-nethergarde"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=1396,["sourceHash"]="8ac63506adec5feafe7525c1d97e7b79445d0268b38590096eea2207e91c3163"},{["minimumStage"]=4,["questID"]=1421,["sourceHash"]="0100491f9d896ab15f0630b8ab130a10e746ddf692860ef03a1506a857eb77b9"},{["minimumStage"]=4,["questID"]=1398,["sourceHash"]="31711729577ee3f0cccd6ee726cad62702a5d7befa8df453e999ee7314f0b210"},{["minimumStage"]=4,["questID"]=1425,["sourceHash"]="5bf06c102df995540108684c5658e1d01f196b1877f7de3f42bf45b2868a7298"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="swamp-biggs-caravan-to-nethergarde-1396",["requiresAll"]={{["minimumStage"]=2,["questID"]=1396}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"1396:description:1-77","1396:description:80-138","1396:description:143-173","1396:description:176-251","1396:description:254-300","1396:objective:1-127"},["questID"]=1396,["sourceHash"]="8ac63506adec5feafe7525c1d97e7b79445d0268b38590096eea2207e91c3163",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Watcher Biggs alone remained with a ruined caravan that had failed to reach the eastern coast. He refused to abandon the surviving supplies, though the swamp’s hunting beasts threatened his exposed camp."},{["episodeID"]="swamp-biggs-caravan-to-nethergarde-1421",["requiresAll"]={{["minimumStage"]=4,["questID"]=1421}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1421:description:1-180","1421:description:185-307","1421:description:310-351","1421:description:354-383","1421:objective:1-104","1421:completion:1-19","1421:completion:21-83","1421:completion:85-226"},["questID"]=1421,["sourceHash"]="0100491f9d896ab15f0630b8ab130a10e746ddf692860ef03a1506a857eb77b9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Before losing consciousness in the attack, Biggs had seen a wagon dragged toward Fallow Sanctuary. Its recovered chest contained reagents for Nethergarde’s wizards, whose work around the Dark Portal made the cargo more than ordinary trade goods."},{["episodeID"]="swamp-biggs-caravan-to-nethergarde-1398",["requiresAll"]={{["minimumStage"]=4,["questID"]=1398}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1398:description:1-22","1398:description:25-60","1398:description:63-122","1398:description:127-187","1398:description:190-204","1398:description:206-222","1398:description:225-292","1398:description:297-377","1398:description:380-394","1398:objective:1-78","1398:completion:1-30","1398:completion:32-45","1398:completion:47-66"},["questID"]=1398,["sourceHash"]="31711729577ee3f0cccd6ee726cad62702a5d7befa8df453e999ee7314f0b210",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Keeping the cargo moving required repairing the wagon. The swamp’s soft, tangled timber would not serve, so dry wood from the sunny coast supplied the strength Biggs needed."},{["episodeID"]="swamp-biggs-caravan-to-nethergarde-1425",["requiresAll"]={{["minimumStage"]=4,["questID"]=1425}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1425:description:1-57","1425:description:62-127","1425:description:130-159","1425:description:162-260","1425:description:265-306","1425:description:309-392","1425:description:395-427","1425:objective:1-80","1425:completion:1-5","1425:completion:7-36","1425:completion:38-70","1425:completion:75-88","1425:completion:90-167","1425:completion:169-195"},["questID"]=1425,["sourceHash"]="5bf06c102df995540108684c5658e1d01f196b1877f7de3f42bf45b2868a7298",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="While Biggs worked on the wagon, the most urgent supplies went ahead to Nethergarde. Lungertz had thought both caravan and driver lost, and welcomed a shipment that might replenish dwindling Azoran Crystals. The route restored needed provisions without claiming Biggs himself had yet arrived."}},["grouping"]="Four stages salvage a ruined caravan. The source’s later reference to ogres conflicts with its initial Lost Ones account; attacker identity is not silently resolved.",["quests"]={1396,1421,1398,1425},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="What the Caravan Could Still Carry"},["teldrassil-gnarlpine-sleepers"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=475,["sourceHash"]="75434eb6abd9ac836b269d56374c34cf47a92a0d0c15c83cf00f12fd4ebcb245"},{["minimumStage"]=4,["questID"]=476,["sourceHash"]="2e4adfcc0385abb257e5a0bfc5cf1107ce241325ddee2d5566e42ef130bd2f02"},{["minimumStage"]=4,["questID"]=483,["sourceHash"]="42cda196ce182c2136decd22ec3703b83e8d589d6d1ed44d0aca10b54232281a"},{["minimumStage"]=4,["questID"]=486,["sourceHash"]="1c681faecd7a5f629a2c2cc7d910cc2a98efcd62f4cefb1c5b36f2287ba011c2"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="teldrassil-gnarlpine-sleepers-475",["requiresAll"]={{["minimumStage"]=2,["questID"]=475}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"475:description:1-44","475:description:49-158","475:description:161-283","475:description:288-344","475:description:347-500","475:objective:1-51"},["questID"]=475,["sourceHash"]="75434eb6abd9ac836b269d56374c34cf47a92a0d0c15c83cf00f12fd4ebcb245",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Gaerolas's silence troubled Athridas because more than one warden's safety depended upon him. Ban'ethil's sleeping Druids of the Talon needed their protector to keep their pact with Ysera."},{["episodeID"]="teldrassil-gnarlpine-sleepers-476",["requiresAll"]={{["minimumStage"]=2,["questID"]=476}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"476:description:1-39","476:description:44-119","476:description:122-221","476:description:224-317","476:description:322-389","476:description:392-425","476:description:428-507","476:objective:1-42"},["questID"]=476,["sourceHash"]="2e4adfcc0385abb257e5a0bfc5cf1107ce241325ddee2d5566e42ef130bd2f02",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The missing report became a warning from a wounded man. Gaerolas accused Ursal of spreading fel moss madness through the once peaceful Gnarlpines, whose attack had left Starbreeze pillaged."},{["episodeID"]="teldrassil-gnarlpine-sleepers-483",["requiresAll"]={{["minimumStage"]=2,["questID"]=483}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"483:description:1-75","483:description:80-190","483:description:192-271","483:description:276-390","483:description:392-430","483:description:433-490","483:objective:1-82"},["questID"]=483,["sourceHash"]="42cda196ce182c2136decd22ec3703b83e8d589d6d1ed44d0aca10b54232281a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The danger had reached the barrow den. Waking the druids safely required four sacred relics; breaking their hibernation carelessly risked leaving them trapped in the Emerald Dream."},{["episodeID"]="teldrassil-gnarlpine-sleepers-486",["requiresAll"]={{["minimumStage"]=4,["questID"]=486}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"486:description:1-54","486:description:56-110","486:description:115-176","486:description:178-276","486:description:279-316","486:description:321-449","486:description:452-506","486:objective:1-68","486:completion:1-54","486:completion:56-160","486:completion:165-234"},["questID"]=486,["sourceHash"]="1c681faecd7a5f629a2c2cc7d910cc2a98efcd62f4cefb1c5b36f2287ba011c2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="While Athridas prepared the relics, Ursal's defeat removed the final obstacle he had named to the awakening. His thanks closed the effort to protect the sleepers, without making every troubled corner of Teldrassil safe."}},["grouping"]="The attack on Starbreeze and the threatened barrow sleepers; no unrelated furbolg tribe is implicated.",["quests"]={475,476,483,486},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Wardens of the Sleeping"},["teldrassil-moonwell-history"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=921,["sourceHash"]="e68518cc1fe6085c5aa2c05860a73dd8793e9c441801ff6df9c80417ede14838"},{["minimumStage"]=4,["questID"]=928,["sourceHash"]="fcda94b8509c04ac66ae6cd5f74c9a8bef5140af013f15e72e53931939e7eeb2"},{["minimumStage"]=4,["questID"]=929,["sourceHash"]="2decdd2f207e21b84d0f8afd3d471a4ecae426e70d7ae78278ddf6145f14be15"},{["minimumStage"]=4,["questID"]=933,["sourceHash"]="5b14c6a4f868f276f7f188502eb28bdb53b255c7e34dbc1870368f82292dc711"},{["minimumStage"]=4,["questID"]=7383,["sourceHash"]="e74b276f6e81d21f206300f3d6b9e509c21859647ec7c861306e93291b5b3805"},{["minimumStage"]=4,["questID"]=935,["sourceHash"]="076c2011985cd4c5d000acbb892bdadb53abefde12e0f44301fcd5c2ae9a0c0b"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="teldrassil-moonwell-history-921",["requiresAll"]={{["minimumStage"]=2,["questID"]=921}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"921:description:1-55","921:description:57-191","921:description:196-260","921:description:262-384","921:description:389-421","921:description:423-495","921:objective:1-77"},["questID"]=921,["sourceHash"]="e68518cc1fe6085c5aa2c05860a73dd8793e9c441801ff6df9c80417ede14838",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Tenaron joined the first gathering of moonwell water to a lesson about Mount Hyjal. Nordrassil's sacrifice had driven back the Legion, leaving the night elves to find a changed place in the world."},{["episodeID"]="teldrassil-moonwell-history-928",["requiresAll"]={{["minimumStage"]=2,["questID"]=928}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"928:description:1-99","928:description:101-141","928:description:143-226","928:description:231-249","928:description:251-296","928:description:298-416","928:description:421-457","928:description:459-508","928:objective:1-68"},["questID"]=928,["sourceHash"]="fcda94b8509c04ac66ae6cd5f74c9a8bef5140af013f15e72e53931939e7eeb2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The first phial became part of a vessel bound for Corithras at Dolanaar. What began beneath Aldrassil would continue across Teldrassil rather than end with a single well."},{["episodeID"]="teldrassil-moonwell-history-929",["requiresAll"]={{["minimumStage"]=2,["questID"]=929}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"929:description:1-58","929:description:60-186","929:description:188-268","929:description:273-403","929:description:405-491","929:objective:1-72"},["questID"]=929,["sourceHash"]="2decdd2f207e21b84d0f8afd3d471a4ecae426e70d7ae78278ddf6145f14be15",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Corithras explained the practical purpose: Darnassus's moonwell needed replenishing from the wells across the tree. Starbreeze's water would carry that shared duty onward."},{["episodeID"]="teldrassil-moonwell-history-933",["requiresAll"]={{["minimumStage"]=4,["questID"]=933}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"933:description:1-107","933:description:109-240","933:description:245-314","933:objective:1-78","933:completion:1-123","933:completion:125-371","933:completion:376-482"},["questID"]=933,["sourceHash"]="5b14c6a4f868f276f7f188502eb28bdb53b255c7e34dbc1870368f82292dc711",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The well beside Arlithrien lay within reach of hostile furbolgs. With its water gathered, Corithras recalled the druids' disarray after Malfurion's disappearance and Fandral's decision to grow a new World Tree."},{["episodeID"]="teldrassil-moonwell-history-7383",["requiresAll"]={{["minimumStage"]=4,["questID"]=7383}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"7383:description:1-42","7383:description:44-234","7383:description:239-276","7383:description:278-348","7383:description:350-431","7383:description:433-479","7383:objective:1-76","7383:completion:1-43","7383:completion:45-82","7383:completion:84-113","7383:completion:118-258","7383:completion:260-353","7383:completion:355-499"},["questID"]=7383,["sourceHash"]="e74b276f6e81d21f206300f3d6b9e509c21859647ec7c861306e93291b5b3805",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The Oracle Glade supplied the last water and the harder part of the telling. The dragons had refused the blessings sought for Teldrassil, leaving its growth flawed rather than restoring the immortality the druids desired."},{["episodeID"]="teldrassil-moonwell-history-935",["requiresAll"]={{["minimumStage"]=4,["questID"]=935}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"935:description:1-126","935:description:128-248","935:description:253-338","935:description:340-428","935:description:433-499","935:objective:1-68","935:completion:1-34","935:completion:36-108","935:completion:110-164","935:completion:166-169","935:completion:174-225","935:completion:227-285","935:completion:287-324","935:completion:329-368"},["questID"]=935,["sourceHash"]="076c2011985cd4c5d000acbb892bdadb53abefde12e0f44301fcd5c2ae9a0c0b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The gathered waters reached Fandral in Darnassus. The archdruid accepted them impatiently, eager to resume work under the burden of Teldrassil's troubles. Delivery completed the task; those troubles remained."}},["grouping"]="The retained six-stage moonwell route through the Oracle Glade; the alternative older referral is not imposed as another required journey.",["quests"]={921,928,929,933,7383,935},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Water for the New World Tree"},["thousand-needles-galak-sacred-relic"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=1195,["sourceHash"]="78ed8423acff3f1b4a13ca435cc91b7ca7ffc1ac6555d46733db0dac927b5550"},{["minimumStage"]=4,["questID"]=1196,["sourceHash"]="82a1c3dab3e654906127087b88182e3b3da292ed709faaf287347e2e7efae5e5"},{["minimumStage"]=4,["questID"]=1197,["sourceHash"]="125b9cae3c52fda7b9852f556fa0f66bc5dd2c740f3315f54491deaa96bca7f4"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="thousand-needles-galak-sacred-relic-1195",["requiresAll"]={{["minimumStage"]=2,["questID"]=1195}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"1195:description:1-109","1195:description:114-214","1195:description:219-370","1195:description:372-490","1195:objective:1-66"},["questID"]=1195,["sourceHash"]="78ed8423acff3f1b4a13ca435cc91b7ca7ffc1ac6555d46733db0dac927b5550",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The Galak guarded a relic associated with the centaurs’ beginnings. Zangen needed moonwell water to reach it, first requiring a dryad’s phial from Raynewood and then water from the well near the Falfarren."},{["episodeID"]="thousand-needles-galak-sacred-relic-1196",["requiresAll"]={{["minimumStage"]=4,["questID"]=1196}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1196:description:1-96","1196:description:98-194","1196:description:199-253","1196:objective:1-72","1196:completion:1-63","1196:completion:65-245"},["questID"]=1196,["sourceHash"]="82a1c3dab3e654906127087b88182e3b3da292ed709faaf287347e2e7efae5e5",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The filled phial reached Rau at Freewind Post. He explained that the dryads’ shared ancestry with the centaurs made this water capable of breaching the flame that protected the artifact."},{["episodeID"]="thousand-needles-galak-sacred-relic-1197",["requiresAll"]={{["minimumStage"]=4,["questID"]=1197}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1197:description:1-106","1197:description:108-184","1197:description:189-265","1197:description:267-338","1197:description:343-473","1197:objective:1-66","1197:completion:1-51","1197:completion:53-150","1197:completion:155-168","1197:completion:170-235"},["questID"]=1197,["sourceHash"]="125b9cae3c52fda7b9852f556fa0f66bc5dd2c740f3315f54491deaa96bca7f4",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="That protection could be quenched only briefly, deep inside guarded Splithoof Hold. The Cloven Hoof returned with a strange energy Rau hoped to understand. Its recovery began his study, leaving the promised revelations about centaur history for another account."}},["grouping"]="Three steps establish the relic’s protection and the reason for the moonwell journey. Future discoveries from studying the Hoof remain unknown.",["quests"]={1195,1196,1197},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Water Against the Eternal Flame"},["uldaman-jarkal"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=2283,["sourceHash"]="f429a5e44305245c86bdf212fe67dd49addc0ebe1eaeb522fc6e7dcd5d28adeb"},{["minimumStage"]=4,["questID"]=2284,["sourceHash"]="7a5afd4ffd779f30bee19f0b0f0af64b8c2690e9631a4f1d6763e2ea8143ccca"},{["minimumStage"]=4,["questID"]=2318,["sourceHash"]="d74be64f79b2ad1e4ff6c1059161ab20037fc28f50b30419a495ab7c8c571fe2"},{["minimumStage"]=4,["questID"]=2338,["sourceHash"]="7dfc3772d88b8ff34b19a4f5e6119e7ca4d064e53d086ca425d2cddfcca34c08"},{["minimumStage"]=4,["questID"]=2339,["sourceHash"]="0a07266f630f39e116d4dcc0d9d959ebb686552133945c93030419f998775023"},{["minimumStage"]=4,["questID"]=2340,["sourceHash"]="899b80655d426a2521032b65370fb523adc588f09fad18bd9e95f3a33c482640"},{["minimumStage"]=4,["questID"]=2341,["sourceHash"]="e02d086660730c7deef8efd77815a9da12627e56fd1595cacd2edff291fbfdc3"}}},["interpretation"]="Every listed leaf requires its own observed completion. This authored route clause is not a claim that the source previousID array encodes all-of gameplay prerequisites.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="uldaman-jarkal-1",["requiresAll"]={{["minimumStage"]=4,["questID"]=2283},{["minimumStage"]=4,["questID"]=2284}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"2283:description:1-64","2283:description:69-113","2283:description:116-183","2283:description:186-249","2283:description:252-321","2283:description:326-385","2283:description:388-480","2283:objective:1-105","2283:objective:108-135","2283:completion:1-13","2283:completion:16-50","2283:completion:53-84","2283:completion:89-136","2283:completion:139-172","2283:completion:175-203","2283:completion:206-250","2283:completion:255-290","2283:completion:292-341","2283:completion:344-392"},["questID"]=2283,["sourceHash"]="f429a5e44305245c86bdf212fe67dd49addc0ebe1eaeb522fc6e7dcd5d28adeb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"2284:description:1-72","2284:description:75-130","2284:description:135-263","2284:description:266-304","2284:description:309-344","2284:description:347-404","2284:description:407-485","2284:objective:1-65","2284:completion:1-86","2284:completion:88-154","2284:completion:156-242","2284:completion:244-365","2284:completion:370-445"},["questID"]=2284,["sourceHash"]="7a5afd4ffd779f30bee19f0b0f0af64b8c2690e9631a4f1d6763e2ea8143ccca",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Dran's promised salvage arrived without its gems, sending the search back below. The paladin's journal survived as a clue that its finder's language could not yet unlock."},{["episodeID"]="uldaman-jarkal-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=2338},{["minimumStage"]=2,["questID"]=2339}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"2338:description:1-92","2338:description:95-168","2338:description:171-208","2338:description:211-312","2338:description:315-402","2338:description:407-460","2338:description:463-479","2338:objective:1-31","2338:objective:34-84"},["questID"]=2338,["sourceHash"]="7dfc3772d88b8ff34b19a4f5e6119e7ca4d064e53d086ca425d2cddfcca34c08",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"2339:description:1-60","2339:description:63-173","2339:description:178-252","2339:description:255-286","2339:description:289-405","2339:description:408-447","2339:description:452-502","2339:objective:1-123","2339:objective:126-217","2339:objective:222-250","2339:objective:253-313","2339:objective:316-407","2339:objective:410-470"},["questID"]=2339,["sourceHash"]="0a07266f630f39e116d4dcc0d9d959ebb686552133945c93030419f998775023",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Jarkal offered translation for the chance to study the setting. His interest added a hidden experiment to the original contract and a power source to the hunt for gems."},{["episodeID"]="uldaman-jarkal-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=2340},{["minimumStage"]=4,["questID"]=2341}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"2340:description:1-78","2340:description:81-160","2340:description:162-168","2340:description:173-284","2340:description:289-369","2340:description:372-477","2340:objective:1-67","2340:completion:1-19","2340:completion:21-53","2340:completion:59-80","2340:completion:82-85","2340:completion:90-133","2340:completion:135-207","2340:completion:209-218","2340:completion:223-275","2340:completion:277-356","2340:completion:358-377"},["questID"]=2340,["sourceHash"]="899b80655d426a2521032b65370fb523adc588f09fad18bd9e95f3a33c482640",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"2341:description:1-103","2341:description:106-245","2341:objective:1-61","2341:completion:1-69","2341:completion:71-173","2341:completion:175-250","2341:completion:255-277","2341:completion:279-319","2341:completion:321-365"},["questID"]=2341,["sourceHash"]="e02d086660730c7deef8efd77815a9da12627e56fd1595cacd2edff291fbfdc3",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The original salvage reached the Droffers while Jarkal's separate bargain succeeded at Kargath. He made two necklaces and retained capacity for more, leaving the salvage partners unaware of his duplication."}},["grouping"]="Authored connected episodes with explicit source-stage gates; branches retained",["quests"]={2283,2284,2318,2338,2339,2340,2341},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="Salvage and a Second Bargain"},["uldaman-talvash"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=2198,["sourceHash"]="da7824d46cac80c055eddba9808a62134d1d3292a859257e7ba67e6ce14e313b"},{["minimumStage"]=4,["questID"]=2199,["sourceHash"]="f4aba0c4e4fa3ab3509f8cbf5b9c10b170e28655b5cdf3eea0f2842e3ef197e9"},{["minimumStage"]=4,["questID"]=2200,["sourceHash"]="cfcdf73e5b01b74220b864b4959849476a52119e420ba3333626c459746517e2"},{["minimumStage"]=4,["questID"]=2201,["sourceHash"]="960974c3148691be838e8177bed9d6beecf629030b2fc8e3ae246f3ea7a43762"},{["minimumStage"]=4,["questID"]=2204,["sourceHash"]="25259ddc756786b2aa46e5291967e4c81351ee8e4c4908b084964175fb275f61"},{["minimumStage"]=4,["questID"]=2361,["sourceHash"]="f7fde84e24f385dfd7ad9ffd4c5cd8fed0fca223f163343627629d3028aad2f7"}}},["interpretation"]="2204 ends with fusion about to begin.2361 is the explicit completed-necklace receipt and is required before the source outcome is marked complete.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="uldaman-talvash-1",["requiresAll"]={{["minimumStage"]=4,["questID"]=2198},{["minimumStage"]=4,["questID"]=2199}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"2198:description:1-99","2198:description:102-182","2198:description:185-269","2198:description:272-326","2198:description:331-425","2198:description:428-475","2198:objective:1-90","2198:completion:1-6","2198:completion:8-47","2198:completion:49-128","2198:completion:130-163","2198:completion:165-225"},["questID"]=2198,["sourceHash"]="da7824d46cac80c055eddba9808a62134d1d3292a859257e7ba67e6ce14e313b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"2199:description:1-49","2199:description:52-80","2199:description:82-148","2199:description:151-210","2199:description:213-297","2199:description:302-412","2199:description:417-498","2199:objective:1-58","2199:completion:1-79","2199:completion:81-93","2199:completion:96-126","2199:completion:131-250","2199:completion:253-293","2199:completion:296-419","2199:completion:424-430","2199:completion:432-504"},["questID"]=2199,["sourceHash"]="f4aba0c4e4fa3ab3509f8cbf5b9c10b170e28655b5cdf3eea0f2842e3ef197e9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The damaged necklace led to a maker ruined by rumor. Silver supplied a new order and bought the account of a paladin whose death had been blamed on the jeweler's work."},{["episodeID"]="uldaman-talvash-2",["requiresAll"]={{["minimumStage"]=4,["questID"]=2200},{["minimumStage"]=4,["questID"]=2201}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"2200:description:1-73","2200:description:76-140","2200:description:145-279","2200:description:284-407","2200:description:410-501","2200:objective:1-84","2200:objective:87-148","2200:completion:1-140","2200:completion:145-256","2200:completion:261-367","2200:completion:372-433"},["questID"]=2200,["sourceHash"]="cfcdf73e5b01b74220b864b4959849476a52119e420ba3333626c459746517e2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"2201:description:1-124","2201:description:127-278","2201:description:283-351","2201:description:354-480","2201:objective:1-73","2201:objective:76-179","2201:objective:184-212","2201:objective:215-275","2201:objective:278-369","2201:objective:374-434","2201:completion:1-37","2201:completion:40-48","2201:completion:51-101","2201:completion:106-158","2201:completion:161-238","2201:completion:241-293","2201:completion:296-341"},["questID"]=2201,["sourceHash"]="960974c3148691be838e8177bed9d6beecf629030b2fc8e3ae246f3ea7a43762",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The dead owner's journal turned the search into three locations contested by troggs and dwarves. Reuniting the stones proved the account useful, but did not replace the magic the setting had lost."},{["episodeID"]="uldaman-talvash-3",["requiresAll"]={{["minimumStage"]=4,["questID"]=2204}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"2204:description:1-117","2204:description:120-187","2204:description:190-275","2204:description:278-335","2204:description:340-405","2204:description:408-497","2204:objective:1-130","2204:completion:1-76","2204:completion:79-201","2204:completion:204-256","2204:completion:261-287","2204:completion:290-318","2204:completion:321-362"},["questID"]=2204,["sourceHash"]="25259ddc756786b2aa46e5291967e4c81351ee8e4c4908b084964175fb275f61",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A construct's power source completed the material search. Talvash prepared the fusion and sought his spell focus, with restoration about to be worked rather than already presumed."}},["grouping"]="Authored connected episodes with explicit source-stage gates; branches retained",["quests"]={2198,2199,2200,2201,2204},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The Maker and His Reputation"},["undercity-cuely-thersa-experiment"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=3568,["sourceHash"]="fe11380a3028d9a5805cdf682b238cebf5601b73f803f8b28c177e550f3dd492"},{["minimumStage"]=4,["questID"]=3569,["sourceHash"]="610f0ce045e152761e59a69a7adab138d59c121898cc24f5a9787e1d33e49b67"},{["minimumStage"]=4,["questID"]=3570,["sourceHash"]="87ebbaf57d45ae0c615edfcedbcae77fd68dce3d3cf65de52082b0c2d6298050"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="undercity-cuely-thersa-experiment-3568",["requiresAll"]={{["minimumStage"]=2,["questID"]=3568}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"3568:description:1-86","3568:description:88-115","3568:description:117-207","3568:description:212-312","3568:description:314-342","3568:description:344-362","3568:description:367-402","3568:description:404-455","3568:description:457-499","3568:objective:1-127"},["questID"]=3568,["sourceHash"]="fe11380a3028d9a5805cdf682b238cebf5601b73f803f8b28c177e550f3dd492",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Thersa’s illness followed naga wounds and a drink from Azshara’s tide pools. Cuely wanted samples from four pools to investigate what she had swallowed, while the sick tauren waited in Undercity."},{["episodeID"]="undercity-cuely-thersa-experiment-3569",["requiresAll"]={{["minimumStage"]=4,["questID"]=3569}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"3569:description:1-20","3569:description:22-48","3569:description:50-61","3569:description:63-109","3569:objective:1-52","3569:completion:1-44","3569:completion:46-61","3569:completion:63-124","3569:completion:126-170","3569:completion:172-243","3569:completion:248-303"},["questID"]=3569,["sourceHash"]="610f0ce045e152761e59a69a7adab138d59c121898cc24f5a9787e1d33e49b67",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The samples led to an elixir with no assurance of a cure. Thersa had already sought priests and shamans without relief; short of time and alternatives, she accepted Cuely’s unsettling help and prayed that the Earthmother would guard her spirit."},{["episodeID"]="undercity-cuely-thersa-experiment-3570",["requiresAll"]={{["minimumStage"]=4,["questID"]=3570}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"3570:completion:1-56","3570:completion:58-71","3570:completion:73-131","3570:completion:133-209"},["questID"]=3570,["sourceHash"]="87ebbaf57d45ae0c615edfcedbcae77fd68dce3d3cf65de52082b0c2d6298050",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Cuely declared that the elixir had taken hold faster than he expected and turned eagerly to the remaining samples for Sylvanas and the Forsaken. His satisfaction closed the experiment’s surviving account, without giving the same certainty about Thersa’s recovery."}},["grouping"]="The water sampling and experimental elixir; the surviving source ending does not establish Thersa’s ultimate fate or a successful cure.",["quests"]={3568,3569,3570},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Remedy Without a Promise"},["undercity-deathstalker-ledger"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=1885,["sourceHash"]="b1310ed62de83dcf2b4832907ed0d03acfadc351d38ce762c86dacede0a24e23"},{["minimumStage"]=4,["questID"]=1886,["sourceHash"]="efdc225b5c9229a83ecb971c81c1304b8a1bfebb145ab331393b1da940443ca1"},{["minimumStage"]=4,["questID"]=1898,["sourceHash"]="22b44c291ea8bc142d06609c1b9d16873f1e7988a4379bbd3d0b318b0a79ea36"},{["minimumStage"]=4,["questID"]=1899,["sourceHash"]="e7dd42bc6abc4b84584f371db764862ada56bd791dc75edaf9b72793fc937711"},{["minimumStage"]=4,["questID"]=1978,["sourceHash"]="0dab743c523e4a82a5e20a9ff3b3e4916f41c38936b512600894f412ddf1513d"}}},["interpretation"]="Every required route step needs its own recorded hand-in and exact source hash. Optional or alternative branches retain their separate rules.",["scope"]="DEFINED_OBSERVED_ROUTE_NOT_WORLD_VICTORY"},["episodes"]={{["episodeID"]="undercity-deathstalker-ledger-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=1885}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"1885:description:5-92","1885:description:94-130","1885:description:135-188","1885:description:190-278","1885:objective:1-65"},["questID"]=1885,["sourceHash"]="b1310ed62de83dcf2b4832907ed0d03acfadc351d38ce762c86dacede0a24e23",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Marion warned that Mennet Carkad's summons should not be ignored. The meeting in the Rogues' Quarter offered an introduction to Deathstalker service."},{["episodeID"]="undercity-deathstalker-ledger-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=1886}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1886:description:1-104","1886:description:109-167","1886:description:172-213","1886:description:215-323","1886:description:325-382","1886:description:387-460","1886:description:462-495","1886:objective:1-89"},["questID"]=1886,["sourceHash"]="efdc225b5c9229a83ecb971c81c1304b8a1bfebb145ab331393b1da940443ca1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Carkad wanted the personal effects of a traveling messenger named Astor. He withheld his reasons, leaving the recruit to obtain the letter without an explanation of the larger plan."},{["episodeID"]="undercity-deathstalker-ledger-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=1898}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1898:description:1-112","1898:description:114-201","1898:description:206-286","1898:description:288-356","1898:description:361-421","1898:description:423-472","1898:objective:1-40"},["questID"]=1898,["sourceHash"]="22b44c291ea8bc142d06609c1b9d16873f1e7988a4379bbd3d0b318b0a79ea36",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Astor's introduction could make its bearer appear to be the messenger Andron expected. Varimathras suspected the shopkeeper was aiding another organization and wanted evidence."},{["episodeID"]="undercity-deathstalker-ledger-4",["requiresAll"]={{["minimumStage"]=2,["questID"]=1899}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"1899:description:1-91","1899:description:93-251","1899:objective:1-75"},["questID"]=1899,["sourceHash"]="e7dd42bc6abc4b84584f371db764862ada56bd791dc75edaf9b72793fc937711",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Andron pointed his presumed messenger toward the ledger. Carrying it back to Carkad would preserve the disguise while returning the information sought."},{["episodeID"]="undercity-deathstalker-ledger-5",["requiresAll"]={{["minimumStage"]=4,["questID"]=1978}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"1978:description:1-14","1978:description:16-44","1978:description:46-125","1978:description:130-292","1978:description:297-323","1978:description:328-356","1978:objective:1-85","1978:completion:1-25","1978:completion:27-104","1978:completion:109-183","1978:completion:185-281"},["questID"]=1978,["sourceHash"]="0dab743c523e4a82a5e20a9ff3b3e4916f41c38936b512600894f412ddf1513d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Andron's ledger was delivered to Varimathras. The evidence had exposed Syndicate dealings and accompanied admission to the Deathstalkers, ending the inquiry with a new place in their service."}},["grouping"]="Source-reviewed continuing narrative; branch and source-stage gates retained.",["quests"]={1885,1886,1898,1899,1978},["referenceStatus"]="RETAINED_QUEST_SOURCE_STAGES_NOT_CURRENT_PLAYABILITY_VERIFICATION",["sourceConflict"]=false,["title"]="The Borrowed Introduction"},["undercity-fragrance-conspiracy"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=8904,["sourceHash"]="e4a242b8f3c6420138cc80cb19f0debb22f4dd457bc99834951ab33b22ce9592"},{["minimumStage"]=4,["questID"]=8979,["sourceHash"]="01b778a213a719758e7ffd2bc25d3b073e96f99f24526cc37d3622169228c4aa"},{["minimumStage"]=4,["questID"]=8980,["sourceHash"]="b6f2b664a2018f9d6246b0b6e5e0ac4998eef6620e46f5d9de28a7b4572e3212"},{["minimumStage"]=4,["questID"]=8982,["sourceHash"]="e036f81b673bc6d23e5e6dfd5b32fc52c5894b2e671fa43720c3c9e02424c7f8"},{["minimumStage"]=4,["questID"]=8983,["sourceHash"]="5b6d00dbad1e055cf282290bb4baa785c2c8ae73f19767da20302e055d3cdbce"},{["minimumStage"]=4,["questID"]=8984,["sourceHash"]="43bd0a3712e1cbf3d57eb4e86a2963b8aa4d03bdd8437baaedb77190b570ed91"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="undercity-fragrance-conspiracy-8904",["requiresAll"]={{["minimumStage"]=2,["questID"]=8904}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"8904:description:1-56","8904:description:58-143","8904:description:148-232","8904:description:234-323","8904:description:328-407","8904:objective:1-76"},["questID"]=8904,["sourceHash"]="e4a242b8f3c6420138cc80cb19f0debb22f4dd457bc99834951ab33b22ce9592",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Fenstad believed even the guardians had succumbed to the city's strange infatuation. Evidence of their involvement made the supposed immunity of the dead a dangerous assumption."},{["episodeID"]="undercity-fragrance-conspiracy-8979",["requiresAll"]={{["minimumStage"]=2,["questID"]=8979}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"8979:description:1-51","8979:description:53-129","8979:description:131-188","8979:description:193-243","8979:description:248-351","8979:description:353-401","8979:description:406-462","8979:objective:1-96"},["questID"]=8979,["sourceHash"]="01b778a213a719758e7ffd2bc25d3b073e96f99f24526cc37d3622169228c4aa",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A fashionable scent above the canals suggested alchemy to Fenstad. He sent perfume and cologne to Zinge, whose skepticism would not prevent an examination."},{["episodeID"]="undercity-fragrance-conspiracy-8980",["requiresAll"]={{["minimumStage"]=2,["questID"]=8980}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"8980:description:1-19","8980:description:21-77","8980:description:79-136","8980:description:141-237","8980:description:239-327","8980:objective:1-59"},["questID"]=8980,["sourceHash"]="b6f2b664a2018f9d6246b0b6e5e0ac4998eef6620e46f5d9de28a7b4572e3212",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The mixture contained signs of sophisticated mind-control work. Zinge's findings turned a dismissed obsession into a search for whoever had introduced the fragrances."},{["episodeID"]="undercity-fragrance-conspiracy-8982",["requiresAll"]={{["minimumStage"]=2,["questID"]=8982}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"8982:description:1-33","8982:description:35-111","8982:description:113-173","8982:objective:1-45"},["questID"]=8982,["sourceHash"]="e036f81b673bc6d23e5e6dfd5b32fc52c5894b2e671fa43720c3c9e02424c7f8",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Katrina's purchase led to Norman's inn. The stock was selling faster than he could keep it, making its supplier a more urgent lead than the shop itself."},{["episodeID"]="undercity-fragrance-conspiracy-8983",["requiresAll"]={{["minimumStage"]=2,["questID"]=8983}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"8983:description:1-34","8983:description:36-99","8983:description:104-157","8983:description:159-176","8983:description:181-266","8983:objective:1-77"},["questID"]=8983,["sourceHash"]="5b6d00dbad1e055cf282290bb4baa785c2c8ae73f19767da20302e055d3cdbce",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Norman named Mara Rennick, a newcomer delivering to the tailor. Her completed sale traced the bottles another step back through the city's trade."},{["episodeID"]="undercity-fragrance-conspiracy-8984",["requiresAll"]={{["minimumStage"]=4,["questID"]=8984}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"8984:description:1-59","8984:description:61-153","8984:description:158-212","8984:description:217-270","8984:description:272-353","8984:description:355-407","8984:objective:1-81","8984:completion:1-29","8984:completion:31-56","8984:completion:58-70","8984:completion:75-223","8984:completion:228-261","8984:completion:263-324","8984:completion:329-355","8984:completion:357-399","8984:completion:401-441","8984:completion:443-497"},["questID"]=8984,["sourceHash"]="43bd0a3712e1cbf3d57eb4e86a2963b8aa4d03bdd8437baaedb77190b570ed91",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The trail ended with Staffron beyond Ravenholdt. He admitted using the fragrances to weaken both factions through affection, expecting the Shadow Council to advance while their warriors worried for loved ones."}},["grouping"]="The Undercity supplier investigation, retaining Zinge's assessment and Staffron's confession at their proper stages.",["quests"]={8904,8979,8980,8982,8983,8984},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Scent Above the Canals"},["undercity-zinge-tanaris-samples"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=232,["sourceHash"]="0f57d383fbfceeb513bb25a14afce89abc8b5c0aacc25c82e4f56fe7b163689d"},{["minimumStage"]=4,["questID"]=238,["sourceHash"]="b5a14d67c6affdc07972fdec5a5daf62bcd27b6fe5b7f6091060253c7233ee42"},{["minimumStage"]=4,["questID"]=243,["sourceHash"]="665c22c5de1cf6a44d1bf7b89d27591a764437bd6fcac09836dda988ba95e676"},{["minimumStage"]=4,["questID"]=379,["sourceHash"]="bc07f39b8cd482dd405c5cebe383559386f059a51100d2493f2cfdb0d71522e4"},{["minimumStage"]=4,["questID"]=654,["sourceHash"]="12c139f0345f69add7419ef75269c52276152f2e0b288f5fa501fc71822d8ce4"},{["minimumStage"]=4,["questID"]=864,["sourceHash"]="f7ff7b5f8e8e43437b12f9e4dfb9286e22dc054ea6841dcab2d5c831605ea18a"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="undercity-zinge-tanaris-samples-232",["requiresAll"]={{["minimumStage"]=2,["questID"]=232}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"232:description:1-51","232:description:54-108","232:description:113-156","232:description:158-167","232:description:169-255","232:description:258-293","232:description:296-426","232:description:429-503","232:objective:1-60"},["questID"]=232,["sourceHash"]="0f57d383fbfceeb513bb25a14afce89abc8b5c0aacc25c82e4f56fe7b163689d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Zinge saw promise in the work of Apothecary Keever, provided a sharper researcher took it in hand. A purchase order for Alessandro Luca’s shop was the first step toward testing whether his ideas could serve her own ambitions."},{["episodeID"]="undercity-zinge-tanaris-samples-238",["requiresAll"]={{["minimumStage"]=2,["questID"]=238}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"238:description:1-21","238:description:24-89","238:description:92-195","238:description:198-247","238:description:252-280","238:description:283-324","238:objective:1-66"},["questID"]=238,["sourceHash"]="b5a14d67c6affdc07972fdec5a5daf62bcd27b6fe5b7f6091060253c7233ee42",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Alessandro charged the kit to the Society’s account and sent warm greetings with it. Zinge had little patience for the pleasantries; her adjustments would send the equipment, and its bearer, far from the Undercity."},{["episodeID"]="undercity-zinge-tanaris-samples-243",["requiresAll"]={{["minimumStage"]=2,["questID"]=243}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"243:description:1-124","243:description:127-228","243:description:231-284","243:description:289-395","243:description:398-462","243:description:467-508","243:objective:1-99"},["questID"]=243,["sourceHash"]="665c22c5de1cf6a44d1bf7b89d27591a764437bd6fcac09836dda988ba95e676",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Tanaris’s basilisks, scorpids and hyenas were to supply tissue samples, though many would fail the test. The altered apparatus also needed a Gadgetzan power source, putting the experiment at the mercy of another specialist’s terms."},{["episodeID"]="undercity-zinge-tanaris-samples-379",["requiresAll"]={{["minimumStage"]=2,["questID"]=379}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"379:description:1-24","379:description:27-51","379:description:54-70","379:description:73-98","379:description:101-172","379:description:177-182","379:description:184-234","379:description:237-332","379:description:335-373","379:objective:1-78"},["questID"]=379,["sourceHash"]="bc07f39b8cd482dd405c5cebe383559386f059a51100d2493f2cfdb0d71522e4",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Bilgewhizzle wanted water from the Wastewander nomads in exchange for the power supply. The engineer’s price turned the desert’s disputed wells into part of Zinge’s research."},{["episodeID"]="undercity-zinge-tanaris-samples-654",["requiresAll"]={{["minimumStage"]=2,["questID"]=654}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"654:description:1-82","654:description:85-123","654:description:128-243","654:description:246-369","654:description:374-420","654:objective:1-70","654:objective:73-176"},["questID"]=654,["sourceHash"]="12c139f0345f69add7419ef75269c52276152f2e0b288f5fa501fc71822d8ce4",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Once powered, the kit glowed and trembled. The work now had a limit: two hours to gather acceptable samples and bring the machine back before its unstable power ruined the findings."},{["episodeID"]="undercity-zinge-tanaris-samples-864",["requiresAll"]={{["minimumStage"]=4,["questID"]=864}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"864:description:1-75","864:description:78-110","864:description:113-178","864:description:183-269","864:description:272-343","864:description:346-415","864:objective:1-72","864:completion:1-37","864:completion:39-101","864:completion:106-118","864:completion:120-189","864:completion:191-264","864:completion:269-374"},["questID"]=864,["sourceHash"]="f7ff7b5f8e8e43437b12f9e4dfb9286e22dc054ea6841dcab2d5c831605ea18a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="With the power safely removed, the sealed kit carried its preserved results back to Zinge. She rewarded a useful assistant and began her analysis, hoping Keever’s strange work would become her own success. What the findings would finally yield remained ahead."}},["grouping"]="The main testing-kit route, ending with preserved data returned to Zinge; replacement power sources are optional, and no successful new plague is inferred.",["quests"]={232,238,243,379,654,864},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Kit for the Desert"},["ungoro-torwa-pacification"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=9063,["sourceHash"]="030fb3696fad9851add9d81ab2cf2ba47845950c91671a3bcbc8a91069e2c770"},{["minimumStage"]=4,["questID"]=9052,["sourceHash"]="151973476dd4f0fcb4cc65c2637d4cd04e5bc7e66cbd25c8a4e4c4ddaa7c3c10"},{["minimumStage"]=4,["questID"]=9051,["sourceHash"]="b3cad26ebc7ad650b5c77a8960849516dbeba338ba41cab8f62d4ee3f512937a"},{["minimumStage"]=4,["questID"]=9053,["sourceHash"]="a9ee3079523291f0ef226542cb793ed39d9c86f0df0705657005e476bff892eb"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="ungoro-torwa-pacification-9063",["requiresAll"]={{["minimumStage"]=2,["questID"]=9063}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"9063:description:1-75","9063:description:78-163","9063:description:168-242","9063:description:245-305","9063:objective:1-46"},["questID"]=9063,["sourceHash"]="030fb3696fad9851add9d81ab2cf2ba47845950c91671a3bcbc8a91069e2c770",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Torwa asked for a druid's skills and respect for nature. His summons led to Un'Goro's entrance, where a hunter's problem awaited an answer other than another dead beast."},{["episodeID"]="ungoro-torwa-pacification-9052",["requiresAll"]={{["minimumStage"]=2,["questID"]=9052}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"9052:description:1-105","9052:description:108-192","9052:description:197-292","9052:description:295-412","9052:objective:1-90"},["questID"]=9052,["sourceHash"]="151973476dd4f0fcb4cc65c2637d4cd04e5bc7e66cbd25c8a4e4c4ddaa7c3c10",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Bloodcaps and Gorishi stings would make a toxin intended to pacify rather than kill. Gathering from the crater's plants and insects gave the first experiment its materials."},{["episodeID"]="ungoro-torwa-pacification-9051",["requiresAll"]={{["minimumStage"]=2,["questID"]=9051}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"9051:description:1-56","9051:description:59-151","9051:description:154-266","9051:description:271-335","9051:description:338-410","9051:objective:1-41","9051:objective:43-121"},["questID"]=9051,["sourceHash"]="b3cad26ebc7ad650b5c77a8960849516dbeba338ba41cab8f62d4ee3f512937a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The barb had to be tested on a living devilsaur. Torwa's purpose was practical: killing one territorial giant merely made room for the next, leaving the same danger for those trying to survive."},{["episodeID"]="ungoro-torwa-pacification-9053",["requiresAll"]={{["minimumStage"]=4,["questID"]=9053}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"9053:description:1-79","9053:description:84-278","9053:description:281-347","9053:description:352-382","9053:objective:1-107","9053:completion:1-42","9053:completion:44-138","9053:completion:143-173","9053:completion:175-210"},["questID"]=9053,["sourceHash"]="a9ee3079523291f0ef226542cb793ed39d9c86f0df0705657005e476bff892eb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The first preparation was too weak. A guardian's vine from the Sunken Temple allowed a stronger mixture, but Torwa would not demand another hazardous test after so much help. The experiment ended with a completed toxin, not proof that every devilsaur could now be safely calmed."}},["grouping"]="One nonlethal toxin investigation; a second successful field test is not invented.",["quests"]={9063,9052,9051,9053},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="A Hunter’s Answer Without the Kill"},["warlock-menara-gold-bloodrobe"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=4781,["sourceHash"]="10310f5356b1d8fe50acd88cbf1615b9f840a02b287276f43c36f96a6938d9ef"},{["minimumStage"]=4,["questID"]=4782,["sourceHash"]="04eb297fa7e28353732fc4d59abbf368cdf00cb9620115fbbed93c176650626d"},{["minimumStage"]=4,["questID"]=4783,["sourceHash"]="e731cd075f46cdb4c7743118fdbe0c986a0bf4f28ebc2954183f38b40bfb53fa"},{["minimumStage"]=4,["questID"]=4784,["sourceHash"]="3a4c40cdc8ebe108b5e4ae0cc97003bbea218d538a4f468cf1327269da825570"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="warlock-menara-gold-bloodrobe-4781",["requiresAll"]={{["minimumStage"]=2,["questID"]=4781}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"4781:description:1-80","4781:description:85-212","4781:description:214-323","4781:description:328-376","4781:description:378-444","4781:description:446-485","4781:description:487-507","4781:objective:1-58"},["questID"]=4781,["sourceHash"]="10310f5356b1d8fe50acd88cbf1615b9f840a02b287276f43c36f96a6938d9ef",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Menara's robe called for gold embroidery that few tailors could make. Xizk in Booty Bay could spin it, provided a gold bar first passed from the miners' craft into his hands."},{["episodeID"]="warlock-menara-gold-bloodrobe-4782",["requiresAll"]={{["minimumStage"]=2,["questID"]=4782}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"4782:description:1-94","4782:description:96-103","4782:description:105-209","4782:description:211-245","4782:description:250-263","4782:description:265-319","4782:description:321-336","4782:description:338-383","4782:description:385-390","4782:objective:1-43"},["questID"]=4782,["sourceHash"]="04eb297fa7e28353732fc4d59abbf368cdf00cb9620115fbbed93c176650626d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Xizk needed time for the thread. His message sent the work back to Menara so that the remaining components could be gathered while the tailor prepared his part."},{["episodeID"]="warlock-menara-gold-bloodrobe-4783",["requiresAll"]={{["minimumStage"]=2,["questID"]=4783}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"4783:description:1-108","4783:description:113-158","4783:description:160-277","4783:description:282-344","4783:description:346-423","4783:description:428-477","4783:objective:1-97"},["questID"]=4783,["sourceHash"]="e731cd075f46cdb4c7743118fdbe0c986a0bf4f28ebc2954183f38b40bfb53fa",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The robe's next materials lay among Desolace's demons: blood from the Hatefury satyrs and a lesser infernal stone from Mannoroc Coven. The craft now demanded a journey through the powers it would draw upon."},{["episodeID"]="warlock-menara-gold-bloodrobe-4784",["requiresAll"]={{["minimumStage"]=4,["questID"]=4784}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"4784:description:1-63","4784:description:68-118","4784:description:120-157","4784:description:162-248","4784:description:250-315","4784:description:320-356","4784:description:361-457","4784:objective:1-102","4784:completion:1-14","4784:completion:16-60","4784:completion:65-92"},["questID"]=4784,["sourceHash"]="3a4c40cdc8ebe108b5e4ae0cc97003bbea218d538a4f468cf1327269da825570",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The gold thread, smoldering coals and a soul shard completed the gathered materials. Menara pronounced everything ready for the robe, closing the search for components without turning it into any greater triumph over the Legion."}},["grouping"]="The connected material-gathering route; the separately offered thread handover is not invented as a prerequisite.",["quests"]={4781,4782,4783,4784},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Gold Thread and Borrowed Fire"},["western-janice"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=5021,["sourceHash"]="44071932fd6301bd4392a7cc99e263d0bb4bc97d45ef55da9bdd99f5d0869bd8"},{["minimumStage"]=4,["questID"]=5050,["sourceHash"]="ceaec94f121a785127d33715b2e275dd27bae0c6d6aa8a2cba93af3b1e30e461"},{["minimumStage"]=4,["questID"]=5051,["sourceHash"]="b5c2431eab2b169d5e142350aa0c669c5a9f066d9a99e4a1469f31566b793152"},{["anyOf"]={{["allOf"]={{["minimumStage"]=4,["questID"]=5022,["sourceHash"]="160ee784c0ee4a8bb81bdaefc38d3adae44c4bb36f6bb44cd8679246fa5cfe10"},{["minimumStage"]=4,["questID"]=5048,["sourceHash"]="c899534d31d377f5d766f48d8e7c2b7ec2530b52f4eff90c99c8df66428b832b"}}},{["allOf"]={{["minimumStage"]=4,["questID"]=5023,["sourceHash"]="58023c251fc39e12098b2946fd7415a2cc9af8439533b82e7d71502de1e9b7c3"},{["minimumStage"]=4,["questID"]=5049,["sourceHash"]="e501298f0e73ea610189c723ab137a752fc2d5a701bc901609cc0adda6070326"}}}}}}},["interpretation"]="Stormwind5022→5048 and Undercity5023→5049 are parallel source routes with different race masks and recipients, converging at5050. A single complete route is sufficient; neither branch implies the other.",["scope"]="OBSERVED_SOURCE_ROUTE_AND_DEFINED_OUTCOME"},["episodes"]={{["episodeID"]="western-janice-1",["requiresAll"]={{["minimumStage"]=2,["questID"]=5021}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"5021:description:1-33","5021:description:35-69","5021:description:74-157","5021:description:160-219","5021:description:222-319","5021:description:324-359","5021:description:362-395","5021:description:398-429","5021:description:432-464","5021:description:466-483","5021:objective:1-81","5021:objective:84-127","5021:objective:130-232"},["questID"]=5021,["sourceHash"]="44071932fd6301bd4392a7cc99e263d0bb4bc97d45ef55da9bdd99f5d0869bd8",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Janice's repeated demand preserved the urgency of a delivery long delayed. The package's destination was lost in her confused account, leaving the barn as the first place to search."},{["episodeID"]="western-janice-2",["requiresAll"]={{["minimumStage"]=2,["questID"]=5022}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"5022:description:1-91","5022:description:94-227","5022:description:232-373","5022:description:376-441","5022:objective:1-87","5022:objective:90-144"},["questID"]=5022,["sourceHash"]="160ee784c0ee4a8bb81bdaefc38d3adae44c4bb36f6bb44cd8679246fa5cfe10",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The Stormwind address belonged to one possible delivery route. Its old date required census work rather than an assumption that the named recipient remained alive and at home."},{["episodeID"]="western-janice-recipient-5048",["requiresAll"]={{["minimumStage"]=4,["questID"]=5048}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"5048:description:1-58","5048:description:60-151","5048:description:156-264","5048:description:267-344","5048:description:349-422","5048:description:425-481","5048:objective:1-67","5048:objective:70-145","5048:completion:1-83","5048:completion:85-90","5048:completion:92-103","5048:completion:108-126","5048:completion:128-138","5048:completion:140-158","5048:completion:160-197","5048:completion:199-269","5048:completion:271-298","5048:completion:300-308","5048:completion:310-350","5048:completion:352-393","5048:completion:395-423","5048:completion:428-434","5048:completion:436-476"},["followingIDs"]={5050},["previousIDs"]={5022},["questID"]=5048,["sourceHash"]="c899534d31d377f5d766f48d8e7c2b7ec2530b52f4eff90c99c8df66428b832b",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The old name reached Emma at last. Alone in Stormwind after the plague took so much of her family, she scarcely believed someone had spoken to her sister. The mention of Janice’s parcel interrupted her suspicion with a remnant of the life she had lost."},{["episodeID"]="western-janice-3",["requiresAll"]={{["minimumStage"]=2,["questID"]=5023}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"5023:description:1-91","5023:description:94-230","5023:description:235-401","5023:description:404-471","5023:objective:1-96","5023:objective:99-175"},["questID"]=5023,["sourceHash"]="58023c251fc39e12098b2946fd7415a2cc9af8439533b82e7d71502de1e9b7c3",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The Lordaeron address formed an alternative route. Undercity records could follow a name changed after the plague without turning that branch into the Stormwind delivery."},{["episodeID"]="western-janice-recipient-5049",["requiresAll"]={{["minimumStage"]=4,["questID"]=5049}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"5049:description:1-155","5049:description:160-230","5049:description:232-243","5049:description:246-303","5049:description:306-354","5049:description:357-498","5049:objective:1-81","5049:objective:84-157","5049:completion:1-36","5049:completion:38-124","5049:completion:129-164","5049:completion:166-210","5049:completion:215-230","5049:completion:235-249","5049:completion:254-361","5049:completion:363-399","5049:completion:404-411","5049:completion:413-453"},["followingIDs"]={5050},["previousIDs"]={5023},["questID"]=5049,["sourceHash"]="e501298f0e73ea610189c723ab137a752fc2d5a701bc901609cc0adda6070326",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Jeremiah had set the Felstone name aside after death. He could not believe the tale of a conversation with his long-dead sister, but the parcel made the stranger’s claim something more than a cruel story."},{["episodeID"]="western-janice-4",["requiresAll"]={{["minimumStage"]=4,["questID"]=5050},{["minimumStage"]=4,["questID"]=5051}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"5050:description:1-79","5050:description:82-187","5050:description:190-234","5050:description:239-315","5050:description:317-345","5050:description:348-427","5050:description:432-499","5050:objective:1-74","5050:completion:1-47","5050:completion:49-89","5050:completion:94-142","5050:completion:144-191","5050:completion:193-200","5050:completion:202-217"},["questID"]=5050,["sourceHash"]="ceaec94f121a785127d33715b2e275dd27bae0c6d6aa8a2cba93af3b1e30e461",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},{["atomIDs"]={"5051:description:1-41","5051:description:46-64","5051:description:67-109","5051:description:112-182","5051:description:185-207","5051:description:209-231","5051:description:234-253","5051:description:258-392","5051:objective:1-117","5051:objective:122-207","5051:completion:1-68","5051:completion:70-141","5051:completion:143-217","5051:completion:222-240","5051:completion:242-274","5051:completion:276-348"},["questID"]=5051,["sourceHash"]="b5c2431eab2b169d5e142350aa0c669c5a9f066d9a99e4a1469f31566b793152",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A returned half-charm was not enough for Janice. Once the matching piece was found and the charm made whole, her gaze cleared and she declared herself free."}},["grouping"]="Authored connected episodes with explicit source-stage gates; branches retained",["quests"]={5021,5022,5048,5023,5049,5050,5051},["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["sourceConflict"]=false,["title"]="The Delivery and the Broken Charm"},["westfall-grimbooze-amber"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=48,["sourceHash"]="fa5f5723cfc5e78b971a059f04c5b41b8bb3b372aca55e8c4663bdaa1dba427a"},{["minimumStage"]=4,["questID"]=49,["sourceHash"]="8b7aaa0789b7791d89bfad051d03e64567c74749bd2f5fc10c92191cc0a3dc98"},{["minimumStage"]=4,["questID"]=50,["sourceHash"]="85a79b3117f89ebb1f890df1965e05f75442216eb2908d59246f1a719d1c1b9d"},{["minimumStage"]=4,["questID"]=51,["sourceHash"]="a9caffecbac956f91ea9453617f6b52b2a24bc94ad208f4bed2d1c8a85289c15"},{["minimumStage"]=4,["questID"]=53,["sourceHash"]="21cf139ca077276c064574ec5d3be47b2bd0110cb409ca825cbbe3d80ed9e6de"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="westfall-grimbooze-amber-48",["requiresAll"]={{["minimumStage"]=2,["questID"]=48}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"48:description:1-52","48:description:55-98","48:description:101-135","48:description:138-176","48:objective:1-49"},["questID"]=48,["sourceHash"]="fa5f5723cfc5e78b971a059f04c5b41b8bb3b372aca55e8c4663bdaa1dba427a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Grimbooze began with a brewer's riddle: somewhere to the south, among tangled vines, a hidden well held the pure spring water for his long-imagined amber drink."},{["episodeID"]="westfall-grimbooze-amber-49",["requiresAll"]={{["minimumStage"]=2,["questID"]=49}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"49:description:1-42","49:description:45-89","49:description:92-136","49:description:139-177","49:objective:1-79"},["questID"]=49,["sourceHash"]="8b7aaa0789b7791d89bfad051d03e64567c74749bd2f5fc10c92191cc0a3dc98",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The water gave the recipe its beginning, but grain would give it substance. Barley, rye and corn were to arrive in separate sacks before Grimbooze could prepare his mash."},{["episodeID"]="westfall-grimbooze-amber-50",["requiresAll"]={{["minimumStage"]=2,["questID"]=50}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"50:description:1-36","50:description:39-76","50:description:79-119","50:description:122-172","50:objective:1-39"},["questID"]=50,["sourceHash"]="85a79b3117f89ebb1f890df1965e05f75442216eb2908d59246f1a719d1c1b9d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The work then moved from fields to metal. A still strong enough for the brew required truesilver, joining a miner's material to the brewer's song."},{["episodeID"]="westfall-grimbooze-amber-51",["requiresAll"]={{["minimumStage"]=2,["questID"]=51}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"51:description:1-38","51:description:41-80","51:description:83-122","51:description:125-174","51:objective:1-49"},["questID"]=51,["sourceHash"]="a9caffecbac956f91ea9453617f6b52b2a24bc94ad208f4bed2d1c8a85289c15",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Distillation left the spirit clear and unfiltered. A sycamore branch would supply the charcoal for the next part of the recipe; the work had not ended at the still."},{["episodeID"]="westfall-grimbooze-amber-53",["requiresAll"]={{["minimumStage"]=4,["questID"]=53}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"53:description:1-42","53:description:45-84","53:description:87-130","53:description:133-170","53:objective:1-52","53:completion:1-41","53:completion:44-91","53:completion:94-129","53:completion:132-179"},["questID"]=53,["sourceHash"]="21cf139ca077276c064574ec5d3be47b2bd0110cb409ca825cbbe3d80ed9e6de",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The charred oak for the cask completed the gathering. Grimbooze answered with a toast to brewer and helper alike. His song spoke of amber deepening over years, a promise beyond the small celebration at hand."}},["grouping"]="One drink’s ingredients, still, filter and cask; the toast does not prove years of aging elapsed.",["quests"]={48,49,50,51,53},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Brewer’s Long Recipe"},["westfall-lewis-armor-route"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=6181,["sourceHash"]="cff7cd07705023766536a44d02da731761c26b2bb05f81ceba5944c0c9eb5de7"},{["minimumStage"]=4,["questID"]=6281,["sourceHash"]="f9151542677103150dbb16e0ca42c77ea1f99453051a9a716ab3969a3d5111b8"},{["minimumStage"]=4,["questID"]=6261,["sourceHash"]="360d0f18beb5d639d1d786f7ba7e57875b97fef8d14947aaa154f39e119f74d9"},{["minimumStage"]=4,["questID"]=6285,["sourceHash"]="a6747a40321f3aae93d2c38d7ff5a656ce1a891253ad150818afbfd0a46f5c9d"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="westfall-lewis-armor-route-6181",["requiresAll"]={{["minimumStage"]=2,["questID"]=6181}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"6181:description:1-119","6181:description:122-146","6181:description:149-208","6181:description:213-276","6181:description:279-305","6181:description:310-374","6181:description:377-457","6181:objective:1-45"},["questID"]=6181,["sourceHash"]="cff7cd07705023766536a44d02da731761c26b2bb05f81ceba5944c0c9eb5de7",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Lewis's shrinking armor stores exposed how little direct help reached Sentinel Hill. His contact Osric in Stormwind could supply replacements, and Thor's gryphons offered the fastest way to carry the request."},{["episodeID"]="westfall-lewis-armor-route-6281",["requiresAll"]={{["minimumStage"]=2,["questID"]=6281}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"6281:description:1-94","6281:description:97-137","6281:description:142-227","6281:description:230-287","6281:objective:1-148"},["questID"]=6281,["sourceHash"]="f9151542677103150dbb16e0ca42c77ea1f99453051a9a716ab3969a3d5111b8",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Thor could arrange the flight for a fee. Osric's shop in Old Town was the destination, keeping the journey's purpose tied to the equipment Westfall's defenders lacked."},{["episodeID"]="westfall-lewis-armor-route-6261",["requiresAll"]={{["minimumStage"]=2,["questID"]=6261}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"6261:description:1-58","6261:description:61-83","6261:description:88-173","6261:description:176-242","6261:description:247-313","6261:description:316-398","6261:objective:1-59"},["questID"]=6261,["sourceHash"]="360d0f18beb5d639d1d786f7ba7e57875b97fef8d14947aaa154f39e119f74d9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Osric gathered the order into a crate and sent it toward Dungar in the Trade District. The requisition had become an armor shipment ready for the return to Thor and Sentinel Hill."},{["episodeID"]="westfall-lewis-armor-route-6285",["requiresAll"]={{["minimumStage"]=4,["questID"]=6285}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"6285:description:1-39","6285:description:42-117","6285:description:122-294","6285:description:299-403","6285:description:406-470","6285:objective:1-128","6285:completion:1-29","6285:completion:31-86","6285:completion:91-104","6285:completion:106-147","6285:completion:149-253"},["questID"]=6285,["sourceHash"]="a6747a40321f3aae93d2c38d7ff5a656ce1a891253ad150818afbfd0a46f5c9d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Lewis received the crate and intended to divide its armor among the people who needed it at once. The gryphon road had carried a concrete answer to the shortage, even while Westfall's larger troubles endured."}},["grouping"]="One supply requisition between Sentinel Hill and Old Town, using the gryphon network; no general victory in Westfall is implied.",["quests"]={6181,6281,6261,6285},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Armor Over the Gryphon Road"},["westfall-militia-fields-and-hills"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=12,["sourceHash"]="ca931237fbf24d9fb1703086d37ba10225b4b81652c6587e2a0b33480b1a8ead"},{["minimumStage"]=4,["questID"]=13,["sourceHash"]="1fef918ba4b0dad5a4de6c2995e82cb31bf8ba8619304923676793fa9bd43794"},{["minimumStage"]=4,["questID"]=14,["sourceHash"]="5c5fc160b5383908e2751ba58769806ce196a8506de7746c0b7e8518c2024d40"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="westfall-militia-fields-and-hills-12",["requiresAll"]={{["minimumStage"]=2,["questID"]=12}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"12:description:1-109","12:description:112-160","12:description:166-250","12:description:253-394","12:description:396-492","12:objective:1-115"},["questID"]=12,["sourceHash"]="ca931237fbf24d9fb1703086d37ba10225b4b81652c6587e2a0b33480b1a8ead",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Stoutmantle’s militia existed to defend farms the kingdom no longer kept safe. Reports from Jangolode and the neighboring fields made Defias trappers and smugglers the first concern around Sentinel Hill."},{["episodeID"]="westfall-militia-fields-and-hills-13",["requiresAll"]={{["minimumStage"]=2,["questID"]=13}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"13:description:1-120","13:description:123-176","13:description:179-252","13:description:257-322","13:description:325-434","13:objective:1-113"},["questID"]=13,["sourceHash"]="1fef918ba4b0dad5a4de6c2995e82cb31bf8ba8619304923676793fa9bd43794",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The pressure extended west to Gold Coast Quarry and through Moonbrook and the Alexston fields. Pillagers and looters threatened the same countryside the militia hoped to restore, widening the work beyond its first patrols."},{["episodeID"]="westfall-militia-fields-and-hills-14",["requiresAll"]={{["minimumStage"]=4,["questID"]=14}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"14:description:1-27","14:description:30-161","14:description:164-240","14:description:244-297","14:objective:1-144","14:completion:1-101","14:completion:103-137","14:completion:139-229","14:completion:231-298","14:completion:300-328"},["questID"]=14,["sourceHash"]="5c5fc160b5383908e2751ba58769806ce196a8506de7746c0b7e8518c2024d40",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The remaining trail led south into the Dagger Hills. After that fighting, Stoutmantle recalled the grim homeland he had found on returning from Lordaeron and welcomed another defender into the militia. Westfall had gained help and hope, while the Brotherhood’s larger danger remained."}},["grouping"]="Three militia assignments follow the Defias threat through Westfall; induction is not the Brotherhood’s defeat.",["quests"]={12,13,14},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Farms Behind Sentinel Hill"},["westfall-sanders-coastal-clues"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=136,["sourceHash"]="5eae480345d75a56650d8495778519e389ba25af3b7f98900d0e1c8dedaa522a"},{["minimumStage"]=4,["questID"]=138,["sourceHash"]="f8aa94767b507acad0670fc349a7c17ec2bb9faaa8e4d145721fbccb6ceaa17a"},{["minimumStage"]=4,["questID"]=139,["sourceHash"]="6c407bb087cf07035c1b602473313e0d9d15e2b4e69e49afa921121d9b92fe63"},{["minimumStage"]=4,["questID"]=140,["sourceHash"]="a79f38e684818e81b03206f520000688b41213603cfb37b4cedcaf70173393a2"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="westfall-sanders-coastal-clues-136",["requiresAll"]={{["minimumStage"]=2,["questID"]=136}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"136:description:1-78","136:description:81-142","136:description:148-183","136:description:186-282","136:description:285-351","136:description:354-396","136:description:399-430","136:objective:1-65"},["questID"]=136,["sourceHash"]="5eae480345d75a56650d8495778519e389ba25af3b7f98900d0e1c8dedaa522a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A drowned captain’s message offered his hidden treasure to whoever could follow the clues. Sanders’s first direction led to a rusty anchor and a half-buried footlocker on Westfall’s coast."},{["episodeID"]="westfall-sanders-coastal-clues-138",["requiresAll"]={{["minimumStage"]=2,["questID"]=138}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"138:description:1-49","138:description:52-80","138:description:83-119","138:description:122-178","138:description:181-232","138:objective:1-77"},["questID"]=138,["sourceHash"]="f8aa94767b507acad0670fc349a7c17ec2bb9faaa8e4d145721fbccb6ceaa17a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The locker’s clue turned the search east, up the bluffs toward the road and a barrel beside an old chimney. Each modest container held another part of the captain’s last directions."},{["episodeID"]="westfall-sanders-coastal-clues-139",["requiresAll"]={{["minimumStage"]=2,["questID"]=139}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"139:description:1-69","139:description:72-129","139:description:132-246","139:description:249-319","139:objective:1-60"},["questID"]=139,["sourceHash"]="6c407bb087cf07035c1b602473313e0d9d15e2b4e69e49afa921121d9b92fe63",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The barrel pointed north to an empty jug beside a lone windmill on the sea bluffs. The trail followed the shore’s abandoned landmarks rather than a single marked destination."},{["episodeID"]="westfall-sanders-coastal-clues-140",["requiresAll"]={{["minimumStage"]=4,["questID"]=140}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"140:description:1-80","140:description:83-255","140:description:258-315","140:description:318-354","140:description:357-423","140:objective:1-58","140:completion:1-58","140:completion:60-103","140:completion:108-123"},["questID"]=140,["sourceHash"]="a79f38e684818e81b03206f520000688b41213603cfb37b4cedcaf70173393a2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The whiskey-stained final message led west into the water and out to an island. There the old chest’s rusty hinges still yielded, bringing the captain’s wandering chain of clues to its hidden reward."}},["grouping"]="A four-clue treasure route; no unidentified item, wider pirate voyage or personal shipwreck is invented.",["quests"]={136,138,139,140},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Captain’s Last Directions"},["wetlands-menethil-statuette"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=279,["sourceHash"]="37ce3b4ced8a78466e3bdf0b724f638f3f6e7ee7e0c5be280f371c7a0dba7018"},{["minimumStage"]=4,["questID"]=281,["sourceHash"]="f6cf918bcce595d9fb6943ddd95e33db2bea032d484bfe0472d7f15de549facf"},{["minimumStage"]=4,["questID"]=284,["sourceHash"]="bdc8a3a7da35252f16842b8f7c76a718b6d6383fdfe1f484da6878ccb0c7c821"},{["minimumStage"]=4,["questID"]=285,["sourceHash"]="8bc84b8c90b1f49259eb4f789d8f564e381d0e0036f0ec776b0bdde9c7e2848a"},{["minimumStage"]=4,["questID"]=286,["sourceHash"]="ca14bc2c0adfeb65b490b7c1b3b5a50717e48daf338c297dfbd57db0d7c33583"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="wetlands-menethil-statuette-279",["requiresAll"]={{["minimumStage"]=2,["questID"]=279}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"279:description:1-91","279:description:94-158","279:description:163-331","279:description:334-395","279:description:400-444","279:description:447-492","279:objective:1-25","279:objective:30-60","279:objective:65-118"},["questID"]=279,["sourceHash"]="37ce3b4ced8a78466e3bdf0b724f638f3f6e7ee7e0c5be280f371c7a0dba7018",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Murlocs moving onto the coast threatened the fishers and merchants of Menethil. Gobbler’s raids from the river inlet made that danger personal to the Merchant Marines, who offered payment for protecting the road."},{["episodeID"]="wetlands-menethil-statuette-281",["requiresAll"]={{["minimumStage"]=2,["questID"]=281}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"281:description:1-74","281:description:77-224","281:description:227-259","281:description:264-349","281:description:352-399","281:objective:1-58"},["questID"]=281,["sourceHash"]="f6cf918bcce595d9fb6943ddd95e33db2bea032d484bfe0472d7f15de549facf",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The danger had already reached the sea lanes. Murlocs had stripped cargo from the Blind Princess, including a valuable likeness of Terenas Menethil. Its captain’s loss sent the search among the coastal hovels."},{["episodeID"]="wetlands-menethil-statuette-284",["requiresAll"]={{["minimumStage"]=2,["questID"]=284}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"284:description:1-97","284:description:102-186","284:objective:1-34"},["questID"]=284,["sourceHash"]="bdc8a3a7da35252f16842b8f7c76a718b6d6383fdfe1f484da6878ccb0c7c821",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The first search brought no sign of the statuette. Nearby shelters farther north and northeast offered another chance to trace the stolen cargo."},{["episodeID"]="wetlands-menethil-statuette-285",["requiresAll"]={{["minimumStage"]=2,["questID"]=285}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"285:description:1-77","285:description:82-148","285:description:153-216","285:objective:1-64"},["questID"]=285,["sourceHash"]="8bc84b8c90b1f49259eb4f789d8f564e381d0e0036f0ec776b0bdde9c7e2848a",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Another cluster of hovels yielded nothing. The search narrowed toward the northern shelters, with the missing figure still somewhere among goods hauled from the sea."},{["episodeID"]="wetlands-menethil-statuette-286",["requiresAll"]={{["minimumStage"]=4,["questID"]=286}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"286:description:1-109","286:description:112-172","286:description:177-212","286:description:215-270","286:objective:1-40","286:completion:1-98","286:completion:100-155","286:completion:160-244"},["questID"]=286,["sourceHash"]="ca14bc2c0adfeb65b490b7c1b3b5a50717e48daf338c297dfbd57db0d7c33583",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="A barrel pulled from the mire held a silvery figure packed in straw. Returned to Karl Boran, the recovered cargo brought relief for the Blind Princess’s captain and payment for dependable service in an unsettled harbor."}},["grouping"]="Merchant defense leads to the recovery of the Blind Princess’s lost statuette; no general coastal pacification is inferred.",["quests"]={279,281,284,285,286},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="Cargo Beneath the Hovels"},["wetlands-nekrosh-menethil-siege"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=473,["sourceHash"]="34bdac1645ada41117350efa2ca4d0aa78771f05d9e85b2a4a12fcef01c7c2c8"},{["minimumStage"]=4,["questID"]=464,["sourceHash"]="e527556b5812e30bd542f142940276b7a1dea804db0869960114a4d969dff5b8"},{["minimumStage"]=4,["questID"]=465,["sourceHash"]="4bb00cf6a37997d979e4f46d767449168327fdb033e7559498d3d5247bb3ce59"},{["minimumStage"]=4,["questID"]=474,["sourceHash"]="555e1798231650d76cc49f95fc4cb816e7dfb9e84f15cc6dcd3781f4d208fe28"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="wetlands-nekrosh-menethil-siege-473",["requiresAll"]={{["minimumStage"]=2,["questID"]=473}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"473:description:6-76","473:description:79-166","473:description:169-207","473:objective:1-29"},["questID"]=473,["sourceHash"]="34bdac1645ada41117350efa2ca4d0aa78771f05d9e85b2a4a12fcef01c7c2c8",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The Dragonmaw threat reached beyond Dun Algaz. Captain Stoutfist called for help in Menethil’s war room, where the danger to the harbor could be faced as a campaign rather than an isolated skirmish."},{["episodeID"]="wetlands-nekrosh-menethil-siege-464",["requiresAll"]={{["minimumStage"]=4,["questID"]=464}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"464:description:1-124","464:description:127-217","464:description:220-310","464:description:315-388","464:description:393-430","464:description:433-479","464:objective:1-51","464:completion:1-16","464:completion:18-124","464:completion:129-231","464:completion:233-344","464:completion:349-437"},["questID"]=464,["sourceHash"]="e527556b5812e30bd542f142940276b7a1dea804db0869960114a4d969dff5b8",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The banners brought news of a clan rebuilding after its flight from Grim Batol. Stoutfist named its leader as Nek’rosh, son of Nekros, who sought revenge on the dragons that had killed his father."},{["episodeID"]="wetlands-nekrosh-menethil-siege-465",["requiresAll"]={{["minimumStage"]=2,["questID"]=465}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"465:description:1-74","465:description:79-141","465:description:144-225","465:description:230-266","465:description:269-304","465:description:309-331","465:description:334-396","465:description:401-451","465:description:454-508","465:objective:1-32"},["questID"]=465,["sourceHash"]="4bb00cf6a37997d979e4f46d767449168327fdb033e7559498d3d5247bb3ce59",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The clan’s new strength took shape in catapults aimed at Menethil. Fighting in the pass had blocked reinforcements, making the siege engines an immediate danger; Stoutfist supplied tinder to burn them before their commander was confronted."},{["episodeID"]="wetlands-nekrosh-menethil-siege-474",["requiresAll"]={{["minimumStage"]=4,["questID"]=474}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"474:description:1-74","474:objective:1-23","474:objective:28-70","474:completion:1-17","474:completion:19-74","474:completion:76-98","474:completion:100-168","474:completion:173-256"},["questID"]=474,["sourceHash"]="555e1798231650d76cc49f95fc4cb816e7dfb9e84f15cc6dcd3781f4d208fe28",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="With the catapults destroyed and Nek’rosh’s head delivered, Stoutfist judged the immediate siege broken and rewarded the service to Ironforge. For Menethil, the burned engines and fallen commander brought an end to the immediate siege."}},["grouping"]="The Menethil campaign against Nek’rosh; the commander’s defeat is not the destruction of every surviving Dragonmaw.",["quests"]={473,464,465,474},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Catapults Above the Harbor"},["wetlands-ormer-raptors"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=294,["sourceHash"]="8ed00f1084bab112c18343b0ba760447bfe0f04b9c80eee17a6f0e3ad49f86c7"},{["minimumStage"]=4,["questID"]=295,["sourceHash"]="838f04860d676233e01bc57068d258c6bbb9265fd87155b85c5b2ed0eb331ca6"},{["minimumStage"]=4,["questID"]=296,["sourceHash"]="d86e79932dea5ffbdc6ccd115131703ed661c7f72737517c4d4ba93cec0d0910"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="wetlands-ormer-raptors-294",["requiresAll"]={{["minimumStage"]=2,["questID"]=294}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"294:description:1-47","294:description:50-104","294:description:107-200","294:description:205-249","294:description:252-323","294:description:326-353","294:description:358-424","294:objective:1-110"},["questID"]=294,["sourceHash"]="8ed00f1084bab112c18343b0ba760447bfe0f04b9c80eee17a6f0e3ad49f86c7",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The excavation had drawn raptors instead of only knowledge from the earth. Ormer’s companions were dead, and he, Merrin and the prospector remained trapped above the dig. His plea for help carried grief as much as concern for the work."},{["episodeID"]="wetlands-ormer-raptors-295",["requiresAll"]={{["minimumStage"]=2,["questID"]=295}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"295:description:1-77","295:description:80-157","295:description:160-213","295:objective:1-146"},["questID"]=295,["sourceHash"]="838f04860d676233e01bc57068d258c6bbb9265fd87155b85c5b2ed0eb331ca6",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The first attacks did not satisfy Ormer’s anger. His attention turned to the larger scytheclaws and razormaws below, extending the reprisal through the beasts gathered around the excavation."},{["episodeID"]="wetlands-ormer-raptors-296",["requiresAll"]={{["minimumStage"]=4,["questID"]=296}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"296:description:1-96","296:description:99-130","296:description:133-215","296:description:220-255","296:description:258-304","296:description:307-382","296:description:385-433","296:objective:1-143","296:completion:1-14","296:completion:16-55","296:completion:57-121","296:completion:123-253"},["questID"]=296,["sourceHash"]="d86e79932dea5ffbdc6ccd115131703ed661c7f72737517c4d4ba93cec0d0910",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Sarltooth’s size and threatening presence convinced Ormer that this raptor might have led the attack, though he could not know it for certain. The talon brought back as proof closed his final demand, and his thanks remembered the dwarves who had died at their work."}},["grouping"]="Ormer’s revenge for the excavation deaths; Sarltooth’s leadership remains his inference, and no permanent removal of local raptors is claimed.",["quests"]={294,295,296},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Bones That Drew Them"},["wetlands-rethiel-marsh-balance"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=463,["sourceHash"]="6430466dae12c93d1b42d9db7ae908fc5b369867ca51d45875995274139a9bb4"},{["minimumStage"]=4,["questID"]=276,["sourceHash"]="47a6a18339f508793955e41700f5be1e574b4357f3ead9bbd5a80a347b51b4db"},{["minimumStage"]=4,["questID"]=277,["sourceHash"]="2c292d4cd315d296da3d592c4b255fb71d4d4ff946741650b0a1779f35dd022f"},{["minimumStage"]=4,["questID"]=275,["sourceHash"]="c85ecff37b7e4e9daa68215ded2ede0de46428da7a8282c28a3495a0e3e7189d"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="wetlands-rethiel-marsh-balance-463",["requiresAll"]={{["minimumStage"]=4,["questID"]=463}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"463:description:1-32","463:description:35-70","463:description:73-158","463:description:163-269","463:description:272-318","463:description:323-348","463:description:351-483","463:objective:1-21","463:completion:1-49","463:completion:51-101","463:completion:103-130","463:completion:135-235"},["questID"]=463,["sourceHash"]="6430466dae12c93d1b42d9db7ae908fc5b369867ca51d45875995274139a9bb4",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The fearful stories told of the Greenwarden gave way to a different voice in the marsh. He named himself Rethiel and spoke for roots and ferns, asking that the wounds of the Wetlands be tended."},{["episodeID"]="wetlands-rethiel-marsh-balance-276",["requiresAll"]={{["minimumStage"]=2,["questID"]=276}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"276:description:1-98","276:description:101-210","276:description:215-258","276:description:261-316","276:description:321-369","276:description:372-426","276:description:429-460","276:objective:1-105"},["questID"]=276,["sourceHash"]="47a6a18339f508793955e41700f5be1e574b4357f3ead9bbd5a80a347b51b4db",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Rethiel remembered years in which the Mosshide had lived peacefully in the fen. Their growing numbers, trampling feet and hunger for firewood had disturbed that balance, bringing his request into conflict with the gnolls near Algaz."},{["episodeID"]="wetlands-rethiel-marsh-balance-277",["requiresAll"]={{["minimumStage"]=2,["questID"]=277}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"277:description:1-105","277:description:108-141","277:description:146-218","277:description:221-315","277:objective:1-45"},["questID"]=277,["sourceHash"]="2c292d4cd315d296da3d592c4b255fb71d4d4ff946741650b0a1779f35dd022f",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Reducing the Mosshide numbers did not quiet the pain of burning wood. Rethiel wanted their fire-making flints broken and cast into the sea, striking at the means of further cutting and burning."},{["episodeID"]="wetlands-rethiel-marsh-balance-275",["requiresAll"]={{["minimumStage"]=4,["questID"]=275}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"275:description:1-61","275:description:64-87","275:description:90-233","275:description:238-299","275:objective:1-76","275:completion:1-75"},["questID"]=275,["sourceHash"]="c85ecff37b7e4e9daa68215ded2ede0de46428da7a8282c28a3495a0e3e7189d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The work turned at last to fevered fen creepers rising in the waterways. Rethiel spoke of land soothed by the effort and granted his boon, a measure of relief within a marsh whose greater troubles had not all been explained."}},["grouping"]="Rethiel’s local requests and limited relief; no comprehensive ecological restoration or hostility to every gnoll is inferred.",["quests"]={463,276,277,275},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Marsh’s Wounds"},["wetlands-third-fleet-eye"]={["authored"]=true,["branchHandling"]={},["completionRequirements"]={["expression"]={["allOf"]={{["minimumStage"]=4,["questID"]=288,["sourceHash"]="896815493d230e088a634aab4679d887b048e1036ce2ee5761d1993970a8628b"},{["minimumStage"]=4,["questID"]=289,["sourceHash"]="0d9c72cb9424b2ceec37e2b10ecb7467a0791297a296dc4c33b39aa4a92d794e"},{["minimumStage"]=4,["questID"]=290,["sourceHash"]="8bb517c63dd76436136e2a6b1de236a218b0ce397d52ca27f5dff6e2603ee808"},{["minimumStage"]=4,["questID"]=292,["sourceHash"]="2b87361234444d77f6bd43a65e8ea84546a57997372f614982341f645ef4903d"},{["minimumStage"]=4,["questID"]=293,["sourceHash"]="33664d152f405e184e5a43fa92b6e3a2a11afeeae13ba547d7a0d338a2e969b4"}}},["interpretation"]="Observed fulfillment of this defined route, not a wider clear, reconciliation, cure or personal experience inferred from reference lore.",["scope"]="OBSERVED_RETAINED_ROUTE_AND_DEFINED_HANDOVER"},["episodes"]={{["episodeID"]="wetlands-third-fleet-eye-288",["requiresAll"]={{["minimumStage"]=2,["questID"]=288}},["role"]="start",["sourceProofs"]={{["atomIDs"]={"288:description:1-90","288:description:93-109","288:description:112-181","288:description:184-210","288:description:215-319","288:description:322-367","288:description:372-405","288:description:408-492","288:objective:1-44"},["questID"]=288,["sourceHash"]="896815493d230e088a634aab4679d887b048e1036ce2ee5761d1993970a8628b",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="Fitzsimmons had been first mate aboard the Wave Mistress when orc-controlled red dragons burned the Third Fleet. Drink loosened the survivor’s account, but survival had not freed him from what remained offshore."},{["episodeID"]="wetlands-third-fleet-eye-289",["requiresAll"]={{["minimumStage"]=2,["questID"]=289}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"289:description:1-46","289:description:51-151","289:description:154-257","289:description:260-423","289:description:428-507","289:objective:1-64","289:objective:67-136"},["questID"]=289,["sourceHash"]="0d9c72cb9424b2ceec37e2b10ecb7467a0791297a296dc4c33b39aa4a92d794e",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="His shipmates still walked the wrecks. Fitzsimmons blamed a hidden treasure whose power bound their souls inside the rotting hulls, turning a tale of dragonfire into a plea for the dead."},{["episodeID"]="wetlands-third-fleet-eye-290",["requiresAll"]={{["minimumStage"]=2,["questID"]=290}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"290:description:1-111","290:description:114-241","290:description:246-282","290:description:285-329","290:description:332-397","290:description:402-488","290:objective:1-53","290:objective:58-109"},["questID"]=290,["sourceHash"]="8bb517c63dd76436136e2a6b1de236a218b0ce397d52ca27f5dff6e2603ee808",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The source of the curse lay in the Intrepid’s strongbox. Captain Halyndor still guarded the key, and Fitzsimmons directed the search toward him before sending the object to Menethil’s priest."},{["episodeID"]="wetlands-third-fleet-eye-292",["requiresAll"]={{["minimumStage"]=2,["questID"]=292}},["role"]="middle",["sourceProofs"]={{["atomIDs"]={"292:description:1-71","292:description:74-143","292:description:148-236","292:description:239-276","292:objective:1-51"},["questID"]=292,["sourceHash"]="2b87361234444d77f6bd43a65e8ea84546a57997372f614982341f645ef4903d",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="The chest held a darkened orb with an unnatural glow: an Eye of Paleth. Glorin Steelbrow recognized the danger, but the answer lay with the human priesthood that had created the Eyes."},{["episodeID"]="wetlands-third-fleet-eye-293",["requiresAll"]={{["minimumStage"]=4,["questID"]=293}},["role"]="end",["sourceProofs"]={{["atomIDs"]={"293:description:1-46","293:description:49-155","293:description:158-190","293:description:193-242","293:description:245-256","293:description:261-282","293:objective:1-53","293:objective:56-121","293:completion:1-17","293:completion:19-112","293:completion:117-243"},["questID"]=293,["sourceHash"]="33664d152f405e184e5a43fa92b6e3a2a11afeeae13ba547d7a0d338a2e969b4",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"}},["text"]="In Stormwind, Archbishop Benedictus recognized an Eye burdened by terrible sorrow and undertook its cleansing. The object’s journey reached an answer in the Cathedral of Light, beyond the power Glorin could offer in the harbor."}},["grouping"]="Fitzsimmons’s account, the captive crews and the Eye’s cleansing; the ending does not independently verify every soul’s release.",["quests"]={288,289,290,292,293},["referenceStatus"]="RETAINED_SOURCE_ROUTE_NOT_CURRENT_SERVER_VERIFIED",["sourceConflict"]=false,["title"]="The Treasure in the Wreck"}}
for id,row in pairs(additions) do assert(not ns.WorldCodexInput.arcs[id],"Duplicate authored arc");ns.WorldCodexInput.arcs[id]=row end
